_SUBJECT_WORKFLOW_REQUEST_CACHE: contextvars.ContextVar[dict[tuple[object, ...], object] | None] = (
    contextvars.ContextVar("subject_workflow_request_cache", default=None)
)


@contextmanager
def subject_workflow_request_cache() -> Iterator[None]:
    existing_cache = _SUBJECT_WORKFLOW_REQUEST_CACHE.get()
    if existing_cache is not None:
        yield
        return
    token = _SUBJECT_WORKFLOW_REQUEST_CACHE.set({})
    try:
        yield
    finally:
        _SUBJECT_WORKFLOW_REQUEST_CACHE.reset(token)


def _subject_workflow_cached_read(cache_key: tuple[object, ...], loader: Callable[[], object]) -> object:
    cache = _SUBJECT_WORKFLOW_REQUEST_CACHE.get()
    if cache is None:
        return loader()
    if cache_key not in cache:
        cache[cache_key] = loader()
    return cache[cache_key]


def _read_json(path: Path) -> dict[str, object]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return payload if isinstance(payload, dict) else {}


def _preview_excerpt(text: str, *, max_lines: int = 32, max_chars: int = 2800) -> str:
    rendered = str(text or "")
    if not rendered.strip():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return "<empty>"
    lines = rendered.splitlines()
    excerpt = "\n".join(lines[:max_lines])
    truncated = len(lines) > max_lines
    if len(excerpt) > max_chars:
        excerpt = excerpt[:max_chars].rstrip()
        truncated = True
    if truncated:
        return f"{excerpt}\n\n[truncated]"
    return excerpt


def _preview_file(path_text: str, *, missing_text: str) -> str:
    path = Path(path_text).expanduser()
    if not path_text or not path.is_file():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return missing_text
    return _preview_excerpt(path.read_text(encoding="utf-8"))


def _preview_binary_artifact(path_text: str, *, missing_text: str, artifact_label: str) -> str:
    path = Path(path_text).expanduser()
    if not path_text or not path.is_file():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return missing_text
    return "\n".join(
        [
            f"{artifact_label} is a binary artifact.",
            f"- path: {path.resolve()}",
            f"- size: {path.stat().st_size} bytes",
            "- use the matching preview action to open it externally",
        ]
    )


def _ui_path_label(root_path: Path, path_text: str) -> str:
    normalized = collapse_ws(path_text)
    if not normalized:
        return "<none>"
    path = Path(normalized).expanduser()
    try:
        resolved = path.resolve(strict=False)
    except Exception:
        resolved = path
    try:
        return str(resolved.relative_to(root_path.expanduser().resolve()))
    except Exception:
        pass
    if not path.is_absolute():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return normalized
    return textwrap.shorten(str(resolved), width=96, placeholder="...")


def _short_text_hash(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:12]


def _stable_json_hash(payload: object) -> str:
    rendered = json.dumps(payload, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(rendered.encode("utf-8")).hexdigest()


def _set_latest_receipt(progress: SubjectProgress, *, title: str, lines: list[str] | tuple[str, ...]) -> None:
    progress.latest_receipt_title = collapse_ws(title) or "Latest Receipt"
    progress.latest_receipt_lines = [str(line).rstrip() for line in lines if str(line).strip()]


def _receipt_section(title: str, lines: list[str] | tuple[str, ...]) -> list[str]:
    if not lines:
        return []
    return [title, *[str(line) for line in lines]]


def _directory_item_count(path_text: str) -> int:
    path = Path(path_text).expanduser()
    if not path.is_dir():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return 0
    return sum(1 for _ in path.iterdir())


def _file_size_text(path_text: str) -> str:
    path = Path(path_text).expanduser()
    if not path.is_file():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return "<missing>"
    return f"{path.stat().st_size} bytes"


def _directory_preview_lines(path_text: str, *, limit: int = 8) -> list[str]:
    path = Path(path_text).expanduser()
    if not path.is_dir():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return ["- packet contents: <unavailable>"]
    entries = sorted(item.name for item in path.iterdir())
    preview = entries[:limit]
    suffix = " ..." if len(entries) > limit else ""
    return [f"- packet contents: {', '.join(preview)}{suffix}" if preview else "- packet contents: <empty>"]


def _manual_rephrase_file_text(
    *,
    title: str,
    label: str,
    text: str,
) -> str:
    return "\n".join(
        [
            f"# {title}",
            "# Save this file, then return to the workstation and apply or discard the rephrase.",
            "# This edits intermediate wording only. It does not rewrite the source markdown.",
            "",
            _MANUAL_REPHRASE_LABEL_MARKER,
            collapse_ws(label),
            "",
            _MANUAL_REPHRASE_TEXT_MARKER,
            str(text or "").strip(),
            "",
        ]
    )


def _parse_manual_rephrase_file(path: Path) -> tuple[str, str] | None:
    try:
        rendered = path.read_text(encoding="utf-8")
    except Exception:
        return None
    return _parse_marked_rephrase_text(rendered)


def _parse_marked_rephrase_text(rendered: str) -> tuple[str, str] | None:
    label_marker = f"\n{_MANUAL_REPHRASE_LABEL_MARKER}\n"
    text_marker = f"\n{_MANUAL_REPHRASE_TEXT_MARKER}\n"
    normalized = "\n" + str(rendered or "").strip() + "\n"
    label_start = normalized.find(label_marker)
    text_start = normalized.find(text_marker)
    if label_start < 0 or text_start < 0 or text_start <= label_start:
        return None
    label_text = normalized[label_start + len(label_marker):text_start]
    body_text = normalized[text_start + len(text_marker):]
    parsed_label = collapse_ws(label_text)
    parsed_text = str(body_text).strip()
    if not parsed_label:
        return None
    return parsed_label, parsed_text


def _write_manual_rephrase_file(
    *,
    title: str,
    label: str,
    text: str,
) -> str:
    directory = Path(runtime_mkdtemp(prefix="workstation-rephrase-"))
    path = directory / "rephrase.txt"
    path.write_text(
        _manual_rephrase_file_text(title=title, label=label, text=text),
        encoding="utf-8",
    )
    return str(path.resolve())


_MANUAL_SOURCE_COLLECTION_DESCRIPTION_MARKER = "[description]"
_MANUAL_SOURCE_COLLECTION_QUERY_MARKER = "[query]"
_SOURCE_COLLECTION_SYNTHESIS_SUMMARY_MARKER = "[summary]"
_SOURCE_COLLECTION_SYNTHESIS_QUESTIONS_MARKER = "[questions]"
_SOURCE_DISCOVERY_BLOCK_MARKER = "[source]"
_SOURCE_DISCOVERY_URL_MARKER = "[url]"
_SOURCE_DISCOVERY_NOTES_MARKER = "[notes]"


def _manual_source_collection_file_text(
    *,
    title: str,
    label: str,
    description: str,
    query_text: str,
) -> str:
    return "\n".join(
        [
            f"# {collapse_ws(title) or 'Gather Source Set Curation'}",
            "",
            "# This edits source-set metadata only. It does not import sources into corpus.",
            "",
            _MANUAL_REPHRASE_LABEL_MARKER,
            collapse_ws(label),
            "",
            _MANUAL_SOURCE_COLLECTION_DESCRIPTION_MARKER,
            str(description or "").strip(),
            "",
            _MANUAL_SOURCE_COLLECTION_QUERY_MARKER,
            str(query_text or "").strip(),
            "",
        ]
    )


def _write_manual_source_collection_file(
    *,
    title: str,
    label: str,
    description: str,
    query_text: str,
) -> str:
    directory = Path(runtime_mkdtemp(prefix="workstation-source-set-"))
    path = directory / "collection.txt"
    path.write_text(
        _manual_source_collection_file_text(
            title=title,
            label=label,
            description=description,
            query_text=query_text,
        ),
        encoding="utf-8",
    )
    return str(path.resolve())


def _parse_marked_source_collection_text(rendered: str) -> tuple[str, str, str] | None:
    label_marker = f"\n{_MANUAL_REPHRASE_LABEL_MARKER}\n"
    description_marker = f"\n{_MANUAL_SOURCE_COLLECTION_DESCRIPTION_MARKER}\n"
    query_marker = f"\n{_MANUAL_SOURCE_COLLECTION_QUERY_MARKER}\n"
    normalized = "\n" + str(rendered or "").strip() + "\n"
    label_start = normalized.find(label_marker)
    description_start = normalized.find(description_marker)
    query_start = normalized.find(query_marker)
    if label_start < 0 or description_start < 0 or query_start < 0:
        return None
    if not (label_start < description_start < query_start):
        return None
    label_text = normalized[label_start + len(label_marker):description_start]
    description_text = normalized[description_start + len(description_marker):query_start]
    query_text = normalized[query_start + len(query_marker):]
    parsed_label = collapse_ws(label_text)
    if not parsed_label:
        return None
    return parsed_label, str(description_text or "").strip(), str(query_text or "").strip()


def _parse_source_collection_creation_text(rendered: str) -> tuple[str, str, str] | None:
    parts = [str(part or "").strip() for part in str(rendered or "").split("|", 2)]
    if len(parts) < 2:
        return None
    title_text = collapse_ws(parts[0])
    query_text = str(parts[1] or "").strip()
    description_text = str(parts[2] or "").strip() if len(parts) > 2 else ""
    if not title_text or not collapse_ws(query_text):
        return None
    return title_text, query_text, description_text


def _parse_manual_source_collection_file(path: Path) -> tuple[str, str, str] | None:
    try:
        rendered = path.read_text(encoding="utf-8")
    except Exception:
        return None
    return _parse_marked_source_collection_text(rendered)


def _parse_marked_source_discovery_text(rendered: str) -> tuple[tuple[str, str, str], ...]:
    block_marker = f"\n{_SOURCE_DISCOVERY_BLOCK_MARKER}\n"
    label_marker = f"\n{_MANUAL_REPHRASE_LABEL_MARKER}\n"
    url_marker = f"\n{_SOURCE_DISCOVERY_URL_MARKER}\n"
    notes_marker = f"\n{_SOURCE_DISCOVERY_NOTES_MARKER}\n"
    normalized = "\n" + str(rendered or "").strip() + "\n"
    block_indexes: list[int] = []
    start = 0
    while True:
        index = normalized.find(block_marker, start)
        if index < 0:
            break
        block_indexes.append(index)
        start = index + len(block_marker)
    if not block_indexes:
        return ()
    parsed: list[tuple[str, str, str]] = []
    seen_urls: set[str] = set()
    for block_index_index, block_start in enumerate(block_indexes):
        block_body_start = block_start + len(block_marker)
        block_end = (
            block_indexes[block_index_index + 1]
            if block_index_index + 1 < len(block_indexes)
            else len(normalized)
        )
        block_text = normalized[block_body_start:block_end]
        block_normalized = "\n" + str(block_text).strip() + "\n"
        label_start = block_normalized.find(label_marker)
        url_start = block_normalized.find(url_marker)
        notes_start = block_normalized.find(notes_marker)
        if label_start < 0 or url_start < 0 or notes_start < 0:
            continue
        if not (label_start < url_start < notes_start):
            continue
        label_text = block_normalized[label_start + len(label_marker):url_start]
        url_text = block_normalized[url_start + len(url_marker):notes_start]
        notes_text = block_normalized[notes_start + len(notes_marker):]
        parsed_label = collapse_ws(label_text)
        parsed_url = str(url_text or "").strip()
        parsed_notes = str(notes_text or "").strip()
        normalized_url_key = collapse_ws(parsed_url).casefold()
        if not parsed_label or not parsed_url or not parsed_notes or normalized_url_key in seen_urls:
            continue
        seen_urls.add(normalized_url_key)
        parsed.append((parsed_label, parsed_url, parsed_notes))
    return tuple(parsed)


def _parse_marked_source_collection_synthesis_text(
    rendered: str,
) -> tuple[str, tuple[str, ...], str] | None:
    summary_marker = f"\n{_SOURCE_COLLECTION_SYNTHESIS_SUMMARY_MARKER}\n"
    questions_marker = f"\n{_SOURCE_COLLECTION_SYNTHESIS_QUESTIONS_MARKER}\n"
    query_marker = f"\n{_MANUAL_SOURCE_COLLECTION_QUERY_MARKER}\n"
    normalized = "\n" + str(rendered or "").strip() + "\n"
    summary_start = normalized.find(summary_marker)
    questions_start = normalized.find(questions_marker)
    query_start = normalized.find(query_marker)
    if summary_start < 0 or questions_start < 0 or query_start < 0:
        return None
    if not (summary_start < questions_start < query_start):
        return None
    summary_text = normalized[summary_start + len(summary_marker):questions_start]
    questions_text = normalized[questions_start + len(questions_marker):query_start]
    query_text = normalized[query_start + len(query_marker):]
    parsed_summary = str(summary_text or "").strip()
    if not collapse_ws(parsed_summary):
        return None
    questions = tuple(
        collapse_ws(line.lstrip("-* ").strip())
        for line in str(questions_text or "").splitlines()
        if collapse_ws(line.lstrip("-* ").strip())
    )
    return parsed_summary, questions, str(query_text or "").strip()


def _parse_marked_source_set_merge_back_text(rendered: str) -> tuple[tuple[str, str, str], ...]:
    block_marker = f"\n{_SOURCE_DISCOVERY_BLOCK_MARKER}\n"
    label_marker = f"\n{_MANUAL_REPHRASE_LABEL_MARKER}\n"
    url_marker = f"\n{_SOURCE_DISCOVERY_URL_MARKER}\n"
    text_marker = f"\n{_MANUAL_REPHRASE_TEXT_MARKER}\n"
    normalized = "\n" + str(rendered or "").strip() + "\n"
    block_indexes: list[int] = []
    start = 0
    while True:
        index = normalized.find(block_marker, start)
        if index < 0:
            break
        block_indexes.append(index)
        start = index + len(block_marker)
    if not block_indexes:
        return ()
    parsed: list[tuple[str, str, str]] = []
    seen_urls: set[str] = set()
    for block_index_index, block_start in enumerate(block_indexes):
        block_body_start = block_start + len(block_marker)
        block_end = (
            block_indexes[block_index_index + 1]
            if block_index_index + 1 < len(block_indexes)
            else len(normalized)
        )
        block_text = normalized[block_body_start:block_end]
        block_normalized = "\n" + str(block_text).strip() + "\n"
        label_start = block_normalized.find(label_marker)
        url_start = block_normalized.find(url_marker)
        text_start = block_normalized.find(text_marker)
        if label_start < 0 or url_start < 0 or text_start < 0:
            continue
        if not (label_start < text_start and url_start < text_start):
            continue
        prefix_markers = sorted(
            [
                (label_start, "label"),
                (url_start, "url"),
            ],
            key=lambda item: item[0],
        )
        first_start, first_kind = prefix_markers[0]
        second_start, second_kind = prefix_markers[1]
        first_body_start = first_start + (len(label_marker) if first_kind == "label" else len(url_marker))
        second_body_start = second_start + (len(label_marker) if second_kind == "label" else len(url_marker))
        first_body = block_normalized[first_body_start:second_start]
        second_body = block_normalized[second_body_start:text_start]
        label_text = first_body if first_kind == "label" else second_body
        url_text = first_body if first_kind == "url" else second_body
        body_text = block_normalized[text_start + len(text_marker):]
        parsed_label = collapse_ws(label_text)
        parsed_url = str(url_text or "").strip()
        parsed_text = str(body_text or "").strip()
        normalized_url = collapse_ws(parsed_url).casefold()
        if not parsed_label or not normalized_url or not parsed_text or normalized_url in seen_urls:
            continue
        seen_urls.add(normalized_url)
        parsed.append((parsed_url, parsed_label, parsed_text))
    return tuple(parsed)


def _source_discovery_markdown_text(
    *,
    label: str,
    url: str,
    notes: str,
    collection_title: str,
    query_text: str,
) -> str:
    rendered_lines = [
        f"# {collapse_ws(label) or 'Discovered Source'}",
        "",
        "This is a staged source reference discovered in Gather. It is not yet admitted corpus.",
        "",
        "## Source URL",
        str(url).strip(),
        "",
        "## Why this source matters",
        str(notes).strip(),
        "",
        "## Discovery context",
        f"- source set: {collapse_ws(collection_title) or '<none>'}",
        (
            f"- query/topic: {str(query_text).strip()}"
            if collapse_ws(query_text)
            else "- query/topic: <none>"
        ),
    ]
    return "\n".join(rendered_lines).rstrip() + "\n"


