def _pending_itemize_manual_rephrase_path(
    *,
    progress: SubjectProgress,
    selected_item: ItemizedSubjectItem | None,
) -> Path | None:
    if selected_item is None:
        return None
    pending_item_id = collapse_ws(progress.itemize_manual_rephrase_item_id)
    selected_item_id = collapse_ws(selected_item.itemized_item_id)
