def _itemization_state(root_path: Path, scenario: SubjectScenario) -> dict[str, object]:
    def _load() -> dict[str, object]:
        if scenario.is_placeholder or not collapse_ws(scenario.subject_id):
        # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
            return {
                "exists": False,
                "freshness": "missing",
                "validation_status": "unavailable",
                "item_count": 0,
                "kind_counts": {},
                "preview_lines": (),
                "session_id": "",
                "direct_llm_decomposition_status": "",
                "direct_llm_candidate_count": 0,
            }
        session_path = itemization_paths(root_path, scenario.subject_id)["session"]
        if not session_path.is_file():
            return {
                "exists": False,
                "freshness": "missing",
                "validation_status": "unavailable",
                "item_count": 0,
                "kind_counts": {},
                "preview_lines": (),
                "session_id": "",
                "direct_llm_decomposition_status": "",
                "direct_llm_candidate_count": 0,
            }
        try:
            session = load_itemization_session(root_path, scenario.subject_id)
            items = list_itemized_subject_items(root_path, scenario.subject_id)
            validation = validate_itemization_session(
                session,
                items=items,
                learning_context_snapshot_hash=scenario.context_snapshot_hash,
            )
        except Exception as exc:
            return {
                "exists": True,
                "freshness": "error",
                "validation_status": "error",
                "item_count": 0,
                "kind_counts": {},
                "preview_lines": (f"- itemization load failed: {collapse_ws(str(exc)) or 'unknown error'}",),
                "session_id": "",
                "direct_llm_decomposition_status": "",
                "direct_llm_candidate_count": 0,
            }
        preview_lines = tuple(
            f"- [{item.item_kind}] {item.canonical_label}"
            for item in items[:8]
        )
        if len(items) > 8:
            preview_lines = (*preview_lines, f"- ... {len(items) - 8} more items")
        return {
            "exists": True,
            "freshness": str(validation.get("snapshot_status", "unknown")),
            "validation_status": str(validation.get("status", "error")),
            "validation_errors": tuple(str(item) for item in validation.get("errors", [])),
            "item_count": int(validation.get("item_count", len(items)) or 0),
            "kind_counts": dict(validation.get("item_kind_counts", {})),
            "preview_lines": preview_lines,
            "session_id": session.itemization_session_id,
            "direct_llm_decomposition_status": collapse_ws(
                str(session.metadata.get("direct_llm_decomposition_status", ""))
            ),
            "direct_llm_candidate_count": int(session.metadata.get("direct_llm_candidate_count", 0) or 0),
        }

    return _subject_workflow_cached_read(("_itemization_state", root_path, scenario), _load)


def _itemization_primary_action_label(itemization_state: dict[str, object]) -> str:
    freshness = collapse_ws(str(itemization_state.get("freshness", "")))
    return "Refresh Itemization" if freshness in {"current", "stale"} else "Generate Itemization"


def _itemization_receipt_lines(
    *,
    scenario: SubjectScenario,
    itemization_state: dict[str, object],
) -> list[str]:
    validation_errors = tuple(str(item) for item in itemization_state.get("validation_errors", ()))
    kind_counts = dict(itemization_state.get("kind_counts", {}))
    freshness = collapse_ws(str(itemization_state.get("freshness", ""))) or "missing"
    validation_status = collapse_ws(str(itemization_state.get("validation_status", ""))) or "unavailable"
    lines = [
        f"- session: {collapse_ws(str(itemization_state.get('session_id', ''))) or '<none>'}",
        f"- freshness: {freshness}",
        f"- validation: {validation_status}",
        f"- item count: {int(itemization_state.get('item_count', 0) or 0)}",
    ]
    direct_llm_status = collapse_ws(str(itemization_state.get("direct_llm_decomposition_status", "")))
    if direct_llm_status:
        lines.append(f"- direct llm decomposition: {direct_llm_status}")
        lines.append(
            f"- direct llm candidates: {int(itemization_state.get('direct_llm_candidate_count', 0) or 0)}"
        )
    if kind_counts:
        lines.append(
            "- item kinds: "
            + ", ".join(f"{kind}={count}" for kind, count in sorted(kind_counts.items()))
        )
    if validation_errors:
        lines.extend(f"- validation error: {error}" for error in validation_errors[:6])
    preview_lines = tuple(str(item) for item in itemization_state.get("preview_lines", ()))
    if preview_lines:
        lines.extend(["- sample items:"])
        lines.extend(preview_lines[:6])
    lines.append(f"- source subject: {scenario.title}")
    return lines


def _itemization_items(root_path: Path, scenario: SubjectScenario) -> tuple[object, ...]:
    def _load() -> tuple[object, ...]:
        if scenario.is_placeholder or not collapse_ws(scenario.subject_id):
        # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
            return ()
        try:
            session = load_itemization_session(root_path, scenario.subject_id)
            items = list_itemized_subject_items(root_path, scenario.subject_id)
        except Exception:
            return ()
        item_by_id = {
            collapse_ws(getattr(item, "itemized_item_id", "")): item
            for item in items
            if collapse_ws(getattr(item, "itemized_item_id", ""))
        }
        ordered: list[object] = [
            item_by_id[item_id]
            for item_id in getattr(session, "item_ids", ())
            if collapse_ws(item_id) in item_by_id
        ]
        extra_items = [
            item
            for item_id, item in item_by_id.items()
            if item_id not in set(getattr(session, "item_ids", ()))
        ]
        extra_items.sort(
            key=lambda item: (
                collapse_ws(getattr(item, "item_kind", "")),
                collapse_ws(getattr(item, "canonical_label", "")),
                collapse_ws(getattr(item, "itemized_item_id", "")),
            )
        )
        ordered.extend(extra_items)
        return tuple(ordered)

    return _subject_workflow_cached_read(("_itemization_items", root_path, scenario), _load)


def _subject_workflow_allows_direct_llm_decomposition(root_path: Path) -> bool:
    try:
        return bool(load_workstation_session(root_path).allow_direct_llm_decomposition)
    except Exception:
        return False


def _itemization_session_and_items(
    root_path: Path,
    scenario: SubjectScenario,
) -> tuple[ItemizationSession | None, tuple[ItemizedSubjectItem, ...]]:
    def _load() -> tuple[ItemizationSession | None, tuple[ItemizedSubjectItem, ...]]:
        if scenario.is_placeholder or not collapse_ws(scenario.subject_id):
        # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
            return None, ()
        try:
            session = load_itemization_session(root_path, scenario.subject_id)
            items = tuple(
                item
                for item in _itemization_items(root_path, scenario)
                if isinstance(item, ItemizedSubjectItem)
            )
        except Exception:
            return None, ()
        return session, items

    return _subject_workflow_cached_read(("_itemization_session_and_items", root_path, scenario), _load)


def _review_composition_and_items(
    root_path: Path,
    scenario: SubjectScenario,
) -> tuple[ReviewComposition | None, tuple[ReviewItem, ...]]:
    def _load() -> tuple[ReviewComposition | None, tuple[ReviewItem, ...]]:
        if scenario.is_placeholder or not collapse_ws(scenario.subject_id):
        # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
            return None, ()
        composition_path = review_composition_paths(root_path, scenario.subject_id)["composition"]
        if not composition_path.is_file():
            return None, ()
        try:
            composition = load_review_composition(root_path, scenario.subject_id)
            items = list_review_items(root_path, scenario.subject_id)
        except Exception:
            return None, ()
        return composition, items

    return _subject_workflow_cached_read(("_review_composition_and_items", root_path, scenario), _load)


def _current_review_composition_and_items(
    root_path: Path,
    scenario: SubjectScenario,
) -> tuple[ReviewComposition | None, tuple[ReviewItem, ...]]:
    def _load() -> tuple[ReviewComposition | None, tuple[ReviewItem, ...]]:
        composition, items = _review_composition_and_items(root_path, scenario)
        if composition is None:
            return None, ()
        if collapse_ws(composition.learning_context_snapshot_hash) != collapse_ws(scenario.context_snapshot_hash):
        # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
            return None, ()
        return composition, items

    return _subject_workflow_cached_read(("_current_review_composition_and_items", root_path, scenario), _load)


def _review_composition_state(root_path: Path, scenario: SubjectScenario) -> dict[str, object]:
    def _load() -> dict[str, object]:
        if scenario.is_placeholder or not collapse_ws(scenario.subject_id):
        # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
            return {
                "exists": False,
                "current": False,
                "status": "missing",
                "item_count": 0,
                "included_item_count": 0,
                "composition_id": "",
                "preview_lines": (),
            }
        composition_path = review_composition_paths(root_path, scenario.subject_id)["composition"]
        if not composition_path.is_file():
            return {
                "exists": False,
                "current": False,
                "status": "missing",
                "item_count": 0,
                "included_item_count": 0,
                "composition_id": "",
                "preview_lines": (),
            }
        try:
            composition, items = _review_composition_and_items(root_path, scenario)
            if composition is None:
                raise ValueError("missing composition payload")
        except Exception as exc:
            return {
                "exists": True,
                "current": False,
                "status": "error",
                "item_count": 0,
                "included_item_count": 0,
                "composition_id": "",
                "preview_lines": (f"- draft composition load failed: {collapse_ws(str(exc)) or 'unknown error'}",),
            }
        preview_lines = tuple(
            f"- [{'x' if item.included else ' '}] {item.semantic_kind} -> {item.render_kind}: {item.metadata.get('canonical_label', '') or item.review_item_id}"
            for item in items[:6]
        )
        if len(items) > 6:
            preview_lines = (*preview_lines, f"- ... {len(items) - 6} more review items")
        return {
            "exists": True,
            "current": collapse_ws(composition.learning_context_snapshot_hash) == collapse_ws(scenario.context_snapshot_hash),
            "status": collapse_ws(composition.status) or "draft",
            "item_count": len(items),
            "included_item_count": sum(1 for item in items if item.included),
            "composition_id": composition.review_composition_id,
            "preview_lines": preview_lines,
        }

    return _subject_workflow_cached_read(("_review_composition_state", root_path, scenario), _load)


def _review_composition_receipt_lines(
    *,
    scenario: SubjectScenario,
    composition: ReviewComposition,
    items: tuple[ReviewItem, ...],
) -> list[str]:
    semantic_counts = Counter(item.semantic_kind for item in items if collapse_ws(item.semantic_kind))
    render_counts = Counter(item.render_kind for item in items if collapse_ws(item.render_kind))
    lines = [
        f"- draft composition: {composition.review_composition_id}",
        f"- itemization session: {composition.itemization_session_id or '<none>'}",
        f"- subject snapshot: {composition.learning_context_snapshot_hash or '<pending>'}",
        f"- status: {composition.status}",
        f"- review items: {len(items)}",
        f"- included items: {sum(1 for item in items if item.included)}",
        f"- source subject: {scenario.title}",
    ]
    if semantic_counts:
        lines.append(
            "- semantic kinds: "
            + ", ".join(f"{kind}={count}" for kind, count in sorted(semantic_counts.items()))
        )
    if render_counts:
        lines.append(
            "- render kinds: "
            + ", ".join(f"{kind}={count}" for kind, count in sorted(render_counts.items()))
        )
    preview_lines = tuple(
        f"- [{'x' if item.included else ' '}] {item.semantic_kind} -> {item.render_kind}: {item.metadata.get('canonical_label', '') or item.review_item_id}"
        for item in items[:6]
    )
    if preview_lines:
        lines.extend(["- sample review items:", *preview_lines])
    return lines


def _refresh_review_composition_for_subject(
    *,
    root_path: Path,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    build_epoch_ms: int | None = None,
    timeline_prefix: str = "Created or refreshed draft composition",
    next_phase: str = "draft",
) -> SubjectActionResult:
    effective_build_epoch_ms = build_epoch_ms or int(time.time() * 1000)
    session, itemized_items = _itemization_session_and_items(root_path, scenario)
    if session is None or not itemized_items:
        return SubjectActionResult("Generate itemization first so Draft has normalized candidates to compose.")
    context = load_learning_context(root_path, scenario.subject_id)
    existing_review_composition, existing_review_items = _review_composition_and_items(root_path, scenario)
    review_composition, review_items = review_composition_from_itemization(
        context,
        session,
        itemized_items,
        existing=existing_review_composition,
        existing_items=existing_review_items,
        build_epoch_ms=effective_build_epoch_ms,
        status="draft",
    )
    persist_review_composition(root_path, review_composition, review_items)
    _sync_implicit_draft_decision_items_after_review_refresh(
        root_path,
        scenario=scenario,
        review_items=review_items,
        build_epoch_ms=effective_build_epoch_ms,
    )
    selected_review_item, _selection_source = _selected_draft_review_item(
        root_path,
        scenario=scenario,
        progress=progress,
    )
    if selected_review_item is not None:
        progress.draft_selected_review_item_id = collapse_ws(selected_review_item.review_item_id)
    _invalidate_downstream_review_and_publication_gate(progress)
    _clear_report_scope_reorder_state(progress)
    _set_latest_receipt(
        progress,
        title="Draft Composition",
        lines=_review_composition_receipt_lines(
            scenario=scenario,
            composition=review_composition,
            items=review_items,
        ),
    )
    entry = (
        f"{timeline_prefix} {review_composition.review_composition_id} "
        f"from {len(review_items)} itemized candidates."
    )
    progress.timeline.append(entry)
    return SubjectActionResult("Draft composition refreshed.", entry, next_phase=next_phase)


def _review_transform_receipt_lines(receipt: ReviewTransformReceipt) -> list[str]:
    lines = [
        f"- receipt: {receipt.receipt_id}",
        f"- transform: {receipt.transform_kind}",
        f"- review item: {receipt.review_item_id}",
        f"- operator: {receipt.operator or '<none>'}",
        f"- created: {int(receipt.created_at_epoch_ms or 0)}",
    ]
    if collapse_ws(receipt.notes):
        lines.append(f"- notes: {collapse_ws(receipt.notes)}")
    for key in ("selected_label", "source_item_id", "merged_review_item_ids", "child_review_item_ids", "promoted_review_item_id"):
        value = receipt.metadata.get(key)
        if isinstance(value, (list, tuple)):
            rendered = ", ".join(collapse_ws(str(item)) for item in value if collapse_ws(str(item)))
            if rendered:
                lines.append(f"- {key}: {rendered}")
        elif collapse_ws(str(value)):
            lines.append(f"- {key}: {collapse_ws(str(value))}")
    return lines


def _persist_review_transform_receipt_for_subject(
    root_path: Path,
    *,
    subject_id: str,
    composition: ReviewComposition,
    source_review_item_id: str,
    transform_kind: str,
    input_items: tuple[ReviewItem, ...],
    output_items: tuple[ReviewItem, ...],
    operator: str,
    notes: str,
    build_epoch_ms: int,
    metadata: dict[str, object] | None = None,
) -> ReviewTransformReceipt:
    receipt = ReviewTransformReceipt(
        receipt_id=stable_review_transform_receipt_id(
            review_item_id=source_review_item_id,
            transform_kind=transform_kind,
            output_snapshot_hash=review_composition_with_items(
                composition,
                output_items,
                build_epoch_ms=build_epoch_ms,
            ).content_hash(),
        ),
        review_item_id=collapse_ws(source_review_item_id),
        review_composition_id=composition.review_composition_id,
        transform_kind=transform_kind,
        input_snapshot_hash=_stable_json_hash([item.to_dict() for item in input_items]),
        output_snapshot_hash=_stable_json_hash([item.to_dict() for item in output_items]),
        operator=operator,
        notes=notes,
        created_at_epoch_ms=max(0, int(build_epoch_ms or 0)),
        metadata=dict(metadata or {}),
    )
    persist_review_transform_receipt(root_path, subject_id, receipt)
    return receipt


def _dst_projection_source_itemized_item_id(
    *,
    selected_item: ReviewItem | None,
    existing_frame: DecisionFrame | None,
    existing_candidates: tuple[TransformationConstructCandidate, ...],
    fixture_id: str,
) -> str:
    selected_itemized_item_id = ""
    if selected_item is not None:
        selected_itemized_item_id = (
            collapse_ws(str(selected_item.metadata.get("source_itemized_item_id", "")))
            or collapse_ws(getattr(selected_item, "source_itemized_item_id", ""))
        )
    if selected_itemized_item_id:
        return selected_itemized_item_id
    if isinstance(existing_frame, DecisionFrame):
        existing_frame_itemized_item_id = collapse_ws(str(existing_frame.metadata.get("source_itemized_item_id", "")))
        if existing_frame_itemized_item_id:
            return existing_frame_itemized_item_id
    for candidate in existing_candidates:
        if collapse_ws(candidate.itemized_item_id):
            return collapse_ws(candidate.itemized_item_id)
    return f"dst:{fixture_id}"


def _upsert_dst_decision_analysis_for_subject(
    *,
    root_path: Path,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    selected_item: ReviewItem | None,
    build_epoch_ms: int,
    require_existing_frame: bool,
) -> SubjectActionResult:
    dst_fixture = _dst_fixture_for_subject(root_path, scenario)
    if dst_fixture is None:
        return SubjectActionResult("This subject does not match a DST source fixture.")
    existing_frame: DecisionFrame | None
    existing_items: tuple[DecisionReviewItem, ...]
    try:
        existing_frame = load_decision_frame(root_path, scenario.subject_id)
        existing_items = list_decision_review_items(root_path, scenario.subject_id)
    except Exception:
        existing_frame = None
        existing_items = ()
    if require_existing_frame and (
        existing_frame is None or not collapse_ws(existing_frame.decision_frame_id)
    ):
        return SubjectActionResult("No DST decision analysis exists yet for this subject.")
    existing_candidates = list_transformation_construct_candidates(root_path, scenario.subject_id)
    existing_selected_candidate = _selected_transformation_construct_candidate(
        root_path,
        scenario=scenario,
        progress=progress,
        include_rejected=True,
    )
    existing_selected_signature = (
        _construct_candidate_continuity_signature(existing_selected_candidate)
        if existing_selected_candidate is not None
        else ()
    )
    try:
        subject_scope = load_subject_reasoning_scope(root_path, scenario.subject_id).to_dict()
        dst_result = run_live_dst_pipeline_from_fixture(
            dst_fixture,
            llm_policy="off",
            subject_scope=subject_scope,
            subject_scope_root_path=root_path,
            subject_id=scenario.subject_id,
            build_epoch_ms=build_epoch_ms,
        )
    except Exception as exc:
        action_label = "refresh" if require_existing_frame else "start"
        return SubjectActionResult(
            f"DST decision analysis {action_label} failed: {collapse_ws(str(exc)) or 'unknown error'}"
        )
    source_itemized_item_id = _dst_projection_source_itemized_item_id(
        selected_item=selected_item,
        existing_frame=existing_frame,
        existing_candidates=existing_candidates,
        fixture_id=dst_fixture.fixture_id,
    )
    incoming_frame = replace(
        dst_result.decision_projection.frame,
        publication_id=scenario.publication_id,
        metadata={
            **dict(dst_result.decision_projection.frame.metadata),
            "dst_seeded": True,
            "dst_fixture_id": dst_fixture.fixture_id,
            "dst_source_ref": dst_fixture.source_ref,
            "dst_discovery_proposal_id": dst_result.discovery_proposal_id,
            "dst_normalization_proposal_id": dst_result.normalization_proposal_id,
            "dst_root_non_achievedness": dst_result.discovery_prompt_packet.root_non_achievedness,
            "source_review_item_id": (
                collapse_ws(selected_item.review_item_id)
                if selected_item is not None
                else collapse_ws(str(existing_frame.metadata.get("source_review_item_id", "")))
                if isinstance(existing_frame, DecisionFrame)
                else ""
            ),
            "source_selection": (
                "draft_selection"
                if selected_item is not None
                else collapse_ws(str(existing_frame.metadata.get("source_selection", "")))
                if isinstance(existing_frame, DecisionFrame)
                else "dst_runtime"
            ),
            "source_itemized_item_id": source_itemized_item_id,
        },
    )
    merged_decision_items, incoming_to_resolved_item_id = _merge_dst_decision_review_items(
        existing_items,
        tuple(dst_result.decision_projection.items),
        build_epoch_ms=build_epoch_ms,
    )
    frame = _merge_dst_decision_frame(
        existing_frame,
        incoming_frame,
        incoming_to_resolved_item_id=incoming_to_resolved_item_id,
        build_epoch_ms=build_epoch_ms,
    )
    frame = _clear_decision_analysis_metadata(frame, build_epoch_ms=build_epoch_ms)
    dst_construct_projection = project_normalized_case_to_transformation_construct_candidates(
        dst_result.normalized_case,
        subject_id=scenario.subject_id,
        itemized_item_id=source_itemized_item_id,
        source_refs=_subject_source_refs(root_path, scenario.subject_id),
        review_item_id=collapse_ws(selected_item.review_item_id) if selected_item is not None else "",
        build_epoch_ms=build_epoch_ms,
    )
    merged_construct_candidates = _merge_transformation_construct_candidates(
        existing_candidates,
        dst_construct_projection.candidates,
    )
    synced_construct_candidates, merged_decision_items = _sync_construct_candidates_with_decision_items(
        merged_construct_candidates,
        merged_decision_items,
        frame=frame,
        build_epoch_ms=build_epoch_ms,
    )
    persist_decision_review(root_path, frame, merged_decision_items)
    persist_transformation_construct_candidates(
        root_path,
        scenario.subject_id,
        synced_construct_candidates,
    )
    policy_profile = load_decision_policy_profile(root_path, scenario.subject_id)
    if not collapse_ws(policy_profile.decision_frame_id):
        policy_profile = default_decision_policy_profile(
            decision_frame_id=frame.decision_frame_id,
            build_epoch_ms=build_epoch_ms,
        )
        persist_decision_policy_profile(root_path, scenario.subject_id, policy_profile)
    prioritized_construct = None
    if existing_selected_signature:
        prioritized_construct = next(
            (
                candidate
                for candidate in synced_construct_candidates
                if _construct_candidate_continuity_signature(candidate) == existing_selected_signature
            ),
            None,
        )
    if prioritized_construct is None and selected_item is not None:
        selected_label = collapse_ws(str(selected_item.metadata.get("canonical_label", ""))).casefold()
        prioritized_construct = next(
            (
                candidate
                for candidate in synced_construct_candidates
                if collapse_ws(candidate.canonical_label).casefold() == selected_label
            ),
            None,
        )
    if prioritized_construct is None and synced_construct_candidates:
        prioritized_construct = synced_construct_candidates[0]
    if prioritized_construct is not None:
        _set_draft_selection_to_construct_candidate_id(
            root_path,
            scenario=scenario,
            progress=progress,
            construct_candidate_id=prioritized_construct.construct_candidate_id,
        )
    synced_composition, approval_invalidated = _sync_current_publication_composition_after_decision_change(
        root_path,
        scenario=scenario,
        progress=progress,
        build_epoch_ms=build_epoch_ms,
    )
    action_phrase = "Refreshed" if require_existing_frame else "Created"
    status_text = (
        "DST decision analysis refreshed. Report plan updated."
        if require_existing_frame
        else "Decision analysis started from DST discovery. Report plan updated."
    )
    _set_latest_receipt(
        progress,
        title="DST Decision Analysis",
        lines=[
            f"- decision frame: {frame.decision_frame_id}",
            f"- fixture: {dst_fixture.title}",
            f"- question: {frame.question}",
            f"- decision items: {len(merged_decision_items)}",
            f"- synced constructs: {len(synced_construct_candidates)}",
            f"- candidate transitions: {len(dst_result.decision_projection.candidate_transition_ids)}",
            f"- candidate decisions: {len(dst_result.decision_projection.candidate_decision_ids)}",
            f"- discovery proposal: {dst_result.discovery_proposal_id or '<none>'}",
            f"- normalization proposal: {dst_result.normalization_proposal_id or '<none>'}",
            *(
                [f"- report plan: {synced_composition.composition_id} refreshed automatically"]
                if synced_composition is not None
                else []
            ),
            *(
                ["- review approval: cleared because the report changed"]
                if approval_invalidated
                else []
            ),
        ],
    )
    entry = (
        f"{action_phrase} DST decision analysis {frame.decision_frame_id} "
        f"from {dst_fixture.fixture_id}."
    )
    if synced_composition is not None:
        entry += f" Refreshed report plan {synced_composition.composition_id}."
    if approval_invalidated:
        entry += " Cleared Review approval because the approved report changed."
    progress.timeline.append(entry)
    return SubjectActionResult(
        status_text,
        entry,
        next_phase="draft",
        reload_subjects=synced_composition is not None,
    )


_DRAFT_REVIEW_SELECTION_LABELS = {
    "itemize_selection": "itemize selection",
    "report_scope_unit": "report scope unit",
    "draft_selection": "draft selection",
    "default_first_active": "default first active item",
}


def _format_orientation_label(value: str) -> str:
    normalized = collapse_ws(value).replace("_", " ")
    if not normalized:
        return "<none>"
    words = normalized.split()
    formatted: list[str] = []
    for word in words:
        if word.upper() == "LLM":
            formatted.append("LLM")
        else:
            formatted.append(word.capitalize())
    return " ".join(formatted)


def _draft_review_items(
    root_path: Path,
    *,
    scenario: SubjectScenario,
) -> tuple[ReviewItem, ...]:
    def _load() -> tuple[ReviewItem, ...]:
        return tuple(
            item
            for item in list_review_items(root_path, scenario.subject_id)
            if collapse_ws(item.review_item_id)
            and collapse_ws(item.status) != "rejected"
        )

    return _subject_workflow_cached_read(("_draft_review_items", root_path, scenario), _load)


def _flatten_draft_review_items(
    root_path: Path,
    *,
    scenario: SubjectScenario,
) -> tuple[tuple[ReviewItem, int], ...]:
    def _load() -> tuple[tuple[ReviewItem, int], ...]:
        return flatten_review_item_tree(_draft_review_items(root_path, scenario=scenario))

    return _subject_workflow_cached_read(("_flatten_draft_review_items", root_path, scenario), _load)


def _decision_review_state(root_path: Path, scenario: SubjectScenario) -> dict[str, object]:
    def _load() -> dict[str, object]:
        if scenario.is_placeholder or not collapse_ws(scenario.subject_id):
            return {
                "exists": False,
                "item_count": 0,
                "included_item_count": 0,
                "recommendation_status": "pending",
                "blocking_conditions": (),
                "policy_profile_kind": "",
            }
        frame = load_decision_frame(root_path, scenario.subject_id)
        items = list_decision_review_items(root_path, scenario.subject_id)
        policy_profile = load_decision_policy_profile(root_path, scenario.subject_id)
        latest_receipts = list_decision_analysis_receipts(root_path, scenario.subject_id)
        latest_receipt_id = collapse_ws(str(frame.metadata.get("latest_analysis_receipt_id", "")))
        latest_receipt = (
            next(
                (
                    receipt
                    for receipt in reversed(latest_receipts)
                    if collapse_ws(getattr(receipt, "receipt_id", "")) == latest_receipt_id
                ),
                None,
            )
            if latest_receipt_id
            else None
        )
        return {
            "exists": bool(collapse_ws(frame.decision_frame_id)),
            "frame": frame,
            "policy_profile": policy_profile,
            "item_count": len(items),
            "included_item_count": sum(1 for item in items if item.included and collapse_ws(item.status) != "rejected"),
            "recommendation_status": collapse_ws(str(frame.metadata.get("recommendation_status", ""))) or "pending",
            "blocking_conditions": tuple(str(item) for item in frame.metadata.get("blocking_conditions", ())),
            "policy_profile_kind": collapse_ws(getattr(policy_profile, "profile_kind", "")) or "",
            "latest_receipt": latest_receipt,
        }

    return _subject_workflow_cached_read(("_decision_review_state", root_path, scenario), _load)


def _dst_decision_analysis_refresh_required(
    root_path: Path,
    scenario: SubjectScenario,
    frame: DecisionFrame | None,
) -> bool:
    dst_fixture = _dst_fixture_for_subject(root_path, scenario)
    if dst_fixture is None:
        return False
    if not isinstance(frame, DecisionFrame) or not collapse_ws(frame.decision_frame_id):
        return False
    if not bool(frame.metadata.get("dst_seeded")):
        return True
    fixture_id = collapse_ws(str(frame.metadata.get("dst_fixture_id", "")))
    if fixture_id != collapse_ws(dst_fixture.fixture_id):
        return True
    source_ref = (
        collapse_ws(str(frame.metadata.get("dst_source_ref", "")))
        or collapse_ws(str(frame.metadata.get("source_ref", "")))
    )
    return source_ref != collapse_ws(dst_fixture.source_ref)


def _decision_review_item_for_review_item(
    decision_items: tuple[DecisionReviewItem, ...],
    review_item: ReviewItem,
) -> DecisionReviewItem | None:
    review_item_id = collapse_ws(getattr(review_item, "review_item_id", ""))
    if not review_item_id:
        return None
    return next(
        (
            item
            for item in decision_items
            if collapse_ws(item.review_item_id) == review_item_id
            and collapse_ws(item.status) != "rejected"
        ),
        None,
    )


def _draft_decision_selection_mode(
    root_path: Path,
    scenario: SubjectScenario,
    frame: DecisionFrame | None,
) -> str:
    if _dst_fixture_for_subject(root_path, scenario) is not None:
        return _DECISION_SELECTION_MODE_EXPLICIT
    if not isinstance(frame, DecisionFrame) or not collapse_ws(frame.decision_frame_id):
        return _DECISION_SELECTION_MODE_IMPLICIT_ALL
    normalized = collapse_ws(str(frame.metadata.get(_DECISION_SELECTION_MODE_METADATA_KEY, "")))
    return normalized or _DECISION_SELECTION_MODE_EXPLICIT


def _draft_uses_implicit_decision_selection(
    root_path: Path,
    scenario: SubjectScenario,
    frame: DecisionFrame | None,
) -> bool:
    return _draft_decision_selection_mode(root_path, scenario, frame) == _DECISION_SELECTION_MODE_IMPLICIT_ALL


def _frame_with_draft_decision_selection_mode(
    frame: DecisionFrame,
    *,
    mode: str,
    build_epoch_ms: int,
) -> DecisionFrame:
    metadata = dict(frame.metadata)
    metadata[_DECISION_SELECTION_MODE_METADATA_KEY] = mode
    return replace(
        frame,
        metadata=metadata,
        updated_at_epoch_ms=build_epoch_ms,
    )


def _materialize_implicit_draft_decision_items(
    review_items: tuple[ReviewItem, ...],
    *,
    frame: DecisionFrame,
    existing_items: tuple[DecisionReviewItem, ...] = (),
    build_epoch_ms: int,
) -> tuple[DecisionReviewItem, ...]:
    existing_by_review_item_id = {
        collapse_ws(item.review_item_id): item
        for item in existing_items
        if collapse_ws(item.review_item_id) and collapse_ws(item.status) != "rejected"
    }
    materialized: list[DecisionReviewItem] = []
    ordering = 1
    for review_item, _depth in flatten_review_item_tree(review_items):
        if collapse_ws(review_item.status) == "rejected" or not bool(review_item.included):
            continue
        existing = existing_by_review_item_id.get(collapse_ws(review_item.review_item_id))
        materialized_item = decision_review_item_from_review_item(
            review_item,
            decision_frame_id=frame.decision_frame_id,
            decision_role=(existing.decision_role if existing is not None else ""),
            ordering=(existing.ordering if existing is not None else ordering),
            build_epoch_ms=build_epoch_ms,
            existing=existing,
        )
        materialized.append(
            replace(
                materialized_item,
                included=True,
                status="active",
                updated_at_epoch_ms=max(0, int(build_epoch_ms or 0)),
            )
        )
        ordering += 1
    return tuple(sorted(materialized, key=lambda item: (int(item.ordering or 0), item.decision_review_item_id)))


def _draft_review_item_effectively_included_in_decision(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    review_item: ReviewItem,
    decision_items: tuple[DecisionReviewItem, ...],
    frame: DecisionFrame | None,
) -> bool:
    selected_decision_item = _decision_review_item_for_review_item(decision_items, review_item)
    if selected_decision_item is not None:
        return bool(selected_decision_item.included) and collapse_ws(selected_decision_item.status) != "rejected"
    return (
        _draft_uses_implicit_decision_selection(root_path, scenario, frame)
        and bool(review_item.included)
        and collapse_ws(review_item.status) != "rejected"
    )


def _draft_effective_decision_included_review_item_ids(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    review_items: tuple[ReviewItem, ...],
    decision_items: tuple[DecisionReviewItem, ...],
    frame: DecisionFrame | None,
) -> tuple[str, ...]:
    return tuple(
        collapse_ws(review_item.review_item_id)
        for review_item, _depth in flatten_review_item_tree(review_items)
        if _draft_review_item_effectively_included_in_decision(
            root_path,
            scenario=scenario,
            review_item=review_item,
            decision_items=decision_items,
            frame=frame,
        )
        and collapse_ws(review_item.review_item_id)
    )


def _sync_implicit_draft_decision_items_after_review_refresh(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    review_items: tuple[ReviewItem, ...],
    build_epoch_ms: int,
) -> None:
    frame = load_decision_frame(root_path, scenario.subject_id)
    if not collapse_ws(frame.decision_frame_id):
        return
    if not _draft_uses_implicit_decision_selection(root_path, scenario, frame):
        return
    decision_items = list_decision_review_items(root_path, scenario.subject_id)
    normalized_frame = _frame_with_draft_decision_selection_mode(
        _clear_decision_analysis_metadata(frame, build_epoch_ms=build_epoch_ms),
        mode=_DECISION_SELECTION_MODE_IMPLICIT_ALL,
        build_epoch_ms=build_epoch_ms,
    )
    persist_decision_review(
        root_path,
        normalized_frame,
        _materialize_implicit_draft_decision_items(
            review_items,
            frame=normalized_frame,
            existing_items=decision_items,
            build_epoch_ms=build_epoch_ms,
        ),
    )


def _clear_decision_analysis_metadata(frame: DecisionFrame, *, build_epoch_ms: int) -> DecisionFrame:
    metadata = dict(frame.metadata)
    for key in (
        "recommendation_status",
        "blocking_conditions",
        "latest_analysis_receipt_id",
        "recommended_option_ids",
    ):
        metadata.pop(key, None)
    return replace(
        frame,
        metadata=metadata,
        updated_at_epoch_ms=build_epoch_ms,
    )


def _draft_review_split_labels(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    item: ReviewItem,
) -> tuple[str, ...]:
    source_item_id = collapse_ws(item.source_itemized_item_id)
    if source_item_id:
        _session, itemized_items = _itemization_session_and_items(root_path, scenario)
        source_item = next(
            (
                candidate
                for candidate in itemized_items
                if collapse_ws(candidate.itemized_item_id) == source_item_id
            ),
            None,
        )
        if source_item is not None:
            labels = _itemize_split_labels(source_item)
            if len(labels) >= 2:
                return labels
    return review_item_split_labels(item)


def _decision_frame_question_from_review_item(item: ReviewItem) -> str:
    label = collapse_ws(str(item.metadata.get("canonical_label", ""))) or item.review_item_id
    summary = collapse_ws(item.notes)
    if summary:
        return f"What decision should the report support for '{label}' given: {summary}?"
    return f"What decision should the report support for '{label}'?"


def _decision_frame_question_from_subject(scenario: SubjectScenario) -> str:
    subject_label = collapse_ws(scenario.title) or collapse_ws(scenario.family_title) or scenario.subject_id
    return f"What decision should the report support for '{subject_label}'?"


def _selected_draft_review_item(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> tuple[ReviewItem | None, str]:
    items = _draft_review_items(root_path, scenario=scenario)
    if not items:
        return None, ""
    explicit_selected_id = collapse_ws(progress.draft_selected_review_item_id)
    if explicit_selected_id:
        explicit_selected_item = review_item_by_id(items, explicit_selected_id)
        if explicit_selected_item is not None and collapse_ws(explicit_selected_item.status) != "rejected":
            return explicit_selected_item, "draft_selection"
    by_source_item_id = {
        collapse_ws(item.source_itemized_item_id): item
        for item in items
        if collapse_ws(item.source_itemized_item_id)
    }
    selected_itemized_item_id = collapse_ws(progress.itemize_selected_item_id)
    if selected_itemized_item_id and selected_itemized_item_id in by_source_item_id:
        return by_source_item_id[selected_itemized_item_id], "itemize_selection"
    if _composition_current(scenario):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        selected_entry = _selected_report_scope_entry(
            _report_scope_entries(root_path, scenario=scenario, progress=progress),
            progress,
        )
        if selected_entry is not None and collapse_ws(selected_entry.item_kind) == "unit":
            target_unit_id = _report_scope_entry_target_id(selected_entry.entry_id)
            matching_items = tuple(
                item for item in items if collapse_ws(item.source_unit_id) == collapse_ws(target_unit_id)
            )
            if matching_items:
                return sorted(
                    matching_items,
                    key=lambda item: (not item.included, item.ordering, item.review_item_id),
                )[0], "report_scope_unit"
    return sorted(items, key=lambda item: (not item.included, item.ordering, item.review_item_id))[0], "default_first_active"


def _set_itemize_selection_to_item_id(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    itemized_item_id: str,
) -> None:
    selected_item_id = collapse_ws(itemized_item_id)
    progress.itemize_selected_item_id = selected_item_id
    _session, items = _itemization_session_and_items(root_path, scenario)
    if not selected_item_id or not items:
        return
    for index, item in enumerate(items):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        if collapse_ws(item.itemized_item_id) == selected_item_id:
            progress.itemize_cursor = index
            return


def _set_draft_selection_to_review_item_id(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    review_item_id: str,
) -> None:
    selected_review_item_id = collapse_ws(review_item_id)
    progress.draft_selected_review_item_id = selected_review_item_id
    if not selected_review_item_id:
        return
    selected_item = review_item_by_id(_draft_review_items(root_path, scenario=scenario), selected_review_item_id)
    if selected_item is not None and collapse_ws(selected_item.source_itemized_item_id):
        _set_itemize_selection_to_item_id(
            root_path,
            scenario=scenario,
            progress=progress,
            itemized_item_id=selected_item.source_itemized_item_id,
        )


def _draft_focus_mode(progress: SubjectProgress) -> str:
    normalized = collapse_ws(progress.draft_focus_mode).casefold()
    return normalized if normalized in _DRAFT_FOCUS_MODES else "compose"


def _draft_model_lens(progress: SubjectProgress) -> str:
    normalized = collapse_ws(progress.draft_model_lens).casefold()
    return normalized if normalized in _DRAFT_MODEL_LENSES else "model"


def _draft_model_lens_label(lens: str) -> str:
    return _DRAFT_MODEL_LENS_LABELS.get(collapse_ws(lens).casefold(), "Model")


def _draft_model_lens_title(lens: str) -> str:
    return _DRAFT_MODEL_LENS_TITLES.get(collapse_ws(lens).casefold(), "Transformation Model")


def _subject_transformation_construct_candidates(
    root_path: Path,
    scenario: SubjectScenario,
    *,
    include_rejected: bool = True,
) -> tuple[TransformationConstructCandidate, ...]:
    def _load() -> tuple[TransformationConstructCandidate, ...]:
        if scenario.is_placeholder or not collapse_ws(scenario.subject_id):
            return ()
        candidates = list_transformation_construct_candidates(root_path, scenario.subject_id)
        if not include_rejected:
            candidates = tuple(
                candidate
                for candidate in candidates
                if collapse_ws(candidate.status) != "rejected"
            )
        return tuple(
            sorted(
                candidates,
                key=lambda candidate: (
                    candidate.sort_kind,
                    candidate.canonical_label.casefold(),
                    candidate.construct_candidate_id,
                ),
            )
        )

    return _subject_workflow_cached_read(
        ("_subject_transformation_construct_candidates", root_path, scenario, include_rejected),
        _load,
    )


def _construct_candidates_for_itemized_item(
    root_path: Path,
    scenario: SubjectScenario,
    *,
    itemized_item_id: str,
    include_rejected: bool = True,
) -> tuple[TransformationConstructCandidate, ...]:
    selected_item_id = collapse_ws(itemized_item_id)
    if not selected_item_id:
        return ()
    return tuple(
        candidate
        for candidate in _subject_transformation_construct_candidates(
            root_path,
            scenario,
            include_rejected=include_rejected,
        )
        if collapse_ws(candidate.itemized_item_id) == selected_item_id
    )


def _set_draft_selection_to_construct_candidate_id(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    construct_candidate_id: str,
) -> None:
    selected_candidate_id = collapse_ws(construct_candidate_id)
    progress.draft_selected_construct_candidate_id = selected_candidate_id
    candidates = _subject_transformation_construct_candidates(root_path, scenario, include_rejected=True)
    if not selected_candidate_id or not candidates:
        return
    for index, candidate in enumerate(candidates):
        if collapse_ws(candidate.construct_candidate_id) != selected_candidate_id:
            continue
        progress.draft_model_cursor = index
        if collapse_ws(candidate.itemized_item_id):
            _set_itemize_selection_to_item_id(
                root_path,
                scenario=scenario,
                progress=progress,
                itemized_item_id=candidate.itemized_item_id,
            )
        if collapse_ws(candidate.review_item_id):
            progress.draft_selected_review_item_id = collapse_ws(candidate.review_item_id)
        else:
            selected_review_item = next(
                (
                    item
                    for item in _draft_review_items(root_path, scenario=scenario)
                    if collapse_ws(item.source_itemized_item_id) == collapse_ws(candidate.itemized_item_id)
                ),
                None,
            )
            if selected_review_item is not None:
                progress.draft_selected_review_item_id = collapse_ws(selected_review_item.review_item_id)
        return


def _selected_transformation_construct_candidate(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    include_rejected: bool = False,
) -> TransformationConstructCandidate | None:
    candidates = _subject_transformation_construct_candidates(
        root_path,
        scenario,
        include_rejected=include_rejected,
    )
    if not candidates:
        return None
    selected_candidate_id = collapse_ws(progress.draft_selected_construct_candidate_id)
    if selected_candidate_id:
        for candidate in candidates:
            if collapse_ws(candidate.construct_candidate_id) == selected_candidate_id:
                return candidate
    selected_index = max(0, min(int(progress.draft_model_cursor or 0), len(candidates) - 1))
    selected_candidate = candidates[selected_index]
    _set_draft_selection_to_construct_candidate_id(
        root_path,
        scenario=scenario,
        progress=progress,
        construct_candidate_id=selected_candidate.construct_candidate_id,
    )
    return selected_candidate


def _construct_candidate_detail_label(candidate: TransformationConstructCandidate) -> str:
    return collapse_ws(candidate.canonical_label) or candidate.construct_candidate_id


def _count_construct_candidates_by_sort(
    candidates: tuple[TransformationConstructCandidate, ...],
    *sort_kinds: str,
) -> int:
    normalized_kinds = {collapse_ws(kind).casefold() for kind in sort_kinds if collapse_ws(kind)}
    return sum(
        1
        for candidate in candidates
        if collapse_ws(candidate.sort_kind).casefold() in normalized_kinds
    )


def _construct_candidate_labels_for_sorts(
    candidates: tuple[TransformationConstructCandidate, ...],
    *sort_kinds: str,
    limit: int = 4,
) -> str:
    normalized_kinds = {collapse_ws(kind).casefold() for kind in sort_kinds if collapse_ws(kind)}
    labels = [
        _construct_candidate_detail_label(candidate)
        for candidate in candidates
        if collapse_ws(candidate.sort_kind).casefold() in normalized_kinds
    ]
    visible_labels = [label for label in labels if collapse_ws(label)]
    if not visible_labels:
        return "<none>"
    if len(visible_labels) <= limit:
        return ", ".join(visible_labels)
    return f"{', '.join(visible_labels[:limit])}, +{len(visible_labels) - limit} more"


def _draft_model_lens_summary_lines(
    lens: str,
    *,
    construct_candidates: tuple[TransformationConstructCandidate, ...],
    decision_frame: DecisionFrame | None,
    latest_decision_receipt: Any | None,
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[str, ...]:
    normalized_lens = collapse_ws(lens).casefold()
    if normalized_lens == "frame":
        return (
            "Lens: Frame",
            "- purpose: define what case this is before exploring alternatives",
            f"- actors: {_count_construct_candidates_by_sort(construct_candidates, 'actor')}",
            f"- objectives: {_count_construct_candidates_by_sort(construct_candidates, 'objective')}",
            f"- boundaries: {_count_construct_candidates_by_sort(construct_candidates, 'boundary')}",
            f"- states: {_count_construct_candidates_by_sort(construct_candidates, 'state')}",
            f"- accepted into frame: {sum(1 for candidate in construct_candidates if collapse_ws(candidate.status) == 'accepted')}",
            (
                f"- current frame states: {len(decision_frame.current_state_ids)} current / {len(decision_frame.target_state_ids)} target"
                if isinstance(decision_frame, DecisionFrame)
                else "- current frame states: <none>"
            ),
        )
    if normalized_lens == "explore":
        recommended_option_ids = (
            tuple(str(item) for item in latest_decision_receipt.metadata.get("recommended_option_ids", ()))
            if latest_decision_receipt is not None
            else ()
        )
        candidate_path_signatures = (
            tuple(str(item) for item in latest_decision_receipt.metadata.get("candidate_path_signatures", ()))
            if latest_decision_receipt is not None
            else ()
        )
        return (
            "Lens: Explore",
            "- purpose: inspect admissible paths, blockers, and recommendation status",
            (
                f"- decision frame: {decision_frame.decision_frame_id}"
                if isinstance(decision_frame, DecisionFrame)
                else "- decision frame: <none>"
            ),
            (
                f"- recommendation status: {collapse_ws(str(latest_decision_receipt.recommendation_status)) or 'pending'}"
                if latest_decision_receipt is not None
                else "- recommendation status: pending"
            ),
            (
                f"- admissible transitions: {len(getattr(latest_decision_receipt, 'admissible_transition_ids', ()))}"
                if latest_decision_receipt is not None
                else "- admissible transitions: 0"
            ),
            (
                f"- valid decisions: {len(getattr(latest_decision_receipt, 'valid_decision_ids', ()))}"
                if latest_decision_receipt is not None
                else "- valid decisions: 0"
            ),
            (
                f"- executable decisions: {len(getattr(latest_decision_receipt, 'executable_decision_ids', ()))}"
                if latest_decision_receipt is not None
                else "- executable decisions: 0"
            ),
            (
                f"- evaluated paths: {len(candidate_path_signatures)}"
                if latest_decision_receipt is not None
                else "- evaluated paths: 0"
            ),
            (
                f"- recommended options: {', '.join(recommended_option_ids[:3])}"
                if recommended_option_ids
                else "- recommended options: <none>"
            ),
        )
    return (
        "Lens: Model",
        "- purpose: structure the case into explicit constructs and relations",
        f"- capabilities: {_count_construct_candidates_by_sort(construct_candidates, 'capability')}",
        f"- dependencies: {_count_construct_candidates_by_sort(construct_candidates, 'dependency')}",
        f"- constraints: {_count_construct_candidates_by_sort(construct_candidates, 'constraint')}",
        f"- transitions: {_count_construct_candidates_by_sort(construct_candidates, 'transition')}",
        f"- decisions: {_count_construct_candidates_by_sort(construct_candidates, 'decision')}",
        f"- accepted decision items: {sum(1 for item in decision_items if collapse_ws(item.status) != 'rejected')}",
    )


def _draft_model_missing_relation_line(
    missing_relation: tuple[str, DecisionReviewItem, DecisionReviewItem | None] | None,
) -> str:
    return f"- next missing relation: {_draft_model_missing_relation_value(missing_relation)}"


def _draft_model_missing_relation_value(
    missing_relation: tuple[str, DecisionReviewItem, DecisionReviewItem | None] | None,
) -> str:
    if missing_relation is None:
        return "<none>"
    missing_kind, missing_item, _related_item = missing_relation
    missing_descriptions = {
        "transition_source": "source state",
        "transition_target": "target state",
        "transition_changed_capability": "changed capability",
        "decision_transition": "selected transition",
        "decision_transition_changed_capability": "transition capability",
        "decision_assigned_actor": "assigned actor",
    }
    return (
        f"{_decision_item_display_label(missing_item)} -> "
        f"{missing_descriptions.get(missing_kind, 'relation')}"
    )


def _draft_model_status_snapshot_lines(
    *,
    construct_candidates: tuple[TransformationConstructCandidate, ...],
    decision_frame: DecisionFrame | None,
    latest_decision_receipt: Any | None,
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[str, ...]:
    return tuple(
        f"- {label}: {value}"
        for label, value in _draft_model_status_snapshot_rows(
            construct_candidates=construct_candidates,
            decision_frame=decision_frame,
            latest_decision_receipt=latest_decision_receipt,
            decision_items=decision_items,
        )
    )


def _draft_model_status_snapshot_rows(
    *,
    construct_candidates: tuple[TransformationConstructCandidate, ...],
    decision_frame: DecisionFrame | None,
    latest_decision_receipt: Any | None,
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[tuple[str, str], ...]:
    recommended_option_ids = (
        tuple(str(item) for item in latest_decision_receipt.metadata.get("recommended_option_ids", ()))
        if latest_decision_receipt is not None
        else ()
    )
    candidate_path_signatures = (
        tuple(str(item) for item in latest_decision_receipt.metadata.get("candidate_path_signatures", ()))
        if latest_decision_receipt is not None
        else ()
    )
    blocking_conditions = (
        tuple(
            str(item)
            for item in getattr(latest_decision_receipt, "blocking_conditions", ())
            if collapse_ws(str(item))
        )
        if latest_decision_receipt is not None
        else ()
    )
    missing_relation = _first_missing_draft_model_relation(decision_items)
    return (
        (
            "accepted constructs",
            str(sum(1 for candidate in construct_candidates if collapse_ws(candidate.status) == "accepted")),
        ),
        (
            "included decision items",
            str(sum(1 for item in decision_items if item.included and collapse_ws(item.status) != "rejected")),
        ),
        (
            "recommendation status",
            (
                collapse_ws(str(latest_decision_receipt.recommendation_status)) or "pending"
                if latest_decision_receipt is not None
                else "pending"
            ),
        ),
        ("open issues", str(len(blocking_conditions) + (1 if missing_relation is not None else 0))),
        ("next missing relation", _draft_model_missing_relation_value(missing_relation)),
        ("blocking conditions", str(len(blocking_conditions))),
        (
            "current states",
            (
                f"{len(decision_frame.current_state_ids)} / target states: {len(decision_frame.target_state_ids)}"
                if isinstance(decision_frame, DecisionFrame)
                else "<none>"
            ),
        ),
        (
            "recommended options",
            ", ".join(recommended_option_ids[:3]) if recommended_option_ids else "<none>",
        ),
        ("evaluated paths", str(len(candidate_path_signatures))),
        (
            "latest receipt",
            str(latest_decision_receipt.receipt_id) if latest_decision_receipt is not None else "<none>",
        ),
    )


def _draft_model_selection_summary_lines(
    selected_candidate: TransformationConstructCandidate,
    *,
    lens: str,
    decision_item: DecisionReviewItem | None,
    decision_items: tuple[DecisionReviewItem, ...],
    decision_frame: DecisionFrame | None,
) -> tuple[str, ...]:
    lines = [
        f"- lens: {_draft_model_lens_label(lens)}",
        f"- selected object: {_construct_candidate_detail_label(selected_candidate)}",
        f"- type: {_format_orientation_label(selected_candidate.sort_kind)}",
        f"- status: {collapse_ws(selected_candidate.status) or '<none>'}",
        f"- confidence: {float(selected_candidate.confidence or 0.0):.2f}",
        f"- source item: {collapse_ws(selected_candidate.itemized_item_id) or '<none>'}",
        f"- linked draft item: {collapse_ws(selected_candidate.review_item_id) or '<none>'}",
        f"- source refs: {len(selected_candidate.source_refs)}",
        (
            f"- included as {_format_orientation_label(_current_construct_candidate_lane(selected_candidate, decision_item=decision_item, frame=decision_frame))}"
            if collapse_ws(selected_candidate.status) == "accepted" and decision_item is not None
            else "- included as: <not accepted>"
        ),
    ]
    if collapse_ws(selected_candidate.status) == "accepted":
        lines.extend(
            _selected_construct_relation_lines(
                selected_candidate,
                decision_item=decision_item,
                decision_items=decision_items,
                frame=decision_frame,
            )
        )
    return tuple(lines)


def _draft_model_governed_provenance_lines(frame: DecisionFrame | None) -> tuple[str, ...]:
    if not isinstance(frame, DecisionFrame) or not frame.metadata:
        return ()
    discovery_proposal_id = collapse_ws(str(frame.metadata.get("dst_discovery_proposal_id", "")))
    normalization_proposal_id = collapse_ws(str(frame.metadata.get("dst_normalization_proposal_id", "")))
    if not discovery_proposal_id and not normalization_proposal_id:
        return ()
    return (
        "Governed provenance",
        f"- discovery proposal: {discovery_proposal_id or '<none>'}",
        f"- normalization proposal: {normalization_proposal_id or '<none>'}",
    )


def move_draft_review_cursor(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    delta: int,
) -> ReviewItem | None:
    if _draft_focus_mode(progress) == "model":
        candidates = _subject_transformation_construct_candidates(
            root_path,
            scenario,
            include_rejected=False,
        )
        if not candidates:
            return None
        selected_candidate = _selected_transformation_construct_candidate(
            root_path,
            scenario=scenario,
            progress=progress,
            include_rejected=False,
        )
        if selected_candidate is None:
            selected_candidate = candidates[0]
        current_index = next(
            (
                index
                for index, candidate in enumerate(candidates)
                if collapse_ws(candidate.construct_candidate_id)
                == collapse_ws(selected_candidate.construct_candidate_id)
            ),
            0,
        )
        next_index = max(0, min(len(candidates) - 1, current_index + int(delta)))
        _set_draft_selection_to_construct_candidate_id(
            root_path,
            scenario=scenario,
            progress=progress,
            construct_candidate_id=candidates[next_index].construct_candidate_id,
        )
        selected_review_item, _selection_source = _selected_draft_review_item(
            root_path,
            scenario=scenario,
            progress=progress,
        )
        return selected_review_item
    rows = _flatten_draft_review_items(root_path, scenario=scenario)
    if not rows:
        return None
    selected_item, _selection_source = _selected_draft_review_item(
        root_path,
        scenario=scenario,
        progress=progress,
    )
    if selected_item is None:
        selected = rows[0][0]
        _set_draft_selection_to_review_item_id(
            root_path,
            scenario=scenario,
            progress=progress,
            review_item_id=selected.review_item_id,
        )
        return selected
    current_index = next(
        (
            index
            for index, (item, _depth) in enumerate(rows)
            if collapse_ws(item.review_item_id) == collapse_ws(selected_item.review_item_id)
        ),
        0,
    )
    next_index = max(0, min(len(rows) - 1, current_index + int(delta)))
    selected = rows[next_index][0]
    _set_draft_selection_to_review_item_id(
        root_path,
        scenario=scenario,
        progress=progress,
        review_item_id=selected.review_item_id,
    )
    return selected


def _construct_candidate_decision_role(
    candidate: TransformationConstructCandidate,
    *,
    frame: DecisionFrame | None = None,
) -> str:
    base_role = _TRANSFORMATION_CONSTRUCT_TO_DECISION_ROLE.get(
        normalize_transformation_construct_sort_kind(candidate.sort_kind),
        "supporting_evidence",
    )
    if base_role != "current_state":
        return base_role
    state_polarity = collapse_ws(str(candidate.relation_hints.get("state_polarity", ""))).casefold()
    if state_polarity == "target":
        return "target_state"
    if state_polarity == "current":
        return "current_state"
    if frame is not None and frame.current_state_ids and not frame.target_state_ids:
        return "target_state"
    return "current_state"


def _construct_candidate_lane_options(candidate: TransformationConstructCandidate) -> tuple[str, ...]:
    return _TRANSFORMATION_CONSTRUCT_LANES_BY_SORT.get(
        normalize_transformation_construct_sort_kind(candidate.sort_kind),
        ("supporting_evidence",),
    )


def _decision_review_item_for_construct_candidate(
    decision_items: tuple[DecisionReviewItem, ...],
    candidate: TransformationConstructCandidate,
    *,
    frame: DecisionFrame | None = None,
) -> DecisionReviewItem | None:
    candidate_id = collapse_ws(candidate.construct_candidate_id)
    if candidate_id:
        direct_match = next(
            (
                item
                for item in decision_items
                if collapse_ws(str(item.metadata.get("construct_candidate_id", ""))) == candidate_id
                and collapse_ws(item.status) != "rejected"
            ),
            None,
        )
    if direct_match is not None:
        return direct_match
    sort_kind = normalize_transformation_construct_sort_kind(candidate.sort_kind)
    candidate_hint_key = _CONSTRUCT_SORT_TO_NORMALIZED_HINT_KEY.get(sort_kind, "")
    decision_item_metadata_key = _CONSTRUCT_SORT_TO_DECISION_ITEM_METADATA_KEY.get(sort_kind, "")
    normalized_link_id = collapse_ws(str(candidate.relation_hints.get(candidate_hint_key, "")))
    if not normalized_link_id or not decision_item_metadata_key:
        return None
    allowed_roles = {
        normalize_decision_review_role(role)
        for role in _construct_candidate_lane_options(candidate)
        if collapse_ws(role)
    }
    preferred_role = _construct_candidate_decision_role(candidate, frame=frame)
    role_order = [preferred_role]
    for role in sorted(allowed_roles):
        if role not in role_order:
            role_order.append(role)
    for role in role_order:
        match = next(
            (
                item
                for item in decision_items
                if collapse_ws(item.status) != "rejected"
                and collapse_ws(item.decision_role) == role
                and collapse_ws(str(item.metadata.get(decision_item_metadata_key, ""))) == normalized_link_id
            ),
            None,
        )
        if match is not None:
            return match
    return next(
        (
            item
            for item in decision_items
            if collapse_ws(item.status) != "rejected"
            and collapse_ws(str(item.metadata.get(decision_item_metadata_key, ""))) == normalized_link_id
        ),
        None,
    )


def _construct_candidate_continuity_signature(
    candidate: TransformationConstructCandidate,
) -> tuple[str, ...]:
    sort_kind = normalize_transformation_construct_sort_kind(candidate.sort_kind)
    hint_key = _CONSTRUCT_SORT_TO_NORMALIZED_HINT_KEY.get(sort_kind, "")
    normalized_hint_id = collapse_ws(str(candidate.relation_hints.get(hint_key, "")))
    if hint_key and normalized_hint_id:
        return (sort_kind, hint_key, normalized_hint_id)
    normalized_itemized_item_id = collapse_ws(candidate.itemized_item_id)
    normalized_label = collapse_ws(candidate.canonical_label).casefold()
    if normalized_itemized_item_id and normalized_label:
        return (sort_kind, "itemized_item", normalized_itemized_item_id, normalized_label)
    if normalized_label:
        return (sort_kind, "label", normalized_label)
    return ()


def _construct_candidate_was_curated(candidate: TransformationConstructCandidate) -> bool:
    return bool(
        collapse_ws(candidate.review_item_id)
        or collapse_ws(candidate.notes)
        or collapse_ws(candidate.status) != "candidate"
    )


def _merge_transformation_construct_candidates(
    existing_candidates: tuple[TransformationConstructCandidate, ...],
    incoming_candidates: tuple[TransformationConstructCandidate, ...],
) -> tuple[TransformationConstructCandidate, ...]:
    merged_by_id: dict[str, TransformationConstructCandidate] = {
        collapse_ws(candidate.construct_candidate_id): candidate
        for candidate in existing_candidates
        if collapse_ws(candidate.construct_candidate_id)
    }
    existing_by_signature: dict[tuple[str, ...], TransformationConstructCandidate] = {
        signature: candidate
        for candidate in existing_candidates
        if (signature := _construct_candidate_continuity_signature(candidate))
    }
    for candidate in incoming_candidates:
        candidate_id = collapse_ws(candidate.construct_candidate_id)
        if not candidate_id:
            continue
        existing = merged_by_id.get(candidate_id)
        if existing is None:
            signature = _construct_candidate_continuity_signature(candidate)
            if signature:
                existing = existing_by_signature.get(signature)
        if existing is None:
            merged_by_id[candidate_id] = candidate
            continue
        merged_relation_hints = {
            **dict(candidate.relation_hints),
            **dict(existing.relation_hints),
        }
        preserve_curated_text = _construct_candidate_was_curated(existing)
        if preserve_curated_text:
            if collapse_ws(candidate.canonical_label) and collapse_ws(candidate.canonical_label) != collapse_ws(existing.canonical_label):
                merged_relation_hints["latest_generated_canonical_label"] = candidate.canonical_label
            if collapse_ws(candidate.summary) and collapse_ws(candidate.summary) != collapse_ws(existing.summary):
                merged_relation_hints["latest_generated_summary"] = candidate.summary
        merged_candidate = replace(
            candidate,
            construct_candidate_id=collapse_ws(existing.construct_candidate_id) or candidate.construct_candidate_id,
            review_item_id=collapse_ws(existing.review_item_id) or candidate.review_item_id,
            status=collapse_ws(existing.status) or candidate.status,
            canonical_label=existing.canonical_label if preserve_curated_text else candidate.canonical_label,
            summary=existing.summary if preserve_curated_text else candidate.summary,
            notes=existing.notes or candidate.notes,
            relation_hints=merged_relation_hints,
            source_refs=_ordered_unique_texts((*candidate.source_refs, *existing.source_refs)),
            created_at_epoch_ms=existing.created_at_epoch_ms or candidate.created_at_epoch_ms,
        )
        merged_by_id[collapse_ws(merged_candidate.construct_candidate_id)] = merged_candidate
    return tuple(
        sorted(
            merged_by_id.values(),
            key=lambda candidate: (
                candidate.sort_kind,
                candidate.canonical_label.casefold(),
                candidate.construct_candidate_id,
            ),
        )
    )


def _decision_review_item_continuity_signature(item: DecisionReviewItem) -> tuple[str, ...]:
    metadata = dict(item.metadata)
    normalized_role = normalize_decision_review_role(item.decision_role)
    for key in _DECISION_ITEM_CONTINUITY_METADATA_KEYS:
        value = collapse_ws(str(metadata.get(key, "")))
        if value:
            return (normalized_role, key, value)
    canonical_label = collapse_ws(str(metadata.get("canonical_label", ""))).casefold()
    if canonical_label:
        return (normalized_role, "label", canonical_label)
    return ()


def _merge_dst_decision_review_items(
    existing_items: tuple[DecisionReviewItem, ...],
    incoming_items: tuple[DecisionReviewItem, ...],
    *,
    build_epoch_ms: int,
) -> tuple[tuple[DecisionReviewItem, ...], dict[str, str]]:
    merged_items_by_id: dict[str, DecisionReviewItem] = {
        collapse_ws(item.decision_review_item_id): item
        for item in existing_items
        if collapse_ws(item.decision_review_item_id)
    }
    existing_by_signature: dict[tuple[str, ...], DecisionReviewItem] = {
        signature: item
        for item in existing_items
        if (signature := _decision_review_item_continuity_signature(item))
    }
    incoming_to_resolved_id: dict[str, str] = {}
    for item in incoming_items:
        incoming_id = collapse_ws(item.decision_review_item_id)
        if not incoming_id:
            continue
        existing = merged_items_by_id.get(incoming_id)
        if existing is None:
            signature = _decision_review_item_continuity_signature(item)
            if signature:
                existing = existing_by_signature.get(signature)
        if existing is None:
            merged_items_by_id[incoming_id] = item
            incoming_to_resolved_id[incoming_id] = incoming_id
            continue
        merged_metadata = {
            **dict(item.metadata),
        }
        for key in _CURATED_DECISION_ITEM_METADATA_KEYS:
            existing_value = existing.metadata.get(key)
            if existing_value not in (None, "", (), [], {}):
                merged_metadata[key] = existing_value
        if collapse_ws(str(item.metadata.get("canonical_label", ""))) and collapse_ws(str(item.metadata.get("canonical_label", ""))) != collapse_ws(str(existing.metadata.get("canonical_label", ""))):
            merged_metadata["latest_generated_canonical_label"] = item.metadata.get("canonical_label", "")
        merged_item = replace(
            item,
            decision_review_item_id=collapse_ws(existing.decision_review_item_id) or item.decision_review_item_id,
            review_item_id=collapse_ws(existing.review_item_id) or item.review_item_id,
            decision_role=normalize_decision_review_role(existing.decision_role or item.decision_role),
            included=existing.included,
            ordering=max(0, int(existing.ordering or item.ordering)),
            child_decision_review_item_ids=existing.child_decision_review_item_ids or item.child_decision_review_item_ids,
            source_refs=_ordered_unique_texts((*item.source_refs, *existing.source_refs)),
            confidence=item.confidence if float(item.confidence or 0.0) > 0.0 else existing.confidence,
            notes=item.notes,
            status=collapse_ws(existing.status) or item.status,
            created_at_epoch_ms=existing.created_at_epoch_ms or item.created_at_epoch_ms,
            updated_at_epoch_ms=max(0, int(build_epoch_ms or item.updated_at_epoch_ms or existing.updated_at_epoch_ms)),
            metadata=merged_metadata,
        )
        resolved_id = collapse_ws(merged_item.decision_review_item_id)
        merged_items_by_id[resolved_id] = merged_item
        incoming_to_resolved_id[incoming_id] = resolved_id
    ordered = tuple(
        sorted(
            merged_items_by_id.values(),
            key=lambda item: (int(item.ordering or 0), item.decision_review_item_id),
        )
    )
    return ordered, incoming_to_resolved_id


def _merge_dst_decision_frame(
    existing_frame: DecisionFrame | None,
    incoming_frame: DecisionFrame,
    *,
    incoming_to_resolved_item_id: Mapping[str, str],
    build_epoch_ms: int,
) -> DecisionFrame:
    def _remap_ids(item_ids: tuple[str, ...]) -> tuple[str, ...]:
        return _ordered_unique_texts(
            incoming_to_resolved_item_id.get(collapse_ws(item_id), collapse_ws(item_id))
            for item_id in item_ids
        )

    if existing_frame is None or not collapse_ws(existing_frame.decision_frame_id):
        return replace(
            incoming_frame,
            current_state_ids=_remap_ids(incoming_frame.current_state_ids),
            target_state_ids=_remap_ids(incoming_frame.target_state_ids),
            primary_objective_ids=_remap_ids(incoming_frame.primary_objective_ids),
            scope_boundary_ids=_remap_ids(incoming_frame.scope_boundary_ids),
        )
    merged_metadata = {
        **dict(incoming_frame.metadata),
        **dict(existing_frame.metadata),
    }
    return replace(
        incoming_frame,
        decision_frame_id=collapse_ws(existing_frame.decision_frame_id) or incoming_frame.decision_frame_id,
        publication_id=collapse_ws(existing_frame.publication_id) or incoming_frame.publication_id,
        question=incoming_frame.question or existing_frame.question,
        decision_mode=collapse_ws(existing_frame.decision_mode) or incoming_frame.decision_mode,
        current_state_ids=_remap_ids(incoming_frame.current_state_ids),
        target_state_ids=_remap_ids(incoming_frame.target_state_ids),
        primary_objective_ids=_remap_ids(incoming_frame.primary_objective_ids),
        scope_boundary_ids=_remap_ids(incoming_frame.scope_boundary_ids),
        status=collapse_ws(existing_frame.status) or incoming_frame.status,
        created_at_epoch_ms=existing_frame.created_at_epoch_ms or incoming_frame.created_at_epoch_ms,
        updated_at_epoch_ms=max(0, int(build_epoch_ms or incoming_frame.updated_at_epoch_ms or existing_frame.updated_at_epoch_ms)),
        metadata=merged_metadata,
    )


def _sync_construct_candidates_with_decision_items(
    construct_candidates: tuple[TransformationConstructCandidate, ...],
    decision_items: tuple[DecisionReviewItem, ...],
    *,
    frame: DecisionFrame | None = None,
    build_epoch_ms: int,
) -> tuple[tuple[TransformationConstructCandidate, ...], tuple[DecisionReviewItem, ...]]:
    matched_candidate_ids_by_item_id: dict[str, str] = {}
    updated_candidates: list[TransformationConstructCandidate] = []
    for candidate in construct_candidates:
        matched_item = _decision_review_item_for_construct_candidate(
            decision_items,
            candidate,
            frame=frame,
        )
        if matched_item is None:
            updated_candidates.append(candidate)
            continue
        matched_candidate_ids_by_item_id[
            collapse_ws(matched_item.decision_review_item_id)
        ] = collapse_ws(candidate.construct_candidate_id)
        updated_candidates.append(
            replace(
                candidate,
                review_item_id=collapse_ws(matched_item.review_item_id) or candidate.review_item_id,
                status="accepted",
                updated_at_epoch_ms=build_epoch_ms,
            )
        )
    updated_decision_items: list[DecisionReviewItem] = []
    for item in decision_items:
        candidate_id = matched_candidate_ids_by_item_id.get(collapse_ws(item.decision_review_item_id), "")
        if not candidate_id:
            updated_decision_items.append(item)
            continue
        metadata = dict(item.metadata)
        if collapse_ws(str(metadata.get("construct_candidate_id", ""))) == candidate_id:
            updated_decision_items.append(item)
            continue
        metadata["construct_candidate_id"] = candidate_id
        updated_decision_items.append(
            replace(
                item,
                metadata=metadata,
                updated_at_epoch_ms=build_epoch_ms,
            )
        )
    return tuple(updated_candidates), tuple(updated_decision_items)


def _current_construct_candidate_lane(
    candidate: TransformationConstructCandidate,
    *,
    decision_item: DecisionReviewItem | None = None,
    frame: DecisionFrame | None = None,
) -> str:
    if decision_item is not None and collapse_ws(decision_item.decision_role):
        return normalize_decision_review_role(decision_item.decision_role)
    return normalize_decision_review_role(
        _construct_candidate_decision_role(candidate, frame=frame)
    )


def subject_draft_model_construct_inventory(
    root_path: Path,
    *,
    scenario: SubjectScenario,
) -> tuple[tuple[TransformationConstructCandidate, str], ...]:
    """Return model candidates with their persisted decision lanes."""
    candidates = _subject_transformation_construct_candidates(
        root_path,
        scenario=scenario,
        include_rejected=False,
    )
    decision_items = list_decision_review_items(root_path, scenario.subject_id)
    frame = load_decision_frame(root_path, scenario.subject_id)
    projected: list[tuple[TransformationConstructCandidate, str]] = []
    for candidate in candidates:
        lane = ""
        if collapse_ws(candidate.status) == "accepted":
            decision_item = _decision_review_item_for_construct_candidate(
                decision_items,
                candidate,
                frame=frame,
            )
            if decision_item is not None:
                lane = _current_construct_candidate_lane(
                    candidate,
                    decision_item=decision_item,
                    frame=frame,
                )
        projected.append((candidate, lane))
    return tuple(projected)


def _next_construct_candidate_lane(
    candidate: TransformationConstructCandidate,
    *,
    current_lane: str,
) -> str:
    allowed = _construct_candidate_lane_options(candidate)
    if not allowed:
        return "supporting_evidence"
    normalized_current = normalize_decision_review_role(current_lane)
    try:
        current_index = allowed.index(normalized_current)
    except ValueError:
        return allowed[0]
    return allowed[(current_index + 1) % len(allowed)]


def _decision_item_display_label(item: DecisionReviewItem) -> str:
    return collapse_ws(str(item.metadata.get("canonical_label", ""))) or item.review_item_id


def _active_decision_review_items(
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[DecisionReviewItem, ...]:
    return tuple(
        item
        for item in decision_items
        if item.included and collapse_ws(item.status) != "rejected"
    )


def _state_decision_review_items(
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[DecisionReviewItem, ...]:
    return tuple(
        item
        for item in _active_decision_review_items(decision_items)
        if item.decision_role in {"current_state", "target_state"}
    )


def _transition_decision_review_items(
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[DecisionReviewItem, ...]:
    return tuple(
        item
        for item in _active_decision_review_items(decision_items)
        if item.decision_role == "transition_candidate"
    )


def _capability_decision_review_items(
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[DecisionReviewItem, ...]:
    return tuple(
        item
        for item in _active_decision_review_items(decision_items)
        if item.decision_role == "capability"
    )


def _dependency_decision_review_items(
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[DecisionReviewItem, ...]:
    return tuple(
        item
        for item in _active_decision_review_items(decision_items)
        if item.decision_role == "dependency"
    )


def _boundary_decision_review_items(
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[DecisionReviewItem, ...]:
    return tuple(
        item
        for item in _active_decision_review_items(decision_items)
        if item.decision_role == "boundary"
    )


def _actor_decision_review_items(
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[DecisionReviewItem, ...]:
    return tuple(
        item
        for item in _active_decision_review_items(decision_items)
        if item.decision_role == "actor"
    )


def _decision_item_by_id(
    decision_items: tuple[DecisionReviewItem, ...],
    decision_review_item_id: str,
) -> DecisionReviewItem | None:
    normalized_id = collapse_ws(decision_review_item_id)
    if not normalized_id:
        return None
    return next(
        (
            item
            for item in decision_items
            if collapse_ws(item.decision_review_item_id) == normalized_id
        ),
        None,
    )


def _metadata_decision_item_ids(
    metadata: dict[str, object],
    *,
    plural_key: str,
    singular_key: str,
) -> tuple[str, ...]:
    raw_value = metadata.get(plural_key)
    values: list[object] = []
    if isinstance(raw_value, (list, tuple, set)):
        values.extend(raw_value)
    elif raw_value is not None and collapse_ws(str(raw_value)):
        values.append(raw_value)
    singular_value = metadata.get(singular_key)
    if singular_value is not None and collapse_ws(str(singular_value)):
        values.append(singular_value)
    ordered_ids: list[str] = []
    seen: set[str] = set()
    for value in values:
        normalized = collapse_ws(str(value))
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        ordered_ids.append(normalized)
    return tuple(ordered_ids)


def _set_metadata_decision_item_ids(
    metadata: dict[str, object],
    *,
    plural_key: str,
    singular_key: str,
    decision_review_item_ids: tuple[str, ...],
) -> None:
    ordered_ids: list[str] = []
    seen: set[str] = set()
    for value in decision_review_item_ids:
        normalized = collapse_ws(str(value))
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        ordered_ids.append(normalized)
    if ordered_ids:
        metadata[plural_key] = list(ordered_ids)
        metadata[singular_key] = ordered_ids[0]
    else:
        metadata.pop(plural_key, None)
        metadata.pop(singular_key, None)


def _decision_items_by_ids(
    decision_items: tuple[DecisionReviewItem, ...],
    decision_review_item_ids: tuple[str, ...],
) -> tuple[DecisionReviewItem, ...]:
    resolved: list[DecisionReviewItem] = []
    seen: set[str] = set()
    for decision_review_item_id in decision_review_item_ids:
        item = _decision_item_by_id(decision_items, decision_review_item_id)
        if item is None:
            continue
        normalized_id = collapse_ws(item.decision_review_item_id)
        if normalized_id in seen:
            continue
        seen.add(normalized_id)
        resolved.append(item)
    return tuple(resolved)


def _dedupe_decision_items(
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[DecisionReviewItem, ...]:
    resolved: list[DecisionReviewItem] = []
    seen: set[str] = set()
    for item in decision_items:
        normalized_id = collapse_ws(item.decision_review_item_id)
        if not normalized_id or normalized_id in seen:
            continue
        seen.add(normalized_id)
        resolved.append(item)
    return tuple(resolved)


def _relation_labels(items: tuple[DecisionReviewItem, ...]) -> str:
    if not items:
        return "<none>"
    return ", ".join(_decision_item_display_label(item) for item in items)


def _next_relation_binding_id(
    current_id: str,
    candidates: tuple[DecisionReviewItem, ...],
) -> str:
    if not candidates:
        return ""
    normalized_current = collapse_ws(current_id)
    ordered_ids = [collapse_ws(item.decision_review_item_id) for item in candidates if collapse_ws(item.decision_review_item_id)]
    if not ordered_ids:
        return ""
    if normalized_current not in ordered_ids:
        return ordered_ids[0]
    current_index = ordered_ids.index(normalized_current)
    return ordered_ids[(current_index + 1) % len(ordered_ids)]


def _next_unbound_relation_binding_id(
    current_ids: tuple[str, ...],
    candidates: tuple[DecisionReviewItem, ...],
) -> str:
    bound_ids = {collapse_ws(item_id) for item_id in current_ids if collapse_ws(item_id)}
    for candidate in candidates:
        candidate_id = collapse_ws(candidate.decision_review_item_id)
        if candidate_id and candidate_id not in bound_ids:
            return candidate_id
    return ""


def _drop_last_relation_binding_id(current_ids: tuple[str, ...]) -> tuple[str, ...]:
    ordered_ids = [collapse_ws(item_id) for item_id in current_ids if collapse_ws(item_id)]
    if not ordered_ids:
        return ()
    return tuple(ordered_ids[:-1])


def _decision_frame_with_synced_decision_item_lanes(
    frame: DecisionFrame,
    decision_items: tuple[DecisionReviewItem, ...],
    *,
    build_epoch_ms: int,
) -> DecisionFrame:
    active_items = _active_decision_review_items(decision_items)
    return replace(
        frame,
        current_state_ids=tuple(
            item.decision_review_item_id
            for item in active_items
            if item.decision_role == "current_state"
        ),
        target_state_ids=tuple(
            item.decision_review_item_id
            for item in active_items
            if item.decision_role == "target_state"
        ),
        primary_objective_ids=tuple(
            item.decision_review_item_id
            for item in active_items
            if item.decision_role == "objective"
        ),
        scope_boundary_ids=tuple(
            item.decision_review_item_id
            for item in active_items
            if item.decision_role == "boundary"
        ),
        updated_at_epoch_ms=build_epoch_ms,
    )


def _decision_review_item_from_construct_candidate(
    candidate: TransformationConstructCandidate,
    *,
    decision_frame_id: str,
    build_epoch_ms: int,
    ordering: int,
    existing: DecisionReviewItem | None = None,
    decision_role: str = "",
) -> DecisionReviewItem:
    normalized_role = normalize_decision_review_role(
        decision_role or _construct_candidate_decision_role(candidate)
    )
    review_item_id = (
        collapse_ws(candidate.review_item_id)
        or f"construct:{collapse_ws(candidate.construct_candidate_id)}"
    )
    return DecisionReviewItem(
        decision_review_item_id=stable_decision_review_item_id(
            decision_frame_id=decision_frame_id,
            review_item_id=review_item_id,
            decision_role=normalized_role,
        ),
        review_item_id=review_item_id,
        decision_frame_id=decision_frame_id,
        decision_role=normalized_role,
        included=True,
        ordering=(existing.ordering if existing is not None else ordering),
        child_decision_review_item_ids=(
            existing.child_decision_review_item_ids if existing is not None else ()
        ),
        source_refs=tuple(candidate.source_refs),
        confidence=float(candidate.confidence or 0.0),
        notes=candidate.summary or candidate.notes,
        status="active",
        created_at_epoch_ms=(existing.created_at_epoch_ms if existing is not None else build_epoch_ms),
        updated_at_epoch_ms=build_epoch_ms,
        metadata={
            **(dict(existing.metadata) if existing is not None else {}),
            "canonical_label": candidate.canonical_label,
            "construct_candidate_id": candidate.construct_candidate_id,
            "source_itemized_item_id": candidate.itemized_item_id,
            "source_review_item_id": collapse_ws(candidate.review_item_id),
            "sort_kind": candidate.sort_kind,
            "relation_hints": dict(candidate.relation_hints),
        },
    )


def _decision_frame_with_construct_candidate(
    frame: DecisionFrame,
    candidate: TransformationConstructCandidate,
    *,
    decision_review_item_id: str,
    build_epoch_ms: int,
) -> DecisionFrame:
    decision_role = _construct_candidate_decision_role(candidate, frame=frame)
    if decision_role == "current_state" and decision_review_item_id not in frame.current_state_ids:
        return replace(
            frame,
            current_state_ids=(*tuple(frame.current_state_ids), decision_review_item_id),
            updated_at_epoch_ms=build_epoch_ms,
        )
    if decision_role == "target_state" and decision_review_item_id not in frame.target_state_ids:
        return replace(
            frame,
            target_state_ids=(*tuple(frame.target_state_ids), decision_review_item_id),
            updated_at_epoch_ms=build_epoch_ms,
        )
    if decision_role == "objective" and decision_review_item_id not in frame.primary_objective_ids:
        return replace(
            frame,
            primary_objective_ids=(*tuple(frame.primary_objective_ids), decision_review_item_id),
            updated_at_epoch_ms=build_epoch_ms,
        )
    if decision_role == "boundary" and decision_review_item_id not in frame.scope_boundary_ids:
        return replace(
            frame,
            scope_boundary_ids=(*tuple(frame.scope_boundary_ids), decision_review_item_id),
            updated_at_epoch_ms=build_epoch_ms,
        )
    return replace(frame, updated_at_epoch_ms=build_epoch_ms)


def _selected_construct_relation_lines(
    selected_candidate: TransformationConstructCandidate,
    *,
    decision_item: DecisionReviewItem | None,
    decision_items: tuple[DecisionReviewItem, ...],
    frame: DecisionFrame | None = None,
) -> tuple[str, ...]:
    return tuple(
        f"- {label}: {value}"
        for label, value in _selected_construct_relation_rows(
            selected_candidate,
            decision_item=decision_item,
            decision_items=decision_items,
            frame=frame,
        )
    )


def _selected_construct_relation_rows(
    selected_candidate: TransformationConstructCandidate,
    *,
    decision_item: DecisionReviewItem | None,
    decision_items: tuple[DecisionReviewItem, ...],
    frame: DecisionFrame | None = None,
) -> tuple[tuple[str, str], ...]:
    selected_lane = _current_construct_candidate_lane(
        selected_candidate,
        decision_item=decision_item,
        frame=frame,
    )
    rows = [("lane", _format_orientation_label(selected_lane))]
    if decision_item is None:
        return tuple(rows)
    metadata = dict(decision_item.metadata)
    if selected_lane == "transition_candidate":
        source_item = _decision_item_by_id(
            decision_items,
            str(metadata.get(_TRANSITION_SOURCE_DECISION_ITEM_ID_KEY, "")),
        )
        target_item = _decision_item_by_id(
            decision_items,
            str(metadata.get(_TRANSITION_TARGET_DECISION_ITEM_ID_KEY, "")),
        )
        rows.extend(
            [
                (
                    "source state",
                    _decision_item_display_label(source_item) if source_item is not None else "<none>",
                ),
                (
                    "target state",
                    _decision_item_display_label(target_item) if target_item is not None else "<none>",
                ),
            ]
        )
        changed_capability_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                metadata,
                plural_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_IDS_KEY,
                singular_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_ID_KEY,
            ),
        )
        rows.append(
            (
                f"changed capabilities ({len(changed_capability_items)})",
                _relation_labels(changed_capability_items),
            )
        )
    elif selected_lane == "capability":
        required_dependency_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                metadata,
                plural_key=_CAPABILITY_REQUIRED_DEPENDENCY_DECISION_ITEM_IDS_KEY,
                singular_key=_CAPABILITY_REQUIRED_DEPENDENCY_DECISION_ITEM_ID_KEY,
            ),
        )
        crossed_boundary_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                metadata,
                plural_key=_CAPABILITY_CROSSED_BOUNDARY_DECISION_ITEM_IDS_KEY,
                singular_key=_CAPABILITY_CROSSED_BOUNDARY_DECISION_ITEM_ID_KEY,
            ),
        )
        rows.append(
            (
                f"required dependencies ({len(required_dependency_items)})",
                _relation_labels(required_dependency_items),
            )
        )
        rows.append(
            (
                f"crossed boundaries ({len(crossed_boundary_items)})",
                _relation_labels(crossed_boundary_items),
            )
        )
    elif selected_lane == "decision_candidate":
        selected_transition_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                metadata,
                plural_key=_DECISION_SELECTED_TRANSITION_ITEM_IDS_KEY,
                singular_key=_DECISION_SELECTED_TRANSITION_ITEM_ID_KEY,
            ),
        )
        rows.append(
            (
                f"selected transitions ({len(selected_transition_items)})",
                _relation_labels(selected_transition_items),
            )
        )
        changed_capability_items = _dedupe_decision_items(
            tuple(
                changed_capability_item
                for transition_item in selected_transition_items
                for changed_capability_item in _decision_items_by_ids(
                    decision_items,
                    _metadata_decision_item_ids(
                        dict(transition_item.metadata),
                        plural_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_IDS_KEY,
                        singular_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_ID_KEY,
                    ),
                )
            )
        )
        rows.append(
            (
                f"transition capabilities ({len(changed_capability_items)})",
                _relation_labels(changed_capability_items),
            )
        )
        assigned_actor_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                metadata,
                plural_key=_DECISION_ASSIGNED_ACTOR_DECISION_ITEM_IDS_KEY,
                singular_key=_DECISION_ASSIGNED_ACTOR_DECISION_ITEM_ID_KEY,
            ),
        )
        rows.append(
            (
                f"assigned actors ({len(assigned_actor_items)})",
                _relation_labels(assigned_actor_items),
            )
        )
    return tuple(rows)


def _first_missing_draft_model_relation(
    decision_items: tuple[DecisionReviewItem, ...],
) -> tuple[str, DecisionReviewItem, DecisionReviewItem | None] | None:
    active_items = tuple(
        sorted(
            _active_decision_review_items(decision_items),
            key=lambda item: (item.ordering, item.decision_review_item_id),
        )
    )
    for item in active_items:
        if item.decision_role != "transition_candidate":
            continue
        metadata = dict(item.metadata)
        source_item = _decision_item_by_id(
            decision_items,
            str(metadata.get(_TRANSITION_SOURCE_DECISION_ITEM_ID_KEY, "")),
        )
        target_item = _decision_item_by_id(
            decision_items,
            str(metadata.get(_TRANSITION_TARGET_DECISION_ITEM_ID_KEY, "")),
        )
        changed_capability_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                metadata,
                plural_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_IDS_KEY,
                singular_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_ID_KEY,
            ),
        )
        if source_item is None:
            return ("transition_source", item, None)
        if target_item is None:
            return ("transition_target", item, source_item)
        if not changed_capability_items:
            return ("transition_changed_capability", item, None)
    for item in active_items:
        if item.decision_role != "decision_candidate":
            continue
        metadata = dict(item.metadata)
        selected_transition_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                metadata,
                plural_key=_DECISION_SELECTED_TRANSITION_ITEM_IDS_KEY,
                singular_key=_DECISION_SELECTED_TRANSITION_ITEM_ID_KEY,
            ),
        )
        if not selected_transition_items:
            return ("decision_transition", item, None)
        for transition_item in selected_transition_items:
            changed_capability_items = _decision_items_by_ids(
                decision_items,
                _metadata_decision_item_ids(
                    dict(transition_item.metadata),
                    plural_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_IDS_KEY,
                    singular_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_ID_KEY,
                ),
            )
            if not changed_capability_items:
                return ("decision_transition_changed_capability", item, transition_item)
        assigned_actor_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                metadata,
                plural_key=_DECISION_ASSIGNED_ACTOR_DECISION_ITEM_IDS_KEY,
                singular_key=_DECISION_ASSIGNED_ACTOR_DECISION_ITEM_ID_KEY,
            ),
        )
        if not assigned_actor_items:
            return ("decision_assigned_actor", item, selected_transition_items[0])
    return None


def _reordered_draft_review_items(
    items: tuple[ReviewItem, ...],
    *,
    selected_review_item_id: str,
    delta: int,
    build_epoch_ms: int,
) -> tuple[ReviewItem, ...] | None:
    normalized_selected_id = collapse_ws(selected_review_item_id)
    if not normalized_selected_id or not items:
        return None
    selected_item = review_item_by_id(items, normalized_selected_id)
    if selected_item is None:
        return None
    parent_id = collapse_ws(selected_item.parent_review_item_id)
    ordered_items = list(
        sorted(
            (
                item
                for item in items
                if collapse_ws(item.parent_review_item_id) == parent_id
                and collapse_ws(item.status) != "rejected"
            ),
            key=lambda item: (item.ordering, item.review_item_id),
        )
    )
    current_index = next(
        (
            index
            for index, item in enumerate(ordered_items)
            if collapse_ws(item.review_item_id) == normalized_selected_id
        ),
        -1,
    )
    if current_index < 0:
        return None
    target_index = current_index + int(delta)
    if target_index < 0 or target_index >= len(ordered_items):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return None
    moving_item = ordered_items.pop(current_index)
    ordered_items.insert(target_index, moving_item)
    sibling_ordering = {
        collapse_ws(item.review_item_id): ordering
        for ordering, item in enumerate(ordered_items, start=1)
    }
    reordered_items: list[ReviewItem] = []
    for item in items:
        item_id = collapse_ws(item.review_item_id)
        if item_id not in sibling_ordering or int(item.ordering or 0) == sibling_ordering[item_id]:
            reordered_items.append(item)
            continue
        reordered_items.append(
            replace(
                item,
                ordering=sibling_ordering[item_id],
                updated_at_epoch_ms=build_epoch_ms,
            )
        )
    return tuple(reordered_items)


def _draft_review_item_lines(item: ReviewItem, *, selection_source: str = "") -> list[str]:
    return [
        f"- {label}: {value}"
        for label, value in _draft_review_item_rows(
            item,
            selection_source=selection_source,
        )
    ]


def _draft_review_item_rows(
    item: ReviewItem,
    *,
    selection_source: str = "",
) -> tuple[tuple[str, str], ...]:
    rows = [
        ("label", collapse_ws(str(item.metadata.get("canonical_label", ""))) or item.review_item_id),
        ("ordering", str(int(item.ordering or 0))),
        ("parent review item", collapse_ws(item.parent_review_item_id) or "<root>"),
        ("child review items", str(len(item.child_review_item_ids))),
        ("included in draft composition", "yes" if item.included else "no"),
        ("semantic kind", _format_orientation_label(item.semantic_kind)),
        ("render kind", _format_orientation_label(item.render_kind)),
        ("evidence mode", _format_orientation_label(item.evidence_mode)),
        ("transform mode", _format_orientation_label(item.transform_mode)),
    ]
    if selection_source:
        rows.append(
            (
                "selection source",
                _DRAFT_REVIEW_SELECTION_LABELS.get(
                    selection_source,
                    _format_orientation_label(selection_source),
                ),
            )
        )
    if item.source_refs:
        rows.append(("source refs", str(len(item.source_refs))))
    if collapse_ws(item.source_unit_id):
        rows.append(("source unit", item.source_unit_id))
    return tuple(rows)


def _draft_review_inventory_lines(
    items: tuple[ReviewItem, ...],
    *,
    selected_review_item_id: str = "",
    decision_included_review_item_ids: tuple[str, ...] = (),
) -> list[str]:
    selected_id = collapse_ws(selected_review_item_id)
    decision_item_ids = {
        collapse_ws(review_item_id)
        for review_item_id in decision_included_review_item_ids
        if collapse_ws(review_item_id)
    }
    lines: list[str] = []
    if not items:
        lines.append("- no persisted draft review items yet")
        return lines
    for item, depth in flatten_review_item_tree(items):
        item_id = collapse_ws(item.review_item_id)
        cursor = ">" if item_id == selected_id else " "
        included = "x" if item.included else " "
        decision_included = "d" if item_id in decision_item_ids else " "
        label = collapse_ws(str(item.metadata.get("canonical_label", ""))) or item.review_item_id
        prefix = "  " * max(0, int(depth))
        lines.append(
            f"{cursor} [{included}][{decision_included}] {prefix}{label} "
            f"({_format_orientation_label(item.semantic_kind)} -> {_format_orientation_label(item.render_kind)})"
        )
    return lines


def subject_draft_review_inventory(
    *,
    root_path: Path,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> tuple[
    tuple[tuple[ReviewItem, int], ...],
    str,
    tuple[str, ...],
    dict[str, str],
]:
    """Return draft inventory state without requiring adapters to decode prose."""
    _review_composition, review_items = _review_composition_and_items(root_path, scenario)
    flattened = flatten_review_item_tree(review_items)
    selected_item, _selection_source = _selected_draft_review_item(
        root_path,
        scenario=scenario,
        progress=progress,
    )
    decision_state = _decision_review_state(root_path, scenario)
    decision_frame = (
        decision_state.get("frame")
        if isinstance(decision_state.get("frame"), DecisionFrame)
        else None
    )
    decision_included_ids = _draft_effective_decision_included_review_item_ids(
        root_path,
        scenario=scenario,
        review_items=review_items,
        decision_items=list_decision_review_items(root_path, scenario.subject_id),
        frame=decision_frame,
    )
    try:
        context = load_learning_context(root_path, scenario.subject_id)
    except Exception:
        source_statement_by_unit_id: dict[str, str] = {}
    else:
        source_statement_by_unit_id = {
            collapse_ws(unit.unit_id): collapse_ws(unit.statement)
            for unit in _admitted_units_in_context_order(context)
            if collapse_ws(unit.unit_id) and collapse_ws(unit.statement)
        }
    return (
        flattened,
        collapse_ws(selected_item.review_item_id) if selected_item is not None else "",
        decision_included_ids,
        source_statement_by_unit_id,
    )


def _cycle_ordered_value(current: str, ordered_values: tuple[str, ...]) -> str:
    normalized_current = collapse_ws(current).lower()
    if not ordered_values:
        return normalized_current
    if normalized_current not in ordered_values:
        return ordered_values[0]
    index = ordered_values.index(normalized_current)
    return ordered_values[(index + 1) % len(ordered_values)]


def _valid_itemize_held_item_ids(
    *,
    items: tuple[ItemizedSubjectItem, ...],
    progress: SubjectProgress,
) -> tuple[str, ...]:
    item_ids = {
        collapse_ws(getattr(item, "itemized_item_id", ""))
        for item in items
        if collapse_ws(getattr(item, "itemized_item_id", ""))
    }
    return tuple(
        item_id
        for item_id in (collapse_ws(item) for item in progress.itemize_held_item_ids)
        if item_id and item_id in item_ids
    )


def _selected_itemization_item(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> ItemizedSubjectItem | None:
    _session, items = _itemization_session_and_items(root_path, scenario)
    if not items:
        return None
    selected_id = collapse_ws(progress.itemize_selected_item_id)
    if selected_id:
        for item in items:
            if collapse_ws(item.itemized_item_id) == selected_id:
                return item
    index = max(0, min(len(items) - 1, int(progress.itemize_cursor or 0)))
    return items[index]


def _selected_item_supports_construct_discovery(item: ItemizedSubjectItem | None) -> bool:
    return item is not None and collapse_ws(item.status) in _ITEMIZE_MUTABLE_STATUSES


def move_itemize_cursor(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    delta: int,
) -> ItemizedSubjectItem | None:
    _session, items = _itemization_session_and_items(root_path, scenario)
    if not items:
        return None
    current_id = collapse_ws(progress.itemize_selected_item_id)
    if current_id:
        current_index = next(
            (
                index
                for index, item in enumerate(items)
                if collapse_ws(item.itemized_item_id) == current_id
            ),
            max(0, min(len(items) - 1, int(progress.itemize_cursor or 0))),
        )
    else:
        current_index = max(0, min(len(items) - 1, int(progress.itemize_cursor or 0)))
    next_index = max(0, min(len(items) - 1, current_index + int(delta)))
    selected = items[next_index]
    progress.itemize_cursor = next_index
    progress.itemize_selected_item_id = collapse_ws(selected.itemized_item_id)
    return selected


def _persist_itemization_edit(
    root_path: Path,
    *,
    session: ItemizationSession,
    items: tuple[ItemizedSubjectItem, ...],
) -> tuple[ItemizationSession, tuple[ItemizedSubjectItem, ...]]:
    now_epoch_ms = int(time.time() * 1000)
    normalized_items = tuple(
        ItemizedSubjectItem.from_dict(
            replace(
                item,
                updated_at_epoch_ms=now_epoch_ms,
            ).to_dict()
        )
        for item in items
    )
    updated_session = ItemizationSession.from_dict(
        replace(
            session,
            item_ids=tuple(item.itemized_item_id for item in normalized_items),
            updated_at_epoch_ms=now_epoch_ms,
            metadata={
                **dict(session.metadata),
                "item_count": len(normalized_items),
            },
        ).to_dict()
    )
    persist_itemization_session(root_path, updated_session, normalized_items)
    return updated_session, normalized_items


def _next_itemize_decision_role(current_role: str) -> str:
    normalized = normalize_itemized_decision_role(current_role)
    try:
        index = _ITEMIZE_DECISION_ROLE_CYCLE.index(normalized)
    except ValueError:
        index = 0
    return _ITEMIZE_DECISION_ROLE_CYCLE[(index + 1) % len(_ITEMIZE_DECISION_ROLE_CYCLE)]


def _itemize_split_labels(item: ItemizedSubjectItem) -> tuple[str, ...]:
    normalized_summary = collapse_ws(item.summary)
    alias_parts = [
        collapse_ws(alias)
        for alias in item.aliases
        if collapse_ws(alias)
        and collapse_ws(alias) != collapse_ws(item.canonical_label)
        and collapse_ws(alias) != normalized_summary
    ]
    if alias_parts:
        return tuple(dict.fromkeys(alias_parts))
    candidates = semantic_chain_decomposition_components(item.summary)
    if len(candidates) > 1:
        return tuple(
            label
            for label in (
                collapse_ws(candidate)
                for candidate in candidates
            )
            if label and label != collapse_ws(item.canonical_label)
        )
    label = collapse_ws(item.canonical_label)
    for delimiter in (" / ", ";", " and "):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        if delimiter in label:
            parts = tuple(
                part
                for part in (collapse_ws(piece) for piece in label.split(delimiter))
                if part and part != label
            )
            if len(parts) > 1:
                return parts
    return ()


def _projection_comparison_status_line(status: str) -> str:
    normalized = collapse_ws(status).casefold() or "pending"
    if normalized == "aligned":
        return "- blocker: none"
    if normalized == "drifted":
        return "- blocker: the maintained files drifted; repair subject.md / subject.typ alignment"
    if normalized == "unavailable":
        return "- blocker: the maintained files are unavailable; open the subject context and materialize both files"
    return f"- blocker: run {_COMPARE_MAINTAINED_FILES_LABEL}"


def _projection_comparison_summary_lines(*, scenario: SubjectScenario, progress: SubjectProgress) -> list[str]:
    lines: list[str] = [
        f"- verdict: {progress.comparison_status}",
        f"- comparison executed: {'yes' if progress.projections_compared else 'no'}",
    ]
    receipt_lines = list(progress.comparison_receipt_lines)
    if receipt_lines:
        interesting_prefixes = (
            "- subject.md lines/hash:",
            "- subject.typ lines/hash:",
            "- items checked:",
            "- items covered in subject.md:",
            "- items covered in subject.typ:",
            "- missing in subject.md:",
            "- missing in subject.typ:",
            "- verdict:",
        )
        lines.extend(
            line
            for line in receipt_lines
            if any(line.startswith(prefix) for prefix in interesting_prefixes)
        )
    else:
        lines.extend(
            [
                f"- subject.md present: {'yes' if Path(scenario.subject_markdown_path).expanduser().is_file() else 'no'}",
                f"- subject.typ present: {'yes' if Path(scenario.subject_typst_path).expanduser().is_file() else 'no'}",
            ]
        )
    lines.append(_projection_comparison_status_line(progress.comparison_status))
    return lines


def _publication_completion_marker_lines(*, scenario: SubjectScenario, progress: SubjectProgress) -> list[str]:
    return [
        f"[{'x' if _review_ready(scenario, progress) else ' '}] reviewed subject selected",
        f"[{'x' if _publication_locked(scenario, progress) else ' '}] publication inputs locked",
        f"[{'x' if bool(collapse_ws(scenario.build_id)) else ' '}] report build produced",
        f"[{'x' if progress.release_packet_opened else ' '}] release folder opened",
        f"[{'x' if progress.release_review_completed else ' '}] release review completed",
        f"[{'x' if Path(scenario.report_pdf_path).expanduser().is_file() else ' '}] report.pdf available",
        f"[{'x' if Path(scenario.report_markdown_path).expanduser().is_file() else ' '}] report.md available",
        f"[{'x' if Path(scenario.report_typst_path).expanduser().is_file() else ' '}] report.typ available",
    ]


def _normalize_import_selection_profile(profile: str) -> str:
    normalized = collapse_ws(profile).casefold() or "units_only"
    return normalized if normalized in SUBJECT_IMPORT_SELECTION_PROFILES else "units_only"


def _subject_import_selection_label(profile: str) -> str:
    normalized = _normalize_import_selection_profile(profile)
    return SUBJECT_IMPORT_SELECTION_LABELS.get(normalized, "units only")


def _next_subject_import_selection_profile(profile: str) -> str:
    normalized = _normalize_import_selection_profile(profile)
    index = SUBJECT_IMPORT_SELECTION_PROFILES.index(normalized)
    if index >= len(SUBJECT_IMPORT_SELECTION_PROFILES) - 1:
        return normalized
    return SUBJECT_IMPORT_SELECTION_PROFILES[index + 1]


def _subject_import_selection_action_label(profile: str) -> str:
    normalized = _normalize_import_selection_profile(profile)
    if normalized == "full_context":
        return "Import Scope Is Full"
    return "Expand Import Scope"


def _subject_import_scope_step(profile: str) -> tuple[int, int]:
    normalized = _normalize_import_selection_profile(profile)
    index = SUBJECT_IMPORT_SELECTION_PROFILES.index(normalized)
    return (index + 1, len(SUBJECT_IMPORT_SELECTION_PROFILES))


def _subject_import_scope_next_step_text(profile: str) -> str:
    normalized = _normalize_import_selection_profile(profile)
    if normalized == "units_only":
        return "expand once to include linked skills"
    if normalized == "units_and_skills":
        return "expand once more to include linked sources"
    return "scope is already full; clear the import source or switch to a target subject"


def _ordered_texts(items: list[str] | tuple[str, ...]) -> tuple[str, ...]:
    ordered: dict[str, None] = {}
    for item in items:
        text = collapse_ws(str(item))
        if text:
            ordered.setdefault(text, None)
    return tuple(ordered)


def subject_import_staging_path(root_path: Path) -> Path:
    return learning_corpus_root(Path(root_path).expanduser().resolve()) / "indexes" / "subject_import_staging.json"


def load_subject_import_staging(root_path: Path) -> SubjectImportStaging | None:
    payload = _read_json(subject_import_staging_path(root_path))
    source_subject_id = collapse_ws(str(payload.get("source_subject_id", "")))
    if not source_subject_id:
        return None
    return SubjectImportStaging(
        source_subject_id=source_subject_id,
        source_subject_title=collapse_ws(str(payload.get("source_subject_title", ""))) or source_subject_id,
        source_subject_version_id=collapse_ws(str(payload.get("source_subject_version_id", ""))),
        import_kind=collapse_ws(str(payload.get("import_kind", ""))) or "definition_support",
        selection_profile=_normalize_import_selection_profile(str(payload.get("selection_profile", "units_only"))),
    )


def persist_subject_import_staging(root_path: Path, staging: SubjectImportStaging) -> Path:
    target = subject_import_staging_path(root_path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(
        json.dumps(
            {
                "schema": "subject_import_staging.v1",
                "source_subject_id": staging.source_subject_id,
                "source_subject_title": staging.source_subject_title,
                "source_subject_version_id": staging.source_subject_version_id,
                "import_kind": staging.import_kind,
                "selection_profile": _normalize_import_selection_profile(staging.selection_profile),
            },
            indent=2,
            sort_keys=True,
        ),
        encoding="utf-8",
    )
    return target


def clear_subject_import_staging(root_path: Path) -> None:
    target = subject_import_staging_path(root_path)
    try:
        target.unlink()
    except FileNotFoundError:
        return


def _pending_subject_imports(root_path: Path, subject_id: str) -> tuple[SubjectImport, ...]:
    return tuple(
        item
        for item in list_subject_imports(root_path, subject_id)
        if item.status == "active" and item.review_status == "pending"
    )


def _latest_pending_subject_import(root_path: Path, subject_id: str) -> SubjectImport | None:
    pending = _pending_subject_imports(root_path, subject_id)
    return pending[-1] if pending else None


def _latest_active_subject_import(root_path: Path, subject_id: str) -> SubjectImport | None:
    active = _active_subject_imports(root_path, subject_id)
    return active[-1] if active else None


def _subject_import_selection_payload(
    root_path: Path,
    staging: SubjectImportStaging,
) -> dict[str, object]:
    source_context = load_learning_context(root_path, staging.source_subject_id)
    admitted_units = tuple(
        unit
        for unit in source_context.units
        if unit.status == "admitted" and collapse_ws(unit.unit_id)
    )
    imported_unit_ids = tuple(unit.unit_id for unit in admitted_units)
    imported_skill_ids = _ordered_texts(
        [
            *list(source_context.linked_skill_ids),
            *[skill_id for unit in admitted_units for skill_id in unit.linked_skill_ids],
        ]
    )
    imported_source_ids = _ordered_texts(
        [
            *list(source_context.linked_source_ids),
            *[source_id for unit in admitted_units for source_id in unit.provenance_refs],
        ]
    )
    selection_profile = _normalize_import_selection_profile(staging.selection_profile)
    if selection_profile == "units_only":
        imported_skill_ids = ()
        imported_source_ids = ()
    elif selection_profile == "units_and_skills":
        imported_source_ids = ()
    unit_labels = tuple(
        collapse_ws(unit.canonical_title or unit.unit_id)
        for unit in admitted_units
        if collapse_ws(unit.canonical_title or unit.unit_id)
    )
    source_labels: list[str] = []
    for source_id in imported_source_ids:
        try:
            source = load_learning_source(root_path, source_context.subject_id, source_id)
        except Exception:
            source_labels.append(source_id)
            continue
        source_labels.append(collapse_ws(source.title or source.source_id) or source_id)
    return {
        "selection_profile": selection_profile,
        "selection_label": _subject_import_selection_label(selection_profile),
        "source_context": source_context,
        "imported_unit_ids": imported_unit_ids,
        "imported_skill_ids": imported_skill_ids,
        "imported_source_ids": imported_source_ids,
        "unit_labels": unit_labels,
        "skill_labels": imported_skill_ids,
        "source_labels": tuple(source_labels),
    }


def _subject_import_scope_text(subject_import: SubjectImport) -> str:
    slice_parts: list[str] = []
    if subject_import.imported_unit_ids:
        slice_parts.append(f"{len(subject_import.imported_unit_ids)} units")
    if subject_import.imported_skill_ids:
        slice_parts.append(f"{len(subject_import.imported_skill_ids)} skills")
    if subject_import.imported_source_ids:
        slice_parts.append(f"{len(subject_import.imported_source_ids)} sources")
    if subject_import.imported_claim_ids:
        slice_parts.append(f"{len(subject_import.imported_claim_ids)} claims")
    if subject_import.imported_section_ids:
        slice_parts.append(f"{len(subject_import.imported_section_ids)} sections")
    return ", ".join(slice_parts) if slice_parts else "bounded import"


def _subject_import_receipt_lines(subject_import: SubjectImport) -> list[str]:
    selection_profile = _normalize_import_selection_profile(str(subject_import.metadata.get("selection_profile", "")))
    lines = [
        f"- import: {subject_import.import_id}",
        f"- source: {subject_import.source_subject_title or subject_import.source_subject_id}",
        f"- source subject id: {subject_import.source_subject_id or '<unknown>'}",
        f"- source version: {subject_import.source_subject_version_id or '<unpinned>'}",
        f"- import kind: {subject_import.import_kind}",
        f"- selection profile: {_subject_import_selection_label(selection_profile)}",
        f"- review status: {subject_import.review_status}",
        f"- lifecycle status: {subject_import.status}",
        f"- scope: {_subject_import_scope_text(subject_import)}",
        f"- rationale: {collapse_ws(subject_import.rationale) or '<none>'}",
    ]
    if subject_import.imported_unit_ids:
        lines.append(
            "- imported units: " + ", ".join(subject_import.imported_unit_ids[:4])
            + (" ..." if len(subject_import.imported_unit_ids) > 4 else "")
        )
    if subject_import.imported_skill_ids:
        lines.append(
            "- imported skills: " + ", ".join(subject_import.imported_skill_ids[:4])
            + (" ..." if len(subject_import.imported_skill_ids) > 4 else "")
        )
    if subject_import.imported_source_ids:
        lines.append(
            "- imported sources: " + ", ".join(subject_import.imported_source_ids[:4])
            + (" ..." if len(subject_import.imported_source_ids) > 4 else "")
        )
    return lines


def _subject_import_staging_receipt_lines(root_path: Path, staging: SubjectImportStaging) -> list[str]:
    scope_step, scope_total = _subject_import_scope_step(staging.selection_profile)
    try:
        payload = _subject_import_selection_payload(root_path, staging)
    except Exception:
        return [
            f"- selected source: {staging.source_subject_title or staging.source_subject_id}",
            f"- source subject id: {staging.source_subject_id or '<unknown>'}",
            f"- source version: {staging.source_subject_version_id or '<unpinned>'}",
            f"- import kind: {staging.import_kind}",
            f"- import scope: {_subject_import_selection_label(staging.selection_profile)}",
            f"- scope step: {scope_step} of {scope_total}",
            f"- next scope step: {_subject_import_scope_next_step_text(staging.selection_profile)}",
            "- staged scope: <unavailable>",
        ]
    lines = [
        f"- selected source: {staging.source_subject_title or staging.source_subject_id}",
        f"- source subject id: {staging.source_subject_id or '<unknown>'}",
        f"- source version: {staging.source_subject_version_id or '<unpinned>'}",
        f"- import kind: {staging.import_kind}",
        f"- import scope: {payload['selection_label']}",
        f"- scope step: {scope_step} of {scope_total}",
        f"- next scope step: {_subject_import_scope_next_step_text(staging.selection_profile)}",
        (
            "- staged scope: "
            + _subject_import_scope_text(
                SubjectImport(
                    import_id="staged",
                    active_subject_id="<pending>",
                    source_subject_id=staging.source_subject_id,
                    source_subject_title=staging.source_subject_title,
                    import_kind=staging.import_kind,
                    imported_unit_ids=tuple(payload["imported_unit_ids"]),
                    imported_skill_ids=tuple(payload["imported_skill_ids"]),
                    imported_source_ids=tuple(payload["imported_source_ids"]),
                )
            )
        ),
    ]
    unit_labels = list(payload["unit_labels"])[:4]
    skill_labels = list(payload["skill_labels"])[:4]
    source_labels = list(payload["source_labels"])[:4]
    if unit_labels:
        lines.append("- staged units: " + ", ".join(unit_labels) + (" ..." if len(tuple(payload["unit_labels"])) > 4 else ""))
    if skill_labels:
        lines.append("- staged skills: " + ", ".join(skill_labels) + (" ..." if len(tuple(payload["skill_labels"])) > 4 else ""))
    if source_labels:
        lines.append("- staged sources: " + ", ".join(source_labels) + (" ..." if len(tuple(payload["source_labels"])) > 4 else ""))
    return lines


def _projection_comparison_receipt(root_path: Path, scenario: SubjectScenario) -> tuple[str, list[str]]:
    md_path = Path(scenario.subject_markdown_path).expanduser()
    typ_path = Path(scenario.subject_typst_path).expanduser()
    lines = [
        f"- subject.md: {scenario.subject_markdown_path or '<missing>'}",
        f"- subject.typ: {scenario.subject_typst_path or '<missing>'}",
    ]
    if not md_path.is_file() or not typ_path.is_file():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        lines.append("- verdict: unavailable")
        return "unavailable", lines
    md_text = md_path.read_text(encoding="utf-8")
    typ_text = typ_path.read_text(encoding="utf-8")
    context = load_learning_context(Path(root_path).expanduser().resolve(), scenario.subject_id)
    admitted_titles = tuple(
        sorted(
            {
                collapse_ws(unit.canonical_title or unit.unit_id)
                for unit in context.units
                if unit.status == "admitted" and collapse_ws(unit.canonical_title or unit.unit_id)
            }
        )
    )
    md_text_key = md_text.casefold()
    typ_text_key = typ_text.casefold()
    title_in_md = scenario.title.casefold() in md_text_key
    title_in_typ = scenario.title.casefold() in typ_text_key
    missing_md = [title for title in admitted_titles if title.casefold() not in md_text_key]
    missing_typ = [title for title in admitted_titles if title.casefold() not in typ_text_key]
    covered_md = len(admitted_titles) - len(missing_md)
    covered_typ = len(admitted_titles) - len(missing_typ)
    subject_typ_validation_status, subject_typ_validation_error = _validate_subject_typ_projection(typ_path)
    status = (
        "aligned"
        if title_in_md and title_in_typ and not missing_md and not missing_typ and subject_typ_validation_status != "error"
        else "drifted"
    )
    lines.extend(
        [
            f"- subject.md lines/hash: {len(md_text.splitlines())} / {_short_text_hash(md_text)}",
            f"- subject.typ lines/hash: {len(typ_text.splitlines())} / {_short_text_hash(typ_text)}",
            f"- subject.md bytes: {md_path.stat().st_size}",
            f"- subject.typ bytes: {typ_path.stat().st_size}",
            f"- subject title found in subject.md: {'yes' if title_in_md else 'no'}",
            f"- subject title found in subject.typ: {'yes' if title_in_typ else 'no'}",
            f"- subject.typ typst validation: {subject_typ_validation_status}",
            f"- items checked: {len(admitted_titles)}",
            f"- items covered in subject.md: {covered_md} / {len(admitted_titles)}",
            f"- items covered in subject.typ: {covered_typ} / {len(admitted_titles)}",
            f"- missing in subject.md: {', '.join(missing_md) if missing_md else '<none>'}",
            f"- missing in subject.typ: {', '.join(missing_typ) if missing_typ else '<none>'}",
            *([] if not subject_typ_validation_error else [f"- subject.typ typst error: {subject_typ_validation_error}"]),
            f"- verdict: {status}",
        ]
    )
    return status, lines


def _validate_subject_typ_projection(typ_path: Path) -> tuple[str, str]:
    typst_bin = shutil.which("typst")
    if not typst_bin:
        return "unavailable", ""
    with runtime_temporary_directory(prefix="subject-typst-validate-") as tempdir_text:
        pdf_path = Path(tempdir_text) / "subject.pdf"
        process = subprocess.run(
            [typst_bin, "compile", str(typ_path), str(pdf_path)],
            capture_output=True,
            text=True,
        )
        if process.returncode == 0 and pdf_path.is_file():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
            return "ok", ""
    error_text = collapse_ws(process.stderr or process.stdout) or "Typst compile failed."
    return "error", error_text


def _summary_for_context(context: LearningContext) -> str:
    if collapse_ws(context.summary):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return collapse_ws(context.summary)
    admitted_units = [unit for unit in context.units if unit.status == "admitted"]
    if admitted_units:
        return textwrap.shorten(collapse_ws(admitted_units[0].statement), width=180, placeholder="...")
    if context.units:
        return "The subject exists but no ready items are available yet."
    return "The subject exists but no items have been captured yet."


def _prune_same_label_construct_clones_for_explicit_item_role(
    selected_item: ItemizedSubjectItem,
    candidates: tuple[TransformationConstructCandidate, ...],
) -> tuple[TransformationConstructCandidate, ...]:
    if collapse_ws(selected_item.item_kind) != "decision_role_candidate":
        return candidates
    explicit_sort_kind = _ITEMIZED_DECISION_ROLE_TO_CONSTRUCT_SORT_KIND.get(
        normalize_itemized_decision_role(selected_item.metadata.get("decision_role", "")),
        "",
    )
    if not explicit_sort_kind:
        return candidates
    selected_label = collapse_ws(selected_item.canonical_label).casefold()
    if not selected_label:
        return candidates
    pruned = tuple(
        candidate
        for candidate in candidates
        if (
            collapse_ws(candidate.canonical_label).casefold() != selected_label
            or normalize_transformation_construct_sort_kind(candidate.sort_kind) == explicit_sort_kind
        )
    )
    return pruned or candidates


def _prune_same_label_subject_title_construct_clones(
    candidates: tuple[TransformationConstructCandidate, ...],
    *,
    subject_title: str,
) -> tuple[TransformationConstructCandidate, ...]:
    normalized_subject_title = collapse_ws(subject_title).casefold()
    if not normalized_subject_title:
        return candidates
    subject_title_candidates = tuple(
        candidate
        for candidate in candidates
        if collapse_ws(candidate.canonical_label).casefold() == normalized_subject_title
    )
    if not subject_title_candidates:
        return candidates
    non_subject_title_candidates = tuple(
        candidate
        for candidate in candidates
        if collapse_ws(candidate.canonical_label).casefold() != normalized_subject_title
    )

    def _candidate_rank(candidate: TransformationConstructCandidate) -> tuple[int, int, float, int]:
        status = collapse_ws(candidate.status)
        curated = int(_construct_candidate_was_curated(candidate))
        status_rank = 2 if status == "accepted" else 1 if status == "candidate" else 0
        try:
            sort_rank = -TRANSFORMATION_CONSTRUCT_SORT_ORDER.index(
                normalize_transformation_construct_sort_kind(candidate.sort_kind)
            )
        except ValueError:
            sort_rank = -len(TRANSFORMATION_CONSTRUCT_SORT_ORDER)
        return (curated, status_rank, float(candidate.confidence or 0.0), sort_rank)

    if non_subject_title_candidates:
        curated_subject_title_candidates = tuple(
            candidate
            for candidate in subject_title_candidates
            if _construct_candidate_was_curated(candidate)
        )
        if not curated_subject_title_candidates:
            return non_subject_title_candidates
        best_curated = max(curated_subject_title_candidates, key=_candidate_rank)
        return non_subject_title_candidates + (best_curated,)

    if len(subject_title_candidates) < 2:
        return candidates
    distinct_sort_kinds = {
        normalize_transformation_construct_sort_kind(candidate.sort_kind)
        for candidate in subject_title_candidates
    }
    if len(distinct_sort_kinds) < 2:
        return candidates

    best_candidate = max(subject_title_candidates, key=_candidate_rank)
    return (best_candidate,)


def _itemized_item_non_unit_source_refs(item: ItemizedSubjectItem) -> frozenset[str]:
    refs: set[str] = set()
    for ref in item.source_refs:
        normalized = collapse_ws(ref)
        if not normalized or normalized.startswith("unit:"):
            continue
        refs.add(normalized)
    return frozenset(refs)


def _is_subject_title_umbrella_item_for_construct_suggestion(
    item: ItemizedSubjectItem,
    *,
    subject_title: str,
) -> bool:
    item_kind = collapse_ws(item.item_kind)
    if item_kind not in {"claim", "entity", "glossary_term"}:
        return False
    return collapse_ws(item.canonical_label).casefold() == collapse_ws(subject_title).casefold()


def _construct_suggestion_seed_items(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    selected_item: ItemizedSubjectItem,
) -> tuple[ItemizedSubjectItem, ...]:
    if not _is_subject_title_umbrella_item_for_construct_suggestion(
        selected_item,
        subject_title=scenario.title,
    ):
        return (selected_item,)
    _session, items = _itemization_session_and_items(root_path, scenario)
    selected_refs = _itemized_item_non_unit_source_refs(selected_item)
    subject_title = collapse_ws(scenario.title).casefold()
    seeds: list[ItemizedSubjectItem] = []
    seen_ids: set[str] = set()
    for item in items:
        if collapse_ws(item.item_kind) != "decision_role_candidate":
            continue
        if collapse_ws(item.status) not in _ITEMIZE_MUTABLE_STATUSES:
            continue
        if not _ITEMIZED_DECISION_ROLE_TO_CONSTRUCT_SORT_KIND.get(
            normalize_itemized_decision_role(item.metadata.get("decision_role", "")),
            "",
        ):
            continue
        label = collapse_ws(item.canonical_label)
        if not label or label.casefold() == subject_title:
            continue
        item_refs = _itemized_item_non_unit_source_refs(item)
        if selected_refs and item_refs and not (selected_refs & item_refs):
            continue
        item_id = collapse_ws(item.itemized_item_id)
        if not item_id or item_id in seen_ids:
            continue
        seen_ids.add(item_id)
        seeds.append(item)
    return tuple(seeds) or (selected_item,)


def _source_preview_lines(root_path: Path, subject_id: str, *, limit: int = 6) -> tuple[str, ...]:
    source_root = learning_context_paths(root_path, subject_id)["sources"]
    if not source_root.exists():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return ()
    lines: list[str] = []
    for index, path in enumerate(sorted(source_root.glob("*.json"))[:limit], start=1):
        source = load_learning_source(root_path, subject_id, path.stem)
        source_ref = collapse_ws(source.source_ref) or collapse_ws(source.body_relpath) or "<no-ref>"
        if source_ref != "<no-ref>":
            source_ref = _ui_path_label(root_path, source_ref)
        lines.append(f"{index}. {source.title or source.source_id}")
        lines.append(f"   kind={source.source_kind}  ref={source_ref}")
    return tuple(lines)


def _staged_source_preview_lines(root_path: Path, subject_id: str, *, limit: int = 6) -> tuple[str, ...]:
    staged_sources = list_staged_sources(root_path, subject_id)
    if not staged_sources:
        return ()
    lines: list[str] = []
    for index, staged_source in enumerate(staged_sources[:limit], start=1):
        revision = latest_source_revision(root_path, staged_source)
        source_ref = collapse_ws(staged_source.source_ref) or "<no-ref>"
        lines.append(f"{index}. {staged_source.title or staged_source.staged_source_id}")
        lines.append(
            "   "
            + "  ".join(
                [
                    f"status={staged_source.status}",
                    f"kind={staged_source.source_kind}",
                    f"ref={source_ref}",
                    (
                        f"bundle={len(revision.bundle_relpaths)} files"
                        if revision is not None
                        else "bundle=missing"
                    ),
                ]
            )
        )
    return tuple(lines)


def _source_collection_preview_lines(root_path: Path, subject_id: str, *, limit: int = 4) -> tuple[str, ...]:
    collections = list_source_collections(root_path, subject_id)
    if not collections:
        return ()
    lines: list[str] = []
    for index, collection in enumerate(collections[:limit], start=1):
        query_text = collapse_ws(collection.query_text) or "<none>"
        lines.append(f"{index}. {collection.title or collection.collection_id}")
        lines.append(
            "   "
            + "  ".join(
                [
                    f"sources={len(collection.staged_source_ids)}",
                    f"query={query_text}",
                ]
            )
        )
    return tuple(lines)


def _source_collection_is_default(collection) -> bool:
    return collapse_ws(str(getattr(collection, "metadata", {}).get("collection_kind", ""))) == "all_gather_sources"


def _source_collection_kind_label(collection) -> str:
    kind = collapse_ws(str(getattr(collection, "metadata", {}).get("collection_kind", "")))
    if kind == "all_gather_sources":
        return "all gather sources"
    if kind == "topic_query":
        return "topic/query"
    return "focused"


def _source_collection_knowledge_summary(collection) -> str:
    return str(getattr(collection, "metadata", {}).get("knowledgebase_summary", "") or "").strip()


def _source_collection_knowledge_questions(collection) -> tuple[str, ...]:
    raw_questions = getattr(collection, "metadata", {}).get("knowledgebase_open_questions", ())
    if isinstance(raw_questions, str):
        return tuple(
            collapse_ws(line.lstrip("-* ").strip())
            for line in raw_questions.splitlines()
            if collapse_ws(line.lstrip("-* ").strip())
        )
    return tuple(
        collapse_ws(str(item))
        for item in tuple(raw_questions or ())
        if collapse_ws(str(item))
    )


def _next_manual_source_collection_title(root_path: Path, subject_id: str, base_title: str) -> str:
    normalized_base = collapse_ws(base_title) or "Focused Sources"
    existing_titles = {
        collapse_ws(collection.title).casefold()
        for collection in list_source_collections(root_path, subject_id)
        if collapse_ws(collection.title)
    }
    if normalized_base.casefold() not in existing_titles:
        return normalized_base
    suffix = 2
    while True:
        candidate = f"{normalized_base} ({suffix})"
        if candidate.casefold() not in existing_titles:
            return candidate
        suffix += 1


def _latest_staged_source_for_subject(root_path: Path, subject_id: str):
    staged_sources = list_staged_sources(root_path, subject_id)
    return staged_sources[0] if staged_sources else None


def _staged_source_by_ref(root_path: Path, *, subject_id: str, source_ref: str):
    normalized_ref = str(source_ref or "").strip()
    if not normalized_ref:
        return None
    normalized_key = collapse_ws(normalized_ref).casefold()
    for staged_source in list_staged_sources(root_path, subject_id, include_archived=True):
        if collapse_ws(staged_source.source_ref).casefold() == normalized_key:
            return staged_source
    return None


def _selected_source_collection(
    root_path: Path,
    *,
    subject_id: str,
    progress: SubjectProgress,
):
    collections = list_source_collections(root_path, subject_id)
    if not collections:
        return None
    selected_id = collapse_ws(progress.research_selected_source_collection_id)
    if selected_id:
        for collection in collections:
            if collapse_ws(collection.collection_id) == selected_id:
                return collection
    index = max(0, min(len(collections) - 1, int(progress.research_collection_cursor or 0)))
    return collections[index]


def _source_collection_by_id(root_path: Path, *, subject_id: str, collection_id: str):
    normalized_collection_id = collapse_ws(collection_id)
    if not normalized_collection_id:
        return None
    for collection in list_source_collections(root_path, subject_id):
        if collapse_ws(collection.collection_id) == normalized_collection_id:
            return collection
    return None


def _staged_sources_for_collection(
    root_path: Path,
    *,
    collection,
):
    if collection is None:
        return ()
    staged_source_ids = {
        collapse_ws(item)
        for item in getattr(collection, "staged_source_ids", ())
        if collapse_ws(item)
    }
    if not staged_source_ids:
        return ()
    return tuple(
        staged_source
        for staged_source in list_staged_sources(root_path, getattr(collection, "subject_id", ""))
        if collapse_ws(getattr(staged_source, "staged_source_id", "")) in staged_source_ids
    )


def _refreshable_staged_sources_for_collection(
    root_path: Path,
    *,
    collection,
):
    return tuple(
        staged_source
        for staged_source in _staged_sources_for_collection(root_path, collection=collection)
        if collapse_ws(getattr(staged_source, "source_kind", "")).casefold() == "url"
        and bool(collapse_ws(getattr(staged_source, "source_ref", "")))
    )


def _staged_sources_for_selected_collection(
    root_path: Path,
    *,
    subject_id: str,
    progress: SubjectProgress,
):
    selected_collection = _selected_source_collection(root_path, subject_id=subject_id, progress=progress)
    staged_sources = list_staged_sources(root_path, subject_id)
    return selected_collection, staged_sources


