def _selected_staged_source_supports_merge_back(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> bool:
    selected_source = _selected_staged_source(root_path, subject_id=scenario.subject_id, progress=progress)
    if selected_source is None:
        return False
    if int(getattr(scenario, "admitted_unit_count", 0) or 0) > 0:
        return True
    itemization_state = _itemization_state(root_path, scenario)
    if bool(itemization_state.get("exists")) and int(itemization_state.get("item_count", 0) or 0) > 0:
        return True
    review_state = _review_composition_state(root_path, scenario)
    if bool(review_state.get("exists")) and int(review_state.get("item_count", 0) or 0) > 0:
        return True
    return bool(_composition_current(scenario))


def _selected_source_collection_supports_merge_back(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> bool:
    selected_collection = _selected_source_collection(root_path, subject_id=scenario.subject_id, progress=progress)
    if selected_collection is None or _source_collection_is_default(selected_collection):
        return False
    if not _staged_sources_for_collection(root_path, collection=selected_collection):
        return False
    if int(getattr(scenario, "admitted_unit_count", 0) or 0) > 0:
        return True
    itemization_state = _itemization_state(root_path, scenario)
    if bool(itemization_state.get("exists")) and int(itemization_state.get("item_count", 0) or 0) > 0:
        return True
    review_state = _review_composition_state(root_path, scenario)
    if bool(review_state.get("exists")) and int(review_state.get("item_count", 0) or 0) > 0:
        return True
    return bool(_composition_current(scenario))


def _selected_source_collection_supports_source_merge_back(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> bool:
    selected_collection = _selected_source_collection(root_path, subject_id=scenario.subject_id, progress=progress)
    if selected_collection is None or _source_collection_is_default(selected_collection):
        return False
    staged_sources = _staged_sources_for_collection(root_path, collection=selected_collection)
    if not staged_sources:
        return False
    return _selected_source_collection_supports_merge_back(
        root_path,
        scenario=scenario,
        progress=progress,
    )


def _selected_staged_source(
    root_path: Path,
    *,
    subject_id: str,
    progress: SubjectProgress,
):
    _selected_collection, staged_sources = _staged_sources_for_selected_collection(
        root_path,
        subject_id=subject_id,
        progress=progress,
    )
    if not staged_sources:
        return None
    selected_id = collapse_ws(progress.research_selected_staged_source_id)
    if selected_id:
        for staged_source in staged_sources:
            if collapse_ws(staged_source.staged_source_id) == selected_id:
                return staged_source
    index = max(0, min(len(staged_sources) - 1, int(progress.research_source_cursor or 0)))
    return staged_sources[index]


def _ensure_research_source_selection_for_subject_id(
    root_path: Path,
    *,
    subject_id: str,
    progress: SubjectProgress,
) -> None:
    _selected_collection, staged_sources = _staged_sources_for_selected_collection(
        root_path,
        subject_id=subject_id,
        progress=progress,
    )
    if not staged_sources:
        progress.research_source_cursor = 0
        progress.research_selected_staged_source_id = ""
        progress.research_selected_source_revision_baseline_id = ""
        return
    selected_id = collapse_ws(progress.research_selected_staged_source_id)
    if selected_id:
        matched_index = next(
            (
                index
                for index, staged_source in enumerate(staged_sources)
                if collapse_ws(staged_source.staged_source_id) == selected_id
            ),
            None,
        )
        if matched_index is not None:
            progress.research_source_cursor = matched_index
            return
    index = max(0, min(len(staged_sources) - 1, int(progress.research_source_cursor or 0)))
    progress.research_source_cursor = index
    progress.research_selected_staged_source_id = collapse_ws(staged_sources[index].staged_source_id)
    progress.research_selected_source_revision_baseline_id = ""


def _ensure_research_source_selection(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> None:
    _ensure_research_source_selection_for_subject_id(
        root_path,
        subject_id=scenario.subject_id,
        progress=progress,
    )


def move_research_source_cursor(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    delta: int,
):
    _selected_collection, staged_sources = _staged_sources_for_selected_collection(
        root_path,
        subject_id=scenario.subject_id,
        progress=progress,
    )
    if not staged_sources:
        return None
    selected_id = collapse_ws(progress.research_selected_staged_source_id)
    if selected_id:
        current_index = next(
            (
                index
                for index, staged_source in enumerate(staged_sources)
                if collapse_ws(staged_source.staged_source_id) == selected_id
            ),
            max(0, min(len(staged_sources) - 1, int(progress.research_source_cursor or 0))),
        )
    else:
        current_index = max(0, min(len(staged_sources) - 1, int(progress.research_source_cursor or 0)))
    next_index = max(0, min(len(staged_sources) - 1, current_index + int(delta)))
    selected = staged_sources[next_index]
    progress.research_source_cursor = next_index
    progress.research_selected_staged_source_id = collapse_ws(selected.staged_source_id)
    progress.research_selected_source_revision_baseline_id = ""
    return selected


def _selected_staged_source_baseline_revision(
    root_path: Path,
    staged_source,
    *,
    progress: SubjectProgress,
):
    revisions = _ordered_staged_source_revisions(root_path, staged_source)
    if len(revisions) <= 1:
        return None
    baseline_candidates = tuple(revisions[1:])
    selected_revision_id = collapse_ws(progress.research_selected_source_revision_baseline_id)
    if selected_revision_id:
        for revision in baseline_candidates:
            if collapse_ws(revision.revision_id) == selected_revision_id:
                return revision
    return baseline_candidates[0]


def move_research_source_collection_cursor(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    delta: int,
):
    collections = list_source_collections(root_path, scenario.subject_id)
    if not collections:
        return None
    selected_id = collapse_ws(progress.research_selected_source_collection_id)
    if selected_id:
        current_index = next(
            (
                index
                for index, collection in enumerate(collections)
                if collapse_ws(collection.collection_id) == selected_id
            ),
            max(0, min(len(collections) - 1, int(progress.research_collection_cursor or 0))),
        )
    else:
        current_index = max(0, min(len(collections) - 1, int(progress.research_collection_cursor or 0)))
    next_index = max(0, min(len(collections) - 1, current_index + int(delta)))
    selected = collections[next_index]
    progress.research_collection_cursor = next_index
    progress.research_selected_source_collection_id = collapse_ws(selected.collection_id)
    progress.research_source_cursor = 0
    progress.research_selected_staged_source_id = ""
    progress.research_selected_source_revision_baseline_id = ""
    return selected


def _selected_staged_source_bundle_files(
    root_path: Path,
    staged_source,
) -> dict[str, bytes]:
    revision = latest_source_revision(root_path, staged_source)
    if revision is None:
        return {}
    bundle_root = staged_source_bundle_root(root_path, staged_source.subject_id, revision.revision_id)
    bundle_files: dict[str, bytes] = {}
    for relpath in revision.bundle_relpaths:
        normalized_relpath = str(relpath or "").strip()
        if not normalized_relpath:
            continue
        path = bundle_root / normalized_relpath
        if not path.is_file():
            continue
        bundle_files[normalized_relpath] = path.read_bytes()
    return bundle_files


def _selected_staged_source_markdown_preview(
    root_path: Path,
    staged_source,
    *,
    limit: int = 6,
) -> tuple[str, ...]:
    revision = latest_source_revision(root_path, staged_source)
    if revision is None:
        return ("- no revision body is available yet",)
    body_path = staged_source_body_path(root_path, staged_source.subject_id, revision.revision_id)
    if not body_path.is_file():
        return (f"- markdown body missing: {_ui_path_label(root_path, str(body_path))}",)
    lines: list[str] = []
    for raw_line in body_path.read_text(encoding="utf-8").splitlines():
        text = collapse_ws(raw_line)
        if not text:
            continue
        lines.append(f"- {text}")
        if len(lines) >= limit:
            break
    return tuple(lines or ("- markdown body is empty",))


def _ordered_staged_source_revisions(
    root_path: Path,
    staged_source,
) -> tuple:
    revisions = list_source_revisions(
        root_path,
        staged_source.subject_id,
        staged_source_id=staged_source.staged_source_id,
    )
    if not revisions:
        return ()
    revision_by_id = {
        collapse_ws(revision.revision_id): revision
        for revision in revisions
        if collapse_ws(revision.revision_id)
    }
    ordered: list = []
    seen: set[str] = set()
    current_id = collapse_ws(staged_source.latest_revision_id)
    while current_id and current_id not in seen:
        current_revision = revision_by_id.get(current_id)
        if current_revision is None:
            break
        ordered.append(current_revision)
        seen.add(current_id)
        current_id = collapse_ws(str(current_revision.metadata.get("previous_revision_id", "")))
    for revision in revisions:
        revision_id = collapse_ws(revision.revision_id)
        if revision_id and revision_id not in seen:
            ordered.append(revision)
    return tuple(ordered)


def _source_revision_markdown_text(
    root_path: Path,
    *,
    subject_id: str,
    revision_id: str,
) -> str:
    normalized_revision_id = collapse_ws(revision_id)
    if not normalized_revision_id:
        return ""
    body_path = staged_source_body_path(root_path, subject_id, normalized_revision_id)
    if not body_path.is_file():
        return ""
    return body_path.read_text(encoding="utf-8")


def _source_revision_markdown_preview_lines(
    root_path: Path,
    *,
    subject_id: str,
    revision_id: str,
    limit: int = 4,
) -> tuple[str, ...]:
    text = _source_revision_markdown_text(
        root_path,
        subject_id=subject_id,
        revision_id=revision_id,
    )
    if not collapse_ws(text):
        return ("- markdown body is empty",)
    lines: list[str] = []
    for raw_line in text.splitlines():
        normalized = collapse_ws(raw_line)
        if not normalized:
            continue
        lines.append(f"- {normalized}")
        if len(lines) >= limit:
            break
    return tuple(lines or ("- markdown body is empty",))


def _selected_staged_source_diff_summary_lines(
    root_path: Path,
    staged_source,
    *,
    baseline_revision=None,
) -> tuple[str, ...]:
    revisions = _ordered_staged_source_revisions(root_path, staged_source)
    if not revisions:
        return ("- no revision history is available yet",)
    latest_revision = revisions[0]
    previous_revision = baseline_revision if baseline_revision is not None else (revisions[1] if len(revisions) > 1 else None)
    if previous_revision is None:
        latest_text = _source_revision_markdown_text(
            root_path,
            subject_id=staged_source.subject_id,
            revision_id=latest_revision.revision_id,
        )
        latest_lines = tuple(collapse_ws(line) for line in latest_text.splitlines() if collapse_ws(line))
        return (
            f"- latest revision kind: {latest_revision.revision_kind}",
            f"- populated lines: {len(latest_lines)}",
            "- no prior revision exists yet",
        )
    latest_text = _source_revision_markdown_text(
        root_path,
        subject_id=staged_source.subject_id,
        revision_id=latest_revision.revision_id,
    )
    previous_text = _source_revision_markdown_text(
        root_path,
        subject_id=staged_source.subject_id,
        revision_id=previous_revision.revision_id,
    )
    latest_lines = tuple(collapse_ws(line) for line in latest_text.splitlines() if collapse_ws(line))
    previous_lines = tuple(collapse_ws(line) for line in previous_text.splitlines() if collapse_ws(line))
    added_lines: list[str] = []
    removed_lines: list[str] = []
    for line in difflib.ndiff(previous_lines, latest_lines):
        if line.startswith("+ "):
            added_lines.append(line[2:])
        elif line.startswith("- "):
            removed_lines.append(line[2:])
    meaningful_added_lines = [line for line in added_lines if not line.startswith("# ")]
    meaningful_removed_lines = [line for line in removed_lines if not line.startswith("# ")]
    lines: list[str] = [
        f"- revision flow: {previous_revision.revision_kind} → {latest_revision.revision_kind}",
        f"- populated lines: {len(previous_lines)} → {len(latest_lines)}",
        f"- lines added: {len(added_lines)}",
        f"- lines removed: {len(removed_lines)}",
    ]
    highlighted_added_lines = meaningful_added_lines or added_lines
    highlighted_removed_lines = meaningful_removed_lines or removed_lines
    if highlighted_added_lines:
        lines.append(f"- latest addition: {highlighted_added_lines[0]}")
    if highlighted_removed_lines:
        lines.append(f"- latest removal: {highlighted_removed_lines[0]}")
    return tuple(lines)


def _source_text_contains_any(source_text_key: str, *candidates: str) -> bool:
    normalized_key = collapse_ws(source_text_key).casefold()
    if not normalized_key:
        return False
    for candidate in candidates:
        normalized_candidate = collapse_ws(candidate).casefold()
        if normalized_candidate and normalized_candidate in normalized_key:
            return True
    return False


def _selected_staged_source_export_entries(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    staged_source,
    limit: int = 6,
) -> tuple[str, ...]:
    latest_revision = latest_source_revision(root_path, staged_source)
    latest_text = (
        _source_revision_markdown_text(
            root_path,
            subject_id=staged_source.subject_id,
            revision_id=latest_revision.revision_id,
        )
        if latest_revision is not None
        else ""
    )
    latest_text_key = collapse_ws(latest_text).casefold()
    proposal_entries: list[str] = []
    seen_entries: set[str] = set()

    def _append_entry(text: str) -> None:
        normalized = collapse_ws(text)
        if not normalized or normalized in seen_entries:
            return
        seen_entries.add(normalized)
        proposal_entries.append(normalized)

    if collapse_ws(scenario.summary) and not _source_text_contains_any(latest_text_key, scenario.summary):
        _append_entry(
            "subject summary note: "
            + textwrap.shorten(collapse_ws(scenario.summary), width=120, placeholder="...")
        )

    try:
        context = load_learning_context(root_path, scenario.subject_id)
    except Exception:
        context = None
    if context is not None:
        admitted_units = tuple(unit for unit in context.units if collapse_ws(unit.status) == "admitted")
        for unit in admitted_units[:6]:
            if len(proposal_entries) >= limit:
                break
            unit_label = collapse_ws(getattr(unit, "canonical_title", "")) or collapse_ws(
                getattr(unit, "unit_id", "")
            )
            unit_statement = collapse_ws(getattr(unit, "statement", ""))
            if _source_text_contains_any(latest_text_key, unit_label, unit_statement):
                continue
            if unit_label and unit_statement:
                _append_entry(
                    f"item note: {unit_label} — "
                    f"{textwrap.shorten(unit_statement, width=110, placeholder='...')}"
                )
            elif unit_label:
                _append_entry(f"item note: {unit_label}")

    try:
        itemized_items = list_itemized_subject_items(root_path, scenario.subject_id)
    except Exception:
        itemized_items = ()
    for item in itemized_items:
        if len(proposal_entries) >= limit:
            break
        if collapse_ws(getattr(item, "status", "")) not in {"candidate", "promoted"}:
            continue
        label = collapse_ws(getattr(item, "canonical_label", ""))
        summary = collapse_ws(getattr(item, "summary", ""))
        if not label or _source_text_contains_any(latest_text_key, label, summary):
            continue
        if summary:
            _append_entry(
                f"itemized note: {label} — "
                f"{textwrap.shorten(summary, width=105, placeholder='...')}"
            )
        else:
            _append_entry(f"itemized note: {label}")

    try:
        review_items = list_review_items(root_path, scenario.subject_id)
    except Exception:
        review_items = ()
    for item in review_items:
        if len(proposal_entries) >= limit:
            break
        if not bool(getattr(item, "included", False)):
            continue
        label = collapse_ws(str(getattr(item, "metadata", {}).get("canonical_label", ""))) or collapse_ws(
            getattr(item, "review_item_id", "")
        )
        notes = collapse_ws(getattr(item, "notes", ""))
        if not label or _source_text_contains_any(latest_text_key, label, notes):
            continue
        if notes:
            _append_entry(
                f"draft emphasis: {label} — "
                f"{textwrap.shorten(notes, width=100, placeholder='...')}"
            )
        else:
            _append_entry(f"draft emphasis: {label}")
    return tuple(proposal_entries[:limit])


def _selected_source_collection_export_targets(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    selected_collection,
    limit_sources: int | None = None,
    limit_entries: int = 6,
) -> tuple[tuple[object, tuple[str, ...]], ...]:
    staged_sources = _staged_sources_for_collection(root_path, collection=selected_collection)
    targets: list[tuple[object, tuple[str, ...]]] = []
    for staged_source in staged_sources:
        entries = _selected_staged_source_export_entries(
            root_path,
            scenario=scenario,
            progress=progress,
            staged_source=staged_source,
            limit=limit_entries,
        )
        if entries:
            targets.append((staged_source, entries))
        if limit_sources is not None and len(targets) >= max(1, int(limit_sources)):
            break
    return tuple(targets)


def _export_entry_key(entries: tuple[str, ...] | list[str]) -> tuple[str, ...]:
    return tuple(
        sorted(
            {
                collapse_ws(str(entry)).casefold()
                for entry in entries
                if collapse_ws(str(entry))
            }
        )
    )


def _export_entry_diff(
    current_entries: tuple[str, ...] | list[str],
    applied_entries: tuple[str, ...] | list[str],
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    current_map = {
        collapse_ws(str(entry)).casefold(): collapse_ws(str(entry))
        for entry in current_entries
        if collapse_ws(str(entry))
    }
    applied_map = {
        collapse_ws(str(entry)).casefold(): collapse_ws(str(entry))
        for entry in applied_entries
        if collapse_ws(str(entry))
    }
    added = tuple(current_map[key] for key in sorted(current_map.keys() - applied_map.keys()))
    removed = tuple(applied_map[key] for key in sorted(applied_map.keys() - current_map.keys()))
    return added, removed


def _latest_collection_export_applied_revision(
    root_path: Path,
    *,
    staged_source,
    collection_id: str,
):
    revisions = _ordered_staged_source_revisions(root_path, staged_source)
    return next(
        (
            revision
            for revision in revisions
            if collapse_ws(revision.revision_kind) == "merge"
            and collapse_ws(str(revision.metadata.get("merge_mode", ""))) == "deterministic_export_preview"
            and collapse_ws(str(revision.metadata.get("source_collection_id", ""))) == collapse_ws(collection_id)
        ),
        None,
    )


def _selected_source_collection_member_export_state(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    selected_collection,
    staged_source,
) -> tuple[str, tuple[str, ...], tuple[str, ...], object | None]:
    latest_revision = latest_source_revision(root_path, staged_source)
    current_entries = _selected_staged_source_export_entries(
        root_path,
        scenario=scenario,
        progress=progress,
        staged_source=staged_source,
        limit=12,
    )
    latest_export_revision = _latest_collection_export_applied_revision(
        root_path,
        staged_source=staged_source,
        collection_id=selected_collection.collection_id,
    )
    applied_entries = tuple(
        str(item)
        for item in latest_export_revision.metadata.get("export_entries", ())
        if collapse_ws(str(item))
    ) if latest_export_revision is not None else ()
    current_key = _export_entry_key(current_entries)
    applied_key = _export_entry_key(applied_entries)
    if current_key:
        if latest_export_revision is None:
            status = "pending"
        elif current_key == applied_key:
            status = "aligned"
        else:
            status = "changed"
    else:
        if latest_export_revision is None:
            status = "none"
        elif applied_entries:
            status = "aligned"
        else:
            status = (
                "aligned"
                if latest_revision is not None
                and collapse_ws(latest_revision.revision_id) == collapse_ws(latest_export_revision.revision_id)
                else "cleared"
            )
    return status, current_entries, applied_entries, latest_export_revision


def _selected_source_collection_has_export_targets(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    selected_collection,
) -> bool:
    if selected_collection is None or _source_collection_is_default(selected_collection):
        return False
    return bool(
        _selected_source_collection_export_targets(
            root_path,
            scenario=scenario,
            progress=progress,
            selected_collection=selected_collection,
            limit_sources=1,
            limit_entries=1,
        )
    )


def _selected_staged_source_has_export_entries(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    staged_source,
) -> bool:
    if staged_source is None:
        return False
    return bool(
        _selected_staged_source_export_entries(
            root_path,
            scenario=scenario,
            progress=progress,
            staged_source=staged_source,
            limit=1,
        )
    )


def _render_staged_source_governed_additions_markdown(
    current_text: str,
    *,
    entries: tuple[str, ...],
) -> str:
    existing_text = str(current_text or "").strip()
    if not entries:
        return (existing_text + "\n") if existing_text else ""
    rendered_entries = "\n".join(f"- {entry}" for entry in entries)
    section_heading = "## Governed learning additions"
    if not existing_text:
        return f"{section_heading}\n\n{rendered_entries}\n"
    if section_heading in existing_text:
        return f"{existing_text.rstrip()}\n{rendered_entries}\n"
    return f"{existing_text.rstrip()}\n\n{section_heading}\n\n{rendered_entries}\n"


def _selected_staged_source_export_proposal_lines(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    staged_source,
    limit: int = 6,
) -> tuple[str, ...]:
    latest_revision = latest_source_revision(root_path, staged_source)
    baseline_revision = _selected_staged_source_baseline_revision(
        root_path,
        staged_source,
        progress=progress,
    )
    selected_collection = _selected_source_collection(
        root_path,
        subject_id=scenario.subject_id,
        progress=progress,
    )
    itemization_state = _itemization_state(root_path, scenario)
    review_state = _review_composition_state(root_path, scenario)
    lines: list[str] = [
        "- proposed revision kind: merge",
        (
            f"- target latest revision: {latest_revision.revision_kind} / {latest_revision.revision_id}"
            if latest_revision is not None
            else "- target latest revision: <none>"
        ),
        (
            f"- selected diff baseline: {baseline_revision.revision_kind} / {baseline_revision.revision_id}"
            if baseline_revision is not None
            else "- selected diff baseline: <none>"
        ),
        f"- source set: {selected_collection.title if selected_collection is not None else 'All Gather Sources'}",
        f"- items considered: {int(scenario.admitted_unit_count or 0)}",
        f"- itemized candidates considered: {int(itemization_state.get('item_count', 0) or 0)}",
        f"- draft items considered: {int(review_state.get('item_count', 0) or 0)}",
        "- admission state: would remain staged source only",
        "- likely additions from current governed learnings:",
    ]
    proposal_entries = tuple(
        f"  - {entry}"
        for entry in _selected_staged_source_export_entries(
            root_path,
            scenario=scenario,
            progress=progress,
            staged_source=staged_source,
            limit=limit,
        )
    )

    if proposal_entries:
        lines.extend(proposal_entries)
    else:
        lines.append("  - no clear additions stand out beyond the current staged wording")
    return tuple(lines)


def _selected_source_collection_export_proposal_lines(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    selected_collection,
    limit: int = 8,
) -> tuple[str, ...]:
    staged_sources = _staged_sources_for_collection(root_path, collection=selected_collection)
    export_state_counts = {
        "pending": 0,
        "aligned": 0,
        "changed": 0,
        "cleared": 0,
        "none": 0,
    }
    for staged_source in staged_sources:
        status, _current_entries, _applied_entries, _latest_export_revision = _selected_source_collection_member_export_state(
            root_path,
            scenario=scenario,
            progress=progress,
            selected_collection=selected_collection,
            staged_source=staged_source,
        )
        export_state_counts[status] = export_state_counts.get(status, 0) + 1
    latest_text_key_parts: list[str] = []
    latest_revision_count = 0
    for staged_source in staged_sources:
        latest_revision = latest_source_revision(root_path, staged_source)
        if latest_revision is None:
            continue
        latest_revision_count += 1
        latest_text_key_parts.append(
            _source_revision_markdown_text(
                root_path,
                subject_id=staged_source.subject_id,
                revision_id=latest_revision.revision_id,
            )
        )
    latest_text_key = collapse_ws("\n".join(latest_text_key_parts)).casefold()
    itemization_state = _itemization_state(root_path, scenario)
    review_state = _review_composition_state(root_path, scenario)
    lines: list[str] = [
        "- proposed target: source-set metadata only",
        f"- source set: {selected_collection.title or selected_collection.collection_id}",
        f"- included staged sources: {len(selected_collection.staged_source_ids)}",
        f"- latest staged revisions considered: {latest_revision_count}",
        f"- members with pending first export: {export_state_counts.get('pending', 0)}",
        f"- members aligned with current export: {export_state_counts.get('aligned', 0)}",
        f"- members with changed export targets: {export_state_counts.get('changed', 0)}",
        f"- members with cleared export targets: {export_state_counts.get('cleared', 0)}",
        f"- items considered: {int(scenario.admitted_unit_count or 0)}",
        f"- itemized candidates considered: {int(itemization_state.get('item_count', 0) or 0)}",
        f"- draft items considered: {int(review_state.get('item_count', 0) or 0)}",
        "- admission state: would remain source-set metadata only",
        "- likely source-set notes/query additions from current governed learnings:",
    ]
    proposal_entries: list[str] = []
    seen_entries: set[str] = set()

    def _append_entry(text: str) -> None:
        normalized = collapse_ws(text)
        if not normalized or normalized in seen_entries:
            return
        seen_entries.add(normalized)
        proposal_entries.append(f"  - {normalized}")

    if collapse_ws(scenario.summary) and not _source_text_contains_any(latest_text_key, scenario.summary):
        _append_entry(
            f"subject framing: {textwrap.shorten(collapse_ws(scenario.summary), width=125, placeholder='...')}"
        )

    try:
        context = load_learning_context(root_path, scenario.subject_id)
    except Exception:
        context = None
    if context is not None:
        admitted_units = tuple(unit for unit in context.units if collapse_ws(unit.status) == "admitted")
        for unit in admitted_units[:6]:
            if len(proposal_entries) >= limit:
                break
            unit_label = collapse_ws(getattr(unit, "canonical_title", "")) or collapse_ws(getattr(unit, "unit_id", ""))
            unit_statement = collapse_ws(getattr(unit, "statement", ""))
            if _source_text_contains_any(latest_text_key, unit_label, unit_statement):
                continue
            if unit_label and unit_statement:
                _append_entry(
                    f"item signal: {unit_label} — "
                    f"{textwrap.shorten(unit_statement, width=110, placeholder='...')}"
                )
            elif unit_label:
                _append_entry(f"item signal: {unit_label}")

    try:
        itemized_items = list_itemized_subject_items(root_path, scenario.subject_id)
    except Exception:
        itemized_items = ()
    for item in itemized_items:
        if len(proposal_entries) >= limit:
            break
        if collapse_ws(getattr(item, "status", "")) not in {"candidate", "promoted"}:
            continue
        label = collapse_ws(getattr(item, "canonical_label", ""))
        summary = collapse_ws(getattr(item, "summary", ""))
        if not label or _source_text_contains_any(latest_text_key, label, summary):
            continue
        if summary:
            _append_entry(
                f"candidate coverage: {label} — "
                f"{textwrap.shorten(summary, width=105, placeholder='...')}"
            )
        else:
            _append_entry(f"candidate coverage: {label}")

    try:
        review_items = list_review_items(root_path, scenario.subject_id)
    except Exception:
        review_items = ()
    for item in review_items:
        if len(proposal_entries) >= limit:
            break
        if not bool(getattr(item, "included", False)):
            continue
        label = collapse_ws(str(getattr(item, "metadata", {}).get("canonical_label", ""))) or collapse_ws(
            getattr(item, "review_item_id", "")
        )
        notes = collapse_ws(getattr(item, "notes", ""))
        if not label or _source_text_contains_any(latest_text_key, label, notes):
            continue
        if notes:
            _append_entry(
                f"draft emphasis: {label} — "
                f"{textwrap.shorten(notes, width=100, placeholder='...')}"
            )
        else:
            _append_entry(f"draft emphasis: {label}")

    if proposal_entries:
        lines.extend(proposal_entries[:limit])
    else:
        lines.append("  - no clear additions stand out beyond the current source-set wording")
    return tuple(lines)


def _selected_source_collection_merge_export_history_lines(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    selected_collection,
    limit_events: int = 5,
) -> tuple[str, ...]:
    staged_sources = _staged_sources_for_collection(root_path, collection=selected_collection)
    if not staged_sources:
        return ("- no staged sources in this source set yet",)
    member_count = len(staged_sources)
    member_with_merge = 0
    total_merge_revisions = 0
    member_with_export_applied = 0
    total_export_applied_revisions = 0
    member_with_export_signal = 0
    member_with_aligned_export = 0
    member_with_changed_export = 0
    member_with_pending_export = 0
    member_with_cleared_export = 0
    latest_revision_events: list[tuple[int, str]] = []
    latest_export_events: list[tuple[int, str]] = []
    for staged_source in staged_sources:
        revisions = _ordered_staged_source_revisions(root_path, staged_source)
        export_status, _current_entries, _applied_entries, latest_export_revision = _selected_source_collection_member_export_state(
            root_path,
            scenario=scenario,
            progress=progress,
            selected_collection=selected_collection,
            staged_source=staged_source,
        )
        if export_status == "aligned":
            member_with_aligned_export += 1
        elif export_status == "changed":
            member_with_changed_export += 1
        elif export_status == "pending":
            member_with_pending_export += 1
        elif export_status == "cleared":
            member_with_cleared_export += 1
        merge_revisions = [
            revision for revision in revisions if collapse_ws(revision.revision_kind) == "merge"
        ]
        if merge_revisions:
            member_with_merge += 1
            total_merge_revisions += len(merge_revisions)
        latest_revision = revisions[0] if revisions else None
        if latest_revision is not None:
            timestamp = (
                time.strftime("%Y-%m-%d %H:%M", time.localtime(latest_revision.created_at_epoch_ms / 1000.0))
                if int(latest_revision.created_at_epoch_ms or 0) > 0
                else "unknown"
            )
            latest_revision_events.append(
                (
                    int(latest_revision.created_at_epoch_ms or 0),
                    f"- {staged_source.title or staged_source.staged_source_id} [{latest_revision.revision_kind}] at {timestamp}",
                )
            )
        export_applied_revisions = [
            revision
            for revision in revisions
            if collapse_ws(revision.revision_kind) == "merge"
            and collapse_ws(str(revision.metadata.get("merge_mode", ""))) == "deterministic_export_preview"
            and collapse_ws(str(revision.metadata.get("source_collection_id", "")))
            == collapse_ws(selected_collection.collection_id)
        ]
        if export_applied_revisions:
            member_with_export_applied += 1
            total_export_applied_revisions += len(export_applied_revisions)
            latest_export_revision = latest_export_revision or export_applied_revisions[0]
            export_timestamp = (
                time.strftime(
                    "%Y-%m-%d %H:%M",
                    time.localtime(latest_export_revision.created_at_epoch_ms / 1000.0),
                )
                if int(latest_export_revision.created_at_epoch_ms or 0) > 0
                else "unknown"
            )
            latest_export_events.append(
                (
                    int(latest_export_revision.created_at_epoch_ms or 0),
                    f"- {staged_source.title or staged_source.staged_source_id} [export] at {export_timestamp}",
                )
            )
        export_lines = _selected_staged_source_export_proposal_lines(
            root_path,
            scenario=scenario,
            progress=progress,
            staged_source=staged_source,
            limit=2,
        )
        if any(
            line.startswith("  - ")
            and "no clear additions stand out" not in line.casefold()
            for line in export_lines
        ):
            member_with_export_signal += 1
    lines: list[str] = [
        f"- member sources: {member_count}",
        f"- members with merge revisions: {member_with_merge}",
        f"- total merge revisions: {total_merge_revisions}",
        f"- members with export-applied revisions: {member_with_export_applied}",
        f"- total export-applied revisions: {total_export_applied_revisions}",
        f"- members with export signals: {member_with_export_signal}",
        f"- members aligned with current export: {member_with_aligned_export}",
        f"- members with changed export targets: {member_with_changed_export}",
        f"- members with pending first export: {member_with_pending_export}",
        f"- members with cleared export targets: {member_with_cleared_export}",
    ]
    collection_metadata = dict(getattr(selected_collection, "metadata", {}) or {})
    last_synced_at = int(collection_metadata.get("last_synced_at_epoch_ms", 0) or 0)
    if last_synced_at > 0:
        lines.append(
            "- last source-set sync: "
            + time.strftime("%Y-%m-%d %H:%M", time.localtime(last_synced_at / 1000.0))
        )
    last_merged_at = int(collection_metadata.get("last_merged_at_epoch_ms", 0) or 0)
    if last_merged_at > 0:
        lines.append(
            "- last source-set metadata merge-back: "
            + time.strftime("%Y-%m-%d %H:%M", time.localtime(last_merged_at / 1000.0))
        )
    last_export_applied_at = int(collection_metadata.get("last_export_applied_at_epoch_ms", 0) or 0)
    if last_export_applied_at > 0:
        lines.append(
            "- last export application: "
            + time.strftime("%Y-%m-%d %H:%M", time.localtime(last_export_applied_at / 1000.0))
        )
    if latest_revision_events:
        lines.append("- recent member revision events:")
        for _timestamp, rendered in sorted(latest_revision_events, key=lambda item: (-item[0], item[1]))[
            : max(1, int(limit_events))
        ]:
            lines.append(f"  {rendered}")
    if latest_export_events:
        lines.append("- recent export events:")
        for _timestamp, rendered in sorted(latest_export_events, key=lambda item: (-item[0], item[1]))[
            : max(1, int(limit_events))
        ]:
            lines.append(f"  {rendered}")
    return tuple(lines)


def _subject_source_refs(root_path: Path, subject_id: str) -> tuple[str, ...]:
    def _load() -> tuple[str, ...]:
        source_root = learning_context_paths(root_path, subject_id)["sources"]
        if not source_root.exists():
            return ()
        refs: list[str] = []
        seen: set[str] = set()
        for path in sorted(source_root.glob("*.json")):
            try:
                source = load_learning_source(root_path, subject_id, path.stem)
            except Exception:
                continue
            for candidate in (source.source_ref, source.body_relpath):
                normalized = collapse_ws(str(candidate))
                if not normalized or normalized in seen:
                    continue
                seen.add(normalized)
                refs.append(normalized)
        return tuple(refs)

    return _subject_workflow_cached_read(("_subject_source_refs", root_path, collapse_ws(subject_id)), _load)


def _dst_fixture_for_subject(root_path: Path, scenario: SubjectScenario):
    def _load():
        if scenario.is_placeholder or not collapse_ws(scenario.subject_id):
            return None
        return match_dst_fixture_for_source_refs(_subject_source_refs(root_path, scenario.subject_id))

    return _subject_workflow_cached_read(("_dst_fixture_for_subject", root_path, scenario), _load)


def _project_dst_fixture_construct_candidates(
    fixture,
    *,
    selected_item: ItemizedSubjectItem,
    build_epoch_ms: int,
) -> tuple[TransformationConstructCandidate, ...]:
    discovery = discovery_result_from_fixture(fixture)
    normalized_case = normalized_case_from_fixture(fixture, discovery)
    projection = project_normalized_case_to_transformation_construct_candidates(
        normalized_case,
        subject_id=selected_item.subject_id,
        itemized_item_id=selected_item.itemized_item_id,
        source_refs=selected_item.source_refs,
        build_epoch_ms=build_epoch_ms,
    )
    return projection.candidates


def _run_live_dst_construct_discovery_with_timeout(
    selected_item: ItemizedSubjectItem,
    *,
    subject_title: str,
    subject_summary: str,
    subject_source_refs: tuple[str, ...],
    supporting_items: tuple[ItemizedSubjectItem, ...],
    subject_scope: dict[str, object],
    subject_scope_root_path: Path,
    build_epoch_ms: int,
    timeout_seconds: float | None = None,
):
    result_queue: Queue[tuple[str, object]] = Queue(maxsize=1)

    def _worker() -> None:
        try:
            result = run_live_dst_construct_discovery_for_itemized_item(
                selected_item,
                subject_title=subject_title,
                subject_summary=subject_summary,
                subject_source_refs=subject_source_refs,
                supporting_items=supporting_items,
                llm_policy="required",
                subject_scope=subject_scope,
                subject_scope_root_path=subject_scope_root_path,
                build_epoch_ms=build_epoch_ms,
            )
            result_queue.put_nowait(("ok", result))
        except Exception as exc:  # pragma: no cover - exercised through caller fallback
            result_queue.put_nowait(("error", exc))

    effective_timeout_seconds = (
        _LIVE_DST_CONSTRUCT_DISCOVERY_TIMEOUT_SECONDS
        if timeout_seconds is None
        else max(0.0, float(timeout_seconds))
    )
    worker = threading.Thread(target=_worker, daemon=True)
    worker.start()
    worker.join(effective_timeout_seconds)
    if worker.is_alive():
        return None, "timed_out"
    if result_queue.empty():
        return None, "empty"
    status, payload = result_queue.get_nowait()
    if status == "ok":
        return payload, ""
    return None, collapse_ws(str(payload)) or "error"


def _unit_preview_lines(context: LearningContext, *, limit: int = 8) -> tuple[str, ...]:
    admitted_units = sorted(
        (unit for unit in context.units if unit.status == "admitted"),
        key=lambda item: (item.unit_kind, item.canonical_title, item.unit_id),
    )
    lines = [
        f"- [{unit.unit_kind}] {unit.canonical_title or unit.unit_id}"
        for unit in admitted_units[:limit]
    ]
    if len(admitted_units) > limit:
        lines.append(f"- ... {len(admitted_units) - limit} more items")
    return tuple(lines)


def _delta_preview_lines(root_path: Path, subject_id: str, *, limit: int = 6) -> tuple[str, ...]:
    delta_root = learning_context_paths(root_path, subject_id)["deltas"]
    if not delta_root.exists():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return ()
    delta_paths = sorted(delta_root.glob("*.json"), key=lambda item: item.stat().st_mtime, reverse=True)
    lines: list[str] = []
    for path in delta_paths[:limit]:
        payload = _read_json(path)
        rationale = collapse_ws(str(payload.get("rationale", "")))
        status = collapse_ws(str(payload.get("status", ""))) or "unknown"
        label = path.stem
        if rationale:
            lines.append(f"- {label} [{status}] {textwrap.shorten(rationale, width=120, placeholder='...')}")
        else:
            lines.append(f"- {label} [{status}]")
    return tuple(lines)


