def _review_operation_guide_lines(*, scenario: SubjectScenario, progress: SubjectProgress) -> list[str]:
    lines = [
        "How To Use Review",
        f"- 1. {_COMPARE_MAINTAINED_FILES_LABEL}: check subject.md against subject.typ.",
    ]
    composition_label = _REFRESH_REPORT_PLAN_LABEL if _composition_current(scenario) else _DRAFT_REPORT_PLAN_LABEL
    lines.append(f"- 2. {composition_label}: create or refresh the report plan from the current subject snapshot.")
    lines.append(f"- 3. {_PREVIEW_REPORT_PLAN_LABEL}: inspect the current report plan.")
    lines.append("- 4. Change Diff Baseline: choose the comparison reference (last approved plan, previous revision, or current subject snapshot).")
    lines.append(f"- 5. {_PREVIEW_REPORT_PLAN_DIFF_LABEL}: compare the current report plan against the selected diff baseline.")
    lines.append("- 6. Report Scope: use the tree to include or exclude items, support, and sections directly.")
    lines.append("- 7. Up/Down moves through the Report Scope tree, X toggles inclusion when available, and Enter previews the selected item.")
    lines.append("- 8. Change Selected Support Use: for an included support item, cycle quickly or choose an exact report use from More Actions.")
    lines.append("- 9. Approve For Report: approve the current report plan so Publication can lock and build it.")
    if not progress.context_opened:
        lines.append("- Start here: Open Subject Context.")
