def _report_section_help_text(section_id: str, role: str, title: str) -> str:
    normalized_role = collapse_ws(role).casefold()
    if normalized_role == "summary":
        return "Lead with the most important findings for a reader who needs the result quickly."
    if normalized_role == "reference":
        return "Explain core definitions and stable concepts the rest of the report depends on."
    if normalized_role == "analysis":
        return "Carry the main body of reasoning, interpretation, and structured evidence."
    if normalized_role == "evidence":
        return "Show supporting examples, calculations, and traceable support without crowding the main narrative."
    if normalized_role == "appendix":
        return "Keep implementation notes and lower-priority support out of the main reading path."
    return f"Section {title} ({section_id}) is part of the current report structure."


def _composition_section_guidance(
    composition: PublicationComposition | None,
    *,
    section_id: str,
) -> tuple[str, str]:
    if composition is None:
        return "", ""
    guidance_by_id = composition.metadata.get(_PUBLICATION_SECTION_GUIDANCE_KEY, {})
    if not isinstance(guidance_by_id, dict):
        return "", ""
    raw_entry = guidance_by_id.get(collapse_ws(section_id), {})
    if not isinstance(raw_entry, dict):
        return "", ""
    label = collapse_ws(str(raw_entry.get("label", "")))
    text = str(raw_entry.get("text", "")).strip()
    return label, text


def _composition_metadata_with_section_guidance(
    metadata: dict[str, object],
    *,
    section_id: str,
    label: str,
    text: str,
    mode: str,
    build_epoch_ms: int,
) -> dict[str, object]:
    updated = dict(metadata)
    guidance_by_id = updated.get(_PUBLICATION_SECTION_GUIDANCE_KEY, {})
    if not isinstance(guidance_by_id, dict):
        guidance_by_id = {}
    else:
        guidance_by_id = dict(guidance_by_id)
    normalized_section_id = collapse_ws(section_id)
    if not normalized_section_id:
        return updated
    normalized_label = collapse_ws(label)
    normalized_text = str(text or "").strip()
    if normalized_text:
        guidance_by_id[normalized_section_id] = {
            "label": normalized_label,
            "text": normalized_text,
            "mode": collapse_ws(mode) or "manual",
            "updated_at_epoch_ms": int(build_epoch_ms or 0),
        }
    else:
        guidance_by_id.pop(normalized_section_id, None)
    if guidance_by_id:
        updated[_PUBLICATION_SECTION_GUIDANCE_KEY] = guidance_by_id
    else:
        updated.pop(_PUBLICATION_SECTION_GUIDANCE_KEY, None)
    return updated


