def _composition_metadata_with_scope_orders(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    composition: PublicationComposition | None,
    context: LearningContext | None = None,
    unit_order_ids: tuple[str, ...] | None = None,
    import_order_ids: tuple[str, ...] | None = None,
    section_order_ids: tuple[str, ...] | None = None,
) -> dict[str, object]:
    active_context = context or load_learning_context(root_path, scenario.subject_id)
    existing_metadata = dict(composition.metadata) if composition is not None else {}
    existing_unit_order = (
        _composition_unit_order_ids(active_context, composition)
        if composition is not None
        else tuple(unit.unit_id for unit in _admitted_units_in_context_order(active_context))
    )
    existing_import_order = (
        _composition_import_order_ids(root_path, scenario.subject_id, composition)
        if composition is not None
        else tuple(
            subject_import.import_id
            for subject_import in sorted(
                _active_subject_imports(root_path, scenario.subject_id),
                key=lambda item: (
                    collapse_ws(item.source_subject_title) or collapse_ws(item.source_subject_id),
                    collapse_ws(item.import_id),
                ),
            )
        )
    )
    existing_section_order = (
        _composition_section_order_ids(composition)
        if composition is not None
        else tuple(section_id for section_id, _role, _title in report_section_specs())
    )
    existing_metadata[_REPORT_SCOPE_UNIT_ORDER_KEY] = list(unit_order_ids or existing_unit_order)
    existing_metadata[_REPORT_SCOPE_IMPORT_ORDER_KEY] = list(import_order_ids or existing_import_order)
    existing_metadata[_REPORT_SCOPE_SECTION_ORDER_KEY] = list(section_order_ids or existing_section_order)
    return existing_metadata


def _composition_with_metadata(composition: PublicationComposition, metadata: dict[str, object]) -> PublicationComposition:
    return PublicationComposition.from_dict(
        {
            **composition.to_dict(),
            "metadata": metadata,
        }
    )


def _report_scope_lane_order_ids(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    composition: PublicationComposition,
    context: LearningContext,
    kind: str,
) -> tuple[str, ...]:
    normalized_kind = collapse_ws(kind)
    if (
        progress.report_scope_preview_order_ids
        and collapse_ws(progress.report_scope_held_item_kind) == normalized_kind
    ):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        if normalized_kind == "unit":
            base_ids = tuple(unit.unit_id for unit in _admitted_units_in_context_order(context))
        elif normalized_kind == "import":
            base_ids = tuple(
                subject_import.import_id
                for subject_import in sorted(
                    _active_subject_imports(root_path, scenario.subject_id),
                    key=lambda item: (
                        collapse_ws(item.source_subject_title) or collapse_ws(item.source_subject_id),
                        collapse_ws(item.import_id),
                    ),
                )
            )
        elif normalized_kind == "section":
            base_ids = tuple(section_id for section_id, _role, _title in report_section_specs())
        else:
            base_ids = ()
        return _ordered_scope_ids(base_ids, progress.report_scope_preview_order_ids)
    if normalized_kind == "unit":
        return _composition_unit_order_ids(context, composition)
    if normalized_kind == "import":
        return _composition_import_order_ids(root_path, scenario.subject_id, composition)
    if normalized_kind == "section":
        return _composition_section_order_ids(composition)
    return ()


def _set_report_scope_cursor_to_entry_id(
    progress: SubjectProgress,
    entries: tuple[SubjectReportScopeEntry, ...],
    entry_id: str,
) -> None:
    normalized_entry_id = collapse_ws(entry_id)
    selectable_entries = _selectable_report_scope_entries(entries)
    for index, entry in enumerate(selectable_entries):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        if collapse_ws(entry.entry_id) == normalized_entry_id:
            progress.report_scope_cursor = index
            return


def _next_same_lane_report_scope_entry_id(
    entries: tuple[SubjectReportScopeEntry, ...],
    *,
    current_entry_id: str,
    item_kind: str,
    held_entry_ids: tuple[str, ...] | list[str],
) -> str:
    normalized_current = collapse_ws(current_entry_id)
    held_ids = {collapse_ws(item) for item in held_entry_ids if collapse_ws(item)}
    selectable_entries = _selectable_report_scope_entries(entries)
    current_index = next(
        (index for index, entry in enumerate(selectable_entries) if collapse_ws(entry.entry_id) == normalized_current),
        -1,
    )
    if current_index < 0:
        return normalized_current
    lane_entries = [
        entry
        for entry in selectable_entries
        if collapse_ws(entry.item_kind) == collapse_ws(item_kind)
    ]
    lane_index_by_id = {
        collapse_ws(entry.entry_id): index
        for index, entry in enumerate(lane_entries)
    }
    lane_current_index = lane_index_by_id.get(normalized_current, -1)
    if lane_current_index < 0:
        return normalized_current
    for next_entry in lane_entries[lane_current_index + 1 :]:
        if collapse_ws(next_entry.entry_id) not in held_ids:
            return collapse_ws(next_entry.entry_id)
    if len(held_ids) > 1:
        return normalized_current
    for next_entry in lane_entries[:lane_current_index]:
        if collapse_ws(next_entry.entry_id) not in held_ids:
            return collapse_ws(next_entry.entry_id)
    for next_entry in selectable_entries[current_index + 1 :]:
        if collapse_ws(next_entry.entry_id) not in held_ids:
            return collapse_ws(next_entry.entry_id)
    for next_entry in selectable_entries[:current_index]:
        if collapse_ws(next_entry.entry_id) not in held_ids:
            return collapse_ws(next_entry.entry_id)
    return normalized_current


def _move_held_report_scope_lane(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    composition: PublicationComposition,
    context: LearningContext,
    delta: int,
    selected_entry_id: str,
) -> tuple[str, ...]:
    kind = collapse_ws(progress.report_scope_held_item_kind)
    current_order = list(
        _report_scope_lane_order_ids(
            root_path,
            scenario=scenario,
            progress=progress,
            composition=composition,
            context=context,
            kind=kind,
        )
    )
    held_target_ids = {
        _report_scope_entry_target_id(item)
        for item in progress.report_scope_held_entry_ids
        if collapse_ws(item)
    }
    held_ids = [item_id for item_id in current_order if item_id in held_target_ids]
    if not current_order or not held_ids:
        return tuple(current_order)
    residual = [item_id for item_id in current_order if item_id not in set(held_ids)]
    if progress.report_scope_preview_order_ids:
        anchor_index = next((index for index, item_id in enumerate(current_order) if item_id in set(held_ids)), 0)
    else:
        first_held_index = next((index for index, item_id in enumerate(current_order) if item_id in set(held_ids)), 0)
        anchor_index = sum(1 for item_id in current_order[:first_held_index] if item_id not in set(held_ids))
    target_index = max(0, min(len(residual), anchor_index + int(delta)))
    preview_order = tuple([*residual[:target_index], *held_ids, *residual[target_index:]])
    progress.report_scope_preview_order_ids = list(preview_order)
    preview_entries = _report_scope_entries(root_path, scenario=scenario, progress=progress)
    _set_report_scope_cursor_to_entry_id(progress, preview_entries, selected_entry_id)
    return preview_order


def _ordered_members_from_lane(
    lane_order_ids: tuple[str, ...] | list[str],
    member_ids: tuple[str, ...] | list[str] | set[str],
) -> tuple[str, ...]:
    member_set = {collapse_ws(item) for item in member_ids if collapse_ws(item)}
    return tuple(item_id for item_id in lane_order_ids if collapse_ws(item_id) in member_set)


def _report_scope_entries(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> tuple[SubjectReportScopeEntry, ...]:
    composition = _latest_publication_composition(
        root_path,
        subject_id=scenario.subject_id,
        subject_title=scenario.title,
        publication_id=scenario.publication_id,
    )
    if composition is None:
        return ()
    try:
        context = load_learning_context(root_path, scenario.subject_id)
    except Exception:
        return ()
    entries: list[SubjectReportScopeEntry] = []
    entries.append(
        SubjectReportScopeEntry(
            entry_id="heading:units",
            item_kind="heading",
            label=f"Items ({len(_admitted_units_in_context_order(context))})",
            selectable=False,
        )
    )
    admitted_unit_by_id = {
        unit.unit_id: unit
        for unit in _admitted_units_in_context_order(context)
    }
    reportable_unit_ids = {
        unit.unit_id
        for unit in admitted_unit_by_id.values()
        if publication_statement_is_reportable(unit.statement, unit_kind=unit.unit_kind)
    }
    included_unit_ids = {
        unit_id
        for unit_id in composition.included_unit_ids
        if unit_id in reportable_unit_ids
    }
    admitted_units = tuple(
        admitted_unit_by_id[unit_id]
        for unit_id in _report_scope_lane_order_ids(
            root_path,
            scenario=scenario,
            progress=progress,
            composition=composition,
            context=context,
            kind="unit",
        )
        if unit_id in admitted_unit_by_id
    )
    if admitted_units:
        for unit in admitted_units:
            title = collapse_ws(unit.canonical_title) or unit.unit_id
            reportable = publication_statement_is_reportable(unit.statement, unit_kind=unit.unit_kind)
            included = unit.unit_id in included_unit_ids
            toggleable = reportable and not (included and len(included_unit_ids) <= 1)
            label = f"[q] {title} [question]" if not reportable else title
            entries.append(
                SubjectReportScopeEntry(
                    entry_id=f"unit:{unit.unit_id}",
                    item_kind="unit",
                    label=label,
                    depth=1,
                    selectable=reportable,
                    toggleable=toggleable,
                    included=included,
                    reportable=reportable,
                    detail_title=title,
                    detail_rows=(
                        ("Type", "Item"),
                        ("Kind", unit.unit_kind),
                        ("Usable in report", "yes" if reportable else "no (question)"),
                        ("Included in report", "yes" if included else "no"),
                        ("Statement", collapse_ws(unit.statement) or "<no statement>"),
                        ("Provenance refs", ", ".join(unit.provenance_refs) or "<none>"),
                    ),
                    detail_lines=(
                        "Type: Item",
                        f"Kind: {unit.unit_kind}",
                        f"Usable in report: {'yes' if reportable else 'no (question)'}",
                        f"Included in report: {'yes' if included else 'no'}",
                        "",
                        "Statement",
                        collapse_ws(unit.statement) or "<no statement>",
                        "",
                        f"Provenance refs: {', '.join(unit.provenance_refs) or '<none>'}",
                        "",
                        "Controls",
                        (
                            "- This question stays out of the report."
                            if not reportable
                            else
                            (
                            "- X includes or removes this item."
                            if toggleable
                            else "- This item must stay in the report."
                            )
                        ),
                        "- Enter copies this preview into the Review receipt.",
                    ),
                )
            )
    else:
        entries.append(
            SubjectReportScopeEntry(
                entry_id="empty:units",
                item_kind="empty",
                label="No items are available yet.",
                depth=1,
                selectable=False,
            )
        )

    active_import_by_id = {
        subject_import.import_id: subject_import
        for subject_import in _active_subject_imports(root_path, scenario.subject_id)
    }
    active_imports = tuple(
        active_import_by_id[import_id]
        for import_id in _report_scope_lane_order_ids(
            root_path,
            scenario=scenario,
            progress=progress,
            composition=composition,
            context=context,
            kind="import",
        )
        if import_id in active_import_by_id
    )
    included_import_ids = set(composition.selected_subject_import_ids)
    entries.append(
        SubjectReportScopeEntry(
            entry_id="heading:imports",
            item_kind="heading",
            label=f"Support ({len(active_imports)})",
            selectable=False,
        )
    )
    if active_imports:
        for subject_import in active_imports:
            source_title = collapse_ws(subject_import.source_subject_title) or subject_import.source_subject_id
            current_mode = _publication_import_usage_label(
                composition.import_usage_by_id.get(subject_import.import_id, "dependency_only")
            )
            included = subject_import.import_id in included_import_ids
            entries.append(
                SubjectReportScopeEntry(
                    entry_id=f"import:{subject_import.import_id}",
                    item_kind="import",
                    label=f"{source_title}{f' [{current_mode}]' if included else ''}",
                    depth=1,
                    toggleable=True,
                    included=included,
                    detail_title=source_title,
                    detail_rows=(
                        ("Type", "Support"),
                        ("Included in report", "yes" if included else "no"),
                        (
                            "Current report use",
                            current_mode if included else "not selected for the report",
                        ),
                        ("Bounded scope", _subject_import_scope_text(subject_import)),
                        (
                            "Selection profile",
                            _subject_import_selection_label(
                                str(subject_import.metadata.get("selection_profile", ""))
                            ),
                        ),
                        ("Version pin", subject_import.source_subject_version_id or "<unpinned>"),
                    ),
                    detail_lines=(
                        "Type: Support",
                        f"Included in report: {'yes' if included else 'no'}",
                        f"Current report use: {current_mode if included else 'not selected for the report'}",
                        f"Bounded scope: {_subject_import_scope_text(subject_import)}",
                        f"Selection profile: {_subject_import_selection_label(str(subject_import.metadata.get('selection_profile', '')))}",
                        f"Version pin: {subject_import.source_subject_version_id or '<unpinned>'}",
                        "Available report uses: dependency only, background only, comparison, transcluded support",
                        "",
                        "Controls",
                        "- X includes or removes this support.",
                        "- Change Selected Support Use cycles quickly through the available uses.",
                        "- Use More Actions to set the exact report use directly.",
                        "- Enter copies this preview into the Review receipt.",
                    ),
                )
            )
    else:
        entries.append(
            SubjectReportScopeEntry(
                entry_id="empty:imports",
                item_kind="empty",
                label="No approved support is available.",
                depth=1,
                selectable=False,
            )
        )

    section_spec_by_id = _report_section_spec_by_id()
    selected_section_ids = set(composition.section_ids)
    entries.append(
        SubjectReportScopeEntry(
            entry_id="heading:sections",
            item_kind="heading",
            label=f"Report sections ({len(section_spec_by_id)})",
            selectable=False,
        )
    )
    for section_id in _report_scope_lane_order_ids(
        root_path,
        scenario=scenario,
        progress=progress,
        composition=composition,
        context=context,
        kind="section",
    ):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        if section_id not in section_spec_by_id:
            continue
        role, title = section_spec_by_id[section_id]
        included = section_id in selected_section_ids
        toggleable = not (included and len(selected_section_ids) <= 1)
        guidance_label, guidance_text = _composition_section_guidance(composition, section_id=section_id)
        entries.append(
            SubjectReportScopeEntry(
                entry_id=f"section:{section_id}",
                item_kind="section",
                label=f"{title} ({role})",
                depth=1,
                toggleable=toggleable,
                included=included,
                detail_title=title,
                detail_rows=(
                    ("Type", "Report section"),
                    ("Included in report", "yes" if included else "no"),
                    ("Role", role),
                    ("Purpose", _report_section_help_text(section_id, role, title)),
                    *(
                        (
                            ("Section brief", guidance_label or "<untitled>"),
                            ("Brief text", guidance_text),
                        )
                        if guidance_text
                        else ()
                    ),
                ),
                detail_lines=(
                    "Type: Report section",
                    f"Included in report: {'yes' if included else 'no'}",
                    f"Role: {role}",
                    f"Purpose: {_report_section_help_text(section_id, role, title)}",
                    *(
                        [
                            f"Section brief: {guidance_label or '<untitled>'}",
                            guidance_text,
                            "",
                        ]
                        if guidance_text
                        else []
                    ),
                    "",
                    "Controls",
                    (
                        "- X toggles whether this section appears in the report plan."
                        if toggleable
                        else "- This section is currently required because the report plan must keep at least one section."
                    ),
                    "- @llm drafts a section brief for the selected report section.",
                    "- = opens manual section-brief editing for the selected report section.",
                    "- Enter copies this section preview into the Review receipt.",
                ),
            )
        )
    selected_entry = _selected_report_scope_entry(entries, progress)
    if selected_entry is not None:
        _sync_report_scope_selection(progress, selected_entry, context=context, active_imports=active_imports)
    return tuple(entries)


def _selectable_report_scope_entries(
    entries: tuple[SubjectReportScopeEntry, ...],
) -> tuple[SubjectReportScopeEntry, ...]:
    return tuple(entry for entry in entries if entry.selectable)


def _selected_report_scope_entry(
    entries: tuple[SubjectReportScopeEntry, ...],
    progress: SubjectProgress,
) -> SubjectReportScopeEntry | None:
    selectable_entries = _selectable_report_scope_entries(entries)
    if not selectable_entries:
        return None
    index = max(0, min(len(selectable_entries) - 1, int(progress.report_scope_cursor or 0)))
    return selectable_entries[index]


def _selected_report_scope_section_entry(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> tuple[PublicationComposition, SubjectReportScopeEntry, str, str, str] | None:
    composition = _latest_current_publication_composition(root_path, scenario=scenario)
    if composition is None:
        return None
    entries = _report_scope_entries(root_path, scenario=scenario, progress=progress)
    selected_entry = _selected_report_scope_entry(entries, progress)
    if selected_entry is None or selected_entry.item_kind != "section":
        return None
    section_id = collapse_ws(selected_entry.entry_id.split(":", 1)[-1])
    role, title = _report_section_spec_by_id().get(section_id, ("", selected_entry.detail_title or selected_entry.label))
    return composition, selected_entry, section_id, role, title


def _sync_report_scope_selection(
    progress: SubjectProgress,
    entry: SubjectReportScopeEntry,
    *,
    context: LearningContext,
    active_imports: tuple[SubjectImport, ...],
) -> None:
    if entry.item_kind == "unit":
        target_unit_id = entry.entry_id.split(":", 1)[-1]
        admitted_units = _admitted_units_in_context_order(context)
        for index, unit in enumerate(admitted_units):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
            if collapse_ws(unit.unit_id) == collapse_ws(target_unit_id):
                progress.composition_unit_cursor = index
                break
    if entry.item_kind == "import":
        target_import_id = entry.entry_id.split(":", 1)[-1]
        for index, subject_import in enumerate(active_imports):
            if collapse_ws(subject_import.import_id) == collapse_ws(target_import_id):
                progress.composition_import_cursor = index
                break


def move_report_scope_cursor(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    delta: int,
) -> SubjectReportScopeEntry | None:
    entries = _report_scope_entries(root_path, scenario=scenario, progress=progress)
    selectable_entries = _selectable_report_scope_entries(entries)
    if not selectable_entries:
        return None
    current_index = max(0, min(len(selectable_entries) - 1, int(progress.report_scope_cursor or 0)))
    progress.report_scope_cursor = max(
        0,
        min(len(selectable_entries) - 1, current_index + int(delta)),
    )
    selected_entry = selectable_entries[progress.report_scope_cursor]
    try:
        context = load_learning_context(root_path, scenario.subject_id)
    except Exception:
        return selected_entry
    _sync_report_scope_selection(
        progress,
        selected_entry,
        context=context,
        active_imports=tuple(
            sorted(
                _active_subject_imports(root_path, scenario.subject_id),
                key=lambda item: (
                    collapse_ws(item.source_subject_title) or collapse_ws(item.source_subject_id),
                    collapse_ws(item.import_id),
                ),
            )
        ),
    )
    return selected_entry


def preview_move_held_report_scope_items(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    delta: int,
) -> SubjectReportScopeEntry | None:
    entries = _report_scope_entries(root_path, scenario=scenario, progress=progress)
    selectable_entries = _selectable_report_scope_entries(entries)
    if not selectable_entries:
        return None
    current_entry = _selected_report_scope_entry(entries, progress)
    held_entry_ids = {collapse_ws(item) for item in progress.report_scope_held_entry_ids if collapse_ws(item)}
    if (
        current_entry is None
        or collapse_ws(progress.report_scope_held_item_kind) not in _REPORT_SCOPE_REORDERABLE_KINDS
        or collapse_ws(current_entry.entry_id) not in held_entry_ids
        or collapse_ws(current_entry.item_kind) != collapse_ws(progress.report_scope_held_item_kind)
    ):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return None
    composition = _latest_publication_composition(
        root_path,
        subject_id=scenario.subject_id,
        subject_title=scenario.title,
        publication_id=scenario.publication_id,
    )
    if composition is None:
        return None
    try:
        context = load_learning_context(root_path, scenario.subject_id)
    except Exception:
        return None
    _move_held_report_scope_lane(
        root_path,
        scenario=scenario,
        progress=progress,
        composition=composition,
        context=context,
        delta=delta,
        selected_entry_id=current_entry.entry_id,
    )
    entries = _report_scope_entries(root_path, scenario=scenario, progress=progress)
    return _selected_report_scope_entry(entries, progress)


def render_subject_report_scope_tree(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder:
        return "\n".join(
            [
                "No report plan is available yet.",
                "",
                "Create a subject first, then align the maintained files and create the report plan.",
            ]
        )
    root_path = _root_path_from_scenario(scenario)
    entries = _report_scope_entries(root_path, scenario=scenario, progress=progress)
    composition = _latest_publication_composition(
        root_path,
        subject_id=scenario.subject_id,
        subject_title=scenario.title,
        publication_id=scenario.publication_id,
    )
    if composition is None:
        return "\n".join(
            [
                "No report plan exists yet.",
                "",
                "Create Report Plan to load the selectable scope for items, support, and sections.",
            ]
        )
    selected_entry = _selected_report_scope_entry(entries, progress)
    selected_entry_id = collapse_ws(selected_entry.entry_id) if selected_entry is not None else ""
    held_entry_ids = {collapse_ws(item) for item in progress.report_scope_held_entry_ids if collapse_ws(item)}
    lines = [
        "Question-shaped items are tagged [question] and excluded from report output.",
        "",
    ]
    for entry in entries:
        prefix = "  " * max(0, int(entry.depth))
        if entry.selectable:
            pointer = "> " if collapse_ws(entry.entry_id) == selected_entry_id else "  "
            held_flag = "h " if collapse_ws(entry.entry_id) in held_entry_ids else "  "
            if entry.toggleable:
                checkbox = "[x]" if entry.included else "[ ]"
            else:
                checkbox = "[-]" if entry.included else "[ ]"
            lines.append(f"{pointer}{held_flag}{prefix}{checkbox} {entry.label}")
        else:
            lines.append(f"{prefix}{entry.label}")
    lines.extend(
        [
            "",
            f"Report plan status: {composition.status}",
            f"Snapshot current: {'yes' if _composition_current(scenario) else 'no'}",
        ]
    )
    return "\n".join(lines)


def render_subject_report_scope_detail(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder:
        return "Select or create a subject to start shaping the report."
    root_path = _root_path_from_scenario(scenario)
    entries = _report_scope_entries(root_path, scenario=scenario, progress=progress)
    composition = _latest_publication_composition(
        root_path,
        subject_id=scenario.subject_id,
        subject_title=scenario.title,
        publication_id=scenario.publication_id,
    )
    if composition is None:
        return "\n".join(
            [
                "Report plan details",
                "",
                "The report plan has not been created yet.",
                "Create Report Plan first so you can choose items, support, and sections directly.",
            ]
        )
    entry = _selected_report_scope_entry(entries, progress)
    if entry is None:
        return "\n".join(
            [
                "Report plan details",
                "",
                "Nothing is selectable yet.",
            ]
        )
    lines = [
        entry.detail_title or entry.label,
        "",
        *entry.detail_lines,
    ]
    if entry.item_kind in _REPORT_SCOPE_REORDERABLE_KINDS:
        lines.extend(
            [
                "",
                "Reordering",
                (
                    "- This item is currently held for reordering."
                    if collapse_ws(entry.entry_id) in {collapse_ws(item) for item in progress.report_scope_held_entry_ids}
                    else "- Press H to hold this item for staged reordering."
                ),
                "- When a held item is selected, Shift+Up/Shift+Down or K/J previews block movement inside its current lane.",
                "- Press R to release held items at the previewed destination.",
            ]
        )
    return "\n".join(lines)


def subject_draft_detail_rows(
    *,
    root_path: Path,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> tuple[tuple[str, str], ...]:
    """Return structured Draft inspector data without decoding rendered prose."""
    if scenario.is_placeholder:
        return (("Draft details", "Select or create a subject to start shaping the draft."),)
    if _draft_focus_mode(progress) == "model":
        lens = _draft_model_lens(progress)
        selected_candidate = _selected_transformation_construct_candidate(
            root_path,
            scenario=scenario,
            progress=progress,
            include_rejected=False,
        )
        if selected_candidate is None:
            return (("Inspector", "No construct candidate is selected yet."),)
        candidates = _subject_transformation_construct_candidates(
            root_path,
            scenario=scenario,
            include_rejected=False,
        )
        decision_items = list_decision_review_items(root_path, scenario.subject_id)
        decision_state = _decision_review_state(root_path, scenario)
        decision_frame = (
            decision_state.get("frame")
            if isinstance(decision_state.get("frame"), DecisionFrame)
            else None
        )
        latest_decision_receipt = decision_state.get("latest_receipt")
        selected_decision_item = _decision_review_item_for_construct_candidate(
            decision_items,
            selected_candidate,
        )
        selected_lane = _current_construct_candidate_lane(
            selected_candidate,
            decision_item=selected_decision_item,
            frame=decision_frame,
        )
        rows: list[tuple[str, str]] = [
            ("lens", _draft_model_lens_label(lens)),
            ("selected object", _construct_candidate_detail_label(selected_candidate)),
            ("type", _format_orientation_label(selected_candidate.sort_kind)),
            ("status", collapse_ws(selected_candidate.status) or "<none>"),
            ("confidence", f"{float(selected_candidate.confidence or 0.0):.2f}"),
            ("source item", collapse_ws(selected_candidate.itemized_item_id) or "<none>"),
            ("linked draft item", collapse_ws(selected_candidate.review_item_id) or "<none>"),
            ("source refs", str(len(selected_candidate.source_refs))),
            (
                "included as",
                (
                    _format_orientation_label(selected_lane)
                    if collapse_ws(selected_candidate.status) == "accepted"
                    and selected_decision_item is not None
                    else "<not accepted>"
                ),
            ),
        ]
        if collapse_ws(selected_candidate.status) == "accepted":
            rows.extend(
                _selected_construct_relation_rows(
                    selected_candidate,
                    decision_item=selected_decision_item,
                    decision_items=decision_items,
                    frame=decision_frame,
                )
            )
        if collapse_ws(selected_candidate.summary):
            rows.append(("Definition", collapse_ws(selected_candidate.summary)))
        if collapse_ws(selected_candidate.notes):
            rows.append(("Notes", collapse_ws(selected_candidate.notes)))
        rows.extend(
            (
                collapse_ws(str(key)),
                collapse_ws(str(value)),
            )
            for key, value in sorted(selected_candidate.relation_hints.items())
            if collapse_ws(str(key)) and collapse_ws(str(value))
        )
        rows.extend(
            _draft_model_status_snapshot_rows(
                construct_candidates=candidates,
                decision_frame=decision_frame,
                latest_decision_receipt=latest_decision_receipt,
                decision_items=decision_items,
            )
        )
        if isinstance(decision_frame, DecisionFrame):
            discovery_proposal_id = collapse_ws(
                str(decision_frame.metadata.get("dst_discovery_proposal_id", ""))
            )
            normalization_proposal_id = collapse_ws(
                str(decision_frame.metadata.get("dst_normalization_proposal_id", ""))
            )
            if discovery_proposal_id or normalization_proposal_id:
                rows.extend(
                    (
                        ("discovery proposal", discovery_proposal_id or "<none>"),
                        ("normalization proposal", normalization_proposal_id or "<none>"),
                    )
                )
        return tuple(rows)

    review_composition, review_items = _review_composition_and_items(root_path, scenario)
    selected_item, selection_source = _selected_draft_review_item(
        root_path,
        scenario=scenario,
        progress=progress,
    )
    if review_composition is None or not review_items or selected_item is None:
        publication_composition = _latest_publication_composition(
            root_path,
            subject_id=scenario.subject_id,
            subject_title=scenario.title,
            publication_id=scenario.publication_id,
        )
        if publication_composition is None:
            return (
                ("Report plan details", "The report plan has not been created yet."),
                (
                    "Next step",
                    "Create Report Plan first so you can choose items, support, and sections directly.",
                ),
            )
        entries = _report_scope_entries(root_path, scenario=scenario, progress=progress)
        selected_entry = _selected_report_scope_entry(entries, progress)
        if selected_entry is None:
            return (("Draft details", "Nothing is selected yet."),)
        return tuple(selected_entry.detail_rows)

    decision_items = list_decision_review_items(root_path, scenario.subject_id)
    decision_state = _decision_review_state(root_path, scenario)
    decision_frame = (
        decision_state.get("frame")
        if isinstance(decision_state.get("frame"), DecisionFrame)
        else None
    )
    selected_decision_item = _decision_review_item_for_review_item(decision_items, selected_item)
    split_labels = _draft_review_split_labels(root_path, scenario=scenario, item=selected_item)
    try:
        context = load_learning_context(root_path, scenario.subject_id)
        source_unit = next(
            (
                unit
                for unit in _admitted_units_in_context_order(context)
                if collapse_ws(unit.unit_id) == collapse_ws(selected_item.source_unit_id)
            ),
            None,
        )
    except Exception:
        source_unit = None
    rows = list(_draft_review_item_rows(selected_item, selection_source=selection_source))
    if source_unit is not None and collapse_ws(getattr(source_unit, "statement", "")):
        rows.append(("Statement", collapse_ws(getattr(source_unit, "statement", ""))))
    rows.extend(
        (
            (
                "split candidates",
                ", ".join(split_labels) if len(split_labels) >= 2 else "<none>",
            ),
            (
                "sibling count",
                str(len(review_item_children(review_items, selected_item.parent_review_item_id))),
            ),
            (
                "selected in decision frame",
                (
                    "yes"
                    if _draft_review_item_effectively_included_in_decision(
                        root_path,
                        scenario=scenario,
                        review_item=selected_item,
                        decision_items=decision_items,
                        frame=decision_frame,
                    )
                    else "no"
                ),
            ),
        )
    )
    if selected_decision_item is not None:
        rows.append(("decision role", _format_orientation_label(selected_decision_item.decision_role)))
    return tuple(rows)


def render_subject_draft_detail(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder:
        return "Select or create a subject to start shaping the draft."
    root_path = _root_path_from_scenario(scenario)
    if _draft_focus_mode(progress) == "model":
        lens = _draft_model_lens(progress)
        selected_construct_candidate = _selected_transformation_construct_candidate(
            root_path,
            scenario=scenario,
            progress=progress,
            include_rejected=False,
        )
        decision_items = list_decision_review_items(root_path, scenario.subject_id)
        decision_state = _decision_review_state(root_path, scenario)
        decision_frame = decision_state.get("frame") if isinstance(decision_state.get("frame"), DecisionFrame) else None
        latest_decision_receipt = decision_state.get("latest_receipt")
        if selected_construct_candidate is None:
            return "\n".join(
                [
                    "Inspector",
                    "",
                    "No construct candidate is selected yet.",
                    "",
                    "Open Itemize and use Suggest DST Constructs first, then return to Draft Model.",
                ]
            )
        selected_decision_item = _decision_review_item_for_construct_candidate(
            decision_items,
            selected_construct_candidate,
        )
        status_snapshot_lines = _draft_model_status_snapshot_lines(
            construct_candidates=_subject_transformation_construct_candidates(
                root_path,
                scenario=scenario,
                include_rejected=False,
            ),
            decision_frame=decision_frame,
            latest_decision_receipt=latest_decision_receipt,
            decision_items=decision_items,
        )
        lines = [
            "Inspector",
            *_draft_model_selection_summary_lines(
                selected_construct_candidate,
                lens=lens,
                decision_item=selected_decision_item,
                decision_items=decision_items,
                decision_frame=decision_frame,
            ),
        ]
        if collapse_ws(selected_construct_candidate.summary):
            lines.extend(["", "Definition", selected_construct_candidate.summary])
        if selected_construct_candidate.notes:
            lines.extend(["", "Notes", selected_construct_candidate.notes])
        if selected_construct_candidate.relation_hints:
            lines.extend(
                [
                    "",
                    "Relations",
                    *(
                        f"- {collapse_ws(str(key))}: {collapse_ws(str(value))}"
                        for key, value in sorted(selected_construct_candidate.relation_hints.items())
                        if collapse_ws(str(key)) and collapse_ws(str(value))
                    ),
                ]
            )
        lines.extend(
            [
                "",
                "Status Snapshot",
                *status_snapshot_lines,
            ]
        )
        provenance_lines = _draft_model_governed_provenance_lines(decision_frame)
        if provenance_lines:
            lines.extend(["", *provenance_lines])
        return "\n".join(lines)
    review_composition, review_items = _review_composition_and_items(root_path, scenario)
    if review_composition is None or not review_items:
        return render_subject_report_scope_detail(scenario=scenario, progress=progress)
    selected_item, selection_source = _selected_draft_review_item(
        root_path,
        scenario=scenario,
        progress=progress,
    )
    if selected_item is None:
        return render_subject_report_scope_detail(scenario=scenario, progress=progress)
    decision_items = list_decision_review_items(root_path, scenario.subject_id)
    decision_state = _decision_review_state(root_path, scenario)
    decision_frame = decision_state.get("frame") if isinstance(decision_state.get("frame"), DecisionFrame) else None
    selected_decision_item = _decision_review_item_for_review_item(decision_items, selected_item)
    split_labels = _draft_review_split_labels(root_path, scenario=scenario, item=selected_item)
    source_statement = ""
    if collapse_ws(selected_item.source_unit_id):
        try:
            context = load_learning_context(root_path, scenario.subject_id)
            source_unit = next(
                (
                    unit
                    for unit in _admitted_units_in_context_order(context)
                    if collapse_ws(unit.unit_id) == collapse_ws(selected_item.source_unit_id)
                ),
                None,
            )
        except Exception:
            source_unit = None
        if source_unit is not None:
            source_statement = collapse_ws(getattr(source_unit, "statement", ""))
    lines = [
        collapse_ws(str(selected_item.metadata.get("canonical_label", ""))) or selected_item.review_item_id,
        "",
        *_draft_review_item_lines(selected_item, selection_source=selection_source),
    ]
    if source_statement:
        lines.extend(["", "Statement", source_statement])
    lines.extend(
        [
            "",
            "Composition",
            f"- split candidates: {', '.join(split_labels) if len(split_labels) >= 2 else '<none>'}",
            f"- sibling count: {len(review_item_children(review_items, selected_item.parent_review_item_id))}",
            (
                "- selected in decision frame: yes"
                if _draft_review_item_effectively_included_in_decision(
                    root_path,
                    scenario=scenario,
                    review_item=selected_item,
                    decision_items=decision_items,
                    frame=decision_frame,
                )
                else "- selected in decision frame: no"
            ),
        ]
    )
    if selected_decision_item is not None:
        lines.append(f"- decision role: {_format_orientation_label(selected_decision_item.decision_role)}")
    return "\n".join(lines)


def render_subject_draft_tree(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder:
        return "\n".join(
            [
                "Draft Item Inventory",
                "- no subject exists yet",
            ]
        )
    root_path = _root_path_from_scenario(scenario)
    if _draft_focus_mode(progress) == "model":
        lens = _draft_model_lens(progress)
        candidates = _subject_transformation_construct_candidates(
            root_path,
            scenario=scenario,
            include_rejected=False,
        )
        decision_state = _decision_review_state(root_path, scenario)
        decision_frame = decision_state.get("frame") if isinstance(decision_state.get("frame"), DecisionFrame) else None
        latest_decision_receipt = decision_state.get("latest_receipt")
        decision_items = list_decision_review_items(root_path, scenario.subject_id)
        selected_candidate = _selected_transformation_construct_candidate(
            root_path,
            scenario=scenario,
            progress=progress,
            include_rejected=False,
        )
        if not candidates:
            return "\n".join(
                [
                    "- no persisted construct candidates yet",
                    "- next: use Suggest DST Constructs in Itemize, then return here to curate them",
                ]
            )
        selected_id = (
            collapse_ws(selected_candidate.construct_candidate_id)
            if selected_candidate is not None
            else ""
        )
        lines: list[str] = []
        for candidate in candidates:
            candidate_id = collapse_ws(candidate.construct_candidate_id)
            cursor = ">" if candidate_id == selected_id else " "
            badge = _TRANSFORMATION_CONSTRUCT_STATUS_BADGES.get(
                collapse_ws(candidate.status),
                "?",
            )
            lane_suffix = ""
            if collapse_ws(candidate.status) == "accepted":
                decision_item = _decision_review_item_for_construct_candidate(decision_items, candidate)
                if decision_item is not None:
                    lane_suffix = (
                        f" -> {_format_orientation_label(_current_construct_candidate_lane(candidate, decision_item=decision_item))}"
                    )
            lines.append(
                f"{cursor} [{badge}] {_construct_candidate_detail_label(candidate)} "
                f"({_format_orientation_label(candidate.sort_kind)}{lane_suffix})"
            )
        return "\n".join(lines)
    review_composition, review_items = _review_composition_and_items(root_path, scenario)
    if review_composition is None or not review_items:
        return "\n".join(
            [
                "- no persisted draft review items yet",
                "- next: create or refresh the draft composition from the current itemization inventory",
            ]
        )
    selected_item, _selection_source = _selected_draft_review_item(
        root_path,
        scenario=scenario,
        progress=progress,
    )
    decision_state = _decision_review_state(root_path, scenario)
    decision_frame = decision_state.get("frame") if isinstance(decision_state.get("frame"), DecisionFrame) else None
    return "\n".join(
        _draft_review_inventory_lines(
            review_items,
            selected_review_item_id=(
                collapse_ws(selected_item.review_item_id)
                if selected_item is not None
                else ""
            ),
            decision_included_review_item_ids=_draft_effective_decision_included_review_item_ids(
                root_path,
                scenario=scenario,
                review_items=review_items,
                decision_items=list_decision_review_items(root_path, scenario.subject_id),
                frame=decision_frame,
            ),
        )
    )


def subject_draft_tree_title(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder:
        return "Draft Item Inventory"
    if _draft_focus_mode(progress) == "model":
        root_path = _root_path_from_scenario(scenario)
        candidates = _subject_transformation_construct_candidates(
            root_path,
            scenario=scenario,
            include_rejected=False,
        )
        return f"Case Objects ({len(candidates)})"
    return "Draft Item Inventory"


def subject_draft_detail_title(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder:
        return "Selection Details"
    if _draft_focus_mode(progress) == "model":
        lens = _draft_model_lens(progress)
        selected_candidate = _selected_transformation_construct_candidate(
            _root_path_from_scenario(scenario),
            scenario=scenario,
            progress=progress,
            include_rejected=False,
        )
        label = (
            _construct_candidate_detail_label(selected_candidate)
            if selected_candidate is not None
            else ""
        )
        return label or f"{_draft_model_lens_label(lens)} Inspector"
    selected_item, _selection_source = _selected_draft_review_item(
        _root_path_from_scenario(scenario),
        scenario=scenario,
        progress=progress,
    )
    label = collapse_ws(str(getattr(selected_item, "metadata", {}).get("canonical_label", ""))) if selected_item is not None else ""
    return label or "Selection Details"


def subject_draft_model_main_title(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder or _draft_focus_mode(progress) != "model":
        return ""
    return _draft_model_lens_title(_draft_model_lens(progress))


def render_subject_draft_model_main(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder:
        return "\n".join(
            [
                "Transformation Model",
                "",
                "Open or create a subject first.",
            ]
        )
    if _draft_focus_mode(progress) != "model":
        return ""
    root_path = _root_path_from_scenario(scenario)
    lens = _draft_model_lens(progress)
    construct_candidates = _subject_transformation_construct_candidates(
        root_path,
        scenario=scenario,
        include_rejected=False,
    )
    decision_state = _decision_review_state(root_path, scenario)
    decision_frame = decision_state.get("frame") if isinstance(decision_state.get("frame"), DecisionFrame) else None
    latest_decision_receipt = decision_state.get("latest_receipt")
    decision_items = list_decision_review_items(root_path, scenario.subject_id)
    dst_fixture = _dst_fixture_for_subject(root_path, scenario)
    selected_candidate = _selected_transformation_construct_candidate(
        root_path,
        scenario=scenario,
        progress=progress,
        include_rejected=False,
    )
    accepted_candidates = tuple(
        candidate for candidate in construct_candidates if collapse_ws(candidate.status) == "accepted"
    )
    if lens == "frame":
        status_snapshot_lines = _draft_model_status_snapshot_lines(
            construct_candidates=construct_candidates,
            decision_frame=decision_frame,
            latest_decision_receipt=latest_decision_receipt,
            decision_items=decision_items,
        )
        return "\n".join(
            [
                "Tabs: Context | Actors | Objectives",
                f"Case: {scenario.title}",
                f"Family: {scenario.family_title or '<none>'}",
                f"Summary: {scenario.summary or '<none>'}",
                (
                    f"Expected solution shape: {len(dst_fixture.candidate_paths)} explicit candidate paths"
                    if dst_fixture is not None and dst_fixture.candidate_paths
                    else "Expected solution shape: unknown"
                ),
                (
                    f"Decision question: {decision_frame.question or '<none>'}"
                    if decision_frame is not None
                    else "Decision question: <none>"
                ),
                f"Actors: {_construct_candidate_labels_for_sorts(construct_candidates, 'actor')}",
                f"Objectives: {_construct_candidate_labels_for_sorts(construct_candidates, 'objective')}",
                f"Boundaries: {_construct_candidate_labels_for_sorts(construct_candidates, 'boundary')}",
                f"States: {_construct_candidate_labels_for_sorts(construct_candidates, 'state')}",
                f"Accepted into frame: {len(accepted_candidates)}",
                (
                    f"Current / target states: {len(decision_frame.current_state_ids)} / {len(decision_frame.target_state_ids)}"
                    if decision_frame is not None
                    else "Current / target states: <none>"
                ),
                (
                    f"Selected object: {_construct_candidate_detail_label(selected_candidate)}"
                    if selected_candidate is not None
                    else "Selected object: <none>"
                ),
                *status_snapshot_lines,
            ]
        )
    if lens == "explore":
        recommended_option_ids = (
            tuple(str(item) for item in latest_decision_receipt.metadata.get("recommended_option_ids", ()))
            if latest_decision_receipt is not None
            else ()
        )
        evaluated_path_signatures = (
            tuple(str(item) for item in latest_decision_receipt.metadata.get("candidate_path_signatures", ()))
            if latest_decision_receipt is not None
            else ()
        )
        candidate_path_titles = (
            tuple(path.title for path in dst_fixture.candidate_paths if collapse_ws(path.title))
            if dst_fixture is not None
            else ()
        )
        status_snapshot_lines = _draft_model_status_snapshot_lines(
            construct_candidates=construct_candidates,
            decision_frame=decision_frame,
            latest_decision_receipt=latest_decision_receipt,
            decision_items=decision_items,
        )
        return "\n".join(
            [
                "Tabs: Alternatives | Compare | Rationale",
                (
                    f"Recommendation status: {collapse_ws(str(latest_decision_receipt.recommendation_status)) or 'pending'}"
                    if latest_decision_receipt is not None
                    else "Recommendation status: pending"
                ),
                f"Explore unlocked: {'yes' if latest_decision_receipt is not None else 'not yet'}",
                (
                    f"Candidate paths: {', '.join(candidate_path_titles[:4])}"
                    if candidate_path_titles
                    else "Candidate paths: <none>"
                ),
                (
                    f"Evaluated paths: {', '.join(evaluated_path_signatures[:3])}"
                    if evaluated_path_signatures
                    else "Evaluated paths: <none>"
                ),
                (
                    f"Recommended options: {', '.join(recommended_option_ids[:4])}"
                    if recommended_option_ids
                    else "Recommended options: <none>"
                ),
                (
                    f"Admissible transitions: {len(latest_decision_receipt.admissible_transition_ids)}"
                    if latest_decision_receipt is not None
                    else "Admissible transitions: 0"
                ),
                (
                    f"Valid decisions: {len(latest_decision_receipt.valid_decision_ids)}"
                    if latest_decision_receipt is not None
                    else "Valid decisions: 0"
                ),
                (
                    f"Executable decisions: {len(latest_decision_receipt.executable_decision_ids)}"
                    if latest_decision_receipt is not None
                    else "Executable decisions: 0"
                ),
                *(
                    [f"Blocker: {item}" for item in latest_decision_receipt.blocking_conditions[:4]]
                    if latest_decision_receipt is not None and latest_decision_receipt.blocking_conditions
                    else ["Blocker: <none>"]
                ),
                (
                    f"Selected object: {_construct_candidate_detail_label(selected_candidate)}"
                    if selected_candidate is not None
                    else "Selected object: <none>"
                ),
                *status_snapshot_lines,
            ]
        )
    status_snapshot_lines = _draft_model_status_snapshot_lines(
        construct_candidates=construct_candidates,
        decision_frame=decision_frame,
        latest_decision_receipt=latest_decision_receipt,
        decision_items=decision_items,
    )
    capability_dependency_link_count = sum(
        len(
            _metadata_decision_item_ids(
                dict(item.metadata),
                plural_key=_CAPABILITY_REQUIRED_DEPENDENCY_DECISION_ITEM_IDS_KEY,
                singular_key=_CAPABILITY_REQUIRED_DEPENDENCY_DECISION_ITEM_ID_KEY,
            )
        )
        for item in decision_items
        if item.included and collapse_ws(item.status) != "rejected" and item.decision_role == "capability"
    )
    capability_boundary_link_count = sum(
        len(
            _metadata_decision_item_ids(
                dict(item.metadata),
                plural_key=_CAPABILITY_CROSSED_BOUNDARY_DECISION_ITEM_IDS_KEY,
                singular_key=_CAPABILITY_CROSSED_BOUNDARY_DECISION_ITEM_ID_KEY,
            )
        )
        for item in decision_items
        if item.included and collapse_ws(item.status) != "rejected" and item.decision_role == "capability"
    )
    return "\n".join(
        [
            "Tabs: Capabilities | Dependencies | Constraints | States | Transitions",
            f"Capabilities: {_count_construct_candidates_by_sort(construct_candidates, 'capability')}",
            f"Dependencies: {_count_construct_candidates_by_sort(construct_candidates, 'dependency')}",
            f"Constraints: {_count_construct_candidates_by_sort(construct_candidates, 'constraint')}",
            f"States: {_count_construct_candidates_by_sort(construct_candidates, 'state')}",
            f"Transitions: {_count_construct_candidates_by_sort(construct_candidates, 'transition')}",
            f"Decisions: {_count_construct_candidates_by_sort(construct_candidates, 'decision')}",
            f"Accepted decision items: {sum(1 for item in decision_items if collapse_ws(item.status) != 'rejected')}",
            f"Capability dependencies: {capability_dependency_link_count}",
            f"Capability boundaries: {capability_boundary_link_count}",
            (
                f"Selected object: {_construct_candidate_detail_label(selected_candidate)}"
                if selected_candidate is not None
                else "Selected object: <none>"
            ),
            *(
                _selected_construct_relation_lines(
                    selected_candidate,
                    decision_item=_decision_review_item_for_construct_candidate(decision_items, selected_candidate),
                    decision_items=decision_items,
                    frame=decision_frame,
                )
                if selected_candidate is not None
                else ()
            ),
            *status_snapshot_lines,
        ]
    )


def subject_draft_result_title(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder:
        return subject_journal_title("draft")
    if _draft_focus_mode(progress) == "model":
        return "Issues & Validation"
    return subject_journal_title("draft")


def render_subject_draft_issue_tray(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder or _draft_focus_mode(progress) != "model":
        return _render_draft_workspace(scenario=scenario, progress=progress)
    root_path = _root_path_from_scenario(scenario)
    decision_state = _decision_review_state(root_path, scenario)
    decision_frame = decision_state.get("frame") if isinstance(decision_state.get("frame"), DecisionFrame) else None
    latest_decision_receipt = decision_state.get("latest_receipt")
    decision_items = list_decision_review_items(root_path, scenario.subject_id)
    missing_relation = _first_missing_draft_model_relation(decision_items)
    blocking_conditions = (
        tuple(str(item) for item in latest_decision_receipt.blocking_conditions if collapse_ws(str(item)))
        if latest_decision_receipt is not None
        else ()
    )
    status_snapshot_lines = _draft_model_status_snapshot_lines(
        construct_candidates=_subject_transformation_construct_candidates(
            root_path,
            scenario=scenario,
            include_rejected=False,
        ),
        decision_frame=decision_frame,
        latest_decision_receipt=latest_decision_receipt,
        decision_items=decision_items,
    )
    lines: list[str] = [
        "Status Snapshot",
        *status_snapshot_lines,
    ]
    if missing_relation is not None:
        lines.extend(
            [
                "",
                "Missing links",
                _draft_model_missing_relation_line(missing_relation).replace("- next missing relation: ", "- "),
            ]
        )
    if blocking_conditions:
        lines.extend(["", "Blocking conditions", *[f"- {item}" for item in blocking_conditions[:4]]])
    else:
        lines.extend(["", "Blocking conditions", "- <none>"])
    provenance_lines = _draft_model_governed_provenance_lines(decision_frame)
    if provenance_lines:
        lines.extend(["", *provenance_lines])
    if progress.latest_receipt_lines:
        lines.extend(["", *(_receipt_section(progress.latest_receipt_title or "Latest Receipt", progress.latest_receipt_lines))])
    return "\n".join(lines)


def _baseline_publication_composition(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    publication_type: str = "report",
) -> PublicationComposition:
    context = load_learning_context(root_path, scenario.subject_id)
    approved_import_ids = tuple(item.import_id for item in _active_subject_imports(root_path, scenario.subject_id))
    return publication_composition_from_learning_context(
        root_path,
        context,
        publication_type=publication_type,
        title=_default_report_publication_title(scenario.title),
        scope_summary=_default_report_scope_summary_for_publication_type(
            publication_type=publication_type,
            subject_title=scenario.title,
        ),
        selected_subject_import_ids=approved_import_ids,
        build_epoch_ms=0,
        status="draft",
        import_usage_by_id={import_id: "dependency_only" for import_id in approved_import_ids},
    )


def _previous_approved_publication_composition(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    composition: PublicationComposition,
) -> PublicationComposition | None:
    revisions = list_publication_composition_revisions(
        root_path,
        scenario.subject_id,
        composition.publication_id,
        composition_id=composition.composition_id,
    )
    approved_revisions = [
        item
        for item in revisions
        if collapse_ws(item.status) == "approved" and item.content_hash() != composition.content_hash()
    ]
    if approved_revisions:
        return approved_revisions[-1]
    current_compositions = list_publication_compositions(
        root_path,
        scenario.subject_id,
        composition.publication_id,
    )
    current = current_compositions[-1] if current_compositions else None
    if current is not None and collapse_ws(current.status) == "approved" and current.content_hash() != composition.content_hash():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return current
    return None


def _previous_publication_composition_revision(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    composition: PublicationComposition,
) -> PublicationComposition | None:
    revisions = list_publication_composition_revisions(
        root_path,
        scenario.subject_id,
        composition.publication_id,
        composition_id=composition.composition_id,
    )
    differing_revisions = [
        item
        for item in revisions
        if item.content_hash() != composition.content_hash()
    ]
    if differing_revisions:
        return differing_revisions[-1]
    return None


def _publication_diff_baseline_label(mode: str) -> str:
    normalized = collapse_ws(mode) or _PUBLICATION_DIFF_BASELINE_SNAPSHOT
    return _PUBLICATION_DIFF_BASELINE_LABELS.get(normalized, normalized.replace("_", " ").title())


def _publication_diff_baseline_candidates(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    composition: PublicationComposition,
) -> tuple[tuple[str, str, PublicationComposition], ...]:
    candidates: list[tuple[str, str, PublicationComposition]] = []
    seen_content_hashes: set[str] = set()
    previous_approved = _previous_approved_publication_composition(
        root_path,
        scenario=scenario,
        composition=composition,
    )
    if previous_approved is not None:
        candidates.append(
            (
                _PUBLICATION_DIFF_BASELINE_APPROVED,
                _publication_diff_baseline_label(_PUBLICATION_DIFF_BASELINE_APPROVED),
                previous_approved,
            )
        )
        seen_content_hashes.add(previous_approved.content_hash())
    previous_revision = _previous_publication_composition_revision(
        root_path,
        scenario=scenario,
        composition=composition,
    )
    if previous_revision is not None and previous_revision.content_hash() not in seen_content_hashes:
        candidates.append(
            (
                _PUBLICATION_DIFF_BASELINE_PREVIOUS_REVISION,
                _publication_diff_baseline_label(_PUBLICATION_DIFF_BASELINE_PREVIOUS_REVISION),
                previous_revision,
            )
        )
        seen_content_hashes.add(previous_revision.content_hash())
    candidates.append(
        (
            _PUBLICATION_DIFF_BASELINE_SNAPSHOT,
            _publication_diff_baseline_label(_PUBLICATION_DIFF_BASELINE_SNAPSHOT),
            _baseline_publication_composition(
                root_path,
                scenario=scenario,
                publication_type=composition.publication_type,
            ),
        )
    )
    return tuple(candidates)


def _resolved_publication_diff_baseline(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    composition: PublicationComposition,
    progress: SubjectProgress,
) -> tuple[str, str, PublicationComposition]:
    candidates = _publication_diff_baseline_candidates(
        root_path,
        scenario=scenario,
        composition=composition,
    )
    if not candidates:
        return (
            _PUBLICATION_DIFF_BASELINE_SNAPSHOT,
            _publication_diff_baseline_label(_PUBLICATION_DIFF_BASELINE_SNAPSHOT),
            _baseline_publication_composition(
                root_path,
                scenario=scenario,
                publication_type=composition.publication_type,
            ),
        )
    candidate_by_mode = {
        collapse_ws(mode): (mode, label, candidate)
        for mode, label, candidate in candidates
    }
    selected_mode = collapse_ws(progress.publication_diff_baseline_mode)
    if selected_mode in candidate_by_mode:
        return candidate_by_mode[selected_mode]
    default_mode = next(
        (
            mode
            for mode in (
                _PUBLICATION_DIFF_BASELINE_APPROVED,
                _PUBLICATION_DIFF_BASELINE_PREVIOUS_REVISION,
                _PUBLICATION_DIFF_BASELINE_SNAPSHOT,
            )
            if mode in candidate_by_mode
        ),
        candidates[0][0],
    )
    return candidate_by_mode.get(default_mode, candidates[0])


def _publication_diff_baseline_action_label(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    composition: PublicationComposition,
    progress: SubjectProgress,
) -> str:
    _mode, label, _baseline = _resolved_publication_diff_baseline(
        root_path,
        scenario=scenario,
        composition=composition,
        progress=progress,
    )
    return f"Change Diff Baseline ({label})"


def _composition_diff_receipt_lines(
    *,
    root_path: Path,
    scenario: SubjectScenario,
    composition: PublicationComposition,
    progress: SubjectProgress,
) -> list[str]:
    baseline_mode, baseline_label, baseline = _resolved_publication_diff_baseline(
        root_path,
        scenario=scenario,
        composition=composition,
        progress=progress,
    )
    context = load_learning_context(root_path, scenario.subject_id)
    title_by_unit_id = {
        unit.unit_id: collapse_ws(unit.canonical_title) or unit.unit_id
        for unit in _admitted_units_in_context_order(context)
    }
    baseline_units = set(baseline.included_unit_ids)
    current_units = set(composition.included_unit_ids)
    removed_units = tuple(title_by_unit_id[unit_id] for unit_id in baseline.included_unit_ids if unit_id not in current_units and unit_id in title_by_unit_id)
    added_units = tuple(title_by_unit_id[unit_id] for unit_id in composition.included_unit_ids if unit_id not in baseline_units and unit_id in title_by_unit_id)
    baseline_imports = set(baseline.selected_subject_import_ids)
    current_imports = set(composition.selected_subject_import_ids)
    removed_sections = tuple(title for title in _composition_section_titles(baseline.section_ids) if title not in set(_composition_section_titles(composition.section_ids)))
    added_sections = tuple(title for title in _composition_section_titles(composition.section_ids) if title not in set(_composition_section_titles(baseline.section_ids)))
    usage_changes = [
        f"{import_id}: { _publication_import_usage_label(baseline.import_usage_by_id.get(import_id, 'dependency_only')) } -> { _publication_import_usage_label(composition.import_usage_by_id.get(import_id, 'dependency_only')) }"
        for import_id in composition.selected_subject_import_ids
        if collapse_ws(composition.import_usage_by_id.get(import_id, "dependency_only")) != collapse_ws(baseline.import_usage_by_id.get(import_id, "dependency_only"))
    ]
    lines = [
        f"- composition: {composition.composition_id}",
        f"- baseline mode: {baseline_label}",
        (
            f"- baseline: {baseline_label.lower()} ({baseline.composition_id})"
            if baseline_mode != _PUBLICATION_DIFF_BASELINE_SNAPSHOT
            else "- baseline: current subject snapshot"
        ),
        f"- included units: {len(composition.included_unit_ids)} / {len(baseline.included_unit_ids)}",
        f"- selected imports: {len(composition.selected_subject_import_ids)} / {len(baseline.selected_subject_import_ids)}",
        f"- section plan: {_composition_section_plan_label(composition.section_ids)}",
    ]
    lines.append(
        "- removed units: " + (", ".join(removed_units) if removed_units else "none")
    )
    lines.append(
        "- added units: " + (", ".join(added_units) if added_units else "none")
    )
    lines.append(
        "- removed imports: " + (", ".join(import_id for import_id in baseline.selected_subject_import_ids if import_id not in current_imports) or "none")
    )
    lines.append(
        "- added imports: " + (", ".join(import_id for import_id in composition.selected_subject_import_ids if import_id not in baseline_imports) or "none")
    )
    lines.append(
        "- removed sections: " + (", ".join(removed_sections) if removed_sections else "none")
    )
    lines.append(
        "- added sections: " + (", ".join(added_sections) if added_sections else "none")
    )
    lines.append(
        "- import usage overrides: " + (", ".join(usage_changes) if usage_changes else "none")
    )
    return lines


def _publication_composition_receipt_lines(composition: PublicationComposition) -> list[str]:
    section_titles = _composition_section_titles(composition.section_ids)
    import_usage_lines = _composition_import_usage_lines(composition)
    exact_draft = collapse_ws(composition.publication_type).casefold() == "exact_draft"
    selection_mode = collapse_ws(str(composition.metadata.get("unit_selection_mode", "")))
    selection_reason = collapse_ws(str(composition.metadata.get("selection_reason", "")))
    draft_review_composition_id = collapse_ws(str(composition.metadata.get("draft_review_composition_id", "")))
    draft_review_item_count = int(composition.metadata.get("draft_review_item_count", 0) or 0)
    draft_review_included_item_count = int(composition.metadata.get("draft_review_included_item_count", 0) or 0)
    review_transform_receipt_count = int(composition.metadata.get("review_transform_receipt_count", 0) or 0)
    decision_frame_payload = composition.metadata.get("decision_frame", {})
    if not isinstance(decision_frame_payload, dict):
        decision_frame_payload = {}
    decision_receipt_payload = composition.metadata.get("decision_analysis_receipt", {})
    if not isinstance(decision_receipt_payload, dict):
        decision_receipt_payload = {}
    auto_excluded_count = int(composition.metadata.get("auto_excluded_unit_count", 0) or 0)
    auto_selected_titles = composition.metadata.get("auto_selected_unit_titles", [])
    if not isinstance(auto_selected_titles, list):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        auto_selected_titles = []
    auto_excluded_titles = composition.metadata.get("auto_excluded_unit_titles", [])
    if not isinstance(auto_excluded_titles, list):
        auto_excluded_titles = []
    return [
        f"- composition: {composition.composition_id}",
        f"- title: {composition.title}",
        f"- output style: {_publication_output_type_label(composition.publication_type)}",
        f"- scope: {collapse_ws(composition.scope_summary) or '<none>'}",
        f"- status: {composition.status}",
        f"- context snapshot: {composition.learning_context_snapshot_hash or '<pending>'}",
        *([f"- draft composition: {draft_review_composition_id}"] if draft_review_composition_id else []),
        *([f"- draft review items: {draft_review_item_count} ({draft_review_included_item_count} included)"] if draft_review_composition_id else []),
        *([f"- review transform receipts: {review_transform_receipt_count}"] if review_transform_receipt_count else []),
        *([f"- decision frame: {collapse_ws(str(decision_frame_payload.get('decision_frame_id', '')))}"] if collapse_ws(str(decision_frame_payload.get("decision_frame_id", ""))) else []),
        *([f"- decision recommendation: {collapse_ws(str(decision_receipt_payload.get('recommendation_status', '')))}"] if collapse_ws(str(decision_receipt_payload.get("recommendation_status", ""))) else []),
        f"- unit selection: {selection_mode or 'explicit'}",
        *([f"- selection rationale: {selection_reason}"] if selection_reason else []),
        f"- included units: {len(composition.included_unit_ids)}",
        *([f"- auto-filtered units: {auto_excluded_count}"] if selection_mode == "curated_default" else []),
        *(
            [f"- selected unit examples: {', '.join(str(item) for item in auto_selected_titles[:3])}"]
            if auto_selected_titles
            else []
        ),
        *(
            [f"- filtered unit examples: {', '.join(str(item) for item in auto_excluded_titles[:3])}"]
            if auto_excluded_titles
            else []
        ),
        f"- selected imports: {len(composition.selected_subject_import_ids)}",
        f"- sections: {len(composition.section_ids)}",
        f"- section plan: {'<none>' if exact_draft else _composition_section_plan_label(composition.section_ids)}",
        (
            f"- section titles: {', '.join(section_titles)}"
            if section_titles
            else "- section titles: <none>"
        ),
        *import_usage_lines,
    ]


def _draft_publication_composition(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    existing: PublicationComposition | None = None,
    selected_subject_import_ids: tuple[str, ...] | None = None,
    build_epoch_ms: int = 0,
    status: str = "draft",
) -> PublicationComposition:
    context = load_learning_context(root_path, scenario.subject_id)
    approved_imports = _active_subject_imports(root_path, scenario.subject_id)
    approved_import_ids = tuple(item.import_id for item in approved_imports)
    draft_composition, draft_items = _current_review_composition_and_items(root_path, scenario)
    existing_current = existing is not None and collapse_ws(existing.learning_context_snapshot_hash) == collapse_ws(context.content_hash())
    existing_selection_mode = (
        collapse_ws(str(existing.metadata.get("unit_selection_mode", "")))
        if existing_current and existing is not None
        else ""
    )
    preserve_explicit_unit_scope = (
        existing_current
        and existing is not None
        and existing_selection_mode == "explicit"
        and bool(existing.included_unit_ids or existing.excluded_unit_ids)
    )
    draft_included_unit_ids: tuple[str, ...] = ()
    draft_excluded_unit_ids: tuple[str, ...] = ()
    if not preserve_explicit_unit_scope and draft_composition is not None and draft_items:
        admitted_unit_ids = tuple(
            unit.unit_id
            for unit in _admitted_units_in_context_order(context)
        )
        reportable_unit_ids = tuple(
            unit.unit_id
            for unit in _admitted_units_in_context_order(context)
            if publication_statement_is_reportable(unit.statement, unit_kind=unit.unit_kind)
        )
        draft_included_unit_ids = tuple(
            unit_id
            for unit_id in included_review_composition_unit_ids(draft_items)
            if unit_id in set(reportable_unit_ids)
        )
        if draft_included_unit_ids:
            draft_excluded_unit_ids = tuple(
                unit_id
                for unit_id in admitted_unit_ids
                if unit_id not in set(draft_included_unit_ids)
            )
    effective_selected_import_ids = selected_subject_import_ids
    if effective_selected_import_ids is None:
        if existing_current:
            effective_selected_import_ids = tuple(
                import_id
                for import_id in existing.selected_subject_import_ids
                if import_id in set(approved_import_ids)
            )
        else:
            effective_selected_import_ids = approved_import_ids
    effective_selected_import_ids = tuple(
        import_id
        for import_id in effective_selected_import_ids
        if import_id in set(approved_import_ids)
    )
    composition = publication_composition_from_learning_context(
        root_path,
        context,
        publication_type=(
            existing.publication_type
            if existing_current and collapse_ws(existing.publication_type)
            else "report"
        ),
        title=(existing.title if existing_current and collapse_ws(existing.title) else _default_report_publication_title(scenario.title)),
        scope_summary=(
            existing.scope_summary
            if existing_current and collapse_ws(existing.scope_summary)
            else _default_report_scope_summary_for_publication_type(
                publication_type=(
                    existing.publication_type
                    if existing_current and collapse_ws(existing.publication_type)
                    else "report"
                ),
                subject_title=scenario.title,
            )
        ),
        included_unit_ids=(
            existing.included_unit_ids
            if preserve_explicit_unit_scope and existing is not None
            else draft_included_unit_ids
        ),
        excluded_unit_ids=(
            existing.excluded_unit_ids
            if preserve_explicit_unit_scope and existing is not None
            else draft_excluded_unit_ids
        ),
        selected_subject_import_ids=effective_selected_import_ids,
        section_ids=(existing.section_ids if existing_current and existing.section_ids else ()),
        build_epoch_ms=build_epoch_ms,
        status=status,
        import_usage_by_id=(
            existing.import_usage_by_id
            if existing_current and existing.import_usage_by_id
            else {import_id: "dependency_only" for import_id in effective_selected_import_ids}
        ),
    )
    metadata = _composition_metadata_with_scope_orders(
        root_path,
        scenario=scenario,
        composition=(existing if existing_current and existing is not None else None),
        context=context,
    )
    transform_receipts = list_review_transform_receipts(root_path, scenario.subject_id)
    decision_frame = load_decision_frame(root_path, scenario.subject_id)
    decision_policy_profile = load_decision_policy_profile(root_path, scenario.subject_id)
    decision_review_items = list_decision_review_items(root_path, scenario.subject_id)
    decision_analysis_receipts = list_decision_analysis_receipts(root_path, scenario.subject_id)
    if draft_composition is not None:
        metadata["draft_review_composition_id"] = draft_composition.review_composition_id
        metadata["draft_review_item_count"] = len(draft_items)
        metadata["draft_review_included_item_count"] = sum(1 for item in draft_items if item.included)
        metadata["draft_review_items"] = [item.to_dict() for item in draft_items]
        metadata["draft_review_root_item_ids"] = list(draft_composition.root_review_item_ids)
        if draft_included_unit_ids:
            metadata["unit_selection_mode"] = "draft_review"
            metadata["selection_reason"] = (
                "Report plan unit scope was seeded from the current draft composition, "
                "which itself was derived from the itemization inventory."
            )
    metadata["review_transform_receipt_count"] = len(transform_receipts)
    metadata["review_transform_receipts"] = [receipt.to_dict() for receipt in transform_receipts[-8:]]
    if collapse_ws(decision_frame.decision_frame_id):
        metadata["decision_frame"] = decision_frame.to_dict()
    if collapse_ws(getattr(decision_policy_profile, "policy_profile_id", "")):
        metadata["decision_policy_profile"] = decision_policy_profile.to_dict()
    if decision_review_items:
        metadata["decision_review_items"] = [item.to_dict() for item in decision_review_items]
    if decision_analysis_receipts:
        metadata["decision_analysis_receipt"] = decision_analysis_receipts[-1].to_dict()
    return _composition_with_metadata(
        composition,
        metadata,
    )


def _rebuild_publication_composition(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    composition: PublicationComposition,
    publication_type: str | None = None,
    scope_summary: str | None = None,
    included_unit_ids: tuple[str, ...] | None = None,
    excluded_unit_ids: tuple[str, ...] | None = None,
    selected_subject_import_ids: tuple[str, ...] | None = None,
    section_ids: tuple[str, ...] | None = None,
    import_usage_by_id: dict[str, str] | None = None,
    metadata: dict[str, object] | None = None,
    status: str = "draft",
) -> PublicationComposition:
    context = load_learning_context(root_path, scenario.subject_id)
    rebuilt = publication_composition_from_learning_context(
        root_path,
        context,
        publication_type=publication_type if publication_type is not None else composition.publication_type,
        title=composition.title,
        scope_summary=scope_summary if scope_summary is not None else composition.scope_summary,
        included_unit_ids=included_unit_ids if included_unit_ids is not None else composition.included_unit_ids,
        excluded_unit_ids=excluded_unit_ids if excluded_unit_ids is not None else composition.excluded_unit_ids,
        selected_subject_import_ids=(
            selected_subject_import_ids
            if selected_subject_import_ids is not None
            else composition.selected_subject_import_ids
        ),
        section_ids=section_ids if section_ids is not None else composition.section_ids,
        build_epoch_ms=int(time.time() * 1000),
        status=status,
        import_usage_by_id=import_usage_by_id if import_usage_by_id is not None else composition.import_usage_by_id,
    )
    return _composition_with_metadata(
        rebuilt,
        metadata
        if metadata is not None
        else _composition_metadata_with_scope_orders(
            root_path,
            scenario=scenario,
            composition=composition,
            context=context,
        ),
    )


def _persist_publication_composition_metadata_change(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    composition: PublicationComposition,
    metadata: dict[str, object],
    build_epoch_ms: int,
) -> tuple[PublicationComposition, bool]:
    approval_invalidated = bool(
        collapse_ws(composition.status) == "approved"
        or progress.review_approved
        or progress.publication_locked
    )
    if approval_invalidated:
        progress.review_approved = False
        progress.publication_locked = False
        progress.release_packet_opened = False
        progress.release_review_completed = False
    updated = _rebuild_publication_composition(
        root_path,
        scenario=scenario,
        composition=composition,
        metadata=metadata,
        status=("draft" if approval_invalidated else (collapse_ws(composition.status) or "draft")),
    )
    persist_publication_composition(root_path, updated)
    return updated, approval_invalidated


def _sync_current_publication_composition_after_decision_change(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    build_epoch_ms: int,
) -> tuple[PublicationComposition | None, bool]:
    composition = _latest_current_publication_composition(root_path, scenario=scenario)
    if composition is None:
        draft_state = _review_composition_state(root_path, scenario)
        if not bool(draft_state.get("current")):
            return None, False
        created = _draft_publication_composition(
            root_path,
            scenario=scenario,
            existing=None,
            build_epoch_ms=build_epoch_ms,
            status="draft",
        )
        persist_publication_composition(root_path, created)
        return created, False
    approval_invalidated = bool(
        collapse_ws(composition.status) == "approved"
        or progress.review_approved
        or progress.publication_locked
    )
    if approval_invalidated:
        progress.review_approved = False
        progress.publication_locked = False
        progress.release_packet_opened = False
        progress.release_review_completed = False
    updated = _draft_publication_composition(
        root_path,
        scenario=scenario,
        existing=composition,
        build_epoch_ms=build_epoch_ms,
        status=("draft" if approval_invalidated else (collapse_ws(composition.status) or "draft")),
    )
    persist_publication_composition(root_path, updated)
    return updated, approval_invalidated


def _latest_publication_snapshot(root_path: Path, subject_id: str) -> dict[str, str]:
    publications_root = publication_subject_root(root_path, subject_id)
    if not publications_root.exists():
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return {}
    best_snapshot: dict[str, str] = {}
    best_rank = -1
    for publication_root in sorted(publications_root.iterdir()):
        publication_path = publication_root / "publication.json"
        if not publication_path.is_file():
            continue
        publication_payload = _read_json(publication_path)
        publication_id = collapse_ws(str(publication_payload.get("publication_id", "")))
        if not publication_id:
            continue
        latest_build_payload: dict[str, object] = {}
        latest_build_path = ""
        latest_build_rank = -1
        for build_path in sorted((publication_root / "builds").glob("*.json")):
            build_payload = _read_json(build_path)
            build_rank = int(
                build_payload.get("finished_at_epoch_ms", 0)
                or build_payload.get("started_at_epoch_ms", 0)
                or int(build_path.stat().st_mtime)
            )
            if build_rank >= latest_build_rank:
                latest_build_rank = build_rank
                latest_build_payload = build_payload
                latest_build_path = str(build_path.resolve())
        candidate_rank = latest_build_rank
        if candidate_rank < 0:
            candidate_rank = int(
                publication_payload.get("updated_at_epoch_ms", 0)
                or publication_payload.get("created_at_epoch_ms", 0)
                or int(publication_path.stat().st_mtime)
            )
        if candidate_rank < best_rank:
            continue
        artifact_paths: dict[str, str] = {}
        for item in latest_build_payload.get("render_artifacts", []):
            if not isinstance(item, dict):
                continue
            artifact_format = collapse_ws(str(item.get("format", "")))
            artifact_path = collapse_ws(str(item.get("path", "")))
            if not artifact_format or not artifact_path:
                continue
            artifact_paths[artifact_format] = str((publication_root / artifact_path).resolve())
        best_rank = candidate_rank
        best_snapshot = {
            "publication_id": publication_id,
            "publication_title": collapse_ws(str(publication_payload.get("title", ""))),
            "build_id": collapse_ws(str(latest_build_payload.get("build_id", ""))),
            "build_status": collapse_ws(str(latest_build_payload.get("build_status", ""))),
            "validation_status": collapse_ws(
                str(
                    (
                        latest_build_payload.get("validation_report", {})
                        if isinstance(latest_build_payload.get("validation_report", {}), dict)
                        else {}
                    ).get("status", "")
                )
            ),
            "build_path": latest_build_path,
            "publication_section_count": str(len(list((publication_root / "sections").glob("*.json")))),
            "publication_claim_count": str(len(list((publication_root / "claims").glob("*.json")))),
            "publication_source_count": str(len(list((publication_root / "sources").glob("*.json")))),
            "publication_entity_count": str(len(list((publication_root / "entities").glob("*.json")))),
            "publication_xref_count": str(len(list((publication_root / "xrefs").glob("*.json")))),
            "publication_review_count": str(len(list((publication_root / "reviews").glob("*.json")))),
            "report_markdown_path": artifact_paths.get("md", ""),
            "report_typst_path": artifact_paths.get("typ", ""),
            "report_pdf_path": artifact_paths.get("pdf", ""),
        }
    return best_snapshot


def _default_report_publication_title(subject_title: str) -> str:
    normalized = collapse_ws(subject_title)
    return f"{normalized or 'Subject'} Report"


def _default_report_scope_summary_for_publication_type(*, publication_type: str, subject_title: str) -> str:
    normalized_subject_title = collapse_ws(subject_title) or "Subject"
    if collapse_ws(publication_type).casefold() == "exact_draft":
        return f"Exact drafted output for {normalized_subject_title}."
    return f"Governed report projection for {normalized_subject_title}."


def _all_publication_compositions_for_subject(
    root_path: Path,
    *,
    subject_id: str,
) -> tuple[PublicationComposition, ...]:
    def _load() -> tuple[PublicationComposition, ...]:
        publications_root = publication_subject_root(root_path, subject_id)
        if not publications_root.exists():
            return ()
        compositions: list[PublicationComposition] = []
        for publication_root in sorted(publications_root.iterdir()):
            composition_root = publication_root / "compositions"
            if not composition_root.exists():
                continue
            for path in sorted(composition_root.glob("*.json")):
                try:
                    payload = json.loads(path.read_text(encoding="utf-8"))
                except Exception:
                    continue
                try:
                    compositions.append(PublicationComposition.from_dict(payload))
                except Exception:
                    continue
        return tuple(
            sorted(
                compositions,
                key=lambda item: (
                    int(item.updated_at_epoch_ms or 0),
                    int(item.created_at_epoch_ms or 0),
                    collapse_ws(item.composition_id),
                ),
            )
        )

    return _subject_workflow_cached_read(
        ("_all_publication_compositions_for_subject", root_path, collapse_ws(subject_id)),
        _load,
    )


def _latest_publication_composition_snapshot(
    root_path: Path,
    *,
    subject_id: str,
    subject_title: str,
    context_snapshot_hash: str,
    publication_id: str = "",
) -> dict[str, str]:
    def _load() -> dict[str, str]:
        target_publication_id = collapse_ws(publication_id)
        scoped_compositions = (
            list_publication_compositions(root_path, subject_id, target_publication_id)
            if target_publication_id
            else ()
        )
        all_compositions = _all_publication_compositions_for_subject(root_path, subject_id=subject_id)
        compositions = scoped_compositions or all_compositions
        if scoped_compositions and all_compositions:
            scoped_latest = scoped_compositions[-1]
            all_latest = all_compositions[-1]
            scoped_rank = (
                int(scoped_latest.updated_at_epoch_ms or 0),
                int(scoped_latest.created_at_epoch_ms or 0),
                collapse_ws(scoped_latest.composition_id),
            )
            all_rank = (
                int(all_latest.updated_at_epoch_ms or 0),
                int(all_latest.created_at_epoch_ms or 0),
                collapse_ws(all_latest.composition_id),
            )
            compositions = all_compositions if all_rank >= scoped_rank else scoped_compositions
        if not compositions:
            return {}
        latest = compositions[-1]
        return {
            "composition_id": latest.composition_id,
            "composition_status": latest.status,
            "composition_title": latest.title,
            "composition_scope_summary": collapse_ws(latest.scope_summary),
            "composition_learning_context_snapshot_hash": latest.learning_context_snapshot_hash,
            "composition_included_unit_count": str(len(latest.included_unit_ids)),
            "composition_selected_import_count": str(len(latest.selected_subject_import_ids)),
            "composition_section_count": str(len(latest.section_ids)),
            "composition_current": "yes" if collapse_ws(latest.learning_context_snapshot_hash) == collapse_ws(context_snapshot_hash) else "no",
        }

    return _subject_workflow_cached_read(
        (
            "_latest_publication_composition_snapshot",
            root_path,
            collapse_ws(subject_id),
            collapse_ws(context_snapshot_hash),
            collapse_ws(publication_id),
        ),
        _load,
    )


def _latest_publication_composition(
    root_path: Path,
    *,
    subject_id: str,
    subject_title: str,
    publication_id: str = "",
) -> PublicationComposition | None:
    def _load() -> PublicationComposition | None:
        target_publication_id = collapse_ws(publication_id)
        scoped_compositions = (
            list_publication_compositions(root_path, subject_id, target_publication_id)
            if target_publication_id
            else ()
        )
        all_compositions = _all_publication_compositions_for_subject(root_path, subject_id=subject_id)
        compositions = scoped_compositions or all_compositions
        if scoped_compositions and all_compositions:
            scoped_latest = scoped_compositions[-1]
            all_latest = all_compositions[-1]
            scoped_rank = (
                int(scoped_latest.updated_at_epoch_ms or 0),
                int(scoped_latest.created_at_epoch_ms or 0),
                collapse_ws(scoped_latest.composition_id),
            )
            all_rank = (
                int(all_latest.updated_at_epoch_ms or 0),
                int(all_latest.created_at_epoch_ms or 0),
                collapse_ws(all_latest.composition_id),
            )
            compositions = all_compositions if all_rank >= scoped_rank else scoped_compositions
        return compositions[-1] if compositions else None

    return _subject_workflow_cached_read(
        (
            "_latest_publication_composition",
            root_path,
            collapse_ws(subject_id),
            collapse_ws(publication_id),
        ),
        _load,
    )


