def default_subject_scenarios(root_path: Path) -> tuple[SubjectScenario, ...]:
    resolved_root = Path(root_path).expanduser().resolve()
    summaries = list_learning_contexts(resolved_root)
    if not summaries:
        return (_empty_subject_scenario(resolved_root),)
    scenarios: list[SubjectScenario] = []
    for summary in summaries:
        subject_id = collapse_ws(str(summary.get("subject_id", "")))
        if not subject_id:
            continue
        context = load_learning_context(resolved_root, subject_id)
        paths = learning_context_paths(resolved_root, subject_id)
        publication_snapshot = _latest_publication_snapshot(resolved_root, subject_id)
        composition_snapshot = _latest_publication_composition_snapshot(
            resolved_root,
            subject_id=subject_id,
            subject_title=context.canonical_title or subject_id,
            context_snapshot_hash=context.content_hash(),
            publication_id=publication_snapshot.get("publication_id", ""),
        )
        subject_imports = list_subject_imports(resolved_root, subject_id)
        pending_subject_imports = [
            item
            for item in subject_imports
            if item.status == "active" and item.review_status == "pending"
        ]
        active_subject_imports = [
            item
            for item in subject_imports
            if item.status == "active" and item.review_status == "approved"
        ]
        source_collections = list_source_collections(resolved_root, subject_id)
        staged_sources = list_staged_sources(resolved_root, subject_id)
        source_count = len(list(paths["sources"].glob("*.json"))) if paths["sources"].exists() else 0
        delta_count = len(list(paths["deltas"].glob("*.json"))) if paths["deltas"].exists() else 0
        admitted_unit_count = sum(1 for unit in context.units if unit.status == "admitted")
        scenarios.append(
            SubjectScenario(
                key=subject_id,
                subject_id=subject_id,
                title=context.canonical_title or subject_id,
                family_title=context.subject_family,
                context_id=subject_id,
                summary=_summary_for_context(context),
                governance_status=context.governance_status,
                context_snapshot_hash=context.content_hash(),
                unit_count=len(context.units),
                admitted_unit_count=admitted_unit_count,
                source_count=source_count,
                delta_count=delta_count,
                applied_delta_count=len(context.applied_delta_ids),
                import_count=len(subject_imports),
                pending_import_count=len(pending_subject_imports),
                reasoning_import_count=len(active_subject_imports),
                imported_subject_count=len({item.source_subject_id for item in active_subject_imports}),
                context_path=str(paths["context"].resolve()),
                subject_markdown_path=str(paths["subject_md"].resolve()),
                subject_typst_path=str(paths["subject_typ"].resolve()),
                publication_id=publication_snapshot.get("publication_id", ""),
                publication_title=publication_snapshot.get("publication_title", ""),
                build_id=publication_snapshot.get("build_id", ""),
                build_status=publication_snapshot.get("build_status", ""),
                validation_status=publication_snapshot.get("validation_status", ""),
                build_path=publication_snapshot.get("build_path", ""),
                publication_section_count=int(publication_snapshot.get("publication_section_count", "0") or 0),
                publication_claim_count=int(publication_snapshot.get("publication_claim_count", "0") or 0),
                publication_source_count=int(publication_snapshot.get("publication_source_count", "0") or 0),
                publication_entity_count=int(publication_snapshot.get("publication_entity_count", "0") or 0),
                publication_xref_count=int(publication_snapshot.get("publication_xref_count", "0") or 0),
                publication_review_count=int(publication_snapshot.get("publication_review_count", "0") or 0),
                report_markdown_path=publication_snapshot.get("report_markdown_path", ""),
                report_typst_path=publication_snapshot.get("report_typst_path", ""),
                report_pdf_path=publication_snapshot.get("report_pdf_path", ""),
                composition_id=composition_snapshot.get("composition_id", ""),
                composition_status=composition_snapshot.get("composition_status", ""),
                composition_title=composition_snapshot.get("composition_title", ""),
                composition_scope_summary=composition_snapshot.get("composition_scope_summary", ""),
                composition_learning_context_snapshot_hash=composition_snapshot.get("composition_learning_context_snapshot_hash", ""),
                composition_included_unit_count=int(composition_snapshot.get("composition_included_unit_count", "0") or 0),
                composition_selected_import_count=int(composition_snapshot.get("composition_selected_import_count", "0") or 0),
                composition_section_count=int(composition_snapshot.get("composition_section_count", "0") or 0),
                source_collection_count=len(source_collections),
                staged_source_count=len(staged_sources),
                source_collection_preview_lines=_source_collection_preview_lines(resolved_root, subject_id),
                source_preview_lines=_source_preview_lines(resolved_root, subject_id),
                staged_source_preview_lines=_staged_source_preview_lines(resolved_root, subject_id),
                unit_preview_lines=_unit_preview_lines(context),
                delta_preview_lines=_delta_preview_lines(resolved_root, subject_id),
                pending_import_preview_lines=_pending_import_preview_lines(resolved_root, subject_id),
                import_preview_lines=_import_preview_lines(resolved_root, subject_id),
            )
        )
    if not scenarios:
        return (_empty_subject_scenario(resolved_root),)
    return tuple(sorted(scenarios, key=lambda item: (item.title.casefold(), item.subject_id)))


