def subject_progress_to_dict(progress: SubjectProgress) -> dict[str, object]:
    return _subject_progress_payload(progress)


def new_subject_progress_client_view_defaults() -> dict[str, object]:
    defaults = _subject_progress_payload(new_subject_progress())
    return {
        key: copy.deepcopy(defaults[key])
        for key in _SUBJECT_PROGRESS_CLIENT_VIEW_KEYS
        if key in defaults
    }


def subject_progress_client_view_payload(progress: SubjectProgress) -> dict[str, object]:
    payload = _subject_progress_payload(progress)
    return {
        key: copy.deepcopy(payload[key])
        for key in _SUBJECT_PROGRESS_CLIENT_VIEW_KEYS
        if key in payload
    }


def infer_subject_progress_client_view_defaults(
    root_path: Path,
    *,
    subject_id: str,
    progress: SubjectProgress,
) -> SubjectProgress:
    inferred = copy.deepcopy(progress)
    normalized_subject_id = collapse_ws(subject_id)
    if not normalized_subject_id:
        return inferred
    if not collapse_ws(inferred.research_selected_source_collection_id):
        collections = list_source_collections(Path(root_path).expanduser().resolve(), normalized_subject_id)
        focused_collections = [collection for collection in collections if not _source_collection_is_default(collection)]
        if len(focused_collections) == 1:
            selected_collection = focused_collections[0]
            inferred.research_selected_source_collection_id = collapse_ws(selected_collection.collection_id)
            inferred.research_collection_cursor = next(
                (
                    index
                    for index, collection in enumerate(collections)
                    if collapse_ws(collection.collection_id)
                    == collapse_ws(selected_collection.collection_id)
                ),
                0,
            )
    _ensure_research_source_selection_for_subject_id(
        Path(root_path).expanduser().resolve(),
        subject_id=normalized_subject_id,
        progress=inferred,
    )
    return inferred


def apply_subject_progress_client_view_payload(
    progress: SubjectProgress,
    payload: Mapping[str, object] | None,
) -> SubjectProgress:
    if not payload:
        return progress
    for key in _SUBJECT_PROGRESS_CLIENT_VIEW_KEYS:
        if key not in payload or not hasattr(progress, key):
            continue
        setattr(progress, key, copy.deepcopy(payload[key]))
    return progress


def sanitized_subject_progress_for_persistence(progress: SubjectProgress) -> SubjectProgress:
    # Normalize persisted progress through the public payload schema so client-view
    # selections survive a round-trip without leaking non-serializable state.
    return subject_progress_from_dict(_subject_progress_payload(progress))


