def subject_progress_fingerprint(progress: SubjectProgress) -> str:
    return _stable_json_hash(_subject_progress_payload(progress))[:16]


def _reconcile_loaded_subject_progress(
    root_path: Path,
    *,
    subject_id: str,
    progress: SubjectProgress,
) -> SubjectProgress:
    resolved_root = Path(root_path).expanduser().resolve()
    scenario = next(
        (
            item
            for item in default_subject_scenarios(resolved_root)
            if not item.is_placeholder and collapse_ws(item.subject_id) == collapse_ws(subject_id)
        ),
        None,
    )
    if scenario is None:
        return progress
    if collapse_ws(progress.draft_selected_construct_candidate_id):
        _set_draft_selection_to_construct_candidate_id(
            resolved_root,
            scenario=scenario,
            progress=progress,
            construct_candidate_id=progress.draft_selected_construct_candidate_id,
        )
        return progress
    if collapse_ws(progress.draft_selected_review_item_id):
        _set_draft_selection_to_review_item_id(
            resolved_root,
            scenario=scenario,
            progress=progress,
            review_item_id=progress.draft_selected_review_item_id,
        )
        return progress
    if collapse_ws(progress.itemize_selected_item_id):
        _set_itemize_selection_to_item_id(
            resolved_root,
            scenario=scenario,
            progress=progress,
            itemized_item_id=progress.itemize_selected_item_id,
        )
    return progress


def load_subject_progress(root_path: Path, subject_id: str) -> SubjectProgress:
    normalized_subject_id = collapse_ws(subject_id)
    if not normalized_subject_id:
        return new_subject_progress()
    payload = _read_json(subject_progress_path(root_path, normalized_subject_id))
    if not payload:
        return new_subject_progress()
    progress = subject_progress_from_dict(payload)
    return _reconcile_loaded_subject_progress(
        root_path,
        subject_id=normalized_subject_id,
        progress=progress,
    )


def persist_subject_progress(root_path: Path, subject_id: str, progress: SubjectProgress) -> Path | None:
    normalized_subject_id = collapse_ws(subject_id)
    if not normalized_subject_id:
        return None
    ensure_learning_context_home(Path(root_path).expanduser().resolve(), normalized_subject_id)
    target = subject_progress_path(root_path, normalized_subject_id)
    target.write_text(
        json.dumps(
            _subject_progress_payload(sanitized_subject_progress_for_persistence(progress)),
            indent=2,
            sort_keys=True,
        ),
        encoding="utf-8",
    )
    return target


def load_subject_progress_map(
    root_path: Path,
    scenarios: tuple[SubjectScenario, ...],
    *,
    existing: dict[str, SubjectProgress] | None = None,
) -> dict[str, SubjectProgress]:
    progress_by_key: dict[str, SubjectProgress] = {}
    existing_map = dict(existing or {})
    for scenario in scenarios:
        if scenario.key in existing_map:
            progress_by_key[scenario.key] = existing_map[scenario.key]
            continue
        if scenario.is_placeholder or not collapse_ws(scenario.subject_id):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
            progress_by_key[scenario.key] = new_subject_progress()
            continue
        progress_by_key[scenario.key] = load_subject_progress(root_path, scenario.subject_id)
    return progress_by_key


def subject_has_pending_research_capture(progress: SubjectProgress) -> bool:
    return bool(collapse_ws(progress.pending_research_capture_markdown_text))


def subject_pending_research_capture_target(progress: SubjectProgress) -> str:
    return collapse_ws(progress.pending_research_capture_subject_title)


def _clear_pending_research_capture(progress: SubjectProgress) -> None:
    progress.pending_research_capture_markdown_text = ""
    progress.pending_research_capture_command_text = ""
    progress.pending_research_capture_subject_title_override = ""
    progress.pending_research_capture_subject_id = ""
    progress.pending_research_capture_subject_title = ""
    progress.pending_research_capture_preview_lines = []


def _invalidate_review_and_publication_gate(progress: SubjectProgress) -> None:
    _invalidate_downstream_review_and_publication_gate(progress, preserve_comparison=False)


def _invalidate_downstream_review_and_publication_gate(
    progress: SubjectProgress,
    *,
    preserve_comparison: bool = True,
) -> None:
    progress.review_approved = False
    progress.publication_locked = False
    progress.release_packet_opened = False
    progress.release_review_completed = False
    progress.build_receipt_lines = []
    if not preserve_comparison:
        progress.projections_compared = False
        progress.comparison_status = "pending"
        progress.comparison_receipt_lines = []


def _research_capture_preview_lines(report: dict[str, object]) -> list[str]:
    canonical_title = collapse_ws(str(report.get("canonical_title", ""))) or "<unknown>"
    matched_existing_subject_id = collapse_ws(str(report.get("matched_existing_subject_id", "")))
    override_title = collapse_ws(str(report.get("subject_title_override", "")))
    lines = [
        f"- document: {collapse_ws(str(report.get('document_title', ''))) or '<unknown>'}",
        f"- proposed subject: {canonical_title}",
        (
            f"- target context: existing subject ({matched_existing_subject_id})"
            if matched_existing_subject_id
            else "- target context: new subject"
        ),
        f"- items to stage: {int(report.get('proposed_unit_count', 0) or 0)}",
    ]
    if override_title:
        lines.append(f"- subject override: {override_title}")
    return lines


def _research_capture_receipt_lines(report: dict[str, object]) -> list[str]:
    return [
        f"- subject: {collapse_ws(str(report.get('canonical_title', ''))) or '<unknown>'}",
        f"- subject_id: {collapse_ws(str(report.get('subject_id', ''))) or '<unknown>'}",
        f"- context: {collapse_ws(str(report.get('context_path', ''))) or '<missing>'}",
        f"- staged source: {collapse_ws(str(report.get('staged_source_id', ''))) or '<unknown>'}",
        f"- revision: {collapse_ws(str(report.get('revision_id', ''))) or '<unknown>'}",
        f"- revision markdown: {collapse_ws(str(report.get('revision_markdown_path', ''))) or '<missing>'}",
        f"- staged items: {int(report.get('proposed_unit_count', 0) or 0)}",
    ]


def subject_phase_title(phase: str) -> str:
    return SUBJECT_PHASE_TITLES.get(str(phase or ""), "Gather")


def subject_status_title(phase: str) -> str:
    normalized = collapse_ws(str(phase or "")).casefold()
    if normalized == "research":
        return "Subject Status"
    return f"{subject_phase_title(normalized)} Status"


def subject_journal_title(phase: str) -> str:
    return f"{subject_phase_title(phase)} Journal"


def subject_itemize_detail_title(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder:
        return "Item Detail"
    selected = _selected_itemization_item(_root_path_from_scenario(scenario), scenario=scenario, progress=progress)
    label = collapse_ws(selected.canonical_label) if selected is not None else ""
    return label or "Item Detail"


def subject_research_target_title(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder:
        return "Source Detail"
    selected = _selected_staged_source(_root_path_from_scenario(scenario), subject_id=scenario.subject_id, progress=progress)
    label = collapse_ws(selected.title) if selected is not None else ""
    return label or "Source Detail"


def subject_report_scope_detail_title(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> str:
    if scenario.is_placeholder:
        return "Selection Details"
    selected = _selected_report_scope_entry(
        _report_scope_entries(_root_path_from_scenario(scenario), scenario=scenario, progress=progress),
        progress,
    )
    label = collapse_ws(selected.label) if selected is not None else ""
    return label or "Selection Details"


def _review_ready(scenario: SubjectScenario, progress: SubjectProgress) -> bool:
    return bool(
        not scenario.is_placeholder
        and _composition_current(scenario)
        and collapse_ws(scenario.composition_status) == "approved"
        and (progress.review_approved or progress.publication_locked)
    )


def _publication_locked(scenario: SubjectScenario, progress: SubjectProgress) -> bool:
    del scenario
    return bool(progress.publication_locked)


def _publication_pdf_ready(scenario: SubjectScenario) -> bool:
    path_text = collapse_ws(scenario.report_pdf_path)
    return bool(path_text and Path(path_text).expanduser().is_file())


def _publication_markdown_ready(scenario: SubjectScenario) -> bool:
    path_text = collapse_ws(scenario.report_markdown_path)
    return bool(path_text and Path(path_text).expanduser().is_file())


def _publication_build_ready(scenario: SubjectScenario) -> bool:
    return bool(
        collapse_ws(scenario.build_id)
        and collapse_ws(scenario.validation_status) == "ok"
        and _publication_pdf_ready(scenario)
    )


def _composition_current(scenario: SubjectScenario) -> bool:
    return bool(
        collapse_ws(scenario.composition_id)
        and collapse_ws(scenario.composition_learning_context_snapshot_hash)
        and collapse_ws(scenario.composition_learning_context_snapshot_hash) == collapse_ws(scenario.context_snapshot_hash)
    )


def _subject_workflow_state_inputs(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    markdown_selected_path: str = "",
    markdown_busy: bool = False,
) -> SubjectWorkflowStateInputs:
    itemization_state: dict[str, object] = {}
    draft_composition_state: dict[str, object] = {}
    if not scenario.is_placeholder:
        root_path = _root_path_from_scenario(scenario)
        itemization_state = _itemization_state(root_path, scenario)
        draft_composition_state = _review_composition_state(root_path, scenario)
    return SubjectWorkflowStateInputs(
        subject_exists=not scenario.is_placeholder,
        context_opened=progress.context_opened,
        admitted_unit_count=int(scenario.admitted_unit_count or 0),
        pending_import_count=int(scenario.pending_import_count or 0),
        itemization_exists=bool(itemization_state.get("exists")),
        itemization_current=collapse_ws(str(itemization_state.get("freshness", ""))) == "current",
        itemization_valid=collapse_ws(str(itemization_state.get("validation_status", ""))) == "ok",
        draft_composition_exists=bool(draft_composition_state.get("exists")),
        draft_composition_current=bool(draft_composition_state.get("current")),
        maintained_files_aligned=collapse_ws(progress.comparison_status) == "aligned",
        report_plan_current=_composition_current(scenario),
        review_approved=bool(progress.review_approved),
        publication_locked=bool(progress.publication_locked),
        publication_build_exists=bool(collapse_ws(scenario.build_id)),
        publication_build_ready=_publication_build_ready(scenario),
        release_packet_opened=bool(progress.release_packet_opened),
        release_review_completed=bool(progress.release_review_completed),
        markdown_busy=bool(markdown_busy),
        markdown_source_label=(Path(collapse_ws(markdown_selected_path)).name if collapse_ws(markdown_selected_path) else ""),
    )


def _subject_workflow_current_step_inputs(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    phase: str,
    import_staging: SubjectImportStaging | None = None,
    markdown_busy: bool = False,
    itemization_exists: bool = False,
    itemization_current: bool = False,
    itemization_valid: bool = False,
    itemization_selected: bool = False,
    draft_composition_exists: bool = False,
    draft_composition_current: bool = False,
    ) -> SubjectWorkflowCurrentStepInputs:
    normalized_phase = collapse_ws(phase).casefold() or "research"
    try:
        phase_enum = SubjectWorkflowTab(normalized_phase)
    except ValueError:
        phase_enum = SubjectWorkflowTab.RESEARCH
    staging_source_id = collapse_ws(import_staging.source_subject_id) if import_staging is not None else ""
    current_subject_id = collapse_ws(scenario.subject_id)
    draft_shape_precedes_report_plan = False
    if (
        phase_enum == SubjectWorkflowTab.DRAFT
        and not scenario.is_placeholder
        and bool(draft_composition_exists)
        and bool(draft_composition_current)
    ):
        decision_state = _decision_review_state(_root_path_from_scenario(scenario), scenario)
        decision_frame_exists = bool(decision_state.get("exists"))
        has_constructs = bool(
            _subject_transformation_construct_candidates(
                _root_path_from_scenario(scenario),
                scenario=scenario,
                include_rejected=False,
            )
        )
        selected_draft_item, _selection_source = _selected_draft_review_item(
            _root_path_from_scenario(scenario),
            scenario=scenario,
            progress=progress,
        )
        draft_shape_precedes_report_plan = bool(
            decision_frame_exists
            or has_constructs
            or (
                selected_draft_item is not None
                and _selected_draft_item_supports_decision_analysis(
                    _root_path_from_scenario(scenario),
                    scenario,
                    selected_draft_item=selected_draft_item,
                    decision_frame_exists=decision_frame_exists,
                )
            )
        )
    return SubjectWorkflowCurrentStepInputs(
        phase=phase_enum,
        subject_exists=not scenario.is_placeholder,
        context_opened=progress.context_opened,
        pending_import_count=int(scenario.pending_import_count or 0),
        markdown_busy=bool(markdown_busy),
        import_staging_active=bool(phase_enum == SubjectWorkflowTab.RESEARCH and staging_source_id),
        import_staging_on_current_subject=bool(current_subject_id and staging_source_id == current_subject_id),
        import_staging_target_ready=bool(current_subject_id and progress.context_opened and staging_source_id and staging_source_id != current_subject_id),
        itemization_exists=bool(itemization_exists),
        itemization_current=bool(itemization_current),
        itemization_valid=bool(itemization_valid),
        itemization_selected=bool(itemization_selected),
        draft_composition_exists=bool(draft_composition_exists),
        draft_composition_current=bool(draft_composition_current),
        draft_shape_precedes_report_plan=bool(draft_shape_precedes_report_plan),
        maintained_files_aligned=collapse_ws(progress.comparison_status) == "aligned",
        report_plan_current=_composition_current(scenario),
        review_approved=bool(progress.review_approved),
        publication_locked=bool(progress.publication_locked),
        publication_build_exists=bool(collapse_ws(scenario.build_id)),
        publication_build_ready=_publication_build_ready(scenario),
        release_packet_opened=bool(progress.release_packet_opened),
        release_review_completed=bool(progress.release_review_completed),
    )


def _latest_current_publication_composition(
    root_path: Path,
    *,
    scenario: SubjectScenario,
) -> PublicationComposition | None:
    if scenario.is_placeholder or not collapse_ws(scenario.subject_id):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return None
    resolved_root = Path(root_path).expanduser().resolve()
    context = load_learning_context(resolved_root, scenario.subject_id)
    composition = _latest_publication_composition(
        resolved_root,
        subject_id=scenario.subject_id,
        subject_title=context.canonical_title or scenario.title,
        publication_id=scenario.publication_id,
    )
    if composition is None:
        return None
    if collapse_ws(composition.learning_context_snapshot_hash) != collapse_ws(context.content_hash()):
        return None
    return composition


def _review_ready_from_storage(root_path: Path, *, scenario: SubjectScenario, progress: SubjectProgress) -> bool:
    composition = _latest_current_publication_composition(root_path, scenario=scenario)
    return bool(
        composition is not None
        and collapse_ws(composition.status) == "approved"
        and (progress.review_approved or progress.publication_locked)
    )


def _latest_active_subject_import_selected_in_composition(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    composition: PublicationComposition | None,
) -> SubjectImport | None:
    if composition is None:
        return None
    selected = set(composition.selected_subject_import_ids)
    for subject_import in reversed(_active_subject_imports(root_path, scenario.subject_id)):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        if subject_import.import_id in selected:
            return subject_import
    return None


def _refreshed_subject_scenario(root_path: Path, scenario: SubjectScenario) -> SubjectScenario:
    if scenario.is_placeholder or not collapse_ws(scenario.subject_id):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        return scenario
    for candidate in default_subject_scenarios(Path(root_path).expanduser().resolve()):
        if candidate.subject_id == scenario.subject_id:
            return candidate
    return scenario


def _publication_packet_path_text(scenario: SubjectScenario) -> str:
    for candidate in (scenario.report_pdf_path, scenario.report_markdown_path, scenario.report_typst_path):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        path_text = collapse_ws(candidate)
        if path_text and Path(path_text).expanduser().is_file():
            return str(Path(path_text).expanduser().resolve().parent)
    build_path_text = collapse_ws(scenario.build_path)
    if build_path_text:
        build_path = Path(build_path_text).expanduser()
        if build_path.is_file():
            publication_root = build_path.parent.parent
            if publication_root.exists():
                return str(publication_root.resolve())
    return ""


def _root_path_from_scenario(scenario: SubjectScenario) -> Path:
    context_path_text = collapse_ws(scenario.context_path)
    if context_path_text:
        context_path = Path(context_path_text).expanduser()
        try:
            return context_path.resolve().parents[2]
        except Exception:
            pass
    return Path(".").resolve()


def subject_action_specs(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    phase: str,
    can_capture_assistant: bool = False,
    import_staging: SubjectImportStaging | None = None,
) -> tuple[SubjectActionSpec, SubjectActionSpec, SubjectActionSpec, SubjectActionSpec]:
    normalized = str(phase or "research")
    has_context = not scenario.is_placeholder
    if normalized == "itemize":
        itemization_state = _itemization_state(_root_path_from_scenario(scenario), scenario)
        if not bool(itemization_state.get("exists")):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
            return (
                SubjectActionSpec(
                    key="open_context",
                    label="Open Subject Context",
                    enabled=has_context and not progress.context_opened,
                ),
                SubjectActionSpec(
                    key="generate_itemization",
                    label=_itemization_primary_action_label(itemization_state),
                    enabled=has_context and progress.context_opened,
                ),
                SubjectActionSpec(
                    key="preview_itemization",
                    label="Preview Itemization",
                    enabled=False,
                ),
                SubjectActionSpec(
                    key="",
                    label="",
                    enabled=False,
                ),
            )
        selected_item = _selected_itemization_item(
            _root_path_from_scenario(scenario),
            scenario=scenario,
            progress=progress,
        )
        held_count = len(
            _valid_itemize_held_item_ids(
                items=_itemization_session_and_items(_root_path_from_scenario(scenario), scenario)[1],
                progress=progress,
            )
        )
        selected_item_supports_construct_discovery = _selected_item_supports_construct_discovery(selected_item)
        return (
            SubjectActionSpec(
                key="merge_held_itemized_items",
                label=f"Merge Held Items ({held_count})",
                enabled=held_count >= 2,
            ),
            SubjectActionSpec(
                key="suggest_transformation_constructs",
                label="Suggest DST Constructs",
                enabled=selected_item_supports_construct_discovery,
            ),
            SubjectActionSpec(
                key="",
                label="",
                enabled=False,
            ),
            SubjectActionSpec(
                key="",
                label="",
                enabled=False,
            ),
        )
    if normalized == "draft":
        if scenario.pending_import_count > 0:
            return (
                SubjectActionSpec(
                    key="open_context",
                    label="Open Subject Context",
                    enabled=has_context,
                ),
                SubjectActionSpec(
                    key="preview_pending_import",
                    label="Preview Pending Import",
                    enabled=has_context,
                ),
                SubjectActionSpec(
                    key="approve_subject_import",
                    label="Approve Import",
                    enabled=has_context,
                ),
                SubjectActionSpec(
                    key="goto_review",
                    label="Review",
                    enabled=has_context and progress.context_opened,
                ),
            )
        draft_composition_state = _review_composition_state(_root_path_from_scenario(scenario), scenario)
        composition_current = _composition_current(scenario)
        comparison_aligned = collapse_ws(progress.comparison_status) == "aligned"
        if not bool(draft_composition_state.get("current")):
            return (
                SubjectActionSpec(
                    key="open_context",
                    label="Open Subject Context",
                    enabled=has_context,
                ),
                SubjectActionSpec(
                    key="refresh_review_composition",
                    label=(
                        "Refresh Draft Composition"
                        if bool(draft_composition_state.get("exists"))
                        else "Create Draft Composition"
                    ),
                    enabled=has_context and progress.context_opened,
                ),
                SubjectActionSpec(
                    key="preview_review_composition",
                    label="Preview Draft Composition",
                    enabled=has_context and progress.context_opened and bool(draft_composition_state.get("exists")),
                ),
                SubjectActionSpec(
                    key="preview_itemization",
                    label="Preview Itemization",
                    enabled=has_context and progress.context_opened,
                ),
            )
        selected_draft_item, _selection_source = _selected_draft_review_item(
            _root_path_from_scenario(scenario),
            scenario=scenario,
            progress=progress,
        )
        if _draft_focus_mode(progress) == "model":
            return (
                SubjectActionSpec(
                    key="open_draft_compose_view",
                    label="Back To Compose",
                    enabled=has_context and progress.context_opened,
                ),
                SubjectActionSpec(
                    key="open_draft_model_frame_view",
                    label="Frame",
                    enabled=has_context and progress.context_opened and _draft_model_lens(progress) != "frame",
                ),
                SubjectActionSpec(
                    key="open_draft_model_model_view",
                    label="Model",
                    enabled=has_context and progress.context_opened and _draft_model_lens(progress) != "model",
                ),
                SubjectActionSpec(
                    key="open_draft_model_explore_view",
                    label="Explore",
                    enabled=has_context and progress.context_opened and _draft_model_lens(progress) != "explore",
                ),
            )
        if selected_draft_item is not None:
            return (
                SubjectActionSpec(
                    key="cycle_selected_draft_review_semantic_kind",
                    label=f"Semantic ({_format_orientation_label(selected_draft_item.semantic_kind)})",
                    enabled=has_context and progress.context_opened,
                ),
                SubjectActionSpec(
                    key="cycle_selected_draft_review_render_kind",
                    label=f"Render ({_format_orientation_label(selected_draft_item.render_kind)})",
                    enabled=has_context and progress.context_opened,
                ),
                SubjectActionSpec(
                    key="cycle_selected_draft_review_evidence_mode",
                    label=f"Evidence ({_format_orientation_label(selected_draft_item.evidence_mode)})",
                    enabled=has_context and progress.context_opened,
                ),
                SubjectActionSpec(
                    key="cycle_selected_draft_review_transform_mode",
                    label=f"Transform ({_format_orientation_label(selected_draft_item.transform_mode)})",
                    enabled=has_context and progress.context_opened,
                ),
            )
        return (
            SubjectActionSpec(
                key="open_context",
                label="Open Subject Context",
                enabled=has_context,
            ),
            SubjectActionSpec(
                key="refresh_publication_composition",
                label="Refresh Report Plan" if composition_current else "Create Report Plan",
                enabled=has_context and progress.context_opened and comparison_aligned,
            ),
            SubjectActionSpec(
                key="preview_review_composition" if not composition_current else "preview_publication_composition",
                label="Preview Draft Composition" if not composition_current else "Preview Report Plan",
                enabled=has_context and progress.context_opened,
            ),
            SubjectActionSpec(
                key="goto_review",
                label="Review",
                enabled=has_context and progress.context_opened,
            ),
        )
    if normalized == "review":
        composition_preview_label = _PREVIEW_REPORT_PLAN_LABEL if _composition_current(scenario) else _REFRESH_REPORT_PLAN_LABEL
        composition_preview_key = "preview_publication_composition" if _composition_current(scenario) else "refresh_publication_composition"
        if scenario.pending_import_count > 0:
            return (
                SubjectActionSpec(
                    key="open_context",
                    label="Open Subject Context",
                    enabled=has_context,
                ),
                SubjectActionSpec(
                    key="preview_pending_import",
                    label="Preview Pending Import",
                    enabled=has_context,
                ),
                SubjectActionSpec(
                    key="approve_subject_import",
                    label="Approve Import",
                    enabled=has_context,
                ),
                SubjectActionSpec(
                    key="reject_subject_import",
                    label="Reject Import",
                    enabled=has_context,
                ),
            )
        composition = (
            _latest_publication_composition(
                _root_path_from_scenario(scenario),
                subject_id=scenario.subject_id,
                subject_title=scenario.title,
                publication_id=scenario.publication_id,
            )
            if _composition_current(scenario)
            else None
        )
        return (
            SubjectActionSpec(
                key="open_context",
                label="Open Subject Context",
                enabled=has_context,
            ),
            SubjectActionSpec(
                key="compare_projections",
                label=_COMPARE_MAINTAINED_FILES_LABEL,
                enabled=has_context,
            ),
            SubjectActionSpec(
                key=composition_preview_key,
                label=composition_preview_label,
                enabled=has_context,
            ),
            SubjectActionSpec(
                key="approve_review",
                label="Approve For Report",
                enabled=has_context and progress.comparison_status == "aligned" and _composition_current(scenario) and not progress.review_approved,
            ),
        )
    if normalized == "publication":
        has_build = bool(collapse_ws(scenario.build_id))
        report_md_ready = bool(collapse_ws(scenario.report_markdown_path)) and Path(scenario.report_markdown_path).expanduser().is_file()
        report_pdf_ready = bool(collapse_ws(scenario.report_pdf_path)) and Path(scenario.report_pdf_path).expanduser().is_file()
        packet_ready = bool(_publication_packet_path_text(scenario))
        composition = _latest_current_publication_composition(_root_path_from_scenario(scenario), scenario=scenario)
        decision_frame = load_decision_frame(_root_path_from_scenario(scenario), scenario.subject_id)
        has_decision_model = bool(collapse_ws(decision_frame.decision_frame_id))
        if has_build:
            specs = [
                SubjectActionSpec(
                    key="preview_publication_pdf",
                    label="Preview report.pdf",
                    enabled=report_pdf_ready,
                ),
                SubjectActionSpec(
                    key="build_report",
                    label="Rebuild Report",
                    enabled=has_context and (_review_ready(scenario, progress) or _publication_locked(scenario, progress)),
                ),
            ]
            if has_decision_model:
                specs.append(
                    SubjectActionSpec(
                        key="goto_draft",
                        label="Open Model",
                        enabled=has_context,
                    )
                )
            specs.append(
                SubjectActionSpec(
                    key="open_release_packet",
                    label=_OPEN_RELEASE_FOLDER_LABEL,
                    enabled=packet_ready,
                )
            )
            if len(specs) < 4:
                specs.append(
                    SubjectActionSpec(
                        key="preview_publication_markdown",
                        label="Preview report.md",
                        enabled=report_md_ready,
                    )
                )
            while len(specs) < 4:
                specs.append(
                    SubjectActionSpec(
                        key="preview_publication_markdown",
                        label="Preview report.md",
                        enabled=False,
                    )
                )
            return tuple(specs[:4])
        specs = [
            SubjectActionSpec(
                key="lock_publication",
                label="Lock Report Inputs",
                enabled=has_context and _review_ready(scenario, progress) and not _publication_locked(scenario, progress),
            ),
            SubjectActionSpec(
                key="build_report",
                label="Rebuild Report" if collapse_ws(scenario.build_id) else "Build Report",
                enabled=has_context and (_review_ready(scenario, progress) or _publication_locked(scenario, progress)),
            ),
        ]
        if composition is not None:
            specs.append(
                SubjectActionSpec(
                    key="preview_publication_composition_diff",
                    label=_PREVIEW_REPORT_PLAN_DIFF_LABEL,
                    enabled=has_context and progress.context_opened,
                )
            )
        while len(specs) < 4:
            specs.append(
                SubjectActionSpec(
                    key="open_release_packet" if len(specs) == 2 else "preview_publication_pdf",
                    label=_OPEN_RELEASE_FOLDER_LABEL if len(specs) == 2 else "Preview report.pdf",
                    enabled=False,
                )
            )
        return tuple(specs[:4])
    import_action = SubjectActionSpec(
        key="open_context",
        label="Open Subject Context",
        enabled=has_context,
    )
    markdown_action = SubjectActionSpec(
        key="use_markdown_ingress",
        label=_MARKDOWN_INGRESS_LABEL,
        enabled=True,
    )
    staging_source_id = collapse_ws(import_staging.source_subject_id) if import_staging is not None else ""
    if has_context and progress.context_opened:
        import_action = SubjectActionSpec(
            key="pin_import_source",
            label="Select As Import Source",
            enabled=True,
        )
        if staging_source_id:
            if staging_source_id == collapse_ws(scenario.subject_id):
                import_action = SubjectActionSpec(
                    key="advance_import_selection",
                    label=_subject_import_selection_action_label(
                        import_staging.selection_profile if import_staging is not None else "units_only"
                    ),
                    enabled=_normalize_import_selection_profile(import_staging.selection_profile if import_staging is not None else "") != "full_context",
                )
                markdown_action = SubjectActionSpec(
                    key="clear_import_staging",
                    label="Clear Import Source",
                    enabled=True,
                )
            else:
                import_action = SubjectActionSpec(
                    key="create_subject_import",
                    label="Create Import From Selected Source",
                    enabled=True,
                )
                markdown_action = SubjectActionSpec(
                    key="clear_import_staging",
                    label="Clear Import Source",
                    enabled=True,
                )
        elif scenario.pending_import_count > 0:
            import_action = SubjectActionSpec(
                key="goto_review",
                label="Inspect Pending Import",
                enabled=True,
            )
        elif scenario.reasoning_import_count > 0:
            import_action = SubjectActionSpec(
                key="retire_subject_import",
                label="Retire Active Import",
                enabled=True,
            )
    follow_up_action = SubjectActionSpec(
        key="stage_assistant_capture" if can_capture_assistant else "goto_chat",
        label="Add Last Assistant" if can_capture_assistant else "Ask Follow-up In Chat",
        enabled=True,
    )
    refresh_action = SubjectActionSpec(
        key="refresh_subjects",
        label="Refresh Subjects",
        enabled=True,
    )
    selected_collection = (
        _selected_source_collection(_root_path_from_scenario(scenario), subject_id=scenario.subject_id, progress=progress)
        if has_context and progress.context_opened
        else None
    )
    source_set_action = SubjectActionSpec(
        key="cycle_research_source_collection",
        label=(
            f"Source Set ({selected_collection.title or selected_collection.collection_id})"
            if selected_collection is not None
            else "Next Source Set"
        ),
        enabled=has_context and progress.context_opened and scenario.source_collection_count > 1,
    )
    if not has_context:
        return (
            follow_up_action,
            markdown_action,
            refresh_action,
            import_action,
        )
    return (
        follow_up_action,
        import_action,
        source_set_action,
        markdown_action if not source_set_action.enabled else refresh_action,
    )


def apply_subject_action(
    *,
    root_path: Path,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    action_key: str,
    assistant_message_text: str = "",
    subject_title_override: str = "",
    import_staging: SubjectImportStaging | None = None,
    markdown_selected_path: str = "",
    markdown_status_text: str = "",
    markdown_busy: bool = False,
) -> SubjectActionResult:
    refreshed_scenario = _refreshed_subject_scenario(root_path, scenario)
    scenario = refreshed_scenario
    normalized = str(action_key or "")
    pre_subject_ids = {
        collapse_ws(item.subject_id)
        for item in default_subject_scenarios(Path(root_path).expanduser().resolve())
        if collapse_ws(item.subject_id)
    }

    def _resolve_post_action_subject_key(*candidates: str) -> str:
        after_scenarios = default_subject_scenarios(Path(root_path).expanduser().resolve())
        after_subject_ids = [
            collapse_ws(item.subject_id)
            for item in after_scenarios
            if collapse_ws(item.subject_id)
        ]
        for candidate in candidates:
            normalized_candidate = collapse_ws(candidate)
            if normalized_candidate and normalized_candidate in after_subject_ids:
                return normalized_candidate
        new_subject_ids = [subject_id for subject_id in after_subject_ids if subject_id not in pre_subject_ids]
        if len(new_subject_ids) == 1:
            return new_subject_ids[0]
        if collapse_ws(scenario.subject_id) and collapse_ws(scenario.subject_id) in after_subject_ids:
            return collapse_ws(scenario.subject_id)
        if len(after_subject_ids) == 1:
            return after_subject_ids[0]
        return ""

    if normalized == "refresh_subjects":
        return SubjectActionResult("Subject list refreshed.", "Refreshed live subject list.", reload_subjects=True)
    if normalized == "use_markdown_ingress":
        selected_markdown_path = collapse_ws(markdown_selected_path)
        if selected_markdown_path:
            resolved_root = Path(root_path).expanduser().resolve()
            subject_title_for_ingress = (
                collapse_ws(subject_title_override)
                or ("" if scenario.is_placeholder else collapse_ws(scenario.title))
            )
            stage_result = workstation_stage_markdown_source_action(
                root_path=resolved_root,
                markdown_path=Path(selected_markdown_path),
                subject_id=scenario.subject_id,
                subject_title=subject_title_for_ingress,
            )
            stage_payload = stage_result.payload if isinstance(stage_result.payload, dict) else {}
            resolved_subject_key = _resolve_post_action_subject_key(
                str(stage_payload.get("subject_id", "")),
                collapse_ws(scenario.subject_id),
            )
            receipt_lines = [
                f"- markdown: {Path(selected_markdown_path).name}",
                f"- stage: {collapse_ws(markdown_status_text) or collapse_ws(stage_result.message) or 'staged'}",
                f"- busy flag seen: {'yes' if markdown_busy else 'no'}",
            ]
            if resolved_subject_key:
                receipt_lines.append(f"- subject: {resolved_subject_key}")
            staged_source_id = collapse_ws(str(stage_payload.get("staged_source_id", "")))
            if staged_source_id:
                receipt_lines.append(f"- staged source: {staged_source_id}")
            if collapse_ws(str(stage_payload.get("context_path", ""))):
                receipt_lines.append(f"- context path: {collapse_ws(str(stage_payload.get('context_path', '')))}")
            if collapse_ws(str(stage_result.status)) != "ok":
                error_text = collapse_ws(stage_result.message) or "Markdown intake failed."
                _set_latest_receipt(
                    progress,
                    title="Markdown Intake Failed",
                    lines=(*receipt_lines, f"- error: {error_text}"),
                )
                progress.timeline.append(f"Markdown intake failed for {Path(selected_markdown_path).name}.")
                return SubjectActionResult(
                    error_text,
                    error_text,
                    next_phase="research",
                    reload_subjects=bool(resolved_subject_key),
                    preferred_subject_key=resolved_subject_key,
                )
            import_result = workstation_import_staged_source_action(
                root_path=resolved_root,
                subject_id=resolved_subject_key or collapse_ws(str(stage_payload.get("subject_id", ""))),
                staged_source_id=staged_source_id,
            )
            import_payload = import_result.payload if isinstance(import_result.payload, dict) else {}
            import_report = import_payload.get("report", {}) if isinstance(import_payload.get("report", {}), dict) else {}
            learning_context = (
                import_report.get("learning_context", {})
                if isinstance(import_report.get("learning_context", {}), dict)
                else {}
            )
            resolved_subject_key = _resolve_post_action_subject_key(
                collapse_ws(str(import_payload.get("subject_id", ""))),
                collapse_ws(str(import_report.get("subject_id", ""))),
                collapse_ws(str(learning_context.get("subject_id", ""))),
                resolved_subject_key,
                collapse_ws(scenario.subject_id),
            )
            if collapse_ws(str(import_payload.get("canonical_export_path", ""))):
                receipt_lines.append(
                    f"- canonical export: {collapse_ws(str(import_payload.get('canonical_export_path', '')))}"
                )
            if collapse_ws(str(import_report.get("context_path", ""))):
                receipt_lines.append(f"- imported context path: {collapse_ws(str(import_report.get('context_path', '')))}")
            elif collapse_ws(str(learning_context.get("context_path", ""))):
                receipt_lines.append(
                    f"- imported context path: {collapse_ws(str(learning_context.get('context_path', '')))}"
                )
            imported_titles = tuple(
                collapse_ws(str(item))
                for item in import_payload.get("imported_titles", ())
                if collapse_ws(str(item))
            ) if isinstance(import_payload.get("imported_titles", ()), (list, tuple)) else ()
            if imported_titles:
                receipt_lines.append(f"- imported titles: {', '.join(imported_titles)}")
            if collapse_ws(str(import_result.status)) == "ok":
                _invalidate_review_and_publication_gate(progress)
                _set_latest_receipt(
                    progress,
                    title="Markdown Intake Receipt",
                    lines=(*receipt_lines, "- import: imported staged source into the subject"),
                )
                entry = (
                    f"Imported {Path(selected_markdown_path).name} into "
                    f"{resolved_subject_key or 'the current Gather subject'}."
                )
                progress.timeline.append(entry)
                return SubjectActionResult(
                    collapse_ws(import_result.message) or "Markdown intake imported.",
                    entry,
                    next_phase="research",
                    reload_subjects=True,
                    preferred_subject_key=resolved_subject_key,
                )
            error_text = collapse_ws(import_result.message) or "Markdown intake import failed."
            _set_latest_receipt(
                progress,
                title="Markdown Intake Failed",
                lines=(*receipt_lines, f"- import error: {error_text}"),
            )
            progress.timeline.append(f"Markdown intake import failed for {Path(selected_markdown_path).name}.")
            return SubjectActionResult(
                error_text,
                error_text,
                next_phase="research",
                reload_subjects=True,
                preferred_subject_key=resolved_subject_key,
            )
        return SubjectActionResult(
            "Use Select Markdown File to choose a markdown document for subject intake.",
            "Guided intake toward markdown file import.",
        )
