        if not latest_assistant or latest_assistant == baseline_assistant:
            return SubjectActionResult("No newer set-source merge-back proposal is available yet.")
        parsed_blocks = _parse_marked_source_set_merge_back_text(latest_assistant)
        if not parsed_blocks:
            return SubjectActionResult(
                "The last assistant reply is missing the required repeated [source] blocks with [url], [label], and [text]."
            )
        staged_sources = _staged_sources_for_collection(root, collection=selected_collection)
