def _build_current_step_itemize_refresh(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    freshness = collapse_ws(str(context.itemization_state.get("freshness", ""))) or "missing"
    validation_status = collapse_ws(str(context.itemization_state.get("validation_status", ""))) or "unavailable"
    item_count = int(context.itemization_state.get("item_count", 0) or 0)
    refresh_label = _itemization_primary_action_label(context.itemization_state)
    selected_item = _selected_itemization_item(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    detail_lines = [f"- refresh action: {refresh_label}"]
    detail_lines.extend(
        f"- validation issue: {error}"
        for error in tuple(context.itemization_state.get("validation_errors", ()))[:3]
    )
    return SubjectCurrentStepView(
        title="Refresh the itemization inventory",
        status=(
            f"The current itemization needs attention. freshness={freshness}, "
            f"validation={validation_status}, items={item_count}."
        ),
        why="Draft and Review should work from a current, validated item inventory for the active subject snapshot.",
        detail_lines=tuple(detail_lines),
        primary_action=_gate_subject_action("generate_itemization", refresh_label),
        secondary_actions=_visible_gate_actions(
            _gate_subject_action("preview_itemization", "Preview Itemization"),
            _gate_subject_action(
                "suggest_transformation_constructs",
                "Suggest DST Constructs",
                enabled=_selected_item_supports_construct_discovery(selected_item),
            ),
        ),
    )


