def _build_current_step_itemize_orient(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    if context.selected_item is None:
        raise AssertionError("Itemize orient state requires a selected item.")
    selected_item = context.selected_item
    pending_path = _pending_itemize_manual_rephrase_path(
        progress=context.progress,
        selected_item=selected_item,
    )
    if pending_path is not None:
        return _build_current_step_itemize_apply_manual_rephrase(context)
    if _pending_itemize_llm_rephrase(progress=context.progress, selected_item=selected_item):
        return _build_current_step_itemize_apply_llm_rephrase(context)
    selected_status = collapse_ws(selected_item.status) or "candidate"
    decision_role = normalize_itemized_decision_role(selected_item.metadata.get("decision_role", ""))
    held_ids = _valid_itemize_held_item_ids(
        items=_itemization_session_and_items(context.root_path, context.scenario)[1],
        progress=context.progress,
    )
    split_labels = _itemize_split_labels(selected_item)
    construct_candidates = _construct_candidates_for_itemized_item(
        context.root_path,
        scenario=context.scenario,
        itemized_item_id=selected_item.itemized_item_id,
        include_rejected=True,
    )
    suggest_action = _gate_subject_action(
        "suggest_transformation_constructs",
        (
            f"Suggest DST Constructs ({len(construct_candidates)})"
            if construct_candidates
            else "Suggest DST Constructs"
        ),
        enabled=_selected_item_supports_construct_discovery(selected_item),
    )
    if selected_status == "candidate":
        primary_action = _gate_subject_action("promote_selected_itemized_item", "Promote Item")
        secondary_actions = (
            _gate_subject_action("reject_selected_itemized_item", "Reject Item"),
            _gate_subject_action("generate_itemization", "Refresh Itemization"),
            suggest_action,
        )
    elif selected_status == "promoted":
        primary_action = _gate_subject_action("restore_selected_itemized_item", "Return To Candidate")
        secondary_actions = (
            _gate_subject_action("reject_selected_itemized_item", "Reject Item"),
            _gate_subject_action("generate_itemization", "Refresh Itemization"),
            suggest_action,
        )
    elif selected_status == "rejected":
        primary_action = _gate_subject_action("restore_selected_itemized_item", "Return To Candidate")
        secondary_actions = (
            _gate_subject_action("promote_selected_itemized_item", "Promote Item"),
            _gate_subject_action("generate_itemization", "Refresh Itemization"),
            suggest_action,
        )
    else:
        primary_action = _gate_subject_action("preview_selected_itemized_item", "Preview Selected Item")
        secondary_actions = (
            _gate_subject_action("cycle_selected_itemized_item_decision_role", "Cycle Decision Role"),
            _gate_subject_action("generate_itemization", "Refresh Itemization"),
            suggest_action,
        )
    return SubjectCurrentStepView(
        title="Orient the selected item",
        status=f"Current item: {selected_item.canonical_label} [{selected_item.item_kind}] status={selected_status}.",
        why="Promote, reject, split, merge, and assign decision roles here before Draft composition and later Review.",
        detail_lines=(
            f"- decision role: {decision_role or '<none>'}",
            f"- held for merge: {len(held_ids)}",
            f"- source refs: {len(selected_item.source_refs)}",
            f"- suggested constructs: {len(construct_candidates)}",
        ),
        primary_action=primary_action,
        secondary_actions=secondary_actions,
    )


