def _build_current_step_review_apply_manual_section_rephrase(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    selected = _selected_report_scope_section_entry(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    if selected is None:
        raise AssertionError("Review section manual rephrase state requires a selected report section.")
    _composition, _entry, section_id, _role, title = selected
    pending_path = _pending_review_section_manual_rephrase_path(
        progress=context.progress,
        section_id=section_id,
    )
    path_label = (
        _ui_path_label(context.root_path, str(pending_path))
        if pending_path is not None
        else "<missing>"
    )
    return SubjectCurrentStepView(
        title="Apply the manual section brief",
        status="A manual section brief draft is open for the selected report section.",
        why="Review is where the report plan is shaped. Section briefs belong here, not in the source prose.",
        detail_lines=(
            f"- section: {title}",
            f"- edit file: {path_label}",
            "- next: save the file, then apply or discard this section brief",
        ),
        primary_action=_gate_subject_action("apply_review_section_manual_rephrase", "Apply Manual Rephrase"),
        secondary_actions=(
            _gate_subject_action("discard_review_section_manual_rephrase", "Discard Manual Rephrase"),
        ),
    )


def _build_current_step_review_apply_llm_section_rephrase(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    selected = _selected_report_scope_section_entry(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    if selected is None:
        raise AssertionError("Review section LLM rephrase state requires a selected report section.")
    _composition, _entry, section_id, _role, title = selected
    return SubjectCurrentStepView(
        title="Apply the LLM section brief",
        status="A chat section brief is pending for the selected report section.",
        why="Review is where the report plan is shaped. Section briefs belong here, not in the source prose.",
        detail_lines=(
            f"- section: {title}",
            "- assistant format: reply using [label] and [text] sections only",
            "- next: return from Chat, then apply or discard the latest assistant reply",
        ),
        primary_action=_gate_subject_action("apply_review_section_llm_rephrase", "Apply LLM Rephrase"),
        secondary_actions=(
            _gate_subject_action("discard_review_section_llm_rephrase", "Discard LLM Rephrase"),
        ),
    )


def _build_current_step_draft_create_report_plan(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    if _draft_focus_mode(context.progress) == "model":
        return _build_current_step_draft_model(context)
    selected_draft_item, _selection_source = _selected_draft_review_item(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    recovery_state = _draft_decision_recovery_state(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    if selected_draft_item is not None:
        pending_path = _pending_draft_manual_rephrase_path(
            progress=context.progress,
            selected_item=selected_draft_item,
        )
        if pending_path is not None:
            return _build_current_step_draft_apply_manual_rephrase(context)
        if _pending_draft_llm_rephrase(progress=context.progress, selected_item=selected_draft_item):
            return _build_current_step_draft_apply_llm_rephrase(context)
        dst_fixture = _dst_fixture_for_subject(context.root_path, context.scenario)
        decision_state = _decision_review_state(context.root_path, context.scenario)
        decision_frame = decision_state.get("frame")
        decision_items = list_decision_review_items(context.root_path, context.scenario.subject_id)
        policy_profile_kind = collapse_ws(str(decision_state.get("policy_profile_kind", ""))) or "conservative"
        latest_decision_receipt = decision_state.get("latest_receipt")
        frame_is_dst_seeded = (
            bool(decision_state.get("exists"))
            and isinstance(decision_frame, DecisionFrame)
            and bool(decision_frame.metadata.get("dst_seeded"))
        )
        dst_refresh_required = _dst_decision_analysis_refresh_required(
            context.root_path,
            context.scenario,
            decision_frame if isinstance(decision_frame, DecisionFrame) else None,
        )
        refresh_dst_action = _gate_subject_action(
            "refresh_dst_decision_analysis",
            "Refresh DST Analysis",
            enabled=bool(dst_fixture is not None),
        )
        selected_in_decision_frame = _draft_review_item_effectively_included_in_decision(
            context.root_path,
            scenario=context.scenario,
            review_item=selected_draft_item,
            decision_items=decision_items,
            frame=decision_frame if isinstance(decision_frame, DecisionFrame) else None,
        )
        selected_label = (
            collapse_ws(str(selected_draft_item.metadata.get("canonical_label", "")))
            or selected_draft_item.review_item_id
        )
        split_labels = _draft_review_split_labels(
            context.root_path,
            scenario=context.scenario,
            item=selected_draft_item,
        )
        sibling_items = review_item_children(
            _draft_review_items(context.root_path, scenario=context.scenario),
            selected_draft_item.parent_review_item_id,
        )
        has_next_sibling = any(
            collapse_ws(item.review_item_id) == collapse_ws(selected_draft_item.review_item_id)
            for item in sibling_items[:-1]
        )
        structure_action = _gate_subject_action(
            (
                "promote_selected_draft_review_item_to_root"
                if collapse_ws(selected_draft_item.parent_review_item_id)
                else "split_selected_draft_review_item"
            ),
            (
                "Promote Child To Root"
                if collapse_ws(selected_draft_item.parent_review_item_id)
                else (f"Split Draft Item ({len(split_labels)})" if len(split_labels) >= 2 else "Split Draft Item")
            ),
            enabled=(
                bool(collapse_ws(selected_draft_item.parent_review_item_id))
                or (len(split_labels) >= 2 and not selected_draft_item.child_review_item_ids)
            ),
        )
        merge_action = _gate_subject_action(
            "merge_selected_draft_review_item_with_next_sibling",
            "Merge With Next Sibling",
            enabled=has_next_sibling,
        )
        open_model_action = _gate_subject_nav_action("open_draft_model_view", "Open Model")
        if recovery_state.recovery_plan is not None:
            return SubjectCurrentStepView(
                title=recovery_state.recovery_plan.title,
                status=recovery_state.recovery_plan.status,
                why=(
                    recovery_state.recovery_plan.why
                    + " Draft will keep the report plan and decision work in sync from the same draft composition."
                ),
                detail_lines=(
                    *recovery_state.recovery_plan.detail_lines,
                    "- report plan: created or refreshed automatically from the current draft composition",
                ),
                primary_action=_gate_subject_action(
                    recovery_state.recovery_plan.action_key,
                    recovery_state.recovery_plan.action_label,
                ),
                secondary_actions=_visible_gate_actions(
                    open_model_action,
                    structure_action,
                    merge_action,
                ),
            )
        selected_decision_role = _selected_draft_item_decision_role(selected_draft_item)
        decision_relevant = _selected_draft_item_supports_decision_analysis(
            context.root_path,
            context.scenario,
            selected_draft_item=selected_draft_item,
            decision_frame_exists=bool(decision_state.get("exists")),
        )
        next_policy_kind = _format_orientation_label(next_decision_policy_profile_kind(policy_profile_kind))
        if decision_relevant:
            if not frame_is_dst_seeded and not selected_in_decision_frame:
                return SubjectCurrentStepView(
                    title="Include this item in the decision analysis",
                    status="A decision analysis exists. Include this item only if it materially changes the choice, comparison, or recommendation.",
                    why="Keep the decision analysis narrow. Draft will update the attached report plan automatically.",
                    detail_lines=(
                        f"- selected item: {selected_label}",
                        *([f"- decision role: {_format_orientation_label(selected_decision_role)}"] if selected_decision_role else []),
                        f"- current decision items: {len(decision_items)}",
                        "- report plan: updated automatically when the decision analysis changes",
                    ),
                    primary_action=_gate_subject_action(
                        "add_selected_draft_review_item_to_decision_frame",
                        "Include In Decision Analysis",
                    ),
                    secondary_actions=_visible_gate_actions(
                        open_model_action,
                        structure_action,
                        merge_action,
                    ),
                )
            if latest_decision_receipt is None:
                return SubjectCurrentStepView(
                    title="Run decision analysis",
                    status="The decision frame exists, but no current analysis receipt is attached yet.",
                    why="Running it again is the recovery path once the current frame, included items, and governed structure are in place.",
                    detail_lines=(
                        f"- selected item: {selected_label}",
                        *([f"- decision role: {_format_orientation_label(selected_decision_role)}"] if selected_decision_role else []),
                        f"- current decision items: {len(decision_items)}",
                    ),
                    primary_action=_gate_subject_action("analyze_decision_frame", "Run Decision Analysis"),
                    secondary_actions=_visible_gate_actions(
                        open_model_action,
                        structure_action,
                        merge_action,
                    ),
                )
            recommended_option_ids = tuple(
                str(item) for item in latest_decision_receipt.metadata.get("recommended_option_ids", ())
            )
            return SubjectCurrentStepView(
                title="Decision analysis is ready",
                status="The latest decision-analysis receipt is available. Hand the draft to Review unless you need to rerun the analysis under a different policy.",
                why="Review should validate and approve the report together with the attached recommendation-grade analysis.",
                detail_lines=(
                    f"- recommendation status: {collapse_ws(str(latest_decision_receipt.recommendation_status)) or 'pending'}",
                    f"- policy: {_format_orientation_label(policy_profile_kind)}",
                    *(
                        [f"- recommended option: {option_id}" for option_id in recommended_option_ids[:3]]
                        if recommended_option_ids
                        else ["- recommended option: <none>"]
                    ),
                ),
                primary_action=_gate_subject_action("goto_review", "Hand To Review"),
                secondary_actions=_visible_gate_actions(
                    _gate_subject_action(
                        "cycle_decision_policy_profile",
                        f"Re-run Analysis ({next_policy_kind})",
                    ),
                    open_model_action,
                    structure_action,
                ),
            )
    if recovery_state.recovery_plan is not None:
        return SubjectCurrentStepView(
            title=recovery_state.recovery_plan.title,
            status=recovery_state.recovery_plan.status,
            why=(
                recovery_state.recovery_plan.why
                + " Draft will keep the report plan and decision work in sync from the same draft composition."
            ),
            detail_lines=(
                *recovery_state.recovery_plan.detail_lines,
                "- report plan: created or refreshed automatically from the current draft composition",
            ),
            primary_action=_gate_subject_action(
                recovery_state.recovery_plan.action_key,
                recovery_state.recovery_plan.action_label,
            ),
            secondary_actions=_visible_gate_actions(
                _gate_subject_action("preview_review_composition", "Preview Draft Composition"),
                _gate_subject_nav_action(
                    "open_draft_model_view",
                    "Open Model",
                    enabled=bool(
                        _subject_transformation_construct_candidates(
                            context.root_path,
                            scenario=context.scenario,
                            include_rejected=False,
                        )
                    ),
                ),
                _gate_phase_action("review"),
            ),
        )
    return SubjectCurrentStepView(
        title="Create the report plan",
        status="The draft composition is current, but no report plan exists for this subject snapshot.",
        why="Draft should turn the broad typed inventory into a governed report plan so composition starts from structured inputs instead of manual one-by-one selection.",
        detail_lines=(
            "- result: a report plan seeded from all non-rejected draft items by default",
            "- Review will still validate maintained files and approve the plan before publication",
        ),
        primary_action=_gate_subject_action("refresh_publication_composition", "Create Report Plan"),
        secondary_actions=_visible_gate_actions(
            _gate_subject_action("preview_review_composition", "Preview Draft Composition"),
            _gate_subject_nav_action(
                "open_draft_model_view",
                "Open Model",
                enabled=bool(
                    _subject_transformation_construct_candidates(
                        context.root_path,
                        scenario=context.scenario,
                        include_rejected=False,
                    )
                ),
            ),
            _gate_phase_action("review"),
        ),
    )


def _build_current_step_draft_model(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    selected_draft_item, _selection_source = _selected_draft_review_item(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    if selected_draft_item is not None:
        pending_path = _pending_draft_manual_rephrase_path(
            progress=context.progress,
            selected_item=selected_draft_item,
        )
        if pending_path is not None:
            return _build_current_step_draft_apply_manual_rephrase(context)
        if _pending_draft_llm_rephrase(progress=context.progress, selected_item=selected_draft_item):
            return _build_current_step_draft_apply_llm_rephrase(context)
    construct_candidates = _subject_transformation_construct_candidates(
        context.root_path,
        scenario=context.scenario,
        include_rejected=False,
    )
    selected_candidate = _selected_transformation_construct_candidate(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
        include_rejected=False,
    )
    recovery_state = _draft_decision_recovery_state(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    decision_state = recovery_state.decision_state
    decision_frame = decision_state.get("frame")
    decision_items = list_decision_review_items(context.root_path, context.scenario.subject_id)
    latest_decision_receipt = decision_state.get("latest_receipt")
    policy_profile_kind = collapse_ws(str(decision_state.get("policy_profile_kind", ""))) or "conservative"
    next_policy_kind = _format_orientation_label(next_decision_policy_profile_kind(policy_profile_kind))
    dst_fixture = _dst_fixture_for_subject(context.root_path, context.scenario)
    dst_refresh_required = _dst_decision_analysis_refresh_required(
        context.root_path,
        context.scenario,
        decision_frame if isinstance(decision_frame, DecisionFrame) else None,
    )
    refresh_dst_action = _gate_subject_action(
        "refresh_dst_decision_analysis",
        "Refresh DST Analysis",
        enabled=bool(dst_fixture is not None),
    )
    back_to_compose = _gate_subject_nav_action("open_draft_compose_view", "Back To Compose")
    if not construct_candidates:
        return SubjectCurrentStepView(
            title="Suggest transformation constructs first",
            status="Draft Model is empty because no transformation constructs have been suggested from Itemize yet.",
            why="Model mode curates typed actors, objectives, capabilities, constraints, states, transitions, and decisions before running decision analysis.",
            detail_lines=(
                "- next phase: Itemize",
                "- use Suggest DST Constructs on the selected itemized candidate",
            ),
            primary_action=_gate_phase_action("itemize"),
            secondary_actions=(back_to_compose,),
        )
    if selected_candidate is None:
        return SubjectCurrentStepView(
            title="Select a transformation construct",
            status="Transformation constructs exist, but none is currently selected in Draft Model.",
            why="Use Up/Down in the construct inventory to focus one construct before accepting it into the decision analysis.",
            detail_lines=(
                f"- available constructs: {len(construct_candidates)}",
                f"- accepted constructs: {sum(1 for item in construct_candidates if collapse_ws(item.status) == 'accepted')}",
            ),
            primary_action=back_to_compose,
            secondary_actions=(),
        )
    if collapse_ws(selected_candidate.status) != "accepted":
        return SubjectCurrentStepView(
            title="Accept this construct into decision analysis",
            status="The selected construct is ready to be added to the decision analysis.",
            why="Draft Model turns suggested constructs into an explicit decision frame before analysis runs or Review sees recommendation-grade output.",
            detail_lines=(
                f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                f"- sort: {_format_orientation_label(selected_candidate.sort_kind)}",
                f"- lane after acceptance: {_format_orientation_label(_current_construct_candidate_lane(selected_candidate, frame=decision_frame if isinstance(decision_frame, DecisionFrame) else None))}",
                f"- pending constructs: {sum(1 for item in construct_candidates if collapse_ws(item.status) == 'candidate')}",
                f"- accepted constructs: {sum(1 for item in construct_candidates if collapse_ws(item.status) == 'accepted')}",
            ),
            primary_action=_gate_subject_action(
                "accept_selected_draft_construct_candidate",
                "Accept Construct",
            ),
            secondary_actions=_visible_gate_actions(
                _gate_subject_action(
                    "cycle_selected_draft_construct_sort",
                    f"Type ({_format_orientation_label(selected_candidate.sort_kind)})",
                ),
                back_to_compose,
            ),
        )
    selected_decision_item = _decision_review_item_for_construct_candidate(decision_items, selected_candidate)
    selected_lane = _current_construct_candidate_lane(
        selected_candidate,
        decision_item=selected_decision_item,
        frame=decision_frame if isinstance(decision_frame, DecisionFrame) else None,
    )
    missing_relation = _first_missing_draft_model_relation(decision_items)
    if (
        missing_relation is not None
        and (
            selected_decision_item is None
            or collapse_ws(selected_decision_item.decision_review_item_id)
            != collapse_ws(missing_relation[1].decision_review_item_id)
        )
    ):
        missing_kind, missing_item, related_item = missing_relation
        missing_label = _decision_item_display_label(missing_item)
        detail_lines = [f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}"]
        if missing_kind == "transition_source":
            title = "Inspect the next missing relation"
            status = f"{missing_label} still needs its source state."
            why = "Draft Model should close one explicit missing relation at a time so the decision model stays reviewable."
        elif missing_kind == "transition_target":
            title = "Inspect the next missing relation"
            status = f"{missing_label} still needs its target state."
            why = "A transition cannot participate in candidate-path evaluation until its destination state is explicit."
            if related_item is not None:
                detail_lines.append(f"- source state: {_decision_item_display_label(related_item)}")
        elif missing_kind == "transition_changed_capability":
            title = "Inspect the next missing relation"
            status = f"{missing_label} still needs its changed capability."
            why = "The model must say what capability a transition actually changes before decisions and assignments can be evaluated."
        elif missing_kind == "decision_transition":
            title = "Inspect the next missing relation"
            status = f"{missing_label} still needs its selected transition."
            why = "A decision candidate is only analyzable when it selects one concrete transition."
        elif missing_kind == "decision_transition_changed_capability":
            title = "Inspect the next missing relation"
            status = f"{missing_label} points at a transition that still needs its changed capability."
            why = "Actor assignment comes after the selected transition says which capability it changes."
            if related_item is not None:
                detail_lines.append(f"- selected transition: {_decision_item_display_label(related_item)}")
        else:
            title = "Inspect the next missing relation"
            status = f"{missing_label} still needs its assigned actor."
            why = "A decision is not valid until every changed capability has an assigned actor."
            if related_item is not None:
                detail_lines.append(f"- selected transition: {_decision_item_display_label(related_item)}")
        detail_lines.append(f"- missing construct: {missing_label}")
        return SubjectCurrentStepView(
            title=title,
            status=status,
            why=why,
            detail_lines=tuple(detail_lines),
            primary_action=_gate_subject_action(
                "focus_next_missing_draft_model_relation",
                "Focus Missing Construct",
            ),
            secondary_actions=(back_to_compose,),
        )
    if selected_decision_item is not None and selected_lane == "capability":
        dependency_items = _dependency_decision_review_items(decision_items)
        boundary_items = _boundary_decision_review_items(decision_items)
        required_dependency_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                dict(selected_decision_item.metadata),
                plural_key=_CAPABILITY_REQUIRED_DEPENDENCY_DECISION_ITEM_IDS_KEY,
                singular_key=_CAPABILITY_REQUIRED_DEPENDENCY_DECISION_ITEM_ID_KEY,
            ),
        )
        crossed_boundary_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                dict(selected_decision_item.metadata),
                plural_key=_CAPABILITY_CROSSED_BOUNDARY_DECISION_ITEM_IDS_KEY,
                singular_key=_CAPABILITY_CROSSED_BOUNDARY_DECISION_ITEM_ID_KEY,
            ),
        )
        add_next_dependency_id = _next_unbound_relation_binding_id(
            tuple(item.decision_review_item_id for item in required_dependency_items),
            dependency_items,
        )
        add_next_boundary_id = _next_unbound_relation_binding_id(
            tuple(item.decision_review_item_id for item in crossed_boundary_items),
            boundary_items,
        )
        relation_secondary_actions: list[SubjectGateAction] = []
        if add_next_dependency_id:
            relation_secondary_actions.append(
                _gate_subject_action(
                    "bind_selected_draft_construct_capability_dependency",
                    f"Add Dependency ({len(required_dependency_items)})",
                )
            )
        relation_secondary_actions.append(
            _gate_subject_action(
                "unbind_selected_draft_construct_capability_dependency",
                "Remove Dependency",
                enabled=bool(required_dependency_items),
            )
        )
        if add_next_boundary_id:
            relation_secondary_actions.append(
                _gate_subject_action(
                    "bind_selected_draft_construct_capability_boundary",
                    f"Add Boundary ({len(crossed_boundary_items)})",
                )
            )
        relation_secondary_actions.append(
            _gate_subject_action(
                "unbind_selected_draft_construct_capability_boundary",
                "Remove Boundary",
                enabled=bool(crossed_boundary_items),
            )
        )
        relation_secondary_actions.append(back_to_compose)
        if dependency_items and not required_dependency_items:
            return SubjectCurrentStepView(
                title="Link the first dependency for this capability",
                status="This capability is accepted, but no required dependency is linked yet.",
                why="Dependencies stay optional, but linking them now gives Explore and Review a more explicit gating model.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- dependency options: {', '.join(_decision_item_display_label(item) for item in dependency_items[:4])}",
                    f"- crossed boundaries ({len(crossed_boundary_items)}): {_relation_labels(crossed_boundary_items)}",
                ),
                primary_action=_gate_subject_action(
                    "bind_selected_draft_construct_capability_dependency",
                    "Bind Dependency",
                ),
                secondary_actions=_visible_gate_actions(*relation_secondary_actions),
            )
        if boundary_items and not crossed_boundary_items:
            return SubjectCurrentStepView(
                title="Link the first boundary for this capability",
                status="This capability is accepted, but no crossed boundary is linked yet.",
                why="Boundary links stay optional, but they let Explore surface friction and coordination edges explicitly.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- required dependencies ({len(required_dependency_items)}): {_relation_labels(required_dependency_items)}",
                    f"- boundary options: {', '.join(_decision_item_display_label(item) for item in boundary_items[:4])}",
                ),
                primary_action=_gate_subject_action(
                    "bind_selected_draft_construct_capability_boundary",
                    "Bind Boundary",
                ),
                secondary_actions=_visible_gate_actions(*relation_secondary_actions),
            )
        if latest_decision_receipt is None:
            return SubjectCurrentStepView(
                title="Run decision analysis for this capability-ready model",
                status="This capability is accepted and any currently selected dependencies or boundaries are linked.",
                why="Run decision analysis now unless this capability still needs more gating relations first.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- required dependencies ({len(required_dependency_items)}): {_relation_labels(required_dependency_items)}",
                    f"- crossed boundaries ({len(crossed_boundary_items)}): {_relation_labels(crossed_boundary_items)}",
                ),
                primary_action=_gate_subject_action("analyze_decision_frame", "Run Decision Analysis"),
                secondary_actions=_visible_gate_actions(*relation_secondary_actions),
            )
        return SubjectCurrentStepView(
            title="Review or refine this capability model",
            status="This capability already has a decision-analysis receipt. Refine its dependency or boundary links only if the modeled gating is incomplete.",
            why="Once the capability relations are explicit, the next workflow step is Review unless the relation set still needs work.",
            detail_lines=(
                f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                f"- required dependencies ({len(required_dependency_items)}): {_relation_labels(required_dependency_items)}",
                f"- crossed boundaries ({len(crossed_boundary_items)}): {_relation_labels(crossed_boundary_items)}",
            ),
            primary_action=_gate_phase_action("review"),
            secondary_actions=_visible_gate_actions(*relation_secondary_actions),
        )
    if selected_decision_item is not None and selected_lane == "transition_candidate":
        state_items = _state_decision_review_items(decision_items)
        source_item = _decision_item_by_id(
            decision_items,
            str(selected_decision_item.metadata.get(_TRANSITION_SOURCE_DECISION_ITEM_ID_KEY, "")),
        )
        target_item = _decision_item_by_id(
            decision_items,
            str(selected_decision_item.metadata.get(_TRANSITION_TARGET_DECISION_ITEM_ID_KEY, "")),
        )
        if not state_items:
            return SubjectCurrentStepView(
                title="Accept states before binding this transition",
                status="This transition is accepted, but there are no accepted state lanes to bind as its source or target yet.",
                why="A transition needs explicit states before decision analysis can reason about admissibility.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- lane: {_format_orientation_label(selected_lane)}",
                ),
                primary_action=back_to_compose,
                secondary_actions=(),
            )
        if source_item is None:
            return SubjectCurrentStepView(
                title="Bind the transition source state",
                status="This accepted transition still needs its source state.",
                why="Decision analysis needs an explicit from-state before it can evaluate whether the transition is admissible.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- available states: {', '.join(_decision_item_display_label(item) for item in state_items[:4])}",
                ),
                primary_action=_gate_subject_action(
                    "bind_selected_draft_construct_transition_source",
                    "Bind Source State",
                ),
                secondary_actions=_visible_gate_actions(
                    back_to_compose,
                ),
            )
        if target_item is None:
            return SubjectCurrentStepView(
                title="Bind the transition target state",
                status="The transition source is set, but the target state is still missing.",
                why="Decision analysis needs an explicit to-state before the transition can participate in candidate-path evaluation.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- source state: {_decision_item_display_label(source_item)}",
                ),
                primary_action=_gate_subject_action(
                    "bind_selected_draft_construct_transition_target",
                    "Bind Target State",
                ),
                secondary_actions=_visible_gate_actions(
                    _gate_subject_action(
                        "bind_selected_draft_construct_transition_source",
                        f"Source ({_decision_item_display_label(source_item)})",
                    ),
                    back_to_compose,
                ),
            )
        capability_items = _capability_decision_review_items(decision_items)
        changed_capability_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                dict(selected_decision_item.metadata),
                plural_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_IDS_KEY,
                singular_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_ID_KEY,
            ),
        )
        if not capability_items:
            return SubjectCurrentStepView(
                title="Accept a capability before this transition",
                status="The transition states are set, but there is no accepted capability to mark as changed yet.",
                why="Decision analysis needs the transition's changed capability before a decision can assign responsibility for it.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- source state: {_decision_item_display_label(source_item)}",
                    f"- target state: {_decision_item_display_label(target_item)}",
                ),
                primary_action=back_to_compose,
                secondary_actions=(
                    _gate_phase_action("itemize"),
                ),
            )
        if not changed_capability_items:
            return SubjectCurrentStepView(
                title="Bind the changed capability for this transition",
                status="The transition states are set, but the changed capability is still missing.",
                why="Decision analysis needs each transition to say which capability it changes before actor assignment becomes meaningful.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- source state: {_decision_item_display_label(source_item)}",
                    f"- target state: {_decision_item_display_label(target_item)}",
                    f"- capability options: {', '.join(_decision_item_display_label(item) for item in capability_items[:4])}",
                ),
                primary_action=_gate_subject_action(
                    "bind_selected_draft_construct_transition_changed_capability",
                    "Bind Changed Capability",
                ),
                secondary_actions=_visible_gate_actions(
                    _gate_subject_action(
                        "bind_selected_draft_construct_transition_target",
                        f"Target ({_decision_item_display_label(target_item)})",
                    ),
                    back_to_compose,
                ),
            )
        add_next_capability_id = _next_unbound_relation_binding_id(
            tuple(item.decision_review_item_id for item in changed_capability_items),
            capability_items,
        )
        secondary_actions: list[SubjectGateAction] = []
        if add_next_capability_id:
            secondary_actions.append(
                _gate_subject_action(
                    "bind_selected_draft_construct_transition_changed_capability",
                    f"Add Capability ({len(changed_capability_items)})",
                )
            )
        secondary_actions.append(
            _gate_subject_action(
                "unbind_selected_draft_construct_transition_changed_capability",
                "Remove Capability",
                enabled=bool(changed_capability_items),
            )
        )
        secondary_actions.append(back_to_compose)
        if latest_decision_receipt is None:
            return SubjectCurrentStepView(
                title="Run decision analysis for this transition-ready model",
                status="This transition has its states and one or more changed capabilities bound.",
                why="Run decision analysis now unless this transition needs more changed capabilities first.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- source state: {_decision_item_display_label(source_item)}",
                    f"- target state: {_decision_item_display_label(target_item)}",
                    f"- changed capabilities ({len(changed_capability_items)}): {_relation_labels(changed_capability_items)}",
                ),
                primary_action=_gate_subject_action("analyze_decision_frame", "Run Decision Analysis"),
                secondary_actions=_visible_gate_actions(*secondary_actions),
            )
        return SubjectCurrentStepView(
            title="Review or refine this transition binding",
            status="This transition already has a decision-analysis receipt. Refine the changed-capability list only if the modeled change is incomplete.",
            why="Once the transition model is explicit, the next workflow step is Review unless the relation set is still wrong.",
            detail_lines=(
                f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                f"- source state: {_decision_item_display_label(source_item)}",
                f"- target state: {_decision_item_display_label(target_item)}",
                f"- changed capabilities ({len(changed_capability_items)}): {_relation_labels(changed_capability_items)}",
            ),
            primary_action=_gate_phase_action("review"),
            secondary_actions=_visible_gate_actions(*secondary_actions),
        )
    if selected_decision_item is not None and selected_lane == "decision_candidate":
        transition_items = _transition_decision_review_items(decision_items)
        selected_transition_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                dict(selected_decision_item.metadata),
                plural_key=_DECISION_SELECTED_TRANSITION_ITEM_IDS_KEY,
                singular_key=_DECISION_SELECTED_TRANSITION_ITEM_ID_KEY,
            ),
        )
        if not transition_items:
            return SubjectCurrentStepView(
                title="Accept a transition before this decision",
                status="This decision candidate is accepted, but there is no accepted transition to select yet.",
                why="A decision becomes analyzable only after it selects a concrete transition candidate.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- lane: {_format_orientation_label(selected_lane)}",
                ),
                primary_action=back_to_compose,
                secondary_actions=(),
            )
        if not selected_transition_items:
            return SubjectCurrentStepView(
                title="Select the first transition for this decision",
                status="This decision candidate still needs at least one selected transition.",
                why="Decision analysis evaluates explicit decisions, not free-floating options. Bind one or more transitions now.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- transition options: {', '.join(_decision_item_display_label(item) for item in transition_items[:4])}",
                ),
                primary_action=_gate_subject_action(
                    "bind_selected_draft_construct_selected_transition",
                    "Select Transition",
                ),
                secondary_actions=_visible_gate_actions(
                    back_to_compose,
                ),
            )
        missing_transition_capability_item = next(
            (
                transition_item
                for transition_item in selected_transition_items
                if not _decision_items_by_ids(
                    decision_items,
                    _metadata_decision_item_ids(
                        dict(transition_item.metadata),
                        plural_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_IDS_KEY,
                        singular_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_ID_KEY,
                    ),
                )
            ),
            None,
        )
        selected_transition_changed_capabilities = _dedupe_decision_items(
            tuple(
                changed_capability_item
                for transition_item in selected_transition_items
                for changed_capability_item in _decision_items_by_ids(
                    decision_items,
                    _metadata_decision_item_ids(
                        dict(transition_item.metadata),
                        plural_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_IDS_KEY,
                        singular_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_ID_KEY,
                    ),
                )
            )
        )
        add_next_transition_id = _next_unbound_relation_binding_id(
            tuple(item.decision_review_item_id for item in selected_transition_items),
            transition_items,
        )
        transition_secondary_actions: list[SubjectGateAction] = []
        if add_next_transition_id:
            transition_secondary_actions.append(
                _gate_subject_action(
                    "bind_selected_draft_construct_selected_transition",
                    f"Add Transition ({len(selected_transition_items)})",
                )
            )
        transition_secondary_actions.append(
            _gate_subject_action(
                "unbind_selected_draft_construct_selected_transition",
                "Remove Transition",
                enabled=bool(selected_transition_items),
            )
        )
        if missing_transition_capability_item is not None:
            return SubjectCurrentStepView(
                title="Bind the changed capability on a selected transition",
                status="One selected transition still has no changed capability.",
                why="Decision analysis cannot assign responsibility until every selected transition says what capability it changes.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- selected transitions ({len(selected_transition_items)}): {_relation_labels(selected_transition_items)}",
                    f"- transition missing capability: {_decision_item_display_label(missing_transition_capability_item)}",
                ),
                primary_action=_gate_subject_action(
                    "bind_selected_draft_construct_transition_changed_capability",
                    "Bind Transition Capability",
                ),
                secondary_actions=_visible_gate_actions(
                    *transition_secondary_actions,
                    back_to_compose,
                ),
            )
        actor_items = _actor_decision_review_items(decision_items)
        assigned_actor_items = _decision_items_by_ids(
            decision_items,
            _metadata_decision_item_ids(
                dict(selected_decision_item.metadata),
                plural_key=_DECISION_ASSIGNED_ACTOR_DECISION_ITEM_IDS_KEY,
                singular_key=_DECISION_ASSIGNED_ACTOR_DECISION_ITEM_ID_KEY,
            ),
        )
        if not actor_items:
            return SubjectCurrentStepView(
                title="Accept an actor before this decision",
                status="One or more transitions are selected and typed, but there is no accepted actor to assign yet.",
                why="A decision becomes valid only after an actor is assigned to the changed capabilities of its selected transitions.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- selected transitions ({len(selected_transition_items)}): {_relation_labels(selected_transition_items)}",
                    f"- changed capabilities ({len(selected_transition_changed_capabilities)}): {_relation_labels(selected_transition_changed_capabilities)}",
                ),
                primary_action=back_to_compose,
                secondary_actions=(
                    _gate_phase_action("itemize"),
                ),
            )
        if not assigned_actor_items:
            return SubjectCurrentStepView(
                title="Assign the actor for this decision",
                status="The decision and selected transitions are set, but the assigned actor is still missing.",
                why="The theory only treats a decision as valid once the changed capabilities of its selected transitions have explicit assigned actors.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- selected transitions ({len(selected_transition_items)}): {_relation_labels(selected_transition_items)}",
                    f"- changed capabilities ({len(selected_transition_changed_capabilities)}): {_relation_labels(selected_transition_changed_capabilities)}",
                    f"- actor options: {', '.join(_decision_item_display_label(item) for item in actor_items[:4])}",
                ),
                primary_action=_gate_subject_action(
                    "bind_selected_draft_construct_assigned_actor",
                    "Assign Actor",
                ),
                secondary_actions=_visible_gate_actions(
                    *transition_secondary_actions,
                    back_to_compose,
                ),
            )
        add_next_actor_id = _next_unbound_relation_binding_id(
            tuple(item.decision_review_item_id for item in assigned_actor_items),
            actor_items,
        )
        secondary_actions = []
        if add_next_actor_id:
            secondary_actions.append(
                _gate_subject_action(
                    "bind_selected_draft_construct_assigned_actor",
                    f"Add Actor ({len(assigned_actor_items)})",
                )
            )
        secondary_actions.append(
            _gate_subject_action(
                "unbind_selected_draft_construct_assigned_actor",
                "Remove Actor",
                enabled=bool(assigned_actor_items),
            )
        )
        secondary_actions.extend(transition_secondary_actions)
        if latest_decision_receipt is None:
            return SubjectCurrentStepView(
                title="Run decision analysis for this decision-ready model",
                status="This decision now selects one or more transitions and has one or more assigned actors.",
                why="Run decision analysis now unless the decision should carry more transitions or assigned actors first.",
                detail_lines=(
                    f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                    f"- selected transitions ({len(selected_transition_items)}): {_relation_labels(selected_transition_items)}",
                    f"- changed capabilities ({len(selected_transition_changed_capabilities)}): {_relation_labels(selected_transition_changed_capabilities)}",
                    f"- assigned actors ({len(assigned_actor_items)}): {_relation_labels(assigned_actor_items)}",
                ),
                primary_action=_gate_subject_action("analyze_decision_frame", "Run Decision Analysis"),
                secondary_actions=_visible_gate_actions(*secondary_actions),
            )
        return SubjectCurrentStepView(
            title="Review or refine this decision assignment",
            status="This decision already has a decision-analysis receipt. Refine the assigned-actor set only if the modeled responsibility is incomplete.",
            why="Once the decision model is explicit, the next workflow step is Review unless the assignment set still needs work.",
            detail_lines=(
                f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                f"- selected transitions ({len(selected_transition_items)}): {_relation_labels(selected_transition_items)}",
                f"- changed capabilities ({len(selected_transition_changed_capabilities)}): {_relation_labels(selected_transition_changed_capabilities)}",
                f"- assigned actors ({len(assigned_actor_items)}): {_relation_labels(assigned_actor_items)}",
            ),
            primary_action=_gate_phase_action("review"),
            secondary_actions=_visible_gate_actions(*secondary_actions),
        )
    if latest_decision_receipt is None:
        return SubjectCurrentStepView(
            title="Run decision analysis",
            status="Accepted constructs are in place and ready to evaluate.",
            why="Run decision analysis now to convert the curated model into admissible options, blockers, and recommendation status.",
            detail_lines=(
                f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                f"- lane: {_format_orientation_label(selected_lane)}",
                *(
                    _selected_construct_relation_lines(
                        selected_candidate,
                        decision_item=selected_decision_item,
                        decision_items=decision_items,
                        frame=decision_frame if isinstance(decision_frame, DecisionFrame) else None,
                    )
                    if selected_decision_item is not None
                    else ()
                ),
                f"- accepted constructs: {sum(1 for item in construct_candidates if collapse_ws(item.status) == 'accepted')}",
                f"- included decision items: {len(tuple(item for item in decision_items if collapse_ws(item.status) != 'rejected'))}",
                f"- policy: {_format_orientation_label(policy_profile_kind)}",
            ),
            primary_action=_gate_subject_action("analyze_decision_frame", "Run Decision Analysis"),
            secondary_actions=_visible_gate_actions(
                back_to_compose,
            ),
        )
    if dst_refresh_required:
        return SubjectCurrentStepView(
            title="Refresh the DST-backed decision analysis",
            status="This subject now matches a governed DST case, but the current decision frame was built before that case became available.",
            why="Refresh the DST-backed analysis now so Draft stops reasoning over the older plain frame and updates the report plan from the governed case model.",
            detail_lines=(
                f"- selected construct: {_construct_candidate_detail_label(selected_candidate)}",
                f"- governed discovery source: {dst_fixture.title if dst_fixture is not None else '<none>'}",
                f"- included decision items: {len(tuple(item for item in decision_items if collapse_ws(item.status) != 'rejected'))}",
                f"- policy: {_format_orientation_label(policy_profile_kind)}",
            ),
            primary_action=refresh_dst_action,
            secondary_actions=_visible_gate_actions(back_to_compose),
        )
    recommended_option_ids = tuple(
        str(item) for item in latest_decision_receipt.metadata.get("recommended_option_ids", ())
    )
    return SubjectCurrentStepView(
        title="Decision analysis is ready",
        status="The latest decision-analysis receipt is available. Move to Review unless you need to change the curated model or rerun under a different policy.",
        why="Review should validate and approve the publication-ready draft together with any attached recommendation-grade analysis.",
        detail_lines=(
            f"- decision frame: {decision_frame.decision_frame_id if isinstance(decision_frame, DecisionFrame) else '<none>'}",
            f"- recommendation status: {collapse_ws(str(latest_decision_receipt.recommendation_status)) or 'pending'}",
            *(
                [f"- recommended option: {option_id}" for option_id in recommended_option_ids[:3]]
                if recommended_option_ids
                else ["- recommended option: <none>"]
            ),
        ),
        primary_action=_gate_subject_action("goto_review", "Hand To Review"),
        secondary_actions=_visible_gate_actions(
            _gate_subject_action(
                "cycle_decision_policy_profile",
                f"Re-run Analysis ({next_policy_kind})",
            ),
            back_to_compose,
        ),
    )


def _build_current_step_draft_approved(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    selected_draft_item, _selection_source = _selected_draft_review_item(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    if selected_draft_item is not None:
        pending_path = _pending_draft_manual_rephrase_path(
            progress=context.progress,
            selected_item=selected_draft_item,
        )
        if pending_path is not None:
            return _build_current_step_draft_apply_manual_rephrase(context)
        if _pending_draft_llm_rephrase(progress=context.progress, selected_item=selected_draft_item):
            return _build_current_step_draft_apply_llm_rephrase(context)
    if _draft_focus_mode(context.progress) == "model":
        return _build_current_step_draft_model(context)
    decision_state = _decision_review_state(context.root_path, context.scenario)
    dst_refresh_available = bool(
        decision_state.get("exists")
        and isinstance(decision_state.get("frame"), DecisionFrame)
        and bool(getattr(decision_state.get("frame"), "metadata", {}).get("dst_seeded"))
    )
    has_constructs = bool(
        _subject_transformation_construct_candidates(
            context.root_path,
            scenario=context.scenario,
            include_rejected=False,
        )
    )
    decision_entry_available = bool(decision_state.get("exists")) or has_constructs or (
        _dst_fixture_for_subject(context.root_path, context.scenario) is not None
    )
    recovery_state = _draft_decision_recovery_state(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    secondary_actions: list[SubjectGateAction] = []
    if decision_entry_available:
        secondary_actions.append(_gate_subject_nav_action("open_draft_model_view", "Open Model"))
    if dst_refresh_available:
        secondary_actions.append(_gate_subject_action("refresh_dst_decision_analysis", "Refresh DST Analysis"))
    if collapse_ws(context.scenario.composition_id):
        secondary_actions.append(_gate_subject_action("preview_publication_composition_diff", "Compare Report Plans"))
    else:
        secondary_actions.append(_gate_subject_action("preview_publication_composition", "Preview Report Plan"))
    if recovery_state.recovery_plan is not None:
        return SubjectCurrentStepView(
            title=recovery_state.recovery_plan.title,
            status=recovery_state.recovery_plan.status,
            why=(
                recovery_state.recovery_plan.why
                + " The approved report plan cannot stay attached to stale or blocked decision work; Review approval will be required again after Draft recovery."
            ),
            detail_lines=(
                *recovery_state.recovery_plan.detail_lines,
                "- review impact: the refreshed report plan will need approval again before Publication proceeds",
            ),
            primary_action=_gate_subject_action(
                recovery_state.recovery_plan.action_key,
                recovery_state.recovery_plan.action_label,
            ),
            secondary_actions=tuple(secondary_actions[:3]),
        )
    return SubjectCurrentStepView(
        title="Draft composition is approved",
        status="The current report plan has already been approved for publication.",
        why=(
            "Continue to Publication unless you need to reopen Draft Model and revise the attached decision work. "
            "Any material change there will refresh the report plan and require Review approval again."
            if decision_entry_available
            else "Continue to Publication unless you need to revisit Draft and refresh the report plan from a newer subject snapshot."
        ),
        detail_lines=(
            "- the Draft tab still shows the report-scope tree for inspection",
            *(
                ("- open Model to inspect or revise the decision analysis without leaving the case workspace",)
                if decision_entry_available
                else ()
            ),
            "- Review remains the explicit approval gate before Publication",
        ),
        primary_action=_gate_phase_action("publication"),
        secondary_actions=tuple(secondary_actions[:2]),
    )


def _visible_gate_actions(*actions: SubjectGateAction) -> tuple[SubjectGateAction, ...]:
    return tuple(action for action in actions if action.enabled)


def _selected_draft_item_decision_role(selected_draft_item: ReviewItem) -> str:
    return normalize_itemized_decision_role(selected_draft_item.metadata.get("decision_role", ""))


def _selected_draft_item_supports_decision_analysis(
    root_path: Path,
    scenario: SubjectScenario,
    *,
    selected_draft_item: ReviewItem,
    decision_frame_exists: bool,
) -> bool:
    if decision_frame_exists:
        return True
    if _dst_fixture_for_subject(root_path, scenario) is not None:
        return True
    return bool(_selected_draft_item_decision_role(selected_draft_item))


def _decision_analysis_status(decision_state: Mapping[str, object]) -> str:
    latest_receipt = decision_state.get("latest_receipt")
    if latest_receipt is not None:
        latest_status = collapse_ws(str(getattr(latest_receipt, "recommendation_status", "")))
        if latest_status:
            return latest_status
    return collapse_ws(str(decision_state.get("recommendation_status", ""))) or "pending"


def _decision_analysis_blocking_conditions(decision_state: Mapping[str, object]) -> tuple[str, ...]:
    latest_receipt = decision_state.get("latest_receipt")
    if latest_receipt is not None:
        latest_conditions = tuple(
            str(item)
            for item in getattr(latest_receipt, "blocking_conditions", ())
            if collapse_ws(str(item))
        )
        if latest_conditions:
            return latest_conditions
    return tuple(str(item) for item in decision_state.get("blocking_conditions", ()) if collapse_ws(str(item)))


@dataclass(frozen=True)
class _DecisionAnalysisRecoveryPlan:
    action_key: str
    action_label: str
    title: str
    status: str
    why: str
    detail_lines: tuple[str, ...]


@dataclass(frozen=True)
class _DraftDecisionRecoveryState:
    decision_state: Mapping[str, object]
    selected_item: ReviewItem | None
    selected_label: str
    selected_decision_role: str
    decision_entry_available: bool
    recovery_plan: _DecisionAnalysisRecoveryPlan | None


def _decision_analysis_recovery_plan(
    root_path: Path,
    scenario: SubjectScenario,
    decision_state: Mapping[str, object],
    *,
    allow_start: bool,
    selected_label: str = "",
    selected_decision_role: str = "",
) -> _DecisionAnalysisRecoveryPlan | None:
    decision_frame = decision_state.get("frame")
    latest_receipt = decision_state.get("latest_receipt")
    dst_fixture = _dst_fixture_for_subject(root_path, scenario)
    dst_refresh_required = _dst_decision_analysis_refresh_required(
        root_path,
        scenario,
        decision_frame if isinstance(decision_frame, DecisionFrame) else None,
    )
    recommendation_status = _decision_analysis_status(decision_state)
    blocking_conditions = _decision_analysis_blocking_conditions(decision_state)
    detail_lines: list[str] = []
    if collapse_ws(selected_label):
        detail_lines.append(f"- selected item: {selected_label}")
    if collapse_ws(selected_decision_role):
        detail_lines.append(f"- decision role: {_format_orientation_label(selected_decision_role)}")
    if dst_refresh_required:
        detail_lines.extend(
            [
                f"- governed discovery source: {dst_fixture.title if dst_fixture is not None else '<none>'}",
                "- recovery reason: newer same-subject material invalidated the older decision frame",
            ]
        )
        return _DecisionAnalysisRecoveryPlan(
            action_key="refresh_dst_decision_analysis",
            action_label="Refresh DST Analysis",
            title="Refresh the DST-backed decision analysis",
            status="The attached decision analysis is stale against the current subject snapshot.",
            why="Refresh it now so the governed case model, decision frame, and report plan all move forward from the same same-subject inputs.",
            detail_lines=tuple(detail_lines),
        )
    if bool(decision_state.get("exists")) and isinstance(decision_frame, DecisionFrame):
        if latest_receipt is None or recommendation_status == "blocked":
            detail_lines.extend(
                [
                    f"- decision question: {decision_frame.question or '<none>'}",
                    f"- recommendation status: {recommendation_status}",
                    *[f"- blocker: {item}" for item in blocking_conditions[:3]],
                ]
            )
            return _DecisionAnalysisRecoveryPlan(
                action_key="analyze_decision_frame",
                action_label="Run Decision Analysis",
                title="Run decision analysis",
                status=(
                    "The decision frame exists, but no current analysis receipt is attached yet."
                    if latest_receipt is None
                    else "The attached decision analysis is blocked."
                ),
                why="Running it again is the recovery path once the current frame, included items, and governed structure are in place.",
                detail_lines=tuple(detail_lines),
            )
        return None
    if allow_start:
        detail_lines.extend(
            [
                *([f"- governed discovery source: {dst_fixture.title}"] if dst_fixture is not None else []),
                "- result: candidate paths, blockers, and recommendation-ready analysis",
            ]
        )
        return _DecisionAnalysisRecoveryPlan(
            action_key="create_decision_frame_from_selected_draft_item",
            action_label="Start Decision Analysis",
            title="Start decision analysis",
            status=(
                f"This subject matches the DST case '{dst_fixture.title}'. Start decision analysis now."
                if dst_fixture is not None
                else "This subject is decision-oriented. Start decision analysis now."
            ),
            why="Keep decision work explicit. Draft should create the frame before Review or Publication depend on it.",
            detail_lines=tuple(detail_lines),
        )
    return None


def _draft_decision_recovery_state(
    root_path: Path,
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> _DraftDecisionRecoveryState:
    decision_state = _decision_review_state(root_path, scenario)
    selected_draft_item, _selection_source = _selected_draft_review_item(
        root_path,
        scenario=scenario,
        progress=progress,
    )
    has_constructs = bool(
        _subject_transformation_construct_candidates(
            root_path,
            scenario=scenario,
            include_rejected=False,
        )
    )
    decision_entry_available = bool(decision_state.get("exists")) or has_constructs or (
        _dst_fixture_for_subject(root_path, scenario) is not None
    )
    selected_label = ""
    selected_decision_role = ""
    allow_start = False
    if selected_draft_item is not None:
        selected_label = (
            collapse_ws(str(selected_draft_item.metadata.get("canonical_label", "")))
            or selected_draft_item.review_item_id
        )
        selected_decision_role = _selected_draft_item_decision_role(selected_draft_item)
    if not bool(decision_state.get("exists")) and decision_entry_available:
        allow_start = True
    recovery_plan = _decision_analysis_recovery_plan(
        root_path,
        scenario,
        decision_state,
        allow_start=allow_start,
        selected_label=selected_label,
        selected_decision_role=selected_decision_role,
    )
    return _DraftDecisionRecoveryState(
        decision_state=decision_state,
        selected_item=selected_draft_item,
        selected_label=selected_label,
        selected_decision_role=selected_decision_role,
        decision_entry_available=decision_entry_available,
        recovery_plan=recovery_plan,
    )


def _build_current_step_draft_shape(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    if _draft_focus_mode(context.progress) == "model":
        return _build_current_step_draft_model(context)
    selected_draft_item, _selection_source = _selected_draft_review_item(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    recovery_state = _draft_decision_recovery_state(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    if selected_draft_item is not None:
        pending_path = _pending_draft_manual_rephrase_path(
            progress=context.progress,
            selected_item=selected_draft_item,
        )
        if pending_path is not None:
            return _build_current_step_draft_apply_manual_rephrase(context)
        if _pending_draft_llm_rephrase(progress=context.progress, selected_item=selected_draft_item):
            return _build_current_step_draft_apply_llm_rephrase(context)
        dst_fixture = _dst_fixture_for_subject(context.root_path, context.scenario)
        split_labels = _draft_review_split_labels(
            context.root_path,
            scenario=context.scenario,
            item=selected_draft_item,
        )
        sibling_items = review_item_children(
            _draft_review_items(context.root_path, scenario=context.scenario),
            selected_draft_item.parent_review_item_id,
        )
        has_next_sibling = any(
            collapse_ws(item.review_item_id) == collapse_ws(selected_draft_item.review_item_id)
            for item in sibling_items[:-1]
        )
        decision_state = _decision_review_state(context.root_path, context.scenario)
        decision_frame = decision_state.get("frame")
        decision_items = list_decision_review_items(context.root_path, context.scenario.subject_id)
        policy_profile_kind = collapse_ws(str(decision_state.get("policy_profile_kind", ""))) or "conservative"
        latest_decision_receipt = decision_state.get("latest_receipt")
        frame_is_dst_seeded = (
            bool(decision_state.get("exists"))
            and isinstance(decision_frame, DecisionFrame)
            and bool(decision_frame.metadata.get("dst_seeded"))
        )
        dst_refresh_required = _dst_decision_analysis_refresh_required(
            context.root_path,
            context.scenario,
            decision_frame if isinstance(decision_frame, DecisionFrame) else None,
        )
        selected_in_decision_frame = _draft_review_item_effectively_included_in_decision(
            context.root_path,
            scenario=context.scenario,
            review_item=selected_draft_item,
            decision_items=decision_items,
            frame=decision_frame if isinstance(decision_frame, DecisionFrame) else None,
        )
        selected_label = (
            collapse_ws(str(selected_draft_item.metadata.get("canonical_label", "")))
            or selected_draft_item.review_item_id
        )
        selected_decision_role = _selected_draft_item_decision_role(selected_draft_item)
        structure_action = _gate_subject_action(
            (
                "promote_selected_draft_review_item_to_root"
                if collapse_ws(selected_draft_item.parent_review_item_id)
                else "split_selected_draft_review_item"
            ),
            (
                "Promote Child To Root"
                if collapse_ws(selected_draft_item.parent_review_item_id)
                else (f"Split Draft Item ({len(split_labels)})" if len(split_labels) >= 2 else "Split Draft Item")
            ),
            enabled=(
                bool(collapse_ws(selected_draft_item.parent_review_item_id))
                or (len(split_labels) >= 2 and not selected_draft_item.child_review_item_ids)
            ),
        )
        merge_action = _gate_subject_action(
            "merge_selected_draft_review_item_with_next_sibling",
            "Merge With Next Sibling",
            enabled=has_next_sibling,
        )
        handoff_action = _gate_subject_action("goto_review", "Hand To Review")
        open_model_action = _gate_subject_nav_action("open_draft_model_view", "Open Model")
        refresh_dst_action = _gate_subject_action(
            "refresh_dst_decision_analysis",
            "Refresh DST Analysis",
            enabled=frame_is_dst_seeded,
        )
        has_construct_candidates = bool(
            _subject_transformation_construct_candidates(
                context.root_path,
                scenario=context.scenario,
                include_rejected=False,
            )
        )
        decision_relevant = _selected_draft_item_supports_decision_analysis(
            context.root_path,
            context.scenario,
            selected_draft_item=selected_draft_item,
            decision_frame_exists=bool(decision_state.get("exists")),
        ) or (not bool(decision_state.get("exists")) and has_construct_candidates)
        next_policy_kind = _format_orientation_label(next_decision_policy_profile_kind(policy_profile_kind))
        if recovery_state.recovery_plan is not None:
            return SubjectCurrentStepView(
                title=recovery_state.recovery_plan.title,
                status=recovery_state.recovery_plan.status,
                why=recovery_state.recovery_plan.why,
                detail_lines=recovery_state.recovery_plan.detail_lines,
                primary_action=_gate_subject_action(
                    recovery_state.recovery_plan.action_key,
                    recovery_state.recovery_plan.action_label,
                ),
                secondary_actions=_visible_gate_actions(
                    open_model_action,
                    structure_action,
                    merge_action,
                    refresh_dst_action,
                    handoff_action,
                ),
            )
        if decision_relevant:
            if not frame_is_dst_seeded and not selected_in_decision_frame:
                return SubjectCurrentStepView(
                    title="Include this item in the decision analysis",
                    status="A decision analysis exists. Include the selected item only if it materially changes the choice, comparison, or recommendation.",
                    why="Decision analysis should stay narrow. Only bring in items that alter the evaluated futures, evidence basis, or constraints.",
                    detail_lines=(
                        f"- selected item: {selected_label}",
                        *([f"- decision role: {_format_orientation_label(selected_decision_role)}"] if selected_decision_role else []),
                        f"- current decision items: {len(decision_items)}",
                    ),
                    primary_action=_gate_subject_action(
                        "add_selected_draft_review_item_to_decision_frame",
                        "Include In Decision Analysis",
                    ),
                    secondary_actions=_visible_gate_actions(
                        open_model_action,
                        structure_action,
                        merge_action,
                        refresh_dst_action,
                        handoff_action,
                    ),
                )
            if latest_decision_receipt is None:
                return SubjectCurrentStepView(
                    title="Run decision analysis",
                    status="The decision frame exists, but no current analysis receipt is attached yet.",
                    why="Running it again is the recovery path once the current frame, included items, and governed structure are in place.",
                    detail_lines=(
                        f"- selected item: {selected_label}",
                        *([f"- decision role: {_format_orientation_label(selected_decision_role)}"] if selected_decision_role else []),
                        f"- current decision items: {len(decision_items)}",
                    ),
                    primary_action=_gate_subject_action("analyze_decision_frame", "Run Decision Analysis"),
                    secondary_actions=_visible_gate_actions(
                        open_model_action,
                        structure_action,
                        merge_action,
                        refresh_dst_action,
                        handoff_action,
                    ),
                )
            recommended_option_ids = tuple(
                str(item) for item in latest_decision_receipt.metadata.get("recommended_option_ids", ())
            )
            return SubjectCurrentStepView(
                title="Decision analysis is ready",
                status="The latest decision-analysis receipt is available. Move to Review unless you need to change included items or rerun the analysis under a different policy.",
                why="Review should validate and approve the publication-ready draft together with any attached recommendation-grade analysis.",
                detail_lines=(
                    f"- recommendation status: {collapse_ws(str(latest_decision_receipt.recommendation_status)) or 'pending'}",
                    f"- policy: {_format_orientation_label(policy_profile_kind)}",
                    *(
                        [f"- recommended option: {option_id}" for option_id in recommended_option_ids[:3]]
                        if recommended_option_ids
                        else ["- recommended option: <none>"]
                    ),
                ),
                primary_action=handoff_action,
                secondary_actions=_visible_gate_actions(
                    _gate_subject_action(
                        "cycle_decision_policy_profile",
                        f"Re-run Analysis ({next_policy_kind})",
                    ),
                    open_model_action,
                    refresh_dst_action,
                    structure_action,
                ),
            )
        return SubjectCurrentStepView(
            title="Finish shaping this report item",
            status="Draft is current. Refine the selected item only if its structure or meaning still needs adjustment; otherwise hand the draft to Review.",
            why="Draft should minimize effort. Decision analysis stays hidden unless the subject or selected item is actually decision-oriented.",
            detail_lines=(
                f"- selected item: {selected_label}",
                f"- child review items: {len(selected_draft_item.child_review_item_ids)}",
                f"- parent review item: {collapse_ws(selected_draft_item.parent_review_item_id) or '<root>'}",
                "- decision analysis: not currently needed for this subject",
            ),
            primary_action=handoff_action,
            secondary_actions=_visible_gate_actions(
                _gate_subject_nav_action(
                    "open_draft_model_view",
                    "Open Model",
                    enabled=bool(
                        _subject_transformation_construct_candidates(
                            context.root_path,
                            scenario=context.scenario,
                            include_rejected=False,
                        )
                    ),
                ),
                structure_action,
                merge_action,
            ),
        )
    return SubjectCurrentStepView(
        title="Finish the draft and hand it to Review",
        status="The report plan is current and ready for final shaping.",
        why="Use the Report Scope panel to include, exclude, reorder, and orient items, support, and sections. When the draft reads the way Publication should build it, hand it to Review.",
        detail_lines=(
            "- the draft composition is persisted separately from the report plan",
            "- Review approves the draft; Publication later builds from the approved plan",
        ),
        primary_action=_gate_subject_action("goto_review", "Hand To Review"),
        secondary_actions=(
            _gate_subject_action("preview_review_composition", "Preview Draft Composition"),
            _gate_subject_action("preview_publication_composition", "Preview Report Plan"),
        ),
    )


