def _build_current_step_review_create_report_plan(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    recovery_state = _draft_decision_recovery_state(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    if recovery_state.recovery_plan is not None:
        return SubjectCurrentStepView(
            title=recovery_state.recovery_plan.title,
            status=(
                recovery_state.recovery_plan.status
                + " Review cannot create or approve the report plan until Draft finishes this decision-analysis recovery step."
            ),
            why="Return to Draft and complete the decision-analysis recovery step first. Draft owns the frame, its reruns, and any DST refresh of the attached report plan.",
            detail_lines=(
                *recovery_state.recovery_plan.detail_lines,
                "- next phase: Draft",
            ),
            primary_action=_gate_phase_action("draft", recovery_state.recovery_plan.action_label),
            secondary_actions=(
                _gate_subject_action("toggle_review_preview", _PREVIEW_MAINTAINED_FILES_LABEL),
            ),
        )
    return SubjectCurrentStepView(
        title="Create the report plan",
        status="The maintained-files check completed and the files are aligned. No current report plan exists for this subject snapshot.",
        why="The report plan decides what goes into the report: included material, support, and report sections.",
        detail_lines=(
            "- next: create the report plan from the current aligned subject snapshot",
            "- after that: use the Report Scope panel to choose items, support, and sections directly",
        ),
        primary_action=_gate_subject_action("refresh_publication_composition", "Create Report Plan"),
        secondary_actions=(
            _gate_subject_action("toggle_review_preview", _PREVIEW_MAINTAINED_FILES_LABEL),
        ),
    )


def _build_current_step_review_approve_report_plan(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    recovery_state = _draft_decision_recovery_state(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    decision_review_state = recovery_state.decision_state
    decision_frame = decision_review_state.get("frame")
    composition = _latest_current_publication_composition(context.root_path, scenario=context.scenario)
    latest_receipts = (
        list_decision_analysis_receipts(context.root_path, context.scenario.subject_id)
        if bool(decision_review_state.get("exists")) and isinstance(decision_frame, DecisionFrame)
        else []
    )
    secondary_actions: list[SubjectGateAction] = []
    if collapse_ws(context.scenario.composition_id):
        secondary_actions.append(_gate_subject_action("preview_publication_composition_diff", "Compare Report Plans"))
        if composition is not None and len(
            _publication_diff_baseline_candidates(
                context.root_path,
                scenario=context.scenario,
                composition=composition,
            )
        ) > 1:
            secondary_actions.append(
                _gate_subject_action(
                    "cycle_publication_diff_baseline",
                    _publication_diff_baseline_action_label(
                        context.root_path,
                        scenario=context.scenario,
                        composition=composition,
                        progress=context.progress,
                    ),
                )
            )
    secondary_actions.append(_gate_subject_action("preview_publication_composition", "Preview Report Plan"))
    if bool(decision_review_state.get("exists")) and isinstance(decision_frame, DecisionFrame):
        secondary_actions.append(_gate_phase_action("draft", "Open Model"))
        if bool(decision_frame.metadata.get("dst_seeded")):
            secondary_actions.append(_gate_subject_action("refresh_dst_decision_analysis", "Refresh DST Analysis"))
    if bool(decision_review_state.get("exists")) and isinstance(decision_frame, DecisionFrame):
        preferred_order = {"Compare Report Plans": 0, "Open Model": 1, "Refresh DST Analysis": 2, "Preview Report Plan": 3}
        secondary_actions.sort(key=lambda action: preferred_order.get(action.label, 99))
    if recovery_state.recovery_plan is not None:
        return SubjectCurrentStepView(
            title=recovery_state.recovery_plan.title,
            status=(
                recovery_state.recovery_plan.status
                + " Review cannot approve the report while the attached decision analysis needs Draft recovery."
            ),
            why="Return to Draft and complete the decision-analysis recovery step first. Review should not approve stale or blocked decision work.",
            detail_lines=(
                *recovery_state.recovery_plan.detail_lines,
                "- next phase: Draft",
            ),
            primary_action=_gate_phase_action("draft", recovery_state.recovery_plan.action_label),
            secondary_actions=tuple(secondary_actions[:4]),
        )
    return SubjectCurrentStepView(
        title=(
            "Approve the report and decision analysis"
            if latest_receipts
            else "Approve the report plan"
        ),
        status="The report plan is current but not yet approved.",
        why=(
            "Publication stays blocked until Review approves what goes into the report and any attached recommendation-grade analysis."
            if latest_receipts
            else "Publication stays blocked until Review approves what goes into the report."
        ),
        detail_lines=(
            "- the report plan controls included items, support, and report structure",
            "- use the Report Scope panel to adjust what is included before you approve",
            *(
                [
                    f"- diff baseline: {_publication_diff_baseline_label(_resolved_publication_diff_baseline(context.root_path, scenario=context.scenario, composition=composition, progress=context.progress)[0])}"
                ]
                if collapse_ws(context.scenario.composition_id) and composition is not None
                else []
            ),
            *(
                [
                    f"- decision analysis: {collapse_ws(str(decision_review_state.get('recommendation_status', 'pending'))) or 'pending'}",
                    f"- decision receipt: {latest_receipts[-1].receipt_id}",
                    "- open Model to revise the attached decision work without leaving the current case",
                ]
                if latest_receipts
                else []
            ),
        ),
        primary_action=_gate_subject_action("approve_review", "Approve For Report"),
        secondary_actions=tuple(secondary_actions[:4]),
    )


def _build_current_step_publication_lock_inputs(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    recovery_state = _draft_decision_recovery_state(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    decision_review_state = recovery_state.decision_state
    decision_frame = decision_review_state.get("frame")
    latest_receipt = decision_review_state.get("latest_receipt")
    secondary_actions: list[SubjectGateAction] = []
    detail_lines: list[str] = []
    if bool(decision_review_state.get("exists")) and isinstance(decision_frame, DecisionFrame):
        detail_lines.extend(
            [
                f"- decision analysis: {collapse_ws(str(decision_review_state.get('recommendation_status', 'pending'))) or 'pending'}",
                f"- decision receipt: {latest_receipt.receipt_id if latest_receipt is not None else '<none>'}",
            ]
        )
        secondary_actions.append(_gate_phase_action("draft", "Open Model"))
        if bool(decision_frame.metadata.get("dst_seeded")):
            secondary_actions.append(_gate_subject_action("refresh_dst_decision_analysis", "Refresh DST Analysis"))
    if recovery_state.recovery_plan is not None:
        return SubjectCurrentStepView(
            title=recovery_state.recovery_plan.title,
            status=(
                recovery_state.recovery_plan.status
                + " Publication cannot lock the report inputs while the attached decision analysis needs Draft recovery."
            ),
            why="Return to Draft and complete the decision-analysis recovery step first. Publication should only lock current approved analysis inputs.",
            detail_lines=(
                *recovery_state.recovery_plan.detail_lines,
                "- next phase: Draft",
            ),
            primary_action=_gate_phase_action("draft", recovery_state.recovery_plan.action_label),
            secondary_actions=tuple(secondary_actions[:2]),
        )
    return SubjectCurrentStepView(
        title="Lock the report inputs",
        status=(
            "Review is approved and publication can begin."
            if not detail_lines
            else "Review is approved and publication can begin with the attached decision analysis."
        ),
        why=(
            "Locking freezes the approved report plan before you build the report outputs."
            if not detail_lines
            else "Locking freezes the approved report plan and attached decision analysis before you build the report outputs."
        ),
        detail_lines=tuple(detail_lines),
        primary_action=_gate_subject_action("lock_publication", "Lock Report Inputs"),
        secondary_actions=tuple(secondary_actions[:2]),
    )


