def _build_current_step_publication_fix_build(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    recovery_state = _draft_decision_recovery_state(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    decision_review_state = recovery_state.decision_state
    decision_frame = decision_review_state.get("frame")
    secondary_actions: list[SubjectGateAction] = []
    if _publication_packet_path_text(context.scenario):
        secondary_actions.append(_gate_subject_action("open_release_packet", _OPEN_RELEASE_FOLDER_LABEL))
    secondary_actions.append(_gate_subject_action("open_subject_typst", _OPEN_SUBJECT_TYPS_LABEL))
    if bool(decision_review_state.get("exists")) and isinstance(decision_frame, DecisionFrame):
        secondary_actions.append(_gate_phase_action("draft", "Open Model"))
    if recovery_state.recovery_plan is not None:
        return SubjectCurrentStepView(
            title=recovery_state.recovery_plan.title,
            status=(
                recovery_state.recovery_plan.status
                + " Publication should not rebuild until Draft resolves the attached decision-analysis recovery step."
            ),
            why="Return to Draft and complete the decision-analysis recovery step first.",
            detail_lines=(
                *recovery_state.recovery_plan.detail_lines,
                "- next phase: Draft",
            ),
            primary_action=_gate_phase_action("draft", recovery_state.recovery_plan.action_label),
            secondary_actions=tuple(secondary_actions[:3]),
        )
    return SubjectCurrentStepView(
        title="Fix the report build",
        status=(
            "The current publication build is not releasable yet. "
            "Typst validation must succeed and report.pdf must exist before release review can complete."
        ),
        why="Release completion is blocked until the rendered PDF is present and the build validates cleanly.",
        primary_action=_gate_subject_action("build_report", "Rebuild Report"),
        secondary_actions=tuple(secondary_actions[:3]),
    )


def _build_current_step_publication_inspect_release_folder(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    recovery_state = _draft_decision_recovery_state(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    decision_review_state = recovery_state.decision_state
    decision_frame = decision_review_state.get("frame")
    secondary_actions: list[SubjectGateAction] = []
    if collapse_ws(context.scenario.report_pdf_path):
        secondary_actions.append(_gate_subject_action("preview_publication_pdf", "Preview report.pdf"))
    if bool(decision_review_state.get("exists")) and isinstance(decision_frame, DecisionFrame):
        secondary_actions.append(_gate_phase_action("draft", "Open Model"))
    if recovery_state.recovery_plan is not None:
        return SubjectCurrentStepView(
            title=recovery_state.recovery_plan.title,
            status=(
                recovery_state.recovery_plan.status
                + " Publication should return to Draft before treating the release folder as current."
            ),
            why="Return to Draft and complete the decision-analysis recovery step first.",
            detail_lines=(
                *recovery_state.recovery_plan.detail_lines,
                "- next phase: Draft",
            ),
            primary_action=_gate_phase_action("draft", recovery_state.recovery_plan.action_label),
            secondary_actions=tuple(secondary_actions[:2]),
        )
    return SubjectCurrentStepView(
        title="Inspect the release folder",
        status="A report build exists and is ready for inspection.",
        why="Check the built outputs before treating the report as released.",
        primary_action=_gate_subject_action("open_release_packet", _OPEN_RELEASE_FOLDER_LABEL),
        secondary_actions=tuple(secondary_actions[:2]),
    )


def _build_current_step_publication_finish_release_review(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    recovery_state = _draft_decision_recovery_state(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    decision_review_state = recovery_state.decision_state
    decision_frame = decision_review_state.get("frame")
    secondary_actions: list[SubjectGateAction] = []
    if collapse_ws(context.scenario.report_pdf_path):
        secondary_actions.append(_gate_subject_action("preview_publication_pdf", "Preview report.pdf"))
    if collapse_ws(context.scenario.report_markdown_path):
        secondary_actions.append(_gate_subject_action("preview_publication_markdown", "Preview report.md"))
    if bool(decision_review_state.get("exists")) and isinstance(decision_frame, DecisionFrame):
        secondary_actions.append(_gate_phase_action("draft", "Open Model"))
    if recovery_state.recovery_plan is not None:
        return SubjectCurrentStepView(
            title=recovery_state.recovery_plan.title,
            status=(
                recovery_state.recovery_plan.status
                + " Publication should return to Draft before signing off this release."
            ),
            why="Return to Draft and complete the decision-analysis recovery step first.",
            detail_lines=(
                *recovery_state.recovery_plan.detail_lines,
                "- next phase: Draft",
            ),
            primary_action=_gate_phase_action("draft", recovery_state.recovery_plan.action_label),
            secondary_actions=tuple(secondary_actions[:3]),
        )
    return SubjectCurrentStepView(
        title="Finish the release review",
        status="The release folder has been opened and the built outputs are ready for sign-off.",
        why="Confirm the rendered outputs are acceptable before treating this publication as complete.",
        primary_action=_gate_subject_action("complete_release_review", "Finish Release Review"),
        secondary_actions=tuple(secondary_actions[:3]),
    )


def _build_current_step_publication_complete(context: _SubjectCurrentStepContext) -> SubjectCurrentStepView:
    recovery_state = _draft_decision_recovery_state(
        context.root_path,
        scenario=context.scenario,
        progress=context.progress,
    )
    decision_review_state = recovery_state.decision_state
    decision_frame = decision_review_state.get("frame")
    secondary_actions: list[SubjectGateAction] = []
    if collapse_ws(context.scenario.report_pdf_path):
        secondary_actions.append(_gate_subject_action("preview_publication_pdf", "Preview report.pdf"))
    if _publication_packet_path_text(context.scenario):
        secondary_actions.append(_gate_subject_action("open_release_packet", _OPEN_RELEASE_FOLDER_LABEL))
    if collapse_ws(context.scenario.report_markdown_path):
        secondary_actions.append(_gate_subject_action("preview_publication_markdown", "Preview report.md"))
    if bool(decision_review_state.get("exists")) and isinstance(decision_frame, DecisionFrame):
        secondary_actions.append(_gate_phase_action("draft", "Open Model"))
    if recovery_state.recovery_plan is not None:
        return SubjectCurrentStepView(
            title=recovery_state.recovery_plan.title,
            status=(
                recovery_state.recovery_plan.status
                + " Publication is no longer current until Draft finishes the decision-analysis recovery step."
            ),
            why="Return to Draft and complete the decision-analysis recovery step first.",
            detail_lines=(
                *recovery_state.recovery_plan.detail_lines,
                "- next phase: Draft",
            ),
            primary_action=_gate_phase_action("draft", recovery_state.recovery_plan.action_label),
            secondary_actions=tuple(secondary_actions[:4]),
        )
    return SubjectCurrentStepView(
        title="Publication review is complete",
        status="The built outputs have been reviewed.",
        why="Rebuild only if the subject or report plan changes.",
        primary_action=secondary_actions[0] if secondary_actions else None,
        secondary_actions=tuple(secondary_actions[1:4]) if secondary_actions else (),
    )


