def subject_current_step_view(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    phase: str,
    can_capture_assistant: bool = False,
    import_staging: SubjectImportStaging | None = None,
    markdown_selected_path: str = "",
    markdown_status_text: str = "",
    markdown_busy: bool = False,
) -> SubjectCurrentStepView:
    context = _resolve_subject_current_step_context(
        scenario=scenario,
        progress=progress,
        phase=phase,
        can_capture_assistant=can_capture_assistant,
        import_staging=import_staging,
        markdown_selected_path=markdown_selected_path,
        markdown_status_text=markdown_status_text,
        markdown_busy=markdown_busy,
    )
    normalized_phase = collapse_ws(phase).casefold() or "research"
    if normalized_phase == "research":
        pending_collection = _source_collection_by_id(
            context.root_path,
            subject_id=context.scenario.subject_id,
            collection_id=context.progress.research_source_collection_discovery_collection_id,
        )
        if _pending_research_source_collection_discovery(
            progress=context.progress,
            selected_collection=pending_collection,
        ):
            return _build_current_step_research_apply_source_collection_discovery(
                context,
                pending_collection=pending_collection,
            )
        pending_collection = _source_collection_by_id(
            context.root_path,
            subject_id=context.scenario.subject_id,
            collection_id=context.progress.research_source_collection_synthesis_collection_id,
        )
        if _pending_research_source_collection_synthesis(
            progress=context.progress,
            selected_collection=pending_collection,
        ):
            return _build_current_step_research_apply_source_collection_synthesis(
                context,
                pending_collection=pending_collection,
            )
        pending_collection = _source_collection_by_id(
            context.root_path,
            subject_id=context.scenario.subject_id,
            collection_id=context.progress.research_source_collection_manual_curation_collection_id,
        )
        if _pending_research_source_collection_manual_curation_path(
            progress=context.progress,
            selected_collection=pending_collection,
        ) is not None:
            return _build_current_step_research_apply_manual_source_collection_curation(
                context,
                pending_collection=pending_collection,
            )
        pending_collection = _source_collection_by_id(
            context.root_path,
            subject_id=context.scenario.subject_id,
            collection_id=context.progress.research_source_collection_llm_curation_collection_id,
        )
        if _pending_research_source_collection_llm_curation(
            progress=context.progress,
            selected_collection=pending_collection,
        ):
            return _build_current_step_research_apply_llm_source_collection_curation(
                context,
                pending_collection=pending_collection,
            )
        pending_collection = _source_collection_by_id(
            context.root_path,
            subject_id=context.scenario.subject_id,
            collection_id=context.progress.research_source_collection_merge_back_collection_id,
        )
        if _pending_research_source_collection_merge_back(
            progress=context.progress,
            selected_collection=pending_collection,
        ):
            return _build_current_step_research_apply_source_collection_merge_back(
                context,
                pending_collection=pending_collection,
            )
        pending_collection = _source_collection_by_id(
            context.root_path,
            subject_id=context.scenario.subject_id,
            collection_id=context.progress.research_source_collection_source_merge_back_collection_id,
        )
        if _pending_research_source_collection_source_merge_back(
            progress=context.progress,
            selected_collection=pending_collection,
        ):
            return _build_current_step_research_apply_source_collection_source_merge_back(
                context,
                pending_collection=pending_collection,
            )
        selected_source = _selected_staged_source(
            context.root_path,
            subject_id=context.scenario.subject_id,
            progress=context.progress,
        )
        if _pending_research_source_manual_curation_path(
            progress=context.progress,
            staged_source=selected_source,
        ) is not None:
            return _build_current_step_research_apply_manual_curation(context)
        if _pending_research_source_merge_back(
            progress=context.progress,
            staged_source=selected_source,
        ):
            return _build_current_step_research_apply_merge_back(context)
        if _pending_research_source_llm_curation(
            progress=context.progress,
            staged_source=selected_source,
        ):
            return _build_current_step_research_apply_llm_curation(context)
    if normalized_phase == "review":
        selected_section = _selected_report_scope_section_entry(
            context.root_path,
            scenario=context.scenario,
            progress=context.progress,
        )
        if selected_section is not None:
            _composition, _entry, section_id, _role, _title = selected_section
            if _pending_review_section_manual_rephrase_path(
                progress=context.progress,
                section_id=section_id,
            ) is not None:
                return _build_current_step_review_apply_manual_section_rephrase(context)
            if _pending_review_section_llm_rephrase(
                progress=context.progress,
                section_id=section_id,
            ):
                return _build_current_step_review_apply_llm_section_rephrase(context)
    builder = _CURRENT_STEP_VIEW_BUILDERS.get(context.current_step_state)
    if builder is None:
        raise AssertionError(f"Unsupported current step state: {context.current_step_state}")
    return builder(context)


def subject_current_step_state(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    phase: str,
    can_capture_assistant: bool = False,
    import_staging: SubjectImportStaging | None = None,
    markdown_selected_path: str = "",
    markdown_status_text: str = "",
    markdown_busy: bool = False,
) -> SubjectWorkflowCurrentStepState:
    return _resolve_subject_current_step_context(
        scenario=scenario,
        progress=progress,
        phase=phase,
        can_capture_assistant=can_capture_assistant,
        import_staging=import_staging,
        markdown_selected_path=markdown_selected_path,
        markdown_status_text=markdown_status_text,
        markdown_busy=markdown_busy,
    ).current_step_state


def subject_guidance_phase(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    phase: str,
    can_capture_assistant: bool = False,
    import_staging: SubjectImportStaging | None = None,
    markdown_selected_path: str = "",
    markdown_status_text: str = "",
    markdown_busy: bool = False,
) -> str:
    current_phase = collapse_ws(str(phase or "")).casefold() or "research"
    try:
        current_tab = SubjectWorkflowTab(current_phase)
    except Exception:
        current_tab = SubjectWorkflowTab.RESEARCH
    state = subject_current_step_state(
        scenario=scenario,
        progress=progress,
        phase=current_phase,
        can_capture_assistant=can_capture_assistant,
        import_staging=import_staging,
        markdown_selected_path=markdown_selected_path,
        markdown_status_text=markdown_status_text,
        markdown_busy=markdown_busy,
    )
    return preferred_subject_workflow_tab_for_current_step(
        state=state,
        current_tab=current_tab,
    ).value


def render_subject_current_step(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    phase: str,
    can_capture_assistant: bool = False,
    import_staging: SubjectImportStaging | None = None,
    markdown_selected_path: str = "",
    markdown_status_text: str = "",
    markdown_busy: bool = False,
) -> str:
    step = subject_current_step_view(
        scenario=scenario,
        progress=progress,
        phase=phase,
        can_capture_assistant=can_capture_assistant,
        import_staging=import_staging,
        markdown_selected_path=markdown_selected_path,
        markdown_status_text=markdown_status_text,
        markdown_busy=markdown_busy,
    )
    lines = [
        f"Do this now: {step.title}",
        f"Status: {step.status}",
        f"Why: {step.why}",
    ]
    lines.extend(step.detail_lines)
    return "\n".join(lines)


def render_subject_journey(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    phase: str,
    import_staging: SubjectImportStaging | None = None,
    markdown_selected_path: str = "",
    markdown_status_text: str = "",
    markdown_busy: bool = False,
) -> str:
    del phase
    del import_staging
    resolution = resolve_subject_workflow_journey(
        _subject_workflow_state_inputs(
            scenario=scenario,
            progress=progress,
            markdown_selected_path=markdown_selected_path,
            markdown_busy=markdown_busy,
        )
    )
    return "\n".join(render_subject_workflow_journey_lines(resolution))


def subject_current_step_actions(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    phase: str,
    can_capture_assistant: bool = False,
    import_staging: SubjectImportStaging | None = None,
    markdown_selected_path: str = "",
    markdown_status_text: str = "",
    markdown_busy: bool = False,
) -> tuple[SubjectGateAction, ...]:
    step = subject_current_step_view(
        scenario=scenario,
        progress=progress,
        phase=phase,
        can_capture_assistant=can_capture_assistant,
        import_staging=import_staging,
        markdown_selected_path=markdown_selected_path,
        markdown_status_text=markdown_status_text,
        markdown_busy=markdown_busy,
    )
    actions: list[SubjectGateAction] = []
    normalized_phase = collapse_ws(phase).casefold() or "research"
    if step.primary_action is not None:
        actions.append(
            _normalize_current_step_gate_action_for_phase(
                current_phase=normalized_phase,
                action=step.primary_action,
            )
        )
    staging_source_id = collapse_ws(import_staging.source_subject_id) if import_staging is not None else ""
    if (
        normalized_phase == "research"
        and not scenario.is_placeholder
        and progress.context_opened
        and (
            step.primary_action is None
            or collapse_ws(step.primary_action.key)
            not in {
                "apply_research_source_llm_curation",
                "apply_research_source_merge_back",
                "apply_research_source_manual_curation",
                "apply_research_source_collection_merge_back",
                "apply_research_source_collection_source_merge_back",
                "apply_research_source_collection_discovery",
                "apply_research_source_collection_llm_curation",
                "apply_research_source_collection_manual_curation",
                "apply_research_source_collection_synthesis",
            }
        )
    ):
        itemization_state = _itemization_state(_root_path_from_scenario(scenario), scenario)
        latest_staged_source = _latest_staged_source_for_subject(_root_path_from_scenario(scenario), scenario.subject_id)
        selected_staged_source = _selected_staged_source(
            _root_path_from_scenario(scenario),
            subject_id=scenario.subject_id,
            progress=progress,
        )
        if staging_source_id:
            if staging_source_id == collapse_ws(scenario.subject_id):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
                normalized_profile = _normalize_import_selection_profile(
                    import_staging.selection_profile if import_staging is not None else ""
                )
                if normalized_profile != "full_context":
                    _append_subject_gate_action_if_absent(
                        actions,
                        _normalize_current_step_gate_action_for_phase(
                            current_phase=normalized_phase,
                            action=_gate_subject_action("advance_import_selection", "Expand Import Scope"),
                        ),
                    )
                _append_subject_gate_action_if_absent(
                    actions,
                    _normalize_current_step_gate_action_for_phase(
                        current_phase=normalized_phase,
                        action=_gate_subject_action("clear_import_staging", "Clear Import Source"),
                    ),
                )
            else:
                _append_subject_gate_action_if_absent(
                    actions,
                    _normalize_current_step_gate_action_for_phase(
                        current_phase=normalized_phase,
                        action=_gate_subject_action("create_subject_import", "Create Import From Selected Source"),
                    ),
                )
                _append_subject_gate_action_if_absent(
                    actions,
                    _normalize_current_step_gate_action_for_phase(
                        current_phase=normalized_phase,
                        action=_gate_subject_action("clear_import_staging", "Clear Import Source"),
                    ),
                )
        elif scenario.pending_import_count == 0:
            _append_subject_gate_action_if_absent(
                actions,
                _normalize_current_step_gate_action_for_phase(
                    current_phase=normalized_phase,
                    action=_gate_subject_action("pin_import_source", "Select As Import Source"),
                ),
            )
            if selected_staged_source is not None:
                _append_subject_gate_action_if_absent(
                    actions,
                    _normalize_current_step_gate_action_for_phase(
                        current_phase=normalized_phase,
                        action=_gate_subject_action(
                            "import_selected_staged_source",
                            "Import Selected Staged Source",
                        ),
                    ),
                )
            elif latest_staged_source is not None:
                _append_subject_gate_action_if_absent(
                    actions,
                    _normalize_current_step_gate_action_for_phase(
                        current_phase=normalized_phase,
                        action=_gate_subject_action("import_latest_staged_source", "Import Latest Staged Source"),
                    ),
                )
            _append_subject_gate_action_if_absent(
                actions,
                _normalize_current_step_gate_action_for_phase(
                    current_phase=normalized_phase,
                    action=_gate_subject_action("generate_itemization", _itemization_primary_action_label(itemization_state)),
                ),
            )
            if bool(itemization_state.get("exists")):
                _append_subject_gate_action_if_absent(
                    actions,
                    _normalize_current_step_gate_action_for_phase(
                        current_phase=normalized_phase,
                        action=_gate_subject_action("preview_itemization", "Preview Itemization"),
                    ),
                )
    secondary_limit = 3 if normalized_phase in {"itemize", "review", "publication"} else 2
    for action in step.secondary_actions[:secondary_limit]:
        _append_subject_gate_action_if_absent(
            actions,
            _normalize_current_step_gate_action_for_phase(
                current_phase=normalized_phase,
                action=action,
            ),
        )
    decorated_actions: list[SubjectGateAction] = []
    for action in actions[:4]:
        if collapse_ws(action.kind) == "phase_nav":
            decorated_actions.append(
                SubjectGateAction(
                    kind=action.kind,
                    key=action.key,
                    label=_current_step_action_button_label_for_phase_nav(
                        scenario=scenario,
                        progress=progress,
                        current_phase=normalized_phase,
                        action=action,
                        can_capture_assistant=can_capture_assistant,
                        import_staging=import_staging,
                        markdown_selected_path=markdown_selected_path,
                        markdown_status_text=markdown_status_text,
                        markdown_busy=markdown_busy,
                    ),
                    enabled=action.enabled,
                )
            )
            continue
        decorated_actions.append(action)
    return tuple(decorated_actions)


def subject_more_action_specs(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    phase: str,
    can_capture_assistant: bool = False,
    import_staging: SubjectImportStaging | None = None,
    markdown_selected_path: str = "",
    markdown_status_text: str = "",
    markdown_busy: bool = False,
) -> tuple[SubjectActionSpec, ...]:
    current_actions = subject_current_step_actions(
        scenario=scenario,
        progress=progress,
        phase=phase,
        can_capture_assistant=can_capture_assistant,
        import_staging=import_staging,
        markdown_selected_path=markdown_selected_path,
        markdown_status_text=markdown_status_text,
        markdown_busy=markdown_busy,
    )
    hidden_keys = {
        action.key
        for action in current_actions
        if collapse_ws(action.kind) == "subject_action" and collapse_ws(action.key)
    }
    if collapse_ws(phase).casefold() == "research":
        hidden_keys.add("use_markdown_ingress")
    specs = [
        spec
        for spec in subject_action_specs(
            scenario=scenario,
            progress=progress,
            phase=phase,
            can_capture_assistant=can_capture_assistant,
            import_staging=import_staging,
        )
        if collapse_ws(spec.key) not in hidden_keys
        and bool(spec.enabled)
        and not (collapse_ws(spec.key) == "open_context" and progress.context_opened)
    ]
    if collapse_ws(phase).casefold() == "research" and not scenario.is_placeholder and progress.context_opened:
        root_path = _root_path_from_scenario(scenario)
        selected_collection = _selected_source_collection(root_path, subject_id=scenario.subject_id, progress=progress)
        selected_source = _selected_staged_source(root_path, subject_id=scenario.subject_id, progress=progress)
        refreshable_sources = (
            _refreshable_staged_sources_for_collection(root_path, collection=selected_collection)
            if selected_collection is not None
            else ()
        )
        selected_in_collection = (
            selected_collection is not None
            and selected_source is not None
            and collapse_ws(selected_source.staged_source_id) in {
                collapse_ws(item) for item in selected_collection.staged_source_ids if collapse_ws(item)
            }
        )
        merge_back_enabled = _selected_staged_source_supports_merge_back(
            root_path,
            scenario=scenario,
            progress=progress,
        )
        collection_merge_back_enabled = _selected_source_collection_supports_merge_back(
            root_path,
            scenario=scenario,
            progress=progress,
        )
        collection_source_merge_back_enabled = _selected_source_collection_supports_source_merge_back(
            root_path,
            scenario=scenario,
            progress=progress,
        )
        selected_source_export_apply_enabled = _selected_staged_source_has_export_entries(
            root_path,
            scenario=scenario,
            progress=progress,
            staged_source=selected_source,
        )
        collection_export_apply_enabled = _selected_source_collection_has_export_targets(
            root_path,
            scenario=scenario,
            progress=progress,
            selected_collection=selected_collection,
        )
        selected_source_baseline = (
            _selected_staged_source_baseline_revision(root_path, selected_source, progress=progress)
            if selected_source is not None
            else None
        )
        selected_source_revision_count = int(getattr(selected_source, "revision_count", 0) or 0) if selected_source is not None else 0
        research_specs = [
            SubjectActionSpec(
                key="apply_selected_staged_source_export_preview",
                label="Apply Selected Source Export Preview",
                enabled=selected_source_export_apply_enabled,
            ),
            SubjectActionSpec(
                key="sync_selected_source_collection",
                label="Sync Source Set",
                enabled=selected_collection is not None and bool(refreshable_sources),
            ),
            SubjectActionSpec(
                key="apply_selected_source_collection_export_preview",
                label="Apply Set Export Preview",
                enabled=collection_export_apply_enabled,
            ),
            SubjectActionSpec(
                key="refresh_selected_staged_source",
                label="Refresh Selected Source",
                enabled=(
                    selected_source is not None
                    and collapse_ws(getattr(selected_source, "source_kind", "")).casefold() == "url"
                    and bool(collapse_ws(getattr(selected_source, "source_ref", "")))
                ),
            ),
            SubjectActionSpec(
                key="cycle_research_source_revision_baseline",
                label=(
                    f"Change Diff Baseline ({selected_source_baseline.revision_kind})"
                    if selected_source_baseline is not None
                    else "Change Diff Baseline"
                ),
                enabled=selected_source is not None and selected_source_revision_count > 1,
            ),
            SubjectActionSpec(
                key="start_research_source_merge_back",
                label="Merge Back In Chat",
                enabled=selected_source is not None and merge_back_enabled,
            ),
            SubjectActionSpec(
                key="create_source_collection_from_selected_staged_source",
                label="Create Source Set",
                enabled=selected_source is not None and (
                    selected_collection is None or _source_collection_is_default(selected_collection)
                ),
            ),
            SubjectActionSpec(
                key="start_research_source_collection_llm_curation",
                label="Curate Source Set In Chat",
                enabled=selected_collection is not None and not _source_collection_is_default(selected_collection),
            ),
            SubjectActionSpec(
                key="start_research_source_collection_discovery",
                label="Find Sources In Chat",
                enabled=(
                    selected_collection is not None
                    and not _source_collection_is_default(selected_collection)
                    and bool(collapse_ws(selected_collection.query_text))
                ),
            ),
            SubjectActionSpec(
                key="start_research_source_collection_synthesis",
                label="Synthesize Source Set In Chat",
                enabled=(
                    selected_collection is not None
                    and not _source_collection_is_default(selected_collection)
                    and bool(selected_collection.staged_source_ids)
                ),
            ),
            SubjectActionSpec(
                key="start_research_source_collection_merge_back",
                label="Merge Source Set In Chat",
                enabled=collection_merge_back_enabled,
            ),
            SubjectActionSpec(
                key="start_research_source_collection_source_merge_back",
                label="Merge Set Sources In Chat",
                enabled=collection_source_merge_back_enabled,
            ),
            SubjectActionSpec(
                key="start_research_source_collection_manual_curation",
                label="Curate Source Set Manually",
                enabled=selected_collection is not None and not _source_collection_is_default(selected_collection),
            ),
            SubjectActionSpec(
                key="toggle_selected_staged_source_in_collection",
                label="Remove From Source Set" if selected_in_collection else "Add To Source Set",
                enabled=selected_source is not None and selected_collection is not None and not _source_collection_is_default(selected_collection),
            ),
            SubjectActionSpec(
                key="refresh_subjects",
                label="Refresh Subjects",
                enabled=True,
            ),
            SubjectActionSpec(
                key="use_markdown_ingress",
                label=_MARKDOWN_INGRESS_LABEL,
                enabled=True,
            ),
        ]
        hidden_keys_local = {collapse_ws(spec.key) for spec in specs if collapse_ws(spec.key)}
        research_specs = [
            spec
            for spec in research_specs
            if collapse_ws(spec.key) not in hidden_keys_local and bool(spec.enabled)
        ]
        specs = [*research_specs, *specs]
    if collapse_ws(phase).casefold() in {"draft", "review", "publication"} and _composition_current(scenario):
    # Sync note: update workstation/subject_workflow_state_transitions.py first, then update this method.
        root_path = _root_path_from_scenario(scenario)
        selected_entry = _selected_report_scope_entry(
            _report_scope_entries(root_path, scenario=scenario, progress=progress),
            progress,
        )
        if selected_entry is not None and selected_entry.item_kind == "import":
            composition = _latest_publication_composition(
                root_path,
                subject_id=scenario.subject_id,
                subject_title=scenario.title,
                publication_id=scenario.publication_id,
            )
            if composition is not None:
                import_id = selected_entry.entry_id.split(":", 1)[-1]
                if import_id in set(composition.selected_subject_import_ids):
                    current_mode = composition.import_usage_by_id.get(import_id, "dependency_only")
                    specs = [
                        spec
                        for spec in specs
                        if collapse_ws(spec.key) != "cycle_selected_publication_import_usage"
                    ]
                    specs.extend(_publication_import_usage_action_specs(current_mode))
    return tuple(specs[:4])


def subject_itemize_decision_role_select_spec(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> SubjectSelectSpec:
    root = _root_path_from_scenario(scenario)
    _session, items = _itemization_session_and_items(root, scenario)
    selected_item = _selected_itemization_item(
        root,
        scenario=scenario,
        progress=progress,
    )
    held_ids = set(
        _valid_itemize_held_item_ids(
            items=items,
            progress=progress,
        )
    )
    enabled = (
        selected_item is not None
        and collapse_ws(selected_item.status) in _ITEMIZE_MUTABLE_STATUSES
        and collapse_ws(selected_item.itemized_item_id) not in held_ids
    )
    current_role = (
        normalize_itemized_decision_role(selected_item.metadata.get("decision_role", ""))
        if selected_item is not None
        else ""
    )
    return SubjectSelectSpec(
        label="Decision Role",
        value=current_role,
        options=tuple(
            (_format_orientation_label(role), role)
            for role in _ITEMIZE_DECISION_ROLE_CYCLE
        ),
        enabled=enabled,
    )


def source_collection_option_label(collection: SourceCollection) -> str:
    title = collapse_ws(collection.title) or collapse_ws(collection.collection_id) or "<unnamed>"
    source_count = len(getattr(collection, "staged_source_ids", ()) or ())
    source_label = "source" if source_count == 1 else "sources"
    query_state = "query saved" if collapse_ws(getattr(collection, "query_text", "")) else "no saved query"
    return f"{title} [{source_count} {source_label}, {query_state}]"


def subject_research_source_inventory(
    *,
    root_path: Path,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> tuple[
    tuple[SourceCollection, ...],
    SourceCollection | None,
    tuple[tuple[StagedSource, SourceRevision | None], ...],
    tuple[tuple[str, str], ...],
]:
    """Return the typed source inventory used by workstation adapters."""
    collections = list_source_collections(root_path, scenario.subject_id)
    selected_collection, staged_sources = _staged_sources_for_selected_collection(
        root_path,
        subject_id=scenario.subject_id,
        progress=progress,
    )
    revisions = tuple(
        (staged_source, latest_source_revision(root_path, staged_source))
        for staged_source in staged_sources
    )
    workbench_rows = subject_research_source_collection_workbench_rows(
        root_path=root_path,
        scenario=scenario,
        progress=progress,
        selected_collection=selected_collection,
    )
    return collections, selected_collection, revisions, workbench_rows


def subject_research_source_collection_workbench_rows(
    *,
    root_path: Path,
    scenario: SubjectScenario,
    progress: SubjectProgress,
    selected_collection: SourceCollection | None = None,
) -> tuple[tuple[str, str], ...]:
    collection = selected_collection
    if collection is None:
        collection = _selected_source_collection(root_path, subject_id=scenario.subject_id, progress=progress)
    if collection is None:
        return (
            ("set type", "<none>"),
            ("find sources ready", "no"),
            ("knowledge synthesis ready", "no"),
            ("knowledge summary", "<none>"),
            ("open questions", "0"),
            ("sync source set ready", "no"),
            ("apply set export ready", "no"),
            ("merge source set ready", "no"),
            ("merge set sources ready", "no"),
            ("refreshable urls", "0"),
        )
    is_default = _source_collection_is_default(collection)
    refreshable_sources = _refreshable_staged_sources_for_collection(root_path, collection=collection)
    knowledge_summary = _source_collection_knowledge_summary(collection)
    knowledge_questions = _source_collection_knowledge_questions(collection)
    last_sync_at_ms = int(getattr(collection, "metadata", {}).get("last_sync_at_epoch_ms", 0) or 0)
    last_sync_summary = (
        "refreshed="
        + str(int(getattr(collection, "metadata", {}).get("last_sync_refreshed_count", 0) or 0))
        + " failed="
        + str(int(getattr(collection, "metadata", {}).get("last_sync_failed_count", 0) or 0))
        + " skipped="
        + str(int(getattr(collection, "metadata", {}).get("last_sync_skipped_count", 0) or 0))
        if last_sync_at_ms > 0
        else "<none>"
    )
    collection_export_ready = _selected_source_collection_has_export_targets(
        root_path,
        scenario=scenario,
        progress=progress,
        selected_collection=collection,
    )
    collection_merge_ready = _selected_source_collection_supports_merge_back(
        root_path,
        scenario=scenario,
        progress=progress,
    )
    collection_source_merge_ready = _selected_source_collection_supports_source_merge_back(
        root_path,
        scenario=scenario,
        progress=progress,
    )
    return (
        ("set type", _source_collection_kind_label(collection)),
        (
            "find sources ready",
            "yes" if (not is_default and bool(collapse_ws(getattr(collection, "query_text", "")))) else "no",
        ),
        (
            "knowledge synthesis ready",
            "yes" if (not is_default and bool(collection.staged_source_ids)) else "no",
        ),
        (
            "knowledge summary",
            textwrap.shorten(knowledge_summary, width=72, placeholder="...") if knowledge_summary else "<none>",
        ),
        ("open questions", str(len(knowledge_questions))),
        ("sync source set ready", "yes" if bool(refreshable_sources) else "no"),
        ("apply set export ready", "yes" if collection_export_ready else "no"),
        ("merge source set ready", "yes" if collection_merge_ready else "no"),
        ("merge set sources ready", "yes" if collection_source_merge_ready else "no"),
        ("refreshable urls", str(len(refreshable_sources))),
        ("last sync", last_sync_summary),
    )


def _research_source_revision_option_label(revision: SourceRevision) -> str:
    revision_kind = collapse_ws(revision.revision_kind) or "revision"
    revision_id = collapse_ws(revision.revision_id)
    if revision_id:
        return f"{revision_kind} / {revision_id[:12]}"
    return revision_kind


def subject_research_source_collection_select_spec(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> SubjectSelectSpec:
    if scenario.is_placeholder or not progress.context_opened:
        return SubjectSelectSpec(
            label="Source Set",
            value="",
            options=(),
            enabled=False,
        )
    root = _root_path_from_scenario(scenario)
    collections = list_source_collections(root, scenario.subject_id)
    selected_collection = _selected_source_collection(
        root,
        subject_id=scenario.subject_id,
        progress=progress,
    )
    current_value = (
        collapse_ws(selected_collection.collection_id)
        if selected_collection is not None
        else (collapse_ws(collections[0].collection_id) if collections else "")
    )
    return SubjectSelectSpec(
        label="Source Set",
        value=current_value,
        options=tuple(
            (source_collection_option_label(collection), collapse_ws(collection.collection_id))
            for collection in collections
        ),
        enabled=bool(collections),
    )


def subject_research_source_revision_baseline_select_spec(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> SubjectSelectSpec:
    if scenario.is_placeholder or not progress.context_opened:
        return SubjectSelectSpec(
            label="Revision Baseline",
            value="",
            options=(),
            enabled=False,
        )
    root = _root_path_from_scenario(scenario)
    selected_source = _selected_staged_source(
        root,
        subject_id=scenario.subject_id,
        progress=progress,
    )
    if selected_source is None:
        return SubjectSelectSpec(
            label="Revision Baseline",
            value="",
            options=(),
            enabled=False,
        )
    revisions = _ordered_staged_source_revisions(root, selected_source)
    baseline_candidates = tuple(revisions[1:])
