def _history_timestamp_label(timestamp_epoch_ms: int) -> str:
    return (
        time.strftime("%Y-%m-%d %H:%M", time.localtime(timestamp_epoch_ms / 1000.0))
        if int(timestamp_epoch_ms or 0) > 0
        else "unknown"
    )


def subject_research_selected_source_revision_history_table_spec(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> SubjectTableSpec:
    if scenario.is_placeholder:
        return SubjectTableSpec(
            label="Revision History",
            columns=("State", "Kind", "Revision", "When"),
            rows=(),
            enabled=False,
        )
    root = _root_path_from_scenario(scenario)
    _ensure_research_source_selection(
        root,
        scenario=scenario,
        progress=progress,
    )
    selected_source = _selected_staged_source(
        root,
        subject_id=scenario.subject_id,
        progress=progress,
    )
    if selected_source is None:
        return SubjectTableSpec(
            label="Revision History",
            columns=("State", "Kind", "Revision", "When"),
            rows=(),
            enabled=False,
        )
    revisions = _ordered_staged_source_revisions(root, selected_source)
    baseline_revision = _selected_staged_source_baseline_revision(
        root,
        selected_source,
        progress=progress,
    )
    latest_revision_id = collapse_ws(selected_source.latest_revision_id)
    baseline_revision_id = collapse_ws(getattr(baseline_revision, "revision_id", ""))
    rows: list[tuple[str, ...]] = []
    for revision in revisions[:8]:
        state_labels: list[str] = []
        if collapse_ws(revision.revision_id) == latest_revision_id:
            state_labels.append("current")
        else:
            state_labels.append("prior")
        if baseline_revision_id and collapse_ws(revision.revision_id) == baseline_revision_id:
            state_labels.append("baseline")
        rows.append(
            (
                " / ".join(state_labels),
                collapse_ws(revision.revision_kind) or "revision",
                collapse_ws(revision.revision_id)[:12] or "<none>",
                _history_timestamp_label(int(revision.created_at_epoch_ms or 0)),
            )
        )
    return SubjectTableSpec(
        label="Revision History",
        columns=("State", "Kind", "Revision", "When"),
        rows=tuple(rows),
        enabled=bool(rows),
    )


def _metric_table_rows(lines: tuple[str, ...]) -> tuple[tuple[str, ...], ...]:
    rows: list[tuple[str, ...]] = []
    for line in lines:
        text = collapse_ws(line)
        if not text.startswith("- "):
            continue
        body = text[2:]
        if ": " not in body:
            continue
        label, value = body.split(": ", 1)
        if not collapse_ws(label) or not collapse_ws(value):
            continue
        rows.append((collapse_ws(label), collapse_ws(value)))
    return tuple(rows)


def _merge_export_history_table_rows(lines: tuple[str, ...]) -> tuple[tuple[str, ...], ...]:
    rows: list[tuple[str, ...]] = []
    current_event_label = ""
    current_event_index = 0
    for line in lines:
        text = str(line or "")
        normalized = collapse_ws(text)
        if normalized.startswith("- recent member revision events:"):
            current_event_label = "member revision"
            current_event_index = 0
            continue
        if normalized.startswith("- recent export events:"):
            current_event_label = "export event"
            current_event_index = 0
            continue
        if normalized.startswith("- ") and ": " in normalized[2:]:
            label, value = normalized[2:].split(": ", 1)
            if collapse_ws(label) and collapse_ws(value):
                rows.append((collapse_ws(label), collapse_ws(value)))
            current_event_label = ""
            current_event_index = 0
            continue
        if text.startswith("  - ") and current_event_label:
            current_event_index += 1
            rows.append((f"{current_event_label} {current_event_index}", collapse_ws(text[4:])))
    return tuple(rows)


def subject_research_selected_source_change_summary_table_spec(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> SubjectTableSpec:
    if scenario.is_placeholder:
        return SubjectTableSpec(
            label="Latest Change Summary",
            columns=("Metric", "Value"),
            rows=(),
            enabled=False,
        )
    root = _root_path_from_scenario(scenario)
    _ensure_research_source_selection(
        root,
        scenario=scenario,
        progress=progress,
    )
    selected_source = _selected_staged_source(
        root,
        subject_id=scenario.subject_id,
        progress=progress,
    )
    if selected_source is None:
        return SubjectTableSpec(
            label="Latest Change Summary",
            columns=("Metric", "Value"),
            rows=(),
            enabled=False,
        )
    baseline_revision = _selected_staged_source_baseline_revision(
        root,
        selected_source,
        progress=progress,
    )
    rows: list[tuple[str, ...]] = []
    for line in _selected_staged_source_diff_summary_lines(
        root,
        selected_source,
        baseline_revision=baseline_revision,
    ):
        text = collapse_ws(line)
        if not text.startswith("- "):
            continue
        body = text[2:]
        if ": " in body:
            label, value = body.split(": ", 1)
            if collapse_ws(label) and collapse_ws(value):
                rows.append((collapse_ws(label), collapse_ws(value)))
            continue
        if collapse_ws(body):
            rows.append(("note", collapse_ws(body)))
    return SubjectTableSpec(
        label="Latest Change Summary",
        columns=("Metric", "Value"),
        rows=tuple(rows),
        enabled=bool(rows),
    )


def subject_research_source_collection_member_export_status_table_spec(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> SubjectTableSpec:
    if scenario.is_placeholder:
        return SubjectTableSpec(
            label="Member Export Status",
            columns=("Source", "Latest", "Status", "Pending", "Applied"),
            rows=(),
            enabled=False,
        )
    root = _root_path_from_scenario(scenario)
    _ensure_research_source_selection(
        root,
        scenario=scenario,
        progress=progress,
    )
    selected_collection = _selected_source_collection(
        root,
        subject_id=scenario.subject_id,
        progress=progress,
    )
    if selected_collection is None:
        return SubjectTableSpec(
            label="Member Export Status",
            columns=("Source", "Latest", "Status", "Pending", "Applied"),
            rows=(),
            enabled=False,
        )
    staged_sources = tuple(
        sorted(
            _staged_sources_for_collection(root, collection=selected_collection),
            key=lambda item: (
                -int(item.updated_at_epoch_ms or 0),
                collapse_ws(item.title or item.staged_source_id).casefold(),
            ),
        )
    )
    rows: list[tuple[str, ...]] = []
    for staged_source in staged_sources[:6]:
        latest_revision = latest_source_revision(root, staged_source)
        status, current_entries, _applied_entries, latest_export_revision = (
            _selected_source_collection_member_export_state(
                root,
                scenario=scenario,
                progress=progress,
                selected_collection=selected_collection,
                staged_source=staged_source,
            )
        )
        rows.append(
            (
                collapse_ws(staged_source.title or staged_source.staged_source_id) or "<unnamed>",
                collapse_ws(getattr(latest_revision, "revision_kind", "")) or "<none>",
                status,
                str(len(current_entries)),
                (
                    _history_timestamp_label(int(latest_export_revision.created_at_epoch_ms or 0))
                    if latest_export_revision is not None
                    else "<none>"
                ),
            )
        )
    return SubjectTableSpec(
        label="Member Export Status",
        columns=("Source", "Latest", "Status", "Pending", "Applied"),
        rows=tuple(rows),
        enabled=bool(rows),
    )


