def subject_research_source_collection_export_applied_table_spec(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> SubjectTableSpec:
    if scenario.is_placeholder:
        return SubjectTableSpec(
            label="Export-Applied Targets",
            columns=("Source", "Entries", "Applied", "Status"),
            rows=(),
            enabled=False,
        )
    root = _root_path_from_scenario(scenario)
    _ensure_research_source_selection(
        root,
        scenario=scenario,
        progress=progress,
    )
    selected_collection = _selected_source_collection(
        root,
        subject_id=scenario.subject_id,
        progress=progress,
    )
    if selected_collection is None:
        return SubjectTableSpec(
            label="Export-Applied Targets",
            columns=("Source", "Entries", "Applied", "Status"),
            rows=(),
            enabled=False,
        )
    staged_sources = _staged_sources_for_collection(root, collection=selected_collection)
    export_targets: list[tuple[int, tuple[str, ...]]] = []
    for staged_source in staged_sources:
        export_revision = _latest_collection_export_applied_revision(
            root,
            staged_source=staged_source,
            collection_id=selected_collection.collection_id,
        )
        if export_revision is None:
            continue
        status, _current_entries, applied_entries, _latest_export_revision = (
            _selected_source_collection_member_export_state(
                root,
                scenario=scenario,
                progress=progress,
                selected_collection=selected_collection,
                staged_source=staged_source,
            )
        )
        export_targets.append(
            (
                int(export_revision.created_at_epoch_ms or 0),
                (
                    collapse_ws(staged_source.title or staged_source.staged_source_id) or "<unnamed>",
                    str(int(export_revision.metadata.get("export_entry_count", 0) or len(applied_entries))),
                    _history_timestamp_label(int(export_revision.created_at_epoch_ms or 0)),
                    status,
                ),
            )
        )
    rows = tuple(row for _timestamp, row in sorted(export_targets, key=lambda item: (-item[0], item[1][0]))[:6])
    return SubjectTableSpec(
        label="Export-Applied Targets",
        columns=("Source", "Entries", "Applied", "Status"),
        rows=rows,
        enabled=bool(rows),
    )


