def subject_itemize_hold_switch_spec(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> SubjectSwitchSpec:
    root = _root_path_from_scenario(scenario)
    _session, items = _itemization_session_and_items(root, scenario)
    selected_item = _selected_itemization_item(
        root,
        scenario=scenario,
        progress=progress,
    )
    held_ids = set(
        _valid_itemize_held_item_ids(
            items=items,
            progress=progress,
        )
    )
    selected_id = collapse_ws(getattr(selected_item, "itemized_item_id", ""))
    enabled = (
        selected_item is not None
        and collapse_ws(selected_item.status) in _ITEMIZE_MUTABLE_STATUSES
    )
    return SubjectSwitchSpec(
        label="Hold For Merge",
        value=selected_id in held_ids if selected_id else False,
        enabled=enabled,
    )


