def subject_draft_model_transition_source_select_spec(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> SubjectSelectSpec:
    root = _root_path_from_scenario(scenario)
    selected_candidate = _selected_transformation_construct_candidate(
        root,
        scenario=scenario,
        progress=progress,
        include_rejected=False,
    )
    if selected_candidate is None or collapse_ws(selected_candidate.status) != "accepted":
        return SubjectSelectSpec(label="Source State", value="", options=(), enabled=False)
    frame = load_decision_frame(root, scenario.subject_id)
    decision_items = list_decision_review_items(root, scenario.subject_id)
    selected_decision_item = _decision_review_item_for_construct_candidate(
        decision_items,
        selected_candidate,
        frame=frame,
    )
    selected_lane = _current_construct_candidate_lane(
        selected_candidate,
        decision_item=selected_decision_item,
        frame=frame,
    )
    if selected_decision_item is None or selected_lane != "transition_candidate":
        return SubjectSelectSpec(label="Source State", value="", options=(), enabled=False)
    state_items = _state_decision_review_items(decision_items)
    source_binding_id = collapse_ws(str(selected_decision_item.metadata.get(_TRANSITION_SOURCE_DECISION_ITEM_ID_KEY, "")))
    target_binding_id = collapse_ws(str(selected_decision_item.metadata.get(_TRANSITION_TARGET_DECISION_ITEM_ID_KEY, "")))
    source_items = state_items
    if len(source_items) > 1 and target_binding_id:
        source_items = tuple(
            item
            for item in source_items
            if collapse_ws(item.decision_review_item_id) != target_binding_id
            or collapse_ws(item.decision_review_item_id) == source_binding_id
        ) or source_items
    return SubjectSelectSpec(
        label="Source State",
        value=source_binding_id,
        options=tuple(
            (_decision_item_display_label(item), item.decision_review_item_id)
            for item in source_items
        ),
        enabled=bool(source_items),
    )


