def subject_draft_model_relation_selection_list_specs(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> tuple[SubjectSelectionListSpec, ...]:
    root = _root_path_from_scenario(scenario)
    selected_candidate = _selected_transformation_construct_candidate(
        root,
        scenario=scenario,
        progress=progress,
        include_rejected=False,
    )
    if selected_candidate is None or collapse_ws(selected_candidate.status) != "accepted":
        return ()
    frame = load_decision_frame(root, scenario.subject_id)
    decision_items = list_decision_review_items(root, scenario.subject_id)
    selected_decision_item = _decision_review_item_for_construct_candidate(
        decision_items,
        selected_candidate,
        frame=frame,
    )
    if selected_decision_item is None:
        return ()
    selected_lane = _current_construct_candidate_lane(
        selected_candidate,
        decision_item=selected_decision_item,
        frame=frame,
    )

    def _build_spec(
        *,
        label: str,
        action_key_prefix: str,
        option_items: tuple[DecisionReviewItem, ...],
        selected_ids: tuple[str, ...],
        enabled: bool = True,
    ) -> SubjectSelectionListSpec:
        selected_id_set = {collapse_ws(item_id) for item_id in selected_ids if collapse_ws(item_id)}
        return SubjectSelectionListSpec(
            label=label,
            action_key_prefix=action_key_prefix,
            options=tuple(
                (
                    _decision_item_display_label(item),
                    item.decision_review_item_id,
                    collapse_ws(item.decision_review_item_id) in selected_id_set,
                )
                for item in option_items
            ),
            enabled=enabled and bool(option_items),
        )

    if selected_lane == "capability":
        dependency_ids = _metadata_decision_item_ids(
            dict(selected_decision_item.metadata),
            plural_key=_CAPABILITY_REQUIRED_DEPENDENCY_DECISION_ITEM_IDS_KEY,
            singular_key=_CAPABILITY_REQUIRED_DEPENDENCY_DECISION_ITEM_ID_KEY,
        )
        boundary_ids = _metadata_decision_item_ids(
            dict(selected_decision_item.metadata),
            plural_key=_CAPABILITY_CROSSED_BOUNDARY_DECISION_ITEM_IDS_KEY,
            singular_key=_CAPABILITY_CROSSED_BOUNDARY_DECISION_ITEM_ID_KEY,
        )
        return (
            _build_spec(
                label="Dependencies",
                action_key_prefix="set_selected_draft_construct_capability_dependencies:",
                option_items=_dependency_decision_review_items(decision_items),
                selected_ids=dependency_ids,
            ),
            _build_spec(
                label="Boundaries",
                action_key_prefix="set_selected_draft_construct_capability_boundaries:",
                option_items=_boundary_decision_review_items(decision_items),
                selected_ids=boundary_ids,
            ),
        )
    if selected_lane == "transition_candidate":
        changed_capability_ids = _metadata_decision_item_ids(
            dict(selected_decision_item.metadata),
            plural_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_IDS_KEY,
            singular_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_ID_KEY,
        )
        return (
            _build_spec(
                label="Changed Capabilities",
                action_key_prefix="set_selected_draft_construct_transition_changed_capabilities:",
                option_items=_capability_decision_review_items(decision_items),
                selected_ids=changed_capability_ids,
            ),
        )
    if selected_lane == "decision_candidate":
        selected_transition_ids = _metadata_decision_item_ids(
            dict(selected_decision_item.metadata),
            plural_key=_DECISION_SELECTED_TRANSITION_ITEM_IDS_KEY,
            singular_key=_DECISION_SELECTED_TRANSITION_ITEM_ID_KEY,
        )
        assigned_actor_ids = _metadata_decision_item_ids(
            dict(selected_decision_item.metadata),
            plural_key=_DECISION_ASSIGNED_ACTOR_DECISION_ITEM_IDS_KEY,
            singular_key=_DECISION_ASSIGNED_ACTOR_DECISION_ITEM_ID_KEY,
        )
        selected_transition_items = _decision_items_by_ids(decision_items, selected_transition_ids)
        selected_transition_changed_capabilities = _dedupe_decision_items(
            tuple(
                changed_capability_item
                for transition_item in selected_transition_items
                for changed_capability_item in _decision_items_by_ids(
                    decision_items,
                    _metadata_decision_item_ids(
                        dict(transition_item.metadata),
                        plural_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_IDS_KEY,
                        singular_key=_TRANSITION_CHANGED_CAPABILITY_DECISION_ITEM_ID_KEY,
                    ),
                )
            )
        )
        return (
            _build_spec(
                label="Selected Transitions",
                action_key_prefix="set_selected_draft_construct_selected_transitions:",
                option_items=_transition_decision_review_items(decision_items),
                selected_ids=selected_transition_ids,
            ),
            _build_spec(
                label="Assigned Actors",
                action_key_prefix="set_selected_draft_construct_assigned_actors:",
                option_items=_actor_decision_review_items(decision_items),
                selected_ids=assigned_actor_ids,
                enabled=bool(selected_transition_items) and bool(selected_transition_changed_capabilities),
            ),
        )
    return ()


