def subject_review_composition_unit_included_switch_spec(
    *,
    scenario: SubjectScenario,
    progress: SubjectProgress,
) -> SubjectSwitchSpec:
    root = _root_path_from_scenario(scenario)
    composition = _latest_publication_composition(
        root,
        subject_id=scenario.subject_id,
        subject_title=scenario.title,
        publication_id=scenario.publication_id,
    )
    if composition is None:
        return SubjectSwitchSpec(
            label="In Report",
            value=False,
            enabled=False,
        )
    context = load_learning_context(root, scenario.subject_id)
    selected_unit = _selected_composition_unit(context, progress)
    selected_unit_id = collapse_ws(getattr(selected_unit, "unit_id", ""))
    included_unit_ids = set(composition.included_unit_ids)
